ui/toggles/fragment.js:
// toggles: one switch per cycle (about 2.6 s): its row lights, it flips, the count follows; hold. The
// switches flip in a fixed order that comes back to the page's own state every six cycles. The count
// keeps the page's words: only its first figure follows ("4 of 5 on" reads "3 of 5 on").
import { loop } from '../ui.js';

export default function init(root, opts = {}) {
  const rows = [...root.querySelectorAll('.ui-tg')];
  const sw = rows.map(r => r.querySelector('.ui-switch'));
  if (!rows.length || sw.some(s => !s)) return null;
  const count = root.querySelector('[data-tg-count]');
  const count0 = count ? count.textContent : '';
  const initial = sw.map(s => s.classList.contains('is-on'));
  const n = rows.length, a = Math.min(2, n - 1), c = Math.min(3, n - 1);
  const order = (opts.order || [a, 0, a, c, 0, c]).filter(i => i < n);
  const set = (i, on) => { sw[i].classList.toggle('is-on', on); sw[i].setAttribute('aria-checked', String(on)); };
  const ons = () => sw.filter(s => s.classList.contains('is-on')).length;
  const on0 = initial.filter(Boolean).length;
  const tally = () => { if (count) count.textContent = ons() === on0 ? count0 : count0.replace(/\d+/, String(ons())); };
  let k = 0;
  // one cycle (2.62 s): two switches flip in turn and the count follows; the second is held 0.38 s
  return loop(root, async api => {
    await api.wait(240);
    for (let n = 0; n < 2; n++) {
      const i = order[k++ % order.length];
      rows[i].classList.add('is-active');
      set(i, !sw[i].classList.contains('is-on'));
      tally();
      await api.wait(900);
      rows[i].classList.remove('is-active');
      await api.wait(n < 1 ? 200 : 380);
    }
  }, { still: () => { k = 0; rows.forEach(r => r.classList.remove('is-active')); initial.forEach((on, i) => set(i, on)); tally(); } });
}

ui/terminal-run/fragment.css:
/* terminal-run: a terminal pane. A command is typed at the prompt and run; a meter, one line per test
   file (a spinner while it runs, then its tick), a summary and a status line stream in below while the
   older run scrolls up. Monospace at the code fragment's size (13/20) in ink tints: the command and the
   status word the ink, output 80% ink, paths and timings muted. The accent is used once, on the
   meter's thin bar. The status line's check is the one green and the strongest mark: an oklch hue
   mixed with the ink (as .ui-avatar mixes its tones), so it follows any palette, light or dark; the
   per-file ticks stay ink (never a row of green checks). */
.ui-term {
  --t-ok: color-mix(in oklab, oklch(0.63 0.15 150) 84%, var(--u-ink));
  width: 440px; overflow: hidden;
  container: ui-term / inline-size;
}
.ui-term__head { display: flex; align-items: center; gap: 10px; height: 40px; padding: 0 12px 0 14px; border-bottom: 1px solid var(--u-line); background: var(--u-fill); min-width: 0; }
.ui-term__title { min-width: 0; margin-left: 4px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 13px; font-weight: 500; line-height: 16px; }
.ui-term__branch { font-family: var(--ui-mono, ui-monospace, monospace); font-weight: 400; }

/* the screen: its height is the finished picture's; while a run streams in it is held at that height
   and the track scrolls up under it, a whole 20px row at a time (every line, the blank one too, is one
   row, so the track never leaves the row grid). A line leaving the top fades out whole (is-gone) as
   it scrolls; the 12px mask only softens its passage through the track's own top padding, so no line
   ever rests half-cut under the header's rule */
.ui-term__screen {
  position: relative; overflow: hidden;
  -webkit-mask: linear-gradient(to bottom, transparent, #000 12px); mask: linear-gradient(to bottom, transparent, #000 12px);
}
.ui-term__track {
  position: relative; padding: 12px 0;
  font: 13px/20px var(--ui-mono, ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace);
  color: var(--u-text-2); letter-spacing: 0; font-feature-settings: normal;
  transition: transform 120ms var(--u-ease);
}
/* every line is one row: it ellipsizes on a narrow pane, never wraps */
.ui-term__ln { display: flex; align-items: center; gap: 10px; height: 20px; padding: 0 16px; min-width: 0; white-space: pre; transition: opacity 120ms var(--u-ease); }
.ui-term__ln > * { flex: none; min-width: 0; overflow: hidden; text-overflow: ellipsis; }
.ui-term__ln.is-gone { opacity: 0; }

/* the prompt: the repo's parent folder goes first on a narrow pane, so the prompt still names it */
.ui-term__cmd { gap: 0; }
.ui-term__cwd { margin-right: 8px; color: var(--u-muted); }
.ui-term__sig { margin-right: 8px; color: var(--u-muted); }
.ui-term__typed { flex: 0 1 auto; color: var(--u-ink); font-weight: 500; }
.ui-term__caret { display: block; width: 7px; height: 15px; margin-left: 1px; border-radius: 1px; background: var(--u-ink); animation: ui-term-caret 1s steps(1) infinite; }
/* typing, paused or off screen: a solid caret (a paused blink could stop in its hidden half) */
.ui-term.is-typing .ui-term__caret, .is-ui-paused .ui-term__caret { animation: none; }
.ui-term__cmd.is-ran .ui-term__caret { display: none; }
@keyframes ui-term-caret { 50% { opacity: 0; } }

/* the meter: its thin bar is the accent touch, quieter than the status check; the count's first
   figure follows the files */
.ui-term__bar { display: block; width: 96px; height: 3px; border-radius: 2px; background: var(--u-fill-3); overflow: hidden; }
.ui-term__bar i { display: block; height: 100%; background: var(--u-accent); transform-origin: left center; transform: scaleX(var(--p, 1)); transition: transform 180ms var(--u-ease); }
.ui-term__count { color: var(--u-text-2); }

/* a file's line: tick (the kit's .ui-spin while the file runs), path, count, time */
.ui-term__tick { width: 14px; height: 14px; fill: none; stroke: var(--u-muted); stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
.ui-term__wait { display: grid; place-items: center; width: 14px; height: 14px; color: var(--u-text-2); }
.ui-term__wait .ui-spin { width: 12px; height: 12px; border-width: 1.75px; animation-duration: 1s; }
/* the path takes up to 28 characters, so on a card-size pane the count and time stay beside it */
.ui-term__path { flex: 0 1 28ch; color: var(--u-text-2); }
.ui-term__n { color: var(--u-muted); }
.ui-term__t { width: 48px; text-align: right; color: var(--u-muted); }

/* the summary, a blank row above it (one row, so the track stays on the 20px grid) */
.ui-term__key { width: 88px; color: var(--u-muted); }
.ui-term__val { color: var(--u-ink); }
.ui-term__dim { flex: 0 1 auto; color: var(--u-muted); }

/* the status: a green check, the word in ink, the duration */
.ui-term__done { gap: 8px; }
.ui-term__done b { font-weight: 500; color: var(--u-ink); }
.ui-term__ok { display: grid; place-items: center; width: 16px; height: 16px; border-radius: 50%; background: var(--t-ok); color: var(--u-bg); overflow: visible; }
.ui-term__ok svg { width: 12px; height: 12px; fill: none; stroke: currentColor; stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }

/* a line arriving in a run (the script marks it is-new): a short rise; a file's tick and the status
   check settle in. Nothing here runs in the finished picture, held, or under reduced motion (base.css) */
.ui-term__ln.is-new { animation: ui-term-in 140ms var(--u-ease) 110ms backwards; }
.ui-term__ln.is-new .ui-term__ok { animation: ui-term-pop 240ms var(--u-ease) 110ms both; }
.ui-term__tick.is-new { animation: ui-term-pop 200ms var(--u-ease) both; }
@keyframes ui-term-in { from { opacity: 0; transform: translateY(4px); } }
@keyframes ui-term-pop { from { opacity: 0; transform: scale(0.6); } }

/* narrow: the pane's own width decides (a container query), so a .fit wrapper or a phone panel never
   slices a column: the test counts go first, then the branch and the repo's parent folder
   (the prompt reads ~/api) */
@container ui-term (max-width: 379px) {
  .ui-term .ui-term__n { display: none; }
  .ui-term .ui-term__bar { width: 80px; }
}
@container ui-term (max-width: 299px) {
  .ui-term .ui-term__branch, .ui-term .ui-term__up { display: none; }
  .ui-term .ui-term__t { width: 44px; }
  .ui-term .ui-term__path { flex: 1 1 0; }
  .ui-term .ui-term__ln { padding: 0 12px; }
  .ui-term .ui-term__key { width: 80px; }
}
/* phone: the pane takes the panel's width (cards.css); the queries above lay it out */
@media (max-width: 639px) { .ui-term { width: 100%; } }

ui/terminal-run/fragment.js:
// terminal-run: one run per cycle (about 3.1 s). The finished picture is the markup as written: a
// command that ran, its output, the status line and a fresh prompt with the caret. A cycle types the
// command again at that fresh prompt, character by character, and runs it: the output lines stream in
// below one by one. Each file's line arrives running (the kit's .ui-spin where its tick goes), then
// its tick settles and the meter fills a step (its count's first figure follows); the summary and the
// status line with its green check follow, then a fresh prompt. The screen keeps its height and the
// older run scrolls up under it a whole row at a time, each line leaving the top fading out whole, so
// the cycle ends on exactly the finished picture and the next one starts from it without a jump; the
// window is never empty. Every word is the page's own: the command is [data-term-cmd] as written (or
// opts.cmd), the lines are the [data-term-out] lines as written (cloned in order), and only the
// meter's first figure changes. A phone and a page's still fragments are held by ui.plan, as for
// every fragment.
import { loop } from '../ui.js';

export default function init(root, opts = {}) {
  const screen = root.querySelector('[data-term-screen]');
  const track = root.querySelector('[data-term-track]');
  const cmd = root.querySelector('[data-term-cmd]');
  const next = root.querySelector('[data-term-next]');
  const outs = [...root.querySelectorAll('[data-term-out]')];
  const typed = next && next.querySelector('.ui-term__typed');
  if (!screen || !track || !cmd || !next || !typed || !outs.length) return null;
  // opts.cmd replaces the command as written, so the first prompt and the typed one always agree
  if (typeof opts.cmd === 'string' && opts.cmd) cmd.textContent = opts.cmd;
  const text = cmd.textContent;
  // the fresh prompt as written (empty, its caret on), for the end of each run
  const fresh = next.cloneNode(true);
  fresh.removeAttribute('data-term-next');

  // the meter: its bar at --p (0..1) and its count's first figure, the words kept as written
  const steps = outs.filter(o => o.hasAttribute('data-term-step')).length || 1;
  const meter = (el, k) => {
    const bar = el.querySelector('.ui-term__bar');
    if (bar) bar.style.setProperty('--p', String(k / steps));
    const c = el.querySelector('[data-term-count]');
    if (c) {
      if (c.dataset.termText == null) c.dataset.termText = c.textContent;
      c.textContent = c.dataset.termText.replace(/\d+/, String(k));
    }
  };

  // scroll by whole 20px rows (every line is one row) and fade out whole each line that leaves the top
  const ROW = 20;
  const pad = () => parseFloat(getComputedStyle(track).paddingTop) || 0;
  let added = [];
  const scroll = () => {
    const over = Math.max(0, track.offsetHeight - screen.clientHeight);
    const dy = Math.max(0, Math.ceil((over - 2) / ROW)) * ROW;
    track.style.transform = dy ? `translateY(${-dy}px)` : '';
    const top = dy + pad();
    for (const ln of track.children) ln.classList.toggle('is-gone', ln.offsetTop < top - 1);
  };
  const add = el => {
    el.classList.add('is-new');
    el.classList.remove('is-gone');
    el.removeAttribute('data-term-out');
    el.setAttribute('aria-hidden', 'true');
    track.append(el);
    added.push(el);
    scroll();
  };
  // a file's line arrives running: the kit's spinner where its tick goes
  const running = el => {
    const tick = el.querySelector('.ui-term__tick');
    if (!tick) return () => {};
    const wait = document.createElement('span');
    wait.className = 'ui-term__wait';
    wait.innerHTML = '<i class="ui-spin"></i>';
    tick.replaceWith(wait);
    return () => { tick.classList.add('is-new'); wait.replaceWith(tick); };
  };
  // back to the markup as written: no copies, no scroll, no faded line, the fresh prompt empty with
  // its caret; nothing transitions on the way back
  const reset = () => {
    added.forEach(el => el.remove());
    added = [];
    const gone = [...track.querySelectorAll('.is-gone')];
    gone.forEach(el => { el.style.transition = 'none'; el.classList.remove('is-gone'); });
    track.style.transition = 'none';
    track.style.transform = '';
    screen.style.height = '';
    typed.textContent = '';
    root.classList.remove('is-typing');
    next.classList.remove('is-ran');
    void track.offsetHeight;
    track.style.transition = '';
    gone.forEach(el => { el.style.transition = ''; });
  };

  // one cycle (about 3.1 s): 0.16 s on the prompt, the command typed in about 0.8 s (50 to 80 ms a
  // character, 12 to 20 characters a second), Enter, the meter and four file lines in 1.1 s (each: the
  // scroll, 0.15 s running with a spinner, then its tick), the summary and the status in 0.45 s, the
  // fresh prompt held 0.4 s (about 13% of the cycle)
  const per = Math.max(50, Math.min(80, 800 / Math.max(1, text.length)));
  return loop(root, async api => {
    reset();
    screen.style.height = `${screen.offsetHeight}px`;
    await api.wait(160);
    root.classList.add('is-typing');
    // typed by the cycle's clock, a tween of the length the characters take: a slow frame skips a character
    // instead of stretching the cycle
    let shown = 0;
    await api.tween(Math.round(per * text.length), k => {
      const n = Math.min(text.length, Math.ceil(k * text.length));
      if (n !== shown) { shown = n; typed.textContent = text.slice(0, n); }
    }, k => k);
    root.classList.remove('is-typing');
    await api.wait(100);
    next.classList.add('is-ran');
    let bar = null, k = 0;
    for (const o of outs) {
      const c = o.cloneNode(true);
      if (o.hasAttribute('data-term-meter')) { bar = c; meter(c, 0); }
      if (o.hasAttribute('data-term-step')) {
        const finish = running(c);
        add(c);
        await api.wait(80);      // the scroll, then the row arrives
        await api.wait(150);     // running: a spinner long enough to read
        finish();
        if (bar) meter(bar, ++k);
        await api.wait(30);
      } else {
        add(c);
        // the blank row comes with the line after it
        if (c.textContent.trim()) await api.wait(o.hasAttribute('data-term-done') ? 260 : 100);
      }
    }
    add(fresh.cloneNode(true));
    await api.wait(400);
  }, { still: reset });
}

ui/stat/fragment.css:
/* stat: one number with its change and a bar chart whose bars rise to the new values.
   .is-window (or opts.window) cuts the bars out of the fragment, so the effect ground under the panel
   shows through them: the effect becomes the data, not the backdrop.
   .is-fill (or opts.fill) lets the chart take whatever height the placement gives the fragment, so the
   bars can run off the panel's bottom edge on purpose. */
.ui-stat { width: 420px; overflow: hidden; }
.ui-stat__head { padding: 16px 16px 4px; }
.ui-stat__top { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
