.ui-stat__range { display: inline-flex; align-items: center; gap: 4px; height: 26px; padding: 0 6px 0 10px; border-radius: 7px; font-size: 13px; color: var(--u-muted); white-space: nowrap; box-shadow: inset 0 0 0 1px var(--u-line-2); }
.ui-stat__range .ui-icon { width: 14px; height: 14px; }
.ui-stat__line { display: flex; align-items: center; gap: 10px; margin-top: 10px; flex-wrap: wrap; }
.ui-stat__num { font-size: 36px; line-height: 40px; font-weight: 600; letter-spacing: -0.035em; font-variant-numeric: tabular-nums; }
/* the change is a quiet ink chip: an accent here would read as an alarm, not as good news */
.ui-stat__delta { color: var(--u-ink); }
.ui-stat__delta svg { width: 11px; height: 11px; margin: 0 -1px 0 -2px; }
.ui-stat__sub { font-size: 13px; line-height: 16px; color: var(--u-muted); }
