ui/cursor/fragment.js:
// cursor: one cycle (about 3.4 s): the pointer glides in, clicks the main button (a ring, a press), a
// short spin, then done; it drifts off and the dialog rests on its finished picture (the done state).
// The words for the busy and done states are the page's own, written beside the text they replace:
// data-busy and data-done on the button, data-done on the state chip and on the line under the item
// (or opts.busy, opts.done, opts.state, opts.sub). Without them a text stays as written.
import { loop, POINTER_SVG } from '../ui.js';

export default function init(root, opts = {}) {
  const btn = root.querySelector('[data-cur-btn]'), label = root.querySelector('[data-cur-label]');
  if (!btn) return null;
  const state = root.querySelector('[data-cur-state]'), sub = root.querySelector('[data-cur-sub]');
  const two = (el, a, b) => {
    const idle = el ? el.textContent : '';
    return { idle, busy: a != null ? a : idle, done: b != null ? b : idle };
  };
  const words = {
    label: two(label, opts.busy ?? btn.dataset.busy, opts.done ?? btn.dataset.done),
    state: two(state, null, opts.state ?? state?.dataset.done),
    sub: two(sub, null, opts.sub ?? sub?.dataset.done),
  };
  const text = (el, s) => { if (el && el.textContent !== s) el.textContent = s; };
  const pointer = document.createElement('span');
  pointer.className = 'ui-pointer';
  pointer.innerHTML = POINTER_SVG;
  pointer.style.opacity = '0';
  const ring = document.createElement('span');
  ring.className = 'ui-ring';
  root.append(ring, pointer);
  const at = (x, y, instant) => {
    if (instant) pointer.style.transition = 'none';
    pointer.style.transform = `translate(${x}px, ${y}px)`;
    if (instant) { pointer.getBoundingClientRect(); pointer.style.transition = ''; }
  };
  const target = () => {
    const r = root.getBoundingClientRect(), b = btn.getBoundingClientRect();
    return [b.left - r.left + b.width * 0.5, b.top - r.top + b.height * 0.55];
  };
  function reset() {
    root.classList.remove('is-live');
    btn.classList.remove('is-busy', 'is-done');
    text(label, words.label.idle); text(state, words.state.idle); text(sub, words.sub.idle);
  }
  function done() {
    btn.classList.remove('is-busy');
    btn.classList.add('is-done');
    text(label, words.label.done); text(state, words.state.done); text(sub, words.sub.done);
    root.classList.add('is-live');
  }
  return loop(root, async api => {
    reset();
    const [tx, ty] = target();
    pointer.style.opacity = '0';
    at(tx - 150, ty + 80, true);
    await api.wait(300);
    pointer.style.opacity = '1';
    at(tx - 4, ty - 2);
    await api.wait(1000);
    pointer.classList.add('is-down');
    btn.classList.add('is-pressed');
    ring.style.setProperty('--at', `translate(${tx - 4}px, ${ty - 2}px)`);
    ring.classList.remove('is-on'); void ring.offsetWidth; ring.classList.add('is-on');
    await api.wait(140);
    pointer.classList.remove('is-down');
    btn.classList.remove('is-pressed');
    btn.classList.add('is-busy');
    text(label, words.label.busy);
    await api.wait(620);
    done();
    await api.wait(300);
    at(tx + 50, ty + 80);
    pointer.style.opacity = '0';
    await api.wait(400);
  }, { still: () => { pointer.style.opacity = '0'; pointer.classList.remove('is-down'); done(); } });
}

ui/code/fragment.css:
/* code: an editor pane with one highlighted line and a short note about it. The tokens are ink tints
   (keywords the ink, names a step lighter, numbers and comments muted); the accent is used once,
   on the marked line (its bar and a faint wash) */
.ui-code { width: 440px; overflow: hidden; }
.ui-code__tabs { display: flex; align-items: center; gap: 2px; height: 40px; padding: 0 12px 0 8px; border-bottom: 1px solid var(--u-line); background: var(--u-fill); }
.ui-code__tab { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border-radius: var(--u-r3); font-size: 13px; line-height: 16px; color: var(--u-muted); }
.ui-code__tab.is-on { background: var(--u-bg); color: var(--u-ink); box-shadow: 0 0 0 1px var(--u-line), 0 1px 2px rgb(0 0 0 / 0.06); }
.ui-code__lang { font: 600 13px/1 var(--ui-mono, ui-monospace, monospace); font-style: normal; padding: 2px 4px; border-radius: 3px; background: var(--u-fill-2); color: var(--u-muted); box-shadow: inset 0 0 0 1px var(--u-line); }
.ui-code__pre { margin: 0; padding: 12px 0; font: 13px/20px var(--ui-mono, ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace); color: var(--u-ink); white-space: pre; overflow: hidden; }
.ui-code__pre code { display: block; font: inherit; white-space: normal; }
.ui-code__ln { position: relative; display: block; padding: 0 16px 0 48px; white-space: pre; transition: background-color 300ms var(--u-ease); }
.ui-code__ln::before { content: attr(data-n); position: absolute; left: 0; width: 32px; text-align: right; color: var(--u-soft); }
.ui-code__ln::after { content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 2px; background: var(--u-accent); opacity: 0; transition: opacity 300ms var(--u-ease); }
.ui-code__ln.is-mark { background: color-mix(in oklab, var(--u-accent) 9%, transparent); }
.ui-code__ln.is-mark::after { opacity: 1; }
.ui-code__ln.is-mark::before { color: var(--u-ink); }
.ui-code .k { color: var(--u-ink); font-weight: 500; }
.ui-code .f { color: color-mix(in oklab, var(--u-ink) 88%, var(--u-bg)); }
.ui-code__pre { color: color-mix(in oklab, var(--u-ink) 68%, var(--u-bg)); }
.ui-code .n { color: var(--u-muted); }
.ui-code .c { color: var(--u-muted); font-style: italic; }
.ui-code__hint {
  display: flex; align-items: center; gap: 8px; height: 40px; padding: 0 16px; border-top: 1px solid var(--u-line);
  font-size: 13px; line-height: 16px; color: var(--u-muted); transition: opacity 240ms var(--u-ease);
}
.ui-code__hint .ui-dot { width: 6px; height: 6px; background: var(--u-ink); }
.ui-code__hint.is-hidden { opacity: 0; }
@media (max-width: 440px) { .ui-code { width: 100%; } .ui-code__pre { font-size: 13px; } }

ui/code/fragment.js:
// code: one change per cycle (about 3 s): the note below goes, the highlight moves to the next changed
// line, the note names that change. The changes are the page's own: the line marked is-mark with the
// note as written in the markup comes first, then every other line that carries data-note="..." (or
// opts.steps [{line, text}]), so the note never shows words the page did not write. The chip is left
// as written.
import { loop } from '../ui.js';

export default function init(root, opts = {}) {
  const lines = [...root.querySelectorAll('.ui-code__ln')];
  const hint = root.querySelector('[data-code-hint]'), text = root.querySelector('[data-code-text]');
  if (!lines.length || !hint || !text) return null;
  const first = lines.find(l => l.classList.contains('is-mark')) || lines.find(l => l.dataset.note) || lines[0];
  const steps = opts.steps || [
    { line: +first.dataset.n, text: text.textContent },
    ...lines.filter(l => l !== first && l.dataset.note).map(l => ({ line: +l.dataset.n, text: l.dataset.note })),
  ];
  const mark = n => lines.forEach(l => l.classList.toggle('is-mark', +l.dataset.n === n));
  const put = s => { mark(s.line); if (text.textContent !== s.text) text.textContent = s.text; };
  let k = 0;
  // one cycle (2.7 s): the highlight moves through three changed lines, the note naming each; the
  // last is held 0.4 s
  return loop(root, async api => {
    for (let n = 0; n < 3; n++) {
      const s = steps[++k % steps.length];
      hint.classList.add('is-hidden');
      lines.forEach(l => l.classList.remove('is-mark'));
      await api.wait(260);
      put(s);
      hint.classList.remove('is-hidden');
      await api.wait(n < 2 ? 760 : 400);
    }
  }, { still: () => { k = 0; put(steps[0]); hint.classList.remove('is-hidden'); } });
}

