const GL_MAX = 4;
export const glBudget = {
  get max() { return (HAS_DOM && window.__tpGlMax) || GL_MAX; },
  get held() { return (HAS_DOM && window.__tpGl) || 0; },
  take() { if (!HAS_DOM) return false; const n = window.__tpGl || 0; if (n >= glBudget.max) return false; window.__tpGl = n + 1; return true; },
  free() { if (!HAS_DOM) return; window.__tpGl = Math.max(0, (window.__tpGl || 0) - 1); },
};
export function gl(canvas, frag, { alpha = true, premultipliedAlpha = true, scale = 1 } = {}) {
  const bad = glslCheck(frag);
  if (bad) { console.warn('scenes: shader refused: ' + bad); return null; }
  if (!glBudget.take()) { console.warn('scenes: the page holds its 4 WebGL contexts; the scene shows its still'); return null; }
  let g = null;
  try { g = canvas.getContext('webgl', { alpha, premultipliedAlpha, antialias: false, depth: false, stencil: false, preserveDrawingBuffer: false, powerPreference: 'low-power' }); } catch { g = null; }
  if (!g) { glBudget.free(); return null; }
  const sh = (type, src) => { const s = g.createShader(type); g.shaderSource(s, src); g.compileShader(s); if (!g.getShaderParameter(s, g.COMPILE_STATUS)) { console.warn('scenes: shader failed: ' + g.getShaderInfoLog(s)); return null; } return s; };
  const drop = () => { try { const x = g.getExtension('WEBGL_lose_context'); x && x.loseContext(); } catch { /* gone */ } glBudget.free(); return null; };
  const vs = sh(g.VERTEX_SHADER, VERT), fs = sh(g.FRAGMENT_SHADER, frag);
  if (!vs || !fs) return drop();
  const prog = g.createProgram(); g.attachShader(prog, vs); g.attachShader(prog, fs); g.linkProgram(prog);
  if (!g.getProgramParameter(prog, g.LINK_STATUS)) { console.warn('scenes: program failed: ' + g.getProgramInfoLog(prog)); return drop(); }
  g.useProgram(prog);
  const buf = g.createBuffer(); g.bindBuffer(g.ARRAY_BUFFER, buf);
  g.bufferData(g.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), g.STATIC_DRAW);
  const loc = g.getAttribLocation(prog, 'a_p'); g.enableVertexAttribArray(loc); g.vertexAttribPointer(loc, 2, g.FLOAT, false, 0, 0);
  const u = {}; const U = n => (u[n] ??= g.getUniformLocation(prog, n));
  const t0 = performance.now();
  let lost = false;
  canvas.addEventListener('webglcontextlost', e => { e.preventDefault(); lost = true; });
  const api = {
    get lost() { return lost; },
    resize(w = canvas.clientWidth, h = canvas.clientHeight) {
      const W = Math.max(1, Math.round(w * scale)), H = Math.max(1, Math.round(h * scale));
      if (canvas.width !== W || canvas.height !== H) { canvas.width = W; canvas.height = H; }
      g.viewport(0, 0, W, H);
    },
    draw(uni = {}) {
      if (lost) return false;
      api.resize();
      g.uniform2f(U('u_res'), canvas.width, canvas.height);
      g.uniform1f(U('u_time'), (performance.now() - t0) / 1000);
      for (const [k, v] of Object.entries(uni)) {
        const l = U(k); if (l == null) continue;
        if (typeof v === 'number') g.uniform1f(l, v);
        else if (v.length === 2) g.uniform2f(l, v[0], v[1]);
        else if (v.length === 3) g.uniform3f(l, v[0], v[1], v[2]);
        else if (v.length === 4) g.uniform4f(l, v[0], v[1], v[2], v[3]);
      }
      g.drawArrays(g.TRIANGLES, 0, 3);
      return true;
    },
    destroy() { if (lost) return; try { const x = g.getExtension('WEBGL_lose_context'); x && x.loseContext(); } catch { /* gone */ } lost = true; glBudget.free(); },
  };
  return api;
}

scenes/print.js:
/*
  scenes/print.js - an object render (assets/objects/print-*) driven by a scene. The scene moves the
  host by transform and turns the object by its scroll: turnTo(deg) sets the rest angle and draws that
  pose. The object is mounted only while the scene is live and near the screen (wake()), and destroyed
  when the scene is far, at rest or gone (sleep()): one WebGL context, counted in the page's shared
  budget (window.__tpGl, at most 4 on a page) by print3d's pool, which refuses it when the page is full (the still stays). Under prefers-reduced-motion, on a phone
  plan that rests, without WebGL or when the shader fails nothing is mounted: the still picture the
  markup carries under the host (an <img> made with assets/scenes/_demo/shoot.mjs make) is the finished composition.
    import { attachPrint } from '../print.js';
    const obj = attachPrint(host, { object: 'print-globe', effect: 'render', params: {...} });
    obj.wake(); obj.turnTo(90); obj.sleep(); obj.destroy();
*/
import { reduced } from './lib.js';

const OBJECTS = new URL('../objects/', import.meta.url);

export function attachPrint(host, { object, effect, params = {}, palette } = {}) {
  let print = null, last = 0, dead = false, awake = false, loading = null;
  const mod = () => (loading ??= import(new URL(`${object}/object.js`, OBJECTS).href).catch(e => { console.warn('scenes: no object', object, e); host.classList.add('is-failed'); return null; }));
  function turnTo(deg, force) {
    if (!print) { last = deg; return; }
    if (!force && Math.abs(deg - last) < 0.8) return;
    last = deg;
    const a = ((deg + 180) % 360 + 360) % 360 - 180;
    try { print.set({ angle: a }); print.pose && print.pose({ t: 0 }); } catch (e) { /* the object draws its fallback */ }
  }
  async function wake() {
    if (dead || awake || reduced() || !host.isConnected) return;
    awake = true;
    const m = await mod();
    if (!m || dead || !awake) return;
    const p = { transparent: 1, turn: 0, interactive: 0, shadow: 0.55, size: 0.96, angle: 0, ...(effect ? { effect } : {}), ...params };
    try { print = m.default.mount(host, { place: 'none', params: p, palette }); host.classList.add('is-awake'); turnTo(last, true); }
    catch (e) { console.warn('scenes: object failed', object, e); host.classList.add('is-failed'); awake = false; }
  }
  function sleep() {
    awake = false;
    if (print) { try { print.destroy(); } catch (_) { /* gone */ } print = null; host.classList.remove('is-awake'); }
  }
  return {
    wake, sleep, turnTo,
    get print() { return print; },
    get awake() { return !!print; },
    destroy() { dead = true; sleep(); },
  };
}

scenes/scenes.css:
/* scenes.css - the held stage every big scene runs on (taste-skill, references/scenes.md). The loader links
   it; a page never writes its own. A scene section holds one stage as its first child. While the scene is
   live the section is (--sc-hold + 1) screens tall and the stage sticks for --sc-hold screens; at rest
   (reduced motion, a small screen, no script, a failed module) the stage is an ordinary block showing the
   finished composition. */
.sc { position: relative; }
.sc > * { position: relative; }
/* the page rhythm (system.css) holds at rest: the section keeps its --h screens (the page writes style="--h: 1", or 2
   when the finished composition needs it) and its --padt / --padb, like every other section; the stage adds no
   block padding or minimum height of its own, so the composition sits where any section's words sit. Live, the
   section is (hold + 1) screens with no padding, so the stage sticks flush; hold 1 makes it exactly two. */
main > .sc:not(.is-live) > .sc__stage { padding-block: 0; min-height: 0; }
/* a finished composition taller than its screens grows its section instead of running over the next one (the page
   rhythm still sets the least: --h screens), so a too-tall rest is a screen-height finding, never an overlap */
@media (max-width: 639px) { main > .sc:not(.is-live) { height: auto; min-height: calc(var(--hm, var(--h, 1)) * 100lvh); } }
main > .sc:not(.is-live) { height: auto; min-height: calc(var(--h, 1) * 100vh); min-height: calc(var(--h, 1) * 100svh); }
/* the hold is whole screens, so the sections after the scene still start on a screen's edge (the page rhythm) */
/* a hero scene at rest (a phone, reduced motion) is the first section, under the fixed header: its words start
   --hgap under it and its content ends --hpadb above the fold, as the hero rule does */
main > .sc[data-big-scene]:first-child:not(.is-live) { padding-top: calc(var(--nav, var(--nav-h, 72px)) + var(--hgap, 40px)); padding-bottom: calc(var(--hpadb, 64px) + var(--bar, 0px)); }
.sc-js .sc.is-live, .sc-js main > .sc.is-live[data-big-scene] { height: calc((var(--sc-hold, 1) + 1) * 100vh); height: calc((var(--sc-hold, 1) + 1) * 100svh); min-height: 0; padding: 0; }
.sc-js .sc.is-live > :first-child {
  position: sticky; top: 0; height: 100vh; height: 100svh; overflow: clip;
  contain: layout paint;
}
/* the moment between the first paint and the mount: the stage waits, a screen tall, instead of showing the
   finished composition and jumping (no script: .sc-js is never set; a slow module: .sc-safe shows it) */
.sc-js:not(.sc-safe) .sc[data-big-scene]:not(.is-live):not(.is-rest) { min-height: 100vh; min-height: 100svh; }
.sc-js:not(.sc-safe) .sc[data-big-scene]:not(.is-live):not(.is-rest) > .sc__stage { visibility: hidden; }
/* parts only the live scene draws */
.sc [data-sc-live] { display: none; }
.sc.is-live [data-sc-live] { display: block; }
/* parts only the finished composition shows */
.sc.is-live [data-sc-rest] { display: none; }
/* split text (lib.split): the inner span moves, the outer keeps the line */
.sc .sc-w, .sc .sc-c { display: inline-block; white-space: pre; }
.sc .sc-i { display: inline-block; will-change: transform; }
/* a plain skip link for keyboard users: live only, visible on focus */
.sc .sc__skip { position: absolute; left: 50%; bottom: 16px; transform: translateX(-50%); z-index: 20; font-size: var(--t-small, 14px);
  color: var(--ink); background: var(--bg); padding: 8px 14px; border-radius: 999px; border: 1px solid var(--line); opacity: 0; pointer-events: none; }
.sc.is-live .sc__skip:focus-visible { opacity: 1; pointer-events: auto; }
.sc:not(.is-live) .sc__skip { display: none; }
/* print: lib.js sends every scene to rest; this only keeps the geometry honest should a scene still be live */
@media print {
  .sc-js .sc.is-live, .sc-js main > .sc.is-live[data-big-scene] { height: auto; min-height: 0; }
  .sc-js .sc.is-live > :first-child { position: static; height: auto; overflow: visible; contain: none; }
}

scenes/scenes.js:
/*
  scenes.js - the loader for the page's one big scene (taste-skill, references/scenes.md).

    <link rel="stylesheet" href="assets/scenes/scenes.css"><link rel="stylesheet" href="assets/scenes/<id>/scene.css">   in <head>
    <section class="sc" data-big-scene="<id>" data-big-scene-opts='{"hold": 1}' style="--h: 1"><div class="sc__stage">…</div></section>
    <script type="module" src="assets/scenes/scenes.js"></script>
  style="--h" is the screens of the finished composition (the scene's meta.json restH: 1, or 2 for the three scenes whose rest is long);
  scenes.css keeps it and the page padding at rest, and the live section is hold + 1 = two screens (hold 1).

  It finds every [data-big-scene], links scenes.css and <id>/scene.css when the page has not (the page
  links both in <head>, so the finished composition is styled without script and nothing jumps), imports <id>/scene.js and calls its
  default export mount(root, opts, lib) -> { destroy }. The page keeps scrolling natively; every scene shows
  its finished composition under prefers-reduced-motion, on a screen too small for it, without script and
  when its module fails.

  Marks on <html>: .sc-js as soon as this runs (a scene's CSS may hide what it will reveal only under
  .sc-js, and .sc-safe arrives 2.5 s later as a fallback that shows everything); data-scenes-ready="n"
  when every scene is mounted (shoot scripts wait for it); data-scenes-over="n" when a page holds more
  than one (a fault: one big scene a page). The attribute is data-big-scene, not data-scene, which the
  print objects (assets/objects) use. One line in <head> sets .sc-js and the timer earlier:
    <script>document.documentElement.classList.add('sc-js');setTimeout(()=>document.documentElement.classList.add('sc-safe'),2500)</script>
*/
import * as lib from './lib.js';

const BASE = new URL('./', import.meta.url);
const html = document.documentElement;
const linked = new Map();
function css(href) {
  if (!linked.has(href)) {
    const done = [...document.querySelectorAll('link[rel="stylesheet"]')].some(l => l.href === href);
    linked.set(href, done ? Promise.resolve() : new Promise(res => {
      const l = document.createElement('link'); l.rel = 'stylesheet'; l.href = href;
      l.onload = l.onerror = () => res();
      document.head.appendChild(l);
    }));
  }
  return linked.get(href);
}

export async function mount(el) {
  const id = el.dataset.bigScene;
  if (!id || el.__scene) return el.__scene || null;
  let opts = {};
  try { opts = JSON.parse(el.dataset.bigSceneOpts || '{}'); } catch { console.warn(`scenes: bad data-big-scene-opts on ${id}`); }
  el.classList.add('sc');
  await Promise.all([css(new URL('scenes.css', BASE).href), css(new URL(`${id}/scene.css`, BASE).href)]);
  const mod = await import(new URL(`${id}/scene.js`, BASE).href);
  const api = mod.default(el, opts, lib) || {};
  el.__scene = api;
  el.dataset.bigSceneMounted = '1';
  return api;
}

export async function mountAll(root = document) {
  html.classList.add('sc-js');
  const els = [...root.querySelectorAll('[data-big-scene]')].filter(el => !el.parentElement?.closest('[data-big-scene]'));
  if (els.length > 1) { html.dataset.scenesOver = String(els.length); console.warn(`scenes: ${els.length} big scenes on one page (one a page)`); }
  await Promise.all(els.map(el => mount(el).catch(e => {
    console.warn(`scenes: ${el.dataset.bigScene} failed: ${e.message}`);
    el.dataset.bigSceneFailed = e.message;
    el.classList.add('sc', 'is-rest');
  })));
  // fonts and the scenes' pictures, then every live scene measured again (a fitted line, a card's place)
  await lib.ready();
  html.dataset.scenesReady = String(els.length);
  return els;
}

export function unmountAll(root = document) {
  root.querySelectorAll('[data-big-scene-mounted]').forEach(el => { try { el.__scene?.destroy?.(); } catch { /* gone */ } delete el.__scene; el.removeAttribute('data-big-scene-mounted'); });
}

html.classList.add('sc-js');
setTimeout(() => html.classList.add('sc-safe'), 2500);
const start = () => { if (!window.__scenesManual) mountAll(document); };
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, { once: true });
else start();

export default { mount, mountAll, unmountAll, lib };

