[data-big-scene="object-through-giant-type"] .ott__object { position: relative; }
[data-big-scene="object-through-giant-type"] .ott__still, [data-big-scene="object-through-giant-type"] .ott__img { display: block; width: 100%; aspect-ratio: 1; object-fit: contain; }
[data-big-scene="object-through-giant-type"] .ott__host { position: absolute; inset: 0; }
