/* letter-bar-floods-the-ground - at rest: the statement on the page ground, then the next
   statement on the inverse ground as a block under it. Live: the line on the held stage, scaled
   round its stem (the pivot glyph hidden under a solid column that scales sharp); the ground a
   full-width layer clipped to the column, the next statement inside it. */
[data-big-scene="letter-bar-floods-the-ground"] { background: var(--bg); color: var(--ink); }
[data-big-scene="letter-bar-floods-the-ground"] .lbf__line { margin: 0; font-family: var(--font-display); font-weight: var(--display-weight); letter-spacing: var(--display-tracking); font-size: var(--t-h1); line-height: 1; white-space: nowrap; }
