/* ---------- finished composition */
[data-big-scene="letter-bar-floods-the-ground"]:not(.is-live) > .sc__stage { display: grid; }
[data-big-scene="letter-bar-floods-the-ground"]:not(.is-live) .lbf__line { width: 100%; max-width: calc(var(--container) + 2 * var(--pad)); margin-inline: auto; padding: var(--section) var(--pad); white-space: normal; text-align: center; }
