[data-big-scene="letter-bar-floods-the-ground"]:not(.is-live) .lbf__next { width: 100%; max-width: var(--container); margin-inline: auto; text-align: center; display: grid; justify-items: center; }

/* ---------- the held stage */
[data-big-scene="letter-bar-floods-the-ground"].is-live > .sc__stage { display: grid; place-items: center; }
[data-big-scene="letter-bar-floods-the-ground"].is-live .lbf__line { grid-area: 1 / 1; position: relative; will-change: transform; }
[data-big-scene="letter-bar-floods-the-ground"].is-live .lbf__pivot { visibility: hidden; }     /* the solid column stands in its place */
