  font-size: var(--t-small); text-align: left; box-shadow: 0 30px 60px -30px rgb(0 0 0 / .35); }
.ux__bar { height: 42px; display: flex; align-items: center; gap: var(--s-3); padding: 0 var(--s-4); border-bottom: 1px solid var(--line); color: var(--muted); }
