const fromCols = (x, y, z) => [x[0], y[0], z[0], x[1], y[1], z[1], x[2], y[2], z[2]];
const I3 = [1, 0, 0, 0, 1, 0, 0, 0, 1];
function euler(r = [0, 0, 0]) {
  const [x, y, z] = r.map(v => (v || 0) * DEG);
