  /* motion groups: each turns about its pivot and axis, after its parent (rest pose = object space) */
  const groups = (spec.motion || []).map(g => ({ ...g, axisV: axisOf(g.axis || 'z') || [0, 0, 1] }));
  const gi = new Map(groups.map((g, i) => [g.id, i]));
