    for (const v of posed(cs, c, c.map(g => (g.rest || 0) * DEG))) for (let k = 0; k < 3; k++) { restLo[k] = Math.min(restLo[k], v[k]); restHi[k] = Math.max(restHi[k], v[k]); }
  }
