    const ang = `-(${f((g.rest || 0) * DEG)} + ${f((g.amp || 0) * DEG)} * sin(u_time * ${f((2 * Math.PI) / per)} + ${f(ph)}))`;
    code += `  vec3 g${i} = rotAx(${parent} - ${v3(P(g.pivot))}, ${v3(g.axisV)}, ${ang}) + ${v3(P(g.pivot))};\n`;
