    camera: { ...cam, target: height / 2 },
    turn,
    step: 'toggle',
    stepTime: 0.6,
    light: spec.light || [-0.42, 1.3, 0.72],
    steps: spec.steps || 190,
    shadowSteps: 56,
    exposure: spec.exposure || 1,
    floorReach: 0.09,
    params: {
