/*
  print-wheel - a road bicycle wheel: tyre with gum sidewalls, a box-section rim with its valve, a hub
  with two flanges and a quick-release skewer, and 24 radial spokes laced to alternate flanges, so the
  wheel is dished like the real thing when it turns edge-on.
  The wheel sways slowly through three-quarter views and rolls round its axle. Hover: the light
  follows the pointer and the wheel leans toward it. Click, Enter or focus: it spins up fast, and
  winds down again on the next click (or when focus leaves).
  The spokes print as wire in the ink on every paper (dark wire on light paper, bright on dark).
  Rendered: a black tread with tan gum sidewalls, an alloy rim, black spokes and a hub in the accent.
*/
import { definePrint } from '../_print-core/print3d.js';

const DEG = Math.PI / 180;

const glsl = /* glsl */ `
const vec3 HUB = vec3(0.0, 0.5, 0.0);           // the tyre (outer radius 0.496) stands on the floor
const float SECTOR = 6.28318530718 / 12.0;   // the angle between two spokes of one flange

// the 12 spokes of one flange: repeat round the axle so the nearest of them is the one evaluated
// (the flanges alternate, so each needs its own repetition or a ray skips a spoke seen at an angle)
float spokes(vec3 s, float off, float zf) {
  float a = atan(s.y, s.x) - off;
  float k = floor(a / SECTOR + 0.5);
  vec2 l = rot2(-(k * SECTOR + off)) * s.xy;
  // a print: never thinner than about half a texel at the wheel, so small frames draw whole spokes,
  // not dashes; the render: a 2 mm spoke, smoothed at its edges, never under about two thirds of a texel
  float sr = u_render > 0.5 ? max(0.0016, 2.0 * u_pix) : max(0.0031, 3.0 * u_pix);
  return sdCapsule(vec3(l, s.z), vec3(0.036, 0.0, zf), vec3(0.403, 0.0, 0.0), sr);
}

vec2 map(vec3 p) {
  vec3 q = p - HUB;
  // hub and skewer do not turn with the wheel (they are round anyway; the lever stays put)
  float hub = sdCyl(q.xzy, 0.019, 0.05, 0.006);
  vec3 fq = vec3(q.xy, abs(q.z) - 0.034);
  hub = min(hub, sdCyl(fq.xzy, 0.041, 0.0035, 0.002));
  float axle = sdCyl(q.xzy, 0.0055, 0.08, 0.002);
  // the quick-release: a polished cam on the skewer's end, the nut on the other, and the lever: a
  // flat blade that widens to a paddle and curves back toward the hub, as on a real skewer
  vec3 lq = q - vec3(0.0, 0.0, 0.086);
  axle = min(axle, sdCyl(lq.xzy, 0.0095, 0.0055, 0.002));
  axle = min(axle, sdCyl((q + vec3(0.0, 0.0, 0.084)).xzy, 0.0085, 0.0045, 0.002));
  vec2 ld = vec2(0.906, -0.423);                      // 25 degrees below the horizontal
  vec2 uv = vec2(dot(lq.xy, ld), dot(lq.xy, vec2(-ld.y, ld.x)));
  float along = clamp(uv.x, 0.0, 0.088);
  float bw = mix(0.0042, 0.0115, smoothstep(0.014, 0.072, along));
  float cross2 = sdRect(vec2(uv.y, lq.z - 0.0045 + 0.7 * along * along), vec2(bw, 0.0028), 0.0019);
  float ends = abs(uv.x - 0.044) - 0.044;
  float lever = min(max(cross2, ends), 0.0) + length(max(vec2(cross2, ends), 0.0)) - 0.0012;
  // the turning parts
  vec3 s = vec3(rot2(u_spin) * q.xy, q.z);
  float r = length(s.xy);
  float tyre = length(vec2(r - 0.462, s.z * 1.1)) - 0.034;
  float rim = sdRect(vec2(r - 0.414, s.z), vec2(0.019, 0.0105), 0.004);
  float valve = sdCapsule(s, vec3(0.0, 0.398, 0.0), vec3(0.0, 0.366, 0.0), 0.0055);
  // 24 radial spokes, laced to the two flanges in turn
  float sp = min(spokes(s, -SECTOR * 0.25, 0.034), spokes(s, SECTOR * 0.25, -0.034));
  vec2 res = vec2(tyre, 1.0);
  if (rim < res.x) res = vec2(rim, 2.0);
  if (sp < res.x) res = vec2(sp, 3.0);
  if (hub < res.x) res = vec2(hub, 4.0);
  if (axle < res.x) res = vec2(axle, 5.0);
  if (lever < res.x) res = vec2(lever, 6.0);
  if (valve < res.x) res = vec2(valve, 5.0);
  return res;
}

void surf(float id, vec3 p, vec3 n, inout Surf s) {
  vec3 q = p - HUB;
  float r = length(q.xy);
  s.coord = r;                                   // engraved: rings round the axle
  if (u_render > 0.5) {
    // the render: a black tread with tan gum sidewalls, a brushed alloy rim with a machined brake
    // track, black stainless spokes, the hub shell anodised in the accent, a polished skewer
    if (id < 1.5) {
      bool wall = r < 0.457 && abs(n.z) > 0.35;
      s.col = wall ? vec3(0.3, 0.16, 0.065) : vec3(0.018); s.gloss = wall ? 0.35 : 0.3; s.shine = wall ? 20.0 : 14.0;
    } else if (id < 2.5) {
      bool track = abs(n.z) > 0.8 && r > 0.398;
      s.col = track ? vec3(0.7, 0.7, 0.72) : vec3(0.55, 0.56, 0.58); s.metal = 1.0; s.gloss = 0.9; s.shine = track ? 30.0 : 55.0;
    } else if (id < 3.5) {
      s.col = vec3(0.03); s.metal = 0.6; s.gloss = 0.7; s.shine = 60.0;
    } else if (id < 4.5) {
      s.accent = 1.0; s.metal = 0.55; s.gloss = 0.85; s.shine = 60.0;
    } else if (id < 5.5) {
      s.col = vec3(0.75, 0.75, 0.76); s.metal = 1.0; s.gloss = 0.9; s.shine = 70.0;
    } else {
      s.col = vec3(0.8, 0.8, 0.81); s.metal = 1.0; s.gloss = 0.95; s.shine = 90.0;   // the lever: polished alloy, like the cam
    }
    return;
  }
  if (id < 1.5) {                                // tyre: black tread, gum sidewalls in the accent
    bool wall = r < 0.457 && abs(n.z) > 0.35;
    s.albedo = wall ? 0.7 : 0.13; s.gloss = wall ? 0.08 : 0.18; s.shine = 12.0;
    s.accent = wall ? 1.0 : 0.0;
  } else if (id < 2.5) {                         // rim: brushed alloy
    s.albedo = 0.82; s.gloss = 0.8; s.shine = 70.0;
  } else if (id < 3.5) {                         // spokes: wire, printed in the ink
    s.albedo = u_dark > 0.5 ? 1.0 : 0.04; s.emit = u_dark > 0.5 ? 0.45 : 0.0; s.gloss = 0.0;
    s.wire = 1.0;                                // whole lines in every print, never dashes
  } else if (id < 4.5) {                         // hub shell, polished
    s.albedo = 0.86; s.gloss = 0.9; s.shine = 80.0; s.coord = q.z * 1.6;
  } else {                                       // skewer, lever and valve
    s.albedo = 0.22; s.gloss = 0.7; s.shine = 60.0;
  }
}
`;

export default definePrint({
  id: 'print-wheel',
  name: 'Bicycle wheel',
  label: 'A road bicycle wheel turning on its axle',
  base: import.meta.url,
  glsl,
  pivot: [0, 0.5, 0],
  radius: 0.52,
  extent: [0.5, 0.52],
  camera: { elev: 12, dist: 6, target: 0.44 },
  turn: { mode: 'sway', amp: 30, period: 20 },
  step: 'toggle',
  stepTime: 1.4,
  light: [-0.36, 1.5, 0.75],
  steps: 160,
  shadowSteps: 48,
  press: 'Press to spin it up.',
  params: { effect: { default: 'render' }, angle: { default: -30 }, size: { default: 0.8 } },
  // card: cut by the bottom-left (the bottom-right corner stays clear for the pause button), and in a
  // panel about as tall as wide (a phone) less cut, so the thing still reads; tile: whole, low; hero:
  // right of the text, smaller and under it in a phone-shaped frame
  place: {
    card: { transparent: 1, size: 1.25, x: -0.25, y: -0.2, narrow: { size: 1.02, x: -0.2, y: -0.16 } },
    tile: { transparent: 1, size: 0.88, y: -0.05 },
    hero: { transparent: 1, size: 1.1, x: 0.22, y: -0.1, narrow: { size: 0.78, x: 0.1, y: -0.2 } },
  },
  // the wheel rolls on its axle: slowly at rest, faster while the step is on (at most about 220
  // degrees a second, under the 7.5 degrees a frame at which 24 spokes would strobe at 60 Hz)
  update(state, dt) {
    const e = state.step * state.step * (3 - 2 * state.step);
    return { spin: state.spin - dt * (18 + 200 * e) * Math.min(state.params.speed, 1.5) * DEG };
  },
});

objects/print-lamp/object.js:
/*
  print-lamp - a balanced-arm desk lamp, the classic design: a heavy stepped round base with a turret,
  a lower and an upper arm each of two parallel rods, two coil springs that carry the arm (hooked to
  a crossbar on the rods), knuckle joints with chrome caps, a domed shade with a vent cowl and a
  rolled rim, and its bulb. Base and shade in the accent; the rods, springs and joints in the ink.
  Rendered: clear-coated enamel in the accent, graphite rods, chrome springs and caps, a white inside.
  It sways slowly about its base, the profile always readable. Hover: the light follows the pointer
  and the lamp leans toward it. Click, Enter or focus: the lamp switches on: the bulb shows under the
  rim, the rim and the inside of the shade light up, and a pool of warm light falls on the desk in
  front of the base; click again to switch it off.
*/
import { definePrint } from '../_print-core/print3d.js';

const glsl = /* glsl */ `
const vec3 BASE = vec3(-0.08, 0.0, 0.0);
const vec3 P0 = vec3(-0.08, 0.098, 0.0);         // the base pivot, in the turret
const vec3 P1 = vec3(-0.262, 0.478, 0.0);        // elbow
const vec3 P2 = vec3(0.118, 0.698, 0.0);         // head joint
const vec3 SD = vec3(0.2465, -0.9200, 0.3048);   // the shade's axis: down, 15 degrees out and swivelled
                                                 // a little toward you, so you see into it when it is on
const vec3 SA = vec3(0.150, 0.664, 0.012);       // the shade's crown on that axis
const float SLEN = 0.17;                         // crown to rim along the axis
const float RIM = 0.122;                         // the rim's radius
const float ROD = 0.024;                         // half the gap between a pair of rods

// the shade in its own (radius, along the axis) plane: a domed crown, then a bell that rounds out at
// the shoulder and flares to a rolled rim, one smooth curve so the enamel shades evenly; the
// distance to the curve scaled by its slope
float shadeProfile(vec2 ra) {
  float rad = ra.x, ax = ra.y, d;
  if (ax < 0.0) d = (length(vec2(rad / 0.046, ax / 0.03)) - 1.0) * 0.03;
  else if (ax > SLEN) d = length(vec2(rad, ax) - vec2(RIM, SLEN));
  else {
    float t = ax / SLEN;
    float R = 0.046 + (RIM - 0.046) * (1.0 - pow(1.0 - t, 2.2));
    float dR = (RIM - 0.046) * 2.2 * pow(1.0 - t, 1.2) / SLEN;
    d = (rad - R) / sqrt(1.0 + dR * dR);
  }
  float shell = abs(d) - 0.0042;
  float rim = length(ra - vec2(RIM + 0.0015, SLEN + 0.002)) - 0.0072;
  // the vent cowl on the crown: a short drum
  vec2 cw = vec2(rad - 0.024, abs(ax + 0.036) - 0.011);
  float cowl = min(max(cw.x, cw.y), 0.0) + length(max(cw, 0.0)) - 0.003;
  return min(min(shell, rim), cowl);
}
vec2 shadeCoords(vec3 p) { vec3 v = p - SA; float ax = dot(v, SD); return vec2(length(v - SD * ax), ax); }

// a coil spring from a to b: rings of wire round the axis, one per pitch; where the rings would be
// finer than a few texels (a small frame) a smooth tube of the same girth, so it never shimmers
float coil(vec3 p, vec3 a, vec3 b, float rc, float wire, float pitch) {
  vec3 ab = b - a;
  float len = length(ab);
  vec3 ax = ab / len, pa = p - a;
  float u = dot(pa, ax);
  float rad = length(pa - ax * u);
  float k = clamp(floor(u / pitch + 0.5), 0.0, floor(len / pitch));
  float rings = length(vec2(rad - rc, u - k * pitch)) - wire;
  float tube = max(rad - rc - wire * 0.6, abs(u - 0.5 * len) - 0.5 * len);
  float sharp = smoothstep(2.5, 4.5, pitch / max(6.0 * u_pix, 1e-5));
  // the hooks at both ends: a short wire to its anchor
  float hooks = min(sdCapsule(p, a - ax * 0.012, a, wire * 1.1), sdCapsule(p, b, b + ax * 0.012, wire * 1.1));
  return min(mix(tube, rings, sharp), hooks);
}

vec2 map(vec3 p) {
  vec3 b = p - BASE;
  // the base: a heavy disc with a bevelled edge, a second step, and the turret the arm pivots in
  float base = min(sdCyl(b - vec3(0.0, 0.019, 0.0), 0.168, 0.019, 0.011), sdCyl(b - vec3(0.0, 0.046, 0.0), 0.108, 0.01, 0.007));
  float turret = sdRoundBox(p - vec3(P0.x, 0.074, 0.0), vec3(0.022, 0.024, 0.036), 0.007);
  vec3 pa = vec3(p.xy, abs(p.z));
  // never thinner than about half a texel, so a small frame (a phone's card) draws whole rods
  float rr = max(0.0052, 3.0 * u_pix);
  float rods = min(sdCapsule(pa, vec3(P0.xy, ROD), vec3(P1.xy, ROD), rr), sdCapsule(pa, vec3(P1.xy, ROD), vec3(P2.xy, ROD), rr));
  // the bracket from the head joint to the shade's crown
  rods = min(rods, sdCapsule(p, P2, SA - SD * 0.02, 0.0085));
  // two springs behind the lower arm, from the turret to a third of the way up
  vec3 dir = normalize(P1 - P0), side = vec3(-dir.y, dir.x, 0.0);
  vec3 s0 = P0 - side * 0.034 + dir * 0.02, s1 = P0 + (P1 - P0) * 0.44 - side * 0.03;
  float sA = coil(p, s0 + vec3(0.0, 0.0, 0.012), s1 + vec3(0.0, 0.0, 0.012), 0.0075, 0.0019, 0.0068);
  float sB = coil(p, s0 - vec3(0.0, 0.0, 0.012), s1 - vec3(0.0, 0.0, 0.012), 0.0075, 0.0019, 0.0068);
  // a print draws the pair as one band: two thin lines joined by their hooks printed as an outline
  float springs = u_render > 0.5 ? min(sA, sB) : smin(sA, sB, 0.018);
  // their lower hooks catch a lug that rises from the turret's top corner, so no spring ends in the air
  vec3 h0 = s0 - normalize(s1 - s0) * 0.012;
  vec3 lugTop = vec3(h0.xy, 0.012), lugFoot = vec3(P0.x + 0.013, P0.y - 0.014, 0.012);
  springs = min(springs, sdCapsule(pa, lugTop, lugFoot, 0.0036));
  // the springs' top hooks on a crossbar clamped across the two rods
  vec3 cl = P0 + (P1 - P0) * 0.47;
  rods = min(rods, sdCapsule(p, cl - vec3(0.0, 0.0, ROD), cl + vec3(0.0, 0.0, ROD), 0.0046));
  rods = min(rods, sdCapsule(pa, vec3(cl.xy, 0.012), vec3((s1 + dir * 0.012).xy, 0.012), 0.0032));
  // knuckles across the rods at the three joints, with a cap on the near end
  float joints = min(sdCyl((p - P0).xzy, 0.019, 0.038, 0.004), sdCyl((p - P1).xzy, 0.016, 0.034, 0.004));
  joints = min(joints, sdCyl((p - P2).xzy, 0.016, 0.034, 0.004));
  float caps = min(sdCyl((p - P1 - vec3(0.0, 0.0, 0.041)).xzy, 0.0125, 0.007, 0.003), sdCyl((p - P2 - vec3(0.0, 0.0, 0.041)).xzy, 0.0125, 0.007, 0.003));
  caps = min(caps, sdCyl((p - P0 - vec3(0.0, 0.0, 0.045)).xzy, 0.014, 0.007, 0.003));
  vec2 sc = shadeCoords(p);
  float shade = shadeProfile(sc);
  float bulb = length(p - (SA + SD * 0.128)) - 0.034;   // it shows a little under the rim
  vec2 res = vec2(base, 1.0);
  if (turret < res.x) res = vec2(turret, 3.0);
  if (rods < res.x) res = vec2(rods, 2.0);
  if (springs < res.x) res = vec2(springs, 6.0);
  if (joints < res.x) res = vec2(joints, 3.0);
  if (caps < res.x) res = vec2(caps, 8.0);
  if (shade < res.x) res = vec2(shade, 4.0);
  if (bulb < res.x) res = vec2(bulb, 5.0);
  return res;
}

void surf(float id, vec3 p, vec3 n, inout Surf s) {
  s.coord = p.y;
  vec2 sc = shadeCoords(p);
  if (u_render > 0.5) {
    // the render: base and shade in a clear-coated enamel in the accent, graphite rods, chrome springs
    // and caps, black knuckles, the inside of the shade white; on, the bulb and the inside glow
    if (id < 1.5) { s.accent = 1.0; s.gloss = 0.9; s.shine = 90.0; }
    else if (id < 2.5) { s.col = vec3(0.03, 0.032, 0.035); s.metal = 0.35; s.gloss = 0.75; s.shine = 60.0; }
    else if (id < 3.5) { s.col = vec3(0.022); s.metal = 0.2; s.gloss = 0.6; s.shine = 40.0; }
    else if (id < 4.5) {
      // outside: the enamel; inside (under the shell, facing the axis): matte white
      float R = sc.y < 0.0 ? 0.0 : 0.046 + (RIM - 0.046) * (1.0 - pow(1.0 - clamp(sc.y / SLEN, 0.0, 1.0), 2.2));
      bool inner = sc.y > 0.004 && sc.y < SLEN - 0.002 && sc.x < R - 0.0005;
      if (!inner) { s.accent = 1.0; s.gloss = 0.9; s.shine = 90.0; s.emit = u_step * 0.3 * smoothstep(SLEN - 0.01, SLEN + 0.004, sc.y); }
      else { s.col = vec3(0.8, 0.77, 0.7); s.gloss = 0.15; s.shine = 10.0; s.emit = u_step * 1.25; }
      if (sc.y < -0.02) { s.accent = 0.0; s.col = vec3(0.03); s.metal = 0.3; s.gloss = 0.6; s.shine = 40.0; s.emit = 0.0; }   // the cowl
    } else if (id < 5.5) { s.col = vec3(0.86, 0.85, 0.82); s.gloss = 0.5; s.shine = 30.0; s.emit = u_step * 2.4; }
    else { s.col = vec3(0.78, 0.78, 0.8); s.metal = 1.0; s.gloss = 0.95; s.shine = 80.0; }   // springs and caps: chrome
    return;
  }
  if (id < 1.5) {                                // base: enamelled, in the accent
    s.albedo = 0.72; s.gloss = 0.55; s.shine = 40.0; s.accent = 1.0;
    s.coord = length(p.xz - BASE.xz);
  } else if (id < 2.5 || (id > 5.5 && id < 7.5)) {   // rods and springs: printed as wire
    s.albedo = u_dark > 0.5 ? 0.95 : 0.2; s.gloss = 0.2; s.shine = 30.0;
    s.wire = 1.0;                                // a clean solid line in every print, never a chain of dots
  } else if (id < 3.5 || id > 7.5) {             // knuckles, turret and caps
    s.albedo = 0.3; s.gloss = 0.6; s.shine = 40.0;
  } else if (id < 4.5) {                         // shade: accent outside, white inside, lit when on
    float ax = sc.y;
    float R = ax < 0.0 ? 0.0 : 0.046 + (RIM - 0.046) * (1.0 - pow(1.0 - clamp(ax / SLEN, 0.0, 1.0), 2.2));
    bool outside = !(ax > 0.004 && ax < SLEN - 0.002 && sc.x < R - 0.0005);
    s.albedo = outside ? 0.74 : 0.92; s.gloss = outside ? 0.55 : 0.1; s.shine = 36.0;
    s.accent = outside ? 1.0 : 0.0;
    // on: the inside glows, and the rolled rim catches the light on the side you see
    float rim = smoothstep(SLEN - 0.012, SLEN + 0.002, ax);
    s.emit = u_step * (outside ? 0.75 * rim : 0.95);
    // the rim and the inside print as the paper; the shell, lit from inside, a little deeper
    // (on light paper that is the paper itself; on dark paper the light ink at full)
    if (u_step > 0.5 && (rim > 0.5 || !outside)) { s.accent = 0.0; if (u_dark > 0.5) s.lo = 0.9; else s.hi = 0.1; }
    else if (outside) s.lo = 0.5 * u_step * (1.0 - u_dark);
    s.coord = ax;
  } else {                                       // the bulb
    s.albedo = 0.9; s.gloss = 0.8; s.shine = 60.0;
    s.emit = u_step * 1.2;
    // on: the brightest thing in the print (the paper itself on light paper, full light ink on dark)
    s.lo = u_dark > 0.5 ? mix(0.18, 0.95, u_step) : 0.18 * (1.0 - u_step);
    s.hi = u_dark > 0.5 ? 1.0 : mix(0.5, 0.0, u_step);
  }
}

// the pool of light the lamp throws on the desk when it is on
#define FLOOR_EMIT
float floorEmit(vec3 w) {
  // a print leaves it out: printed in dots, a pool apart from the base reads as noise
  if (u_step < 0.001 || u_render < 0.5) return 0.0;
  vec3 p = u_rot * (w - u_pivot) + u_pivot;
  vec3 v = p - (SA + SD * 0.1);
  float d = length(v);
  float cone = smoothstep(0.55, 1.0, dot(v / d, SD));   // bright under the shade, fading out: no hard disc
  // the pool lies under the shade and ends a hand's width out, well inside any frame
  float reach = 1.0 - smoothstep(0.0, 0.26, length(p.xz - vec2(0.34, 0.19)));
  return 0.9 * u_step * cone * cone * reach * clamp(0.5 / (0.12 + d * d), 0.0, 1.0);
}

`;

export default definePrint({
  id: 'print-lamp',
  name: 'Desk lamp',
  label: 'A balanced-arm desk lamp; it switches on when chosen',
  base: import.meta.url,
  glsl,
  pivot: [0.02, 0.37, 0],
  radius: 0.5,
  extent: [0.34, 0.41],
  camera: { elev: 13, dist: 6, target: 0.37 },
  light: [-0.22, 1.45, 0.85],
  turn: { mode: 'sway', amp: 34, period: 22 },
  step: 'toggle',
  stepTime: 0.7,
  budget: 420000,
  press: 'Press to switch it on.',
  params: { effect: { default: 'render' }, angle: { default: 8 }, size: { default: 0.8 } },
  // card: whole but for the base's foot, cut by the panel's bottom edge (a lamp without its base reads
  // as a stray arm), the shade toward the top right, the bottom-right corner clear for the pause
  // button; in a panel about as tall as wide (a phone) a little smaller; tile: whole, low; hero: right
  // of the text, smaller and under it in a phone-shaped frame
  place: {
    card: { transparent: 1, size: 0.98, x: -0.1, y: -0.06, narrow: { size: 0.94, x: -0.04, y: -0.04 } },
    tile: { transparent: 1, size: 0.78, y: -0.01 },
    hero: { transparent: 1, size: 1.0, x: 0.22, y: -0.06, narrow: { size: 0.72, x: 0.1, y: -0.2 } },
  },
});

objects/print-globe/object.js:
/*
  print-globe - a desk globe: the Earth on its tilted axis (23.4 degrees), held at the poles by a half
  meridian band, on a turned stem and a stepped round base. The land is the real coastline, traced
  into a small map once per page; a blue or teal accent prints the sea, any other accent the land,
  and the stand prints in the ink. Rendered: parchment land, the sea in a blue accent or a deep ocean
  blue, a brass meridian and a walnut stand.
  The Earth turns slowly on its axis while the stand sways a little. Hover: the light follows the
  pointer and the globe leans toward it. Click, Enter or focus: a flick, the Earth spins up and runs
  down again, as a real globe does under a hand.
*/
import { definePrint } from '../_print-core/print3d.js';
import { LAND, LAKES } from './land.js';

const DEG = Math.PI / 180;

const glsl = /* glsl */ `
const vec3 GC = vec3(0.0, 0.6, 0.0);
const float GR = 0.29;
const vec3 AX = vec3(-0.3971, 0.9178, 0.0);     // the axis, tilted 23.4 degrees
const vec2 AXP = vec2(0.9178, 0.3971);           // across it, in the meridian's plane
const float TILT = 0.4084;

vec2 map(vec3 p) {
  vec3 q = p - GC;
  float earth = length(q) - GR;
  // the half meridian: a flat band round one side, through the poles and under the globe
  float ring = sdRect(vec2(length(q.xy) - 0.318, q.z), vec2(0.0042, 0.0115), 0.002);
  ring = max(ring, dot(q.xy, AXP));
  float pins = min(sdCapsule(q, AX * 0.27, AX * 0.334, 0.0042), sdCapsule(q, -AX * 0.27, -AX * 0.334, 0.0042));
  pins = min(pins, min(length(q - AX * 0.336), length(q + AX * 0.336)) - 0.009);
  // the stand: a stem with a turned knop, a stepped base
  float stem = sdCapsule(p, vec3(0.0, 0.05, 0.0), vec3(0.0, GC.y - 0.318, 0.0), 0.0105);
  vec3 kq = (p - vec3(0.0, 0.16, 0.0)) / vec3(1.0, 1.45, 1.0);
  stem = smin(stem, (length(kq) - 0.026) * 0.69, 0.012);
  float base = min(sdCyl(p - vec3(0.0, 0.018, 0.0), 0.15, 0.018, 0.008), sdCyl(p - vec3(0.0, 0.046, 0.0), 0.082, 0.011, 0.005));
  vec2 res = vec2(earth, 1.0);
  if (ring < res.x) res = vec2(ring, 2.0);
  if (pins < res.x) res = vec2(pins, 2.0);
  float st = min(stem, base);
  if (st < res.x) res = vec2(st, 3.0);
  return res;
}

void surf(float id, vec3 p, vec3 n, inout Surf s) {
  vec3 q = p - GC;
  if (id < 1.5) {
    // into the Earth's own frame: axis up, turned by the spin
    vec3 e = q;
    e.xy = rot2(-TILT) * e.xy;
    e.xz = rot2(u_spin) * e.xz;
    float lon = atan(e.x, e.z), lat = asin(clamp(e.y / GR, -1.0, 1.0));
    // textureLod, never texture(): surf runs inside the march's loops, where a GPU's compiler (ANGLE
    // on Direct3D) may refuse sampling with implicit gradients; the level from a texel's footprint on
    // the ball (1024 map texels round it, a screen texel u_pix * 6 units wide at the camera's distance)
    float lod = max(0.0, log2(1024.0 / (2.0 * PI * GR) * u_pix * 6.0));
    float land = textureLod(u_aux, vec2(0.5 + lon / (2.0 * PI), 0.5 - lat / PI), lod).a;
    // a faint graticule every 30 degrees
    float gl = abs(fract(lat / (PI / 6.0) + 0.5) - 0.5) * 30.0;
    float gm = abs(fract(lon / (PI / 6.0) + 0.5) - 0.5) * 30.0 * cos(lat);
    float grid = 1.0 - smoothstep(0.25, 0.6, min(gl, gm)) * 1.0;
    s.gloss = 0.35; s.shine = 30.0;
    // the accent goes on the sea when it is a blue or a teal; any other accent (an orange, a green)
    // goes on the land, so a sea never reads as land
    float blue = step(0.06, u_accent.b - max(u_accent.r, u_accent.g * 0.85));
    bool lit = land > 0.5;
    if (u_render > 0.5) {
      // the render: a varnished paper globe, parchment land, the sea in a blue accent or a deep
      // ocean blue, the graticule printed faintly over both
      vec3 sea = blue > 0.5 ? toLin(u_accent) : vec3(0.025, 0.075, 0.14);
      s.col = mix(sea, vec3(0.6, 0.5, 0.31), smoothstep(0.35, 0.65, land)) * (1.0 - 0.22 * grid);
      s.accent = blue > 0.5 ? 1.0 - smoothstep(0.35, 0.65, land) : 0.0;   // the poster relights a blue sea in the accent
      s.gloss = 0.7; s.shine = 45.0;
      return;
    }
    if (blue > 0.5) {
      s.albedo = mix(0.5, 0.97, land) * (1.0 - 0.16 * grid * (1.0 - land));
      s.accent = lit ? 0.0 : 1.0;
      // land never prints darker than a mid tone and the sea never lighter than a light one, so the
      // coastlines hold whatever the light (or the pointer) does
      if (lit) { s.lo = 0.0; s.hi = 0.48; } else { s.lo = 0.34; s.hi = 0.95; }
    } else {
      // the land in the accent, a full plate; the sea a light tone of the ink with its graticule
      s.albedo = mix(0.86, 0.6, land) * (1.0 - 0.18 * grid * (1.0 - land));
      s.accent = lit ? 1.0 : 0.0;
      if (lit) { s.lo = 0.42; s.hi = 0.95; } else { s.lo = 0.0; s.hi = 0.42; }
    }
    // engraved lines: parallel planes tipped back 22 degrees, a little more than the camera's 14, so
    // the lines bow gently round the ball like latitudes seen from a little above while their poles
    // stay on (or just inside) the outline (circles about the Earth's own pole crowded into a bullseye,
    // and a flat tint there printed as a blotch)
    s.coord = dot(q, u_rot * vec3(0.0, 0.9272, -0.3746)) * 1.1;
  } else if (id < 2.5) {                         // the brass meridian and its pins
    s.albedo = 0.7; s.gloss = 0.85; s.shine = 70.0;
    if (u_render > 0.5) { s.col = vec3(0.6, 0.42, 0.16); s.metal = 1.0; s.shine = 45.0; }
    s.coord = length(q.xy);
  } else {                                       // turned wood stand
    s.albedo = 0.46; s.gloss = 0.45; s.shine = 30.0;
    // the render: oiled walnut, its grain running up the stem and round the base
    if (u_render > 0.5) { float gr = 0.5 + 0.5 * sin(p.y * 160.0 + 9.0 * sin(atan(p.z, p.x) * 3.0 + p.y * 20.0)); s.col = mix(vec3(0.07, 0.034, 0.016), vec3(0.12, 0.062, 0.03), gr); s.gloss = 0.55; s.shine = 36.0; }
    s.coord = p.y;
  }
}
`;

// the same test as the shader's: a blue or teal accent (blue well above red and green)
function seaAccent(hex) {
  let h = String(hex || '').replace('#', '');
  if (h.length === 3) h = h.split('').map(c => c + c).join('');
  const n = parseInt(h.slice(0, 6), 16);
  if (!Number.isFinite(n)) return false;
  const r = ((n >> 16) & 255) / 255, g = ((n >> 8) & 255) / 255, b = (n & 255) / 255;
  return b - Math.max(r, g * 0.85) >= 0.06;
}

// the land as a 1024 x 512 equirectangular mask (white land on clear), made once per page
let landCanvas = null;
function landMask() {
  if (landCanvas) return landCanvas;
  const w = 1024, h = 512, c = document.createElement('canvas');
  c.width = w; c.height = h;
  const x = c.getContext('2d');
  const sx = w / 360, sy = h / 180;
  const fill = (poly, off) => {
    x.beginPath();
    x.moveTo((poly[0] + 180 + off) * sx, (90 - poly[1]) * sy);
    for (let i = 2; i < poly.length; i += 2) x.lineTo((poly[i] + 180 + off) * sx, (90 - poly[i + 1]) * sy);
    x.closePath();
    x.fill();
  };
  x.filter = 'blur(0.6px)';
  x.fillStyle = '#fff';
  for (const off of [-360, 0, 360]) for (const p of LAND) fill(p, off);
  x.globalCompositeOperation = 'destination-out';
  for (const p of LAKES) fill(p, 0);
  landCanvas = c;
  return c;
}

export default definePrint({
  id: 'print-globe',
  name: 'Desk globe',
  label: 'A desk globe turning on its tilted axis',
  base: import.meta.url,
  glsl,
  pivot: [0, 0.46, 0],
  radius: 0.5,
  extent: [0.34, 0.47],
  camera: { elev: 14, dist: 6, target: 0.44 },
  light: [-0.32, 1.6, 0.75],
  turn: { mode: 'sway', amp: 16, period: 26 },
  step: 'impulse',
  texture: landMask,
  posterPrint: 'engrave',
  // the accent sits on the sea when it is blue (as the shader decides), else on the land (a print) or
  // nowhere (the render keeps its deep ocean blue): so each picture has a second set of posters
  poster: (pal, dark, render) => (seaAccent(pal.accent) ? `./fallback-${render ? 'render-' : ''}sea${dark ? '-dark' : ''}.png` : null),
  plates: [
    { file: 'fallback-sea.png', paper: 'light', accent: '#2f5f93' }, { file: 'fallback-sea-dark.png', paper: 'dark', accent: '#5a8fd0' },
    { file: 'fallback-render-sea.png', paper: 'light', accent: '#2f5f93', render: 1 }, { file: 'fallback-render-sea-dark.png', paper: 'dark', accent: '#5a8fd0', render: 1 },
  ],
  press: 'Press to spin it.',
  params: { effect: { default: 'render' }, angle: { default: 22 }, size: { default: 0.8 } },
  // card: cut by the bottom-left (the bottom-right corner stays clear for the pause button), and in a
  // panel about as tall as wide (a phone) less cut, so the thing still reads; tile: whole, low; hero:
  // right of the text, smaller and under it in a phone-shaped frame
  place: {
    card: { transparent: 1, size: 1.12, x: -0.2, y: -0.24, narrow: { size: 0.94, x: -0.1, y: -0.24 } },
    tile: { transparent: 1, size: 0.86, y: -0.06 },
    hero: { transparent: 1, size: 0.9, x: 0.2, y: -0.02, narrow: { size: 0.66, x: 0.1, y: -0.2 } },
  },
  // the Earth turns on its axis; a click flicks it, and the spin runs down
  update(state, dt) {
    const flick = state.kicks ? 300 * Math.exp(-state.kick * 0.85) : 0;
    return { spin: state.spin + dt * (9 + flick) * state.params.speed * DEG };
  },
});

objects/print-cup/object.js:
/*
  print-cup - a coffee cup on its saucer, modelled as revolved profiles (the saucer's well and
  rim, the cup's foot, belly and lip), a looped handle and the coffee's surface. The glaze outside the
  cup is the accent plate; the white inside, the saucer and the coffee print in the ink. Rendered:
  white porcelain, the glaze in the accent, glossy coffee with milk.
  Turns slowly on the saucer's axis. Hover: the light follows the pointer and the cup leans toward
  it. Click or Enter: rings run out across the coffee, catch the light and settle.
*/
import { definePrint } from '../_print-core/print3d.js';

const glsl = /* glsl */ `
// revolved profiles in (radius, height); every line has its own thickness, so lips and rims are round
float saucer(vec2 q) {
  float d = sdSeg(q, vec2(0.0, 0.026), vec2(0.17, 0.026));
  d = smin(d, sdSeg(q, vec2(0.17, 0.026), vec2(0.33, 0.041)), 0.03);
  d = smin(d, sdSeg(q, vec2(0.33, 0.041), vec2(0.445, 0.072)), 0.04);
  d -= 0.011;
  return min(d, length(q - vec2(0.155, 0.009)) - 0.009);   // the foot ring underneath
}
// the wall follows one smooth curve from the foot (r 0.112 at y 0.052) to the lip (r 0.259 at y
// 0.352), round in the belly, so it reads as thrown porcelain and not as bands; the distance to the
// curve is scaled by its slope, beyond its ends it is the distance to the end
float cupWall(vec2 q) {
  float y = clamp(q.y, 0.052, 0.352);
  float t = (y - 0.052) / 0.3;
  float R = 0.112 + 0.147 * (1.0 - pow(1.0 - t, 2.8));
  float dR = 0.147 * 2.8 * pow(1.0 - t, 1.8) / 0.3;
  float d = q.y > 0.352 || q.y < 0.052 ? length(q - vec2(R, y)) : abs(q.x - R) / sqrt(1.0 + dR * dR);
  d = min(d, sdSeg(q, vec2(0.0, 0.052), vec2(0.112, 0.052)));   // the bottom
  return d - 0.0135;
}
float handle(vec3 p) {
  vec3 h = p - vec3(0.302, 0.222, 0.0);
  h.y *= 0.84;
  float d = length(vec2(length(h.xy) - 0.066, h.z * 0.86)) - 0.0145;
  return max(d, 0.238 - p.x);
}
// rings that run out from the middle after a click and die away: phase and strength
float ringEnv(float r) {
  float k = u_kick;
  float front = 0.03 + k * 0.17;
  return exp(-k * 0.55) * smoothstep(front, front - 0.08, r) * smoothstep(0.0, 0.03, r + 0.01);
}
float ripple(float r) { return 0.011 * ringEnv(r) * sin(r * 62.0 - u_kick * 8.0); }
// the coffee's surface: level, with rings after a click, and a meniscus where it climbs the porcelain
// (it curves up the last few millimetres, so its far side catches the light above and its near side
// goes dark: the rim that tells a liquid from a disc)
float coffee(vec3 p, float r) {
  float m = smoothstep(0.205, 0.245, r);
  float d = max(p.y - (0.298 + ripple(r) + 0.0055 * m * m), r - 0.245);
  return max(d * 0.7, 0.25 - p.y);   // a disc inside the wall, never through it (0.7: the rings are steep)
}

vec2 map(vec3 p) {
  float r = length(p.xz);
  vec2 q = vec2(r, p.y);
  vec2 res = vec2(saucer(q), 1.0);
  float c = cupWall(q), h = handle(p);
  float ch = smin(c, h, 0.014);
  if (ch < res.x) res = vec2(ch, h < c ? 3.0 : 2.0);
  float k = coffee(p, r);
  if (k < res.x) res = vec2(k, 4.0);
  return res;
}

void surf(float id, vec3 p, vec3 n, inout Surf s) {
  float r = length(p.xz);
  if (u_render > 0.5) {
    // the render: white porcelain, the glaze outside the cup in the accent, coffee with its crema
    s.gloss = 0.85; s.shine = 70.0;
    if (id < 1.5) s.col = vec3(0.8, 0.79, 0.76);
    else if (id < 3.5) {
      bool outside = id > 2.5 || (dot(n.xz, p.xz) > 0.0 && !(p.y > 0.34 && n.y > 0.45));
      if (outside) s.accent = 1.0; else s.col = vec3(0.8, 0.79, 0.76);
    } else {
      // coffee with milk: an even crema, a shade deeper in the middle; glossy, so the room above lies
      // on it and the meniscus at the porcelain catches the light (no painted line there: it stepped)
      s.col = mix(vec3(0.125, 0.056, 0.02), vec3(0.19, 0.088, 0.034), smoothstep(0.04, 0.23, r));
      s.gloss = 1.0; s.shine = 120.0;
    }
    // the line where the coffee meets the white inside: a texel's hit is the one or the other, so the
    // line stair-steps; within about a texel of it each side takes up to half of the other's colour
    // and finish (a texel is about 6 u_pix wide here; the coffee's plane is seen foreshortened)
    const vec3 PORC = vec3(0.8, 0.79, 0.76), CREMA = vec3(0.19, 0.088, 0.034);
    float fw = max(6.0 * u_pix, 1e-4);
    if (id > 3.5) {
      float e = 0.5 * clamp(1.0 - (0.2447 - r) / (1.8 * fw), 0.0, 1.0);
      s.col = mix(s.col, PORC, e); s.gloss = mix(s.gloss, 0.85, e); s.shine = mix(s.shine, 70.0, e);
    } else if (id > 1.5 && id < 2.5 && s.accent < 0.5 && p.y > 0.27 && p.y < 0.34) {
      float e = 0.5 * clamp(1.0 - (p.y - 0.3035) / (1.1 * fw), 0.0, 1.0);
      s.col = mix(s.col, CREMA, e); s.gloss = mix(s.gloss, 1.0, e); s.shine = mix(s.shine, 120.0, e);
    }
    return;
  }
  if (id < 1.5) {            // saucer, white glaze
    s.albedo = 0.9; s.gloss = 0.5; s.shine = 36.0; s.coord = r;
  } else if (id < 3.5) {     // the cup: coloured glaze outside, white inside
    bool outside = id > 2.5 || (dot(n.xz, p.xz) > 0.0 && !(p.y > 0.34 && n.y > 0.45));
    s.albedo = outside ? 0.74 : 0.92;
    s.gloss = 0.55; s.shine = 48.0;
    s.accent = outside ? 1.0 : 0.0;
    s.coord = p.y;
  } else {                   // coffee: dark middle, the crema lighter toward the cup; the crests of the rings catch the light
    s.albedo = 0.42 + 0.34 * smoothstep(0.1, 0.245, r);
    s.gloss = 0.9; s.shine = 90.0;
    float crest = smoothstep(0.35, 0.95, sin(r * 62.0 - u_kick * 8.0)) * ringEnv(r);
    s.emit = 0.55 * crest;
    s.coord = r;
  }
}
`;

export default definePrint({
  id: 'print-cup',
  name: 'Cup and saucer',
  label: 'A cup of coffee on its saucer',
  press: 'Press to stir the coffee.',
  base: import.meta.url,
  glsl,
  pivot: [0, 0.18, 0],
  radius: 0.5,
  extent: [0.47, 0.36],
  foot: 0.45,
  camera: { elev: 27, dist: 6 },
  turn: { mode: 'spin', speed: 10 },
  step: 'impulse',
  kickTime: 5,
  kickStill: 0.9,
  params: { effect: { default: 'render' }, angle: { default: -32 }, size: { default: 0.72 } },
  // card: cut by the bottom-left (the bottom-right corner stays clear for the pause button), and in a
  // panel about as tall as wide (a phone) less cut, so the thing still reads; tile: whole, low; hero:
  // right of the text, smaller and under it in a phone-shaped frame
  place: {
    card: { transparent: 1, size: 1.12, x: -0.2, y: -0.22, narrow: { size: 0.92, x: -0.1, y: -0.24 } },
    tile: { transparent: 1, size: 0.92, y: -0.1 },
    hero: { transparent: 1, size: 1.0, x: 0.2, y: -0.1, narrow: { size: 0.8, x: 0.05, y: -0.26 } },
  },
});

objects/print-cards/object.js:
/*
  print-cards - a loose stack of ten playing cards: rounded corners, each a hair off true, the backs
  with a white border round a diamond lattice and a ruled frame, and the top card turned face up (an
  ace of diamonds), so it reads as playing cards at any size. The backs and the pips print in the
  accent, the card stock and edges in the ink. Rendered: white stock, red pips, backs in the accent.
  At rest the cards lie in a loose spread and turn slowly on the table. Hover: the light follows the
  pointer and the stack leans toward it. Click, Enter or focus: the cards fan out from the near edge like a hand being spread; click
  again to gather them.
*/
import { definePrint } from '../_print-core/print3d.js';

const glsl = /* glsl */ `
const vec2 FAN = vec2(0.0, 0.215);              // the fan's pivot, near the bottom edge
const vec3 CARD = vec3(0.2, 0.0026, 0.28);      // half sizes: 63 x 88 card proportions
const float PITCH = 0.0062;

// card i's frame: jitter, then the fan about its pivot
vec3 cardFrame(vec3 p, float fi) {
  float a = (hash1(fi + 3.1) - 0.5) * 0.09 + mix(0.5, 1.0, u_step) * (fi / 9.0 - 0.5) * 1.05;
  vec2 j = (vec2(hash1(fi + 7.7), hash1(fi + 1.3)) - 0.5) * 0.014;
  vec3 q = p - vec3(FAN.x, 0.0026 + fi * PITCH, FAN.y);
  q.xz = rot2(-a) * q.xz;
  q.xz += FAN - j;
  return q;
}
// a diamond pip of half width a, half height b, its sides curved in a little as on real cards
// (roughly a distance: negative inside)
float pip(vec2 c, vec2 hb) {
  vec2 k = abs(c) / hb;
  float f = pow(k.x, 0.82) + pow(k.y, 0.82) - 1.0;
  return f * min(hb.x, hb.y) * 0.62;
}
// the face's ink: the big pip, and in the far-left and near-right corners an A over a small pip,
// both upright for a reader at that corner's edge (negative inside)
float faceMark(vec2 c) {
  float m = pip(c, vec2(0.068, 0.098));
  float sg = c.x < 0.0 ? -1.0 : 1.0;
  if (c.x * c.y > 0.0) {
    vec2 u = vec2((c.x - sg * 0.162) * -sg, (c.y - sg * 0.236) * sg);
    float a = min(sdSeg(u, vec2(-0.0125, -0.017), vec2(0.0, 0.018)), sdSeg(u, vec2(0.0, 0.018), vec2(0.0125, -0.017)));
    a = min(a, sdSeg(u, vec2(-0.0068, -0.0035), vec2(0.0068, -0.0035)));
    m = min(m, a - 0.0034);
    m = min(m, pip(u - vec2(0.0, -0.043), vec2(0.0115, 0.016)));
  }
  return m;
}
float card(vec3 q) { return extrude(sdRect(q.xz, CARD.xz, 0.032), q.y, CARD.y, 0.0012); }

vec2 map(vec3 p) {
  vec2 res = vec2(1e9, 0.0);
  // above the stack: no card is nearer than the top card's face (y 0.0612); a bound that is too short
  // would also darken the whole face through the occlusion
  if (p.y > 0.09) return vec2(p.y - 0.062, 0.0);
  for (int i = min(u_steps, 0); i < 10; i++) {
    float fi = float(i);
    float d = card(cardFrame(p, fi));
    if (d < res.x) res = vec2(d, fi);
  }
  return res;
}

void surf(float id, vec3 p, vec3 n, inout Surf s) {
  vec3 q = cardFrame(p, id);
  s.albedo = 0.94; s.gloss = 0.25; s.shine = 26.0;
  s.coord = q.z;
  s.hi = 0.5;                                     // white stock: never a dark grey
  // the render: linen-finish card stock, red pips, the backs printed in the accent
  bool rend = u_render > 0.5;
  if (rend) { s.col = vec3(0.8, 0.79, 0.75); s.gloss = 0.45; s.shine = 34.0; }
  if (id > 8.5 && n.y > 0.6) {
    // the top card, face up: the ace of diamonds, one large pip in the middle and in two opposite
    // corners the index (an A over a small pip), each edge softened over about a texel
    float m = faceMark(q.xz);
    float w = max(u_pix * 7.0, 0.0012);
    float ink = 1.0 - smoothstep(-w, w, m);
    if (rend) { s.col = mix(s.col, vec3(0.48, 0.012, 0.02), ink); s.gloss = mix(0.45, 0.6, ink); return; }
    // the face is white card: it prints almost clean, so the pips and the dark edge of the stack carry it
    s.albedo = 0.98; s.hi = 0.0;
    if (ink > 0.5) { s.albedo = 0.6; s.accent = 1.0; s.lo = 0.55; s.hi = 1.0; }
    return;
  }
  if (abs(n.y) > 0.6) {
    // the back: a white border, a ruled frame, then a diamond lattice in the accent
    float inset = sdRect(q.xz, CARD.xz - 0.022, 0.016);
    if (inset < 0.0) {
      float fq = rend ? 30.0 : 13.0;
      vec2 g = vec2(q.x + q.z, q.x - q.z) * fq;
      vec2 f = abs(fract(g) - 0.5);
      float lattice = smoothstep(0.1, 0.16, min(f.x, f.y));
      lattice = mix(0.72, lattice, smoothstep(3.0, 6.0, 1.0 / (fq * max(6.0 * u_pix, 1e-5))));
      float frame = smoothstep(0.003, 0.005, abs(inset + 0.009));
      s.albedo = mix(0.32, 0.76, lattice) * mix(0.45, 1.0, frame);
      if (rend) { s.col = toLin(u_accent) * mix(0.4, 1.0, lattice) * mix(0.5, 1.0, frame); s.accent = 1.0; return; }
      s.lo = 0.3;                                 // the back always prints as a coloured field
      s.hi = 1.0;
      s.accent = 1.0;
      s.gloss = 0.4;
      s.coord = (q.x + q.z) * 0.8;
    }
  }
}
`;

export default definePrint({
  id: 'print-cards',
  name: 'Playing cards',
  label: 'A stack of playing cards; it fans out when chosen',
  base: import.meta.url,
  glsl,
  pivot: [0, 0.04, 0],
  radius: 0.4,
  extent: [0.44, 0.32],
  bound: 0.82,
  camera: { elev: 38, dist: 6, target: 0.02 },
  light: [-0.45, 1.25, 0.55],
  turn: { mode: 'spin', speed: 6 },
  step: 'toggle',
  stepTime: 1.0,
  shadowSteps: 32,
  floorReach: 0.04,
  press: 'Press to fan the cards out.',
  params: { effect: { default: 'render' }, angle: { default: 20 }, size: { default: 0.82 } },
  // card: cut by the bottom-left (the bottom-right corner stays clear for the pause button), and in a
  // panel about as tall as wide (a phone) less cut, so the thing still reads; tile: whole, low; hero:
  // right of the text, smaller and under it in a phone-shaped frame
  place: {
    card: { transparent: 1, size: 1.2, x: -0.22, y: -0.14, narrow: { size: 1.0, x: -0.12, y: -0.12 } },
    tile: { transparent: 1, size: 1.0, y: -0.04 },
    hero: { transparent: 1, size: 1.05, x: 0.22, y: -0.04, narrow: { size: 0.8, x: 0.05, y: -0.22 } },
  },
});

objects/photo-kit/demo.css:
/* photo-kit/demo.css - the shared page of the photo objects' demos */
:root, :root[data-palette="light"] {
  --bg: #f2f0eb; --surface: #e8e5de; --ink: #141414; --muted: #6f6b64; --accent: #2b50e6; --accent-ink: #ffffff;
  --line: color-mix(in oklab, var(--ink) 14%, transparent);
}
:root[data-palette="dark"] {
  --bg: #0e0f11; --surface: #17191c; --ink: #ecebe6; --muted: #8b8d92; --accent: #ff7a45; --accent-ink: #111111;
}
/* a blue held toward cyan (OKLCH hue about 255), so its light tints read as sky, never lavender */
:root[data-palette="colour"] {
  --bg: #0d4fae; --surface: #175bbb; --ink: #f6f3ec; --muted: #a9c3e8; --accent: #ffb547; --accent-ink: #121212;
}

* { box-sizing: border-box; }
html { -webkit-text-size-adjust: 100%; }
body {
  margin: 0; background: var(--bg); color: var(--ink);
  font: 400 15px/1.5 "Inter", ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  font-feature-settings: "ss01", "cv11";
  -webkit-font-smoothing: antialiased;
  transition: background-color .4s ease, color .4s ease;
}
a { color: inherit; text-decoration-thickness: 1px; text-underline-offset: 3px; text-decoration-color: color-mix(in oklab, currentColor 40%, transparent); }
a:hover { text-decoration-color: currentColor; }

.page { max-width: 1320px; margin: 0 auto; padding: 32px 40px 72px; }
.top { display: grid; grid-template-columns: 1fr auto; align-items: end; gap: 24px 48px; padding-bottom: 28px; }
.eyebrow { margin: 0 0 14px; font-size: 13px; color: var(--muted); letter-spacing: .01em; }
.eyebrow b { font-weight: 500; color: var(--ink); }
h1 { margin: 0; font-weight: 500; font-size: clamp(30px, 3.4vw, 46px); line-height: 1.04; letter-spacing: -.025em; }
.blurb { margin: 14px 0 0; max-width: 60ch; color: var(--muted); font-size: 15px; }

.controls { display: flex; gap: 10px; align-items: center; flex-wrap: wrap; justify-content: flex-end; }
.seg { display: inline-flex; padding: 3px; border-radius: 999px; background: var(--surface); }
.seg button, .btn {
  appearance: none; border: 0; background: transparent; color: var(--muted); font: inherit; font-size: 13px; font-weight: 500;
  height: 32px; padding: 0 14px; border-radius: 999px; cursor: pointer; transition: background-color .2s, color .2s;
}
.seg button[aria-pressed="true"] { background: var(--bg); color: var(--ink); box-shadow: 0 1px 2px color-mix(in oklab, var(--ink) 12%, transparent); }
.btn { background: var(--ink); color: var(--bg); }
.seg button:focus-visible, .btn:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; }

.grid { display: grid; grid-template-columns: 5fr 7fr; gap: 20px; }
.grid figure { margin: 0; display: flex; flex-direction: column; min-width: 0; }
.grid .wide { grid-column: 1 / -1; }
.frame { position: relative; overflow: hidden; border-radius: 6px; background: var(--surface); cursor: crosshair; }
.grid figure:nth-child(1) .frame { aspect-ratio: 4 / 5; }
.grid figure:nth-child(2) .frame { flex: 1; min-height: 0; }
.grid .wide .frame { aspect-ratio: 21 / 9; }
figcaption { display: flex; justify-content: space-between; gap: 16px; padding-top: 10px; font-size: 12.5px; color: var(--muted); }
figcaption .kind { color: var(--ink); font-weight: 500; }
figcaption .credit { text-align: right; max-width: 48%; }
.notes { margin-top: 40px; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 24px; border-top: 1px solid var(--line); padding-top: 22px; }
.notes h2 { margin: 0 0 6px; font-size: 13px; font-weight: 500; }
.notes p { margin: 0; font-size: 13.5px; color: var(--muted); }

/* solo: one picture filling the window (hero shots and frame-rate checks) */
body.solo .page { max-width: none; padding: 0; }
body.solo .top, body.solo .notes { display: none; }
/* the credit stays in solo: a small line over the picture's bottom left */
body.solo figcaption > span:first-child { display: none; }
body.solo figcaption .credit { max-width: none; text-align: left; }
body.solo figcaption {
  position: fixed; left: 12px; bottom: 12px; z-index: 2; padding: 4px 9px; border-radius: 999px;
  background: color-mix(in oklab, var(--bg) 82%, transparent); color: var(--ink); font-size: 11.5px;
}
body.solo .grid { display: block; }
body.solo .grid figure:not(:first-child) { display: none; }
body.solo .grid figure:first-child .frame { aspect-ratio: auto; height: 100vh; width: 100vw; border-radius: 0; }

@media (max-width: 760px) {
  .page { padding: 20px 16px 48px; }
  .top { grid-template-columns: 1fr; gap: 18px; }
  .controls { justify-content: flex-start; }
  .grid { grid-template-columns: 1fr; gap: 16px; }
  .grid figure:nth-child(2) .frame { aspect-ratio: 4 / 3; flex: none; }
  .grid .wide .frame { aspect-ratio: 4 / 3; }
  .notes { grid-template-columns: 1fr; gap: 16px; }
  figcaption { flex-direction: column; gap: 2px; }
  figcaption .credit { text-align: left; max-width: none; }
}

objects/photo-kit/demo.js:
/*
  photo-kit/demo.js - the shared demo page of a photo object: three vetted photographs of different
  kinds (a product, a room, a building), each credited, in the light, dark or colour palette.

    demo(object, { blurb, notes: [[title, text] x3], photos: ['lamp', 'room', 'concrete'], params, per: { lamp: {...} } })

  Query: ?palette=light|dark|colour, ?solo=<photo key> (one picture filling the window),
  ?photos=lamp,room,platform, ?p={"cell":4} (params as JSON), ?clock=8 (frozen, for screenshots).
  window.__pk holds the mounted controllers (info.fps, replay()).
*/
import fx from '../../effects/fx.js';
import { photoCredit } from './photo.js';

const q = new URLSearchParams(location.search);
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);

export async function demo(object, opts = {}) {
  const lib = await fetch(new URL('./photos.json', import.meta.url)).then(r => r.json());
  const byKey = Object.fromEntries(lib.photos.map(p => [p.key, p]));
  const solo = q.get('solo');
  const keys = solo ? [solo] : (q.get('photos') || '').split(',').filter(k => byKey[k]).concat(opts.photos || ['lamp', 'room', 'concrete']).slice(0, 3);
  const palette = ['light', 'dark', 'colour'].includes(q.get('palette')) ? q.get('palette') : opts.palette || 'light';
  let extra = {};
  try { extra = JSON.parse(q.get('p') || '{}'); } catch (_) { /* ignore */ }

  document.documentElement.dataset.palette = palette;
  // ?clock=8 freezes every object at 8 s with the entry done (screenshots: no frames run, hover still answers)
  if (q.has('clock')) fx.setClock(+q.get('clock'));
  // ?webgl1 tests the GLSL ES 1.00 path
  if (q.has('webgl1')) fx.config.forceWebGL1 = true;
  if (solo) document.body.classList.add('solo');
  document.title = object.name;

  const figs = keys.map((k, i) => {
    const p = byKey[k];
    return `<figure class="${i === 2 ? 'wide' : ''}">
      <div class="frame" data-key="${esc(k)}" role="img" aria-label="${esc(p.alt)}"></div>
      <figcaption><span><span class="kind">${esc(p.kind[0].toUpperCase() + p.kind.slice(1))}</span> &middot; ${esc(p.alt)}</span>
      <span class="credit">${photoCredit(p)}</span></figcaption>
    </figure>`;
  }).join('');
  const notes = (opts.notes || []).map(([h, t]) => `<div><h2>${esc(h)}</h2><p>${esc(t)}</p></div>`).join('');

  document.body.innerHTML = `<main class="page">
    <header class="top">
      <div>
        <p class="eyebrow"><b>Photo objects</b> &middot; a real photograph through an effect</p>
        <h1>${esc(object.name)}</h1>
        <p class="blurb">${esc(opts.blurb || '')}</p>
      </div>
      <div class="controls">
        <div class="seg" role="group" aria-label="Palette">
          ${['light', 'dark', 'colour'].map(n => `<button type="button" data-pal="${n}" aria-pressed="${n === palette}">${n[0].toUpperCase() + n.slice(1)}</button>`).join('')}
        </div>
        <button type="button" class="btn" data-replay>Replay</button>
      </div>
    </header>
    <section class="grid">${figs}</section>
    ${notes ? `<section class="notes">${notes}</section>` : ''}
  </main>`;

  const ctrls = [...document.querySelectorAll('.frame')].map(el => {
    const p = byKey[el.dataset.key];
    const params = { focusX: p.focus[0], focusY: p.focus[1], ...(opts.params || {}), ...((opts.per || {})[p.key] || {}), ...extra };
    const c = object.mount(el, { palette: fx.readPalette(el), src: new URL(p.file, import.meta.url).href, params });
    c.key = p.key;
    return c;
  });
  window.__pk = ctrls;

  document.querySelectorAll('[data-pal]').forEach(b => b.addEventListener('click', () => {
    document.documentElement.dataset.palette = b.dataset.pal;
    document.querySelectorAll('[data-pal]').forEach(x => x.setAttribute('aria-pressed', String(x === b)));
    const u = new URL(location.href);
    u.searchParams.set('palette', b.dataset.pal);
    history.replaceState(null, '', u);
    requestAnimationFrame(() => document.querySelectorAll('.frame').forEach((el, i) => ctrls[i].setPalette(fx.readPalette(el))));
  }));
  document.querySelector('[data-replay]')?.addEventListener('click', () => ctrls.forEach(c => c.replay && c.replay()));
  return ctrls;
}

objects/photo-kit/photo.js:
/*
  photo-kit/photo.js - the shared runtime of the photo prints (photo-halftone, photo-engraving,
  photo-dither): a photograph printed whole by a fragment shader in the page palette, on the page's
  surface as paper; hover (a tap on a phone) shows the photograph under the print. A print is one
  crafted moment on a page, never a filter over the hero or a section's main photograph.

    photoGL(el, spec) -> { destroy, pause, resume, set(params), setPalette(p), redraw, info, canvas }
    creditsBlock(entries, { adapted }) -> the footer's credits block (HTML), as scripts/photos.mjs
      credits prints it, for photographs that did not come through photos.mjs; photoCredit(entry) and
      creditsLine(entries) write one photograph's credit and a plain line (demos, scenes)
    glslLint(src), photoShader(object) -> the faults a GPU's compiler rejects, and the source to check

  spec = {
    frag            GLSL body (no version, precision or uniform lines); writes fxColor
    schema, params  the object's params; each becomes a float uniform u_<name>
    palette, src    the page palette and the photograph's URL (else the <img> inside el: its largest
                    srcset size; else data-src)
    focus           [x, y] 0..1 of the photograph kept in frame; given focusX/Y params win, then the
                    <img>'s object-position (photos.mjs fetch writes the subject's place there)
    uniforms(ctx)   extra uniforms { u_name: number | [2..4 numbers] }, rebuilt on resize, palette, set()
    textures(ctx)   extra textures { u_name: { source, width, height, filter, wrap, mip, key } }
    stats           true: u_stats, the photograph's edge density (r) and lightness (g), mipmapped
    trail           n: u_trail[n], the cursor's recent path (xy canvas px, z strength 0..1)
    entry           seconds of an entry animation (the prints use 0: finished from the first frame,
                    never half developed in a screenshot or on a slow machine)
    crisp           true: whole device px per canvas px (at most 1 canvas px per CSS px), pixelated upscaling (dither)
    maxScale        canvas px per CSS px at most (default 1; the halftone and engraving take 2, so
                    dots and lines stay sharp on a sharp screen)
    heavy           true: 0.75 canvas px per CSS px in a large frame (more than a few texture reads per pixel)
    still           seconds used for the reduced-motion still frame
  }

  Every object gets, in canvas pixels with y up: u_time, u_res, u_dpr (canvas px per CSS px), u_fit (0.6..1: smaller
  frames take finer screens; objects multiply their sizes by it),
  u_frame (the frame's CSS size), u_mouse (xy, z = hover 0..1, eased), u_vel, u_enter, the photograph u_img (mipmapped) with u_imgRes,
  u_texRes, u_focus, u_zoom and u_levels (its own black and white points in OKLab lightness), and the
  palette u_bg, u_surface, u_ink, u_muted, u_accent, u_accentInk, u_paperLight. The helpers in PK_LIB
  (below) map canvas pixels to the photograph, read its tone and give the paper (pk_paper).

  Built in: one canvas, its own WebGL context counted in the effects' context budget (fx.glBudget),
  paused off screen and while the tab is hidden, released 1.5 s after it leaves the screen (the greyed
  <img> stands in until it returns), one still frame under prefers-reduced-motion (hover still
  answers, without easing), and the photograph itself, greyed into the palette, whenever it cannot
  draw: no WebGL, a shader that fails to compile or link, or one that uses a GLSL ES reserved word
  (refused here, since CPU WebGL compiles some that a laptop's GPU rejects).

  Cost, for an integrated laptop GPU: never over 1.5 MP of canvas; at most 1 canvas px per CSS px
  unless spec.maxScale allows more; a heavy object drops to 0.75 in a large frame (over 1 MP of CSS
  px); a crisp object (dither) shows each canvas px as whole device px (0.875 at DPR 1.75), so its
  cells stay sharp. At most 3 photo objects hold a context at once: a fourth waits, showing its still,
  until one leaves the screen, and a frame scrolling away gives way to one coming in. Each pixel reads
  the photograph 2 to 5 times from its mipmaps, with no loops over neighbours.
*/
import fx from '../../effects/fx.js';

const { color, normalizePalette, readPalette, resolveParams, lifecycle, glBudget, fallbackCSS, GLSL_LIB, config, hashSeed } = fx;

// render scale: canvas px per CSS px (see "Cost" above)
export const MAX_SCALE = 1, LARGE_SCALE = 0.75, LARGE_AREA = 1e6, MAX_PIXELS = 1.5e6, MAX_LIVE = 3;
/**
  the canvas px per CSS px for a frame of w x h CSS px on this screen. maxScale (default 1) lets a
  print whose dots or lines must stay sharp render up to that many canvas px per CSS px on a sharp
  screen (the halftone takes 2: a soft upscale of round dots reads as a low-resolution picture); the
  1.5 MP cap holds either way, so the work per frame never grows past it
*/
export function renderScale(w, h, { crisp = false, heavy = false, maxScale = MAX_SCALE } = {}, dpr = (typeof window !== 'undefined' && window.devicePixelRatio) || 1) {
  const area = Math.max(1, w * h), top = Math.min(dpr, maxScale);
  if (crisp) {
    // whole device px per canvas px, so the screen shows every cell as a sharp square (a soft upscale
    // blurs a dither): 1 at DPR 1, 2 or 3; 0.875 at 1.75 and 0.75 at 1.5 (each canvas px 2 device px)
    let k = Math.max(1, Math.ceil(dpr / MAX_SCALE - 1e-6));
    while (area * (dpr / k) * (dpr / k) > MAX_PIXELS) k++;
    return dpr / k;
  }
  let s = heavy && area > LARGE_AREA ? Math.min(top, LARGE_SCALE) : top;
  if (area * s * s > MAX_PIXELS) s = Math.sqrt(MAX_PIXELS / area);
  return s;
}
// the photo objects holding a WebGL context right now (a page keeps at most MAX_LIVE)
const livePK = new Set();
const HAS_DOM = typeof window !== 'undefined' && typeof document !== 'undefined';
const reducedQ = HAS_DOM && window.matchMedia ? window.matchMedia('(prefers-reduced-motion: reduce)') : null;
const noHoverQ = HAS_DOM && window.matchMedia ? window.matchMedia('(hover: none)') : null;
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const reduced = () => !!(reducedQ && reducedQ.matches);

/* ------------------------------------------------------------------ images */

const images = new Map();
/** load (once per URL) and decode an image with CORS, so WebGL may read it */
export function loadImage(src) {
  if (!images.has(src)) {
    images.set(src, new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = 'anonymous';
      img.decoding = 'async';
      img.onload = () => (img.decode ? img.decode().catch(() => {}) : Promise.resolve()).then(() => resolve(img));
      img.onerror = () => { images.delete(src); reject(new Error(`photo-kit: could not load ${src}`)); };
      img.src = src;
    }));
  }
  return images.get(src);
}

/** an <img>'s largest candidate (srcset by width, else src): the print reads it at full size */
export function bestSrc(img) {
  let best = img.getAttribute('src') ? img.src : img.currentSrc, bw = 0;
  for (const part of (img.getAttribute('srcset') || '').split(',')) {
    const [u, d] = part.trim().split(/\s+/);
    const w = d && /w$/.test(d) ? parseFloat(d) : 0;
    if (u && w > bw && w <= 2400) { bw = w; best = new URL(u, document.baseURI).href; }
  }
  return best || img.currentSrc || img.src;
}
/** CSS object-position ("50% 30%", "center top", "left") as [x, y] 0..1; null when it says nothing usable */
export function parsePosition(v) {
  const words = String(v || '').trim().toLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return null;
  const K = { left: [0, null], right: [1, null], top: [null, 0], bottom: [null, 1], center: [null, null] };
  const out = [null, null];
  let axis = 0;
  for (const w of words.slice(0, 2)) {
    if (w.endsWith('%')) { out[axis] = clamp(parseFloat(w) / 100, 0, 1); axis = 1; continue; }
    const k = K[w];
    if (!k) { axis = 1; continue; } // a length (px): no fraction to take from it
    if (k[0] != null) out[0] = k[0];
    else if (k[1] != null) out[1] = k[1];
    axis = 1;
  }
  return out[0] == null && out[1] == null && !words.includes('center') ? null : [out[0] ?? 0.5, out[1] ?? 0.5];
}

// lightness: the cube root of luminance (sRGB squared as its linear light), which is OKLab L for a
// grey and close to it for a colour; the shaders use the same formula (pk_L), one pow per sample
function okL(r, g, b) {
  return Math.cbrt((0.2126 * r * r + 0.7152 * g * g + 0.0722 * b * b) / 65025);
}

const analyses = new WeakMap();
/**
  The photograph's tonal range: the 1st and 99th percentile of its OKLab lightness, from a small
  copy, so a pale photograph (a white room) still spans the whole tone scale of an effect.
*/
export function analyse(img) {
  if (analyses.has(img)) return analyses.get(img);
  let out = { levels: [0, 1], mean: 0.5 };
  try {
    const w = 160, h = Math.max(1, Math.round((160 * img.naturalHeight) / img.naturalWidth));
    const c = document.createElement('canvas');
    c.width = w; c.height = h;
    const g = c.getContext('2d', { willReadFrequently: true });
    g.drawImage(img, 0, 0, w, h);
    const d = g.getImageData(0, 0, w, h).data;
    const hist = new Uint32Array(256);
    let sum = 0;
    for (let i = 0; i < d.length; i += 4) { const L = okL(d[i], d[i + 1], d[i + 2]); hist[Math.min(255, (L * 255) | 0)]++; sum += L; }
    const n = d.length / 4;
    const pct = q => { let acc = 0; for (let i = 0; i < 256; i++) { acc += hist[i]; if (acc >= q * n) return i / 255; } return 1; };
    out = { levels: [pct(0.01), Math.max(pct(0.99), pct(0.01) + 0.1)], mean: sum / n };
  } catch (_) { /* a tainted image: keep the full range */ }
  analyses.set(img, out);
  return out;
}

const palettes = new WeakMap();
const srgbLin = v => (v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4));
function toOklab(r, g, b) {
  r = srgbLin(r / 255); g = srgbLin(g / 255); b = srgbLin(b / 255);
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  return [0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s, 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s, 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s];
}
/**
  The photograph's own palette: n colours (OKLab, darkest first) from k-means on a small copy, with its
  darkest and lightest kept, so a dither in them spans the whole picture. Made once per image.
*/
export function photoPalette(img, n = 8) {
  const key = img && palettes.get(img);
  if (key && key.length === n) return key;
  let out = null;
  try {
    const w = 96, h = Math.max(1, Math.round((96 * img.naturalHeight) / img.naturalWidth));
    const c = document.createElement('canvas');
    c.width = w; c.height = h;
    const g = c.getContext('2d', { willReadFrequently: true });
    g.drawImage(img, 0, 0, w, h);
    const d = g.getImageData(0, 0, w, h).data;
    const pts = [];
    for (let i = 0; i < d.length; i += 4) pts.push(toOklab(d[i], d[i + 1], d[i + 2]));
    const dist = (a, b) => (a[0] - b[0]) ** 2 + (a[1] - b[1]) ** 2 + (a[2] - b[2]) ** 2;
    // seeds: the darkest, the lightest, then k-means++ (seeded, so a picture always gets one palette)
    const r = fx.rng('photo-kit:palette');
    const byL = pts.slice().sort((a, b) => a[0] - b[0]);
    const cent = [byL[Math.floor(byL.length * 0.01)].slice(), byL[Math.floor(byL.length * 0.99)].slice()];
    while (cent.length < n) {
      const dd = pts.map(p => Math.min(...cent.map(q => dist(p, q))));
      let x = r() * dd.reduce((s, v) => s + v, 0), k = 0;
      for (; k < pts.length - 1 && (x -= dd[k]) > 0; k++);
      cent.push(pts[k].slice());
    }
    for (let it = 0; it < 10; it++) {
      const sum = cent.map(() => [0, 0, 0, 0]);
      for (const p of pts) {
        let best = 0, bv = Infinity;
        for (let j = 0; j < n; j++) { const v = dist(p, cent[j]); if (v < bv) { bv = v; best = j; } }
        const s = sum[best]; s[0] += p[0]; s[1] += p[1]; s[2] += p[2]; s[3]++;
      }
      // the two ends stay at the picture's extremes; the others move to their clusters' middles
      for (let j = 2; j < n; j++) if (sum[j][3]) cent[j] = [sum[j][0] / sum[j][3], sum[j][1] / sum[j][3], sum[j][2] / sum[j][3]];
    }
    out = cent.sort((a, b) => a[0] - b[0]);
  } catch (_) { /* a tainted image: no palette */ }
  if (out && img) palettes.set(img, out);
  return out;
}

const statsCache = new WeakMap();
/** edge density (r) and lightness (g) of the photograph at 512 x 512, for detail-led effects */
function statsOf(img) {
  if (statsCache.has(img)) return statsCache.get(img);
  const W = 512, H = 512;
  const c = document.createElement('canvas');
  c.width = W; c.height = H;
  const g = c.getContext('2d', { willReadFrequently: true });
  g.drawImage(img, 0, 0, W, H);
  let d;
  try { d = g.getImageData(0, 0, W, H).data; } catch (_) { statsCache.set(img, null); return null; }
  const L = new Float32Array(W * H);
  for (let i = 0; i < W * H; i++) L[i] = okL(d[i * 4], d[i * 4 + 1], d[i * 4 + 2]);
  const out = new Uint8Array(W * H * 4);
  const at = (x, y) => L[clamp(y, 0, H - 1) * W + clamp(x, 0, W - 1)];
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const gx = at(x + 1, y - 1) + 2 * at(x + 1, y) + at(x + 1, y + 1) - at(x - 1, y - 1) - 2 * at(x - 1, y) - at(x - 1, y + 1);
      const gy = at(x - 1, y + 1) + 2 * at(x, y + 1) + at(x + 1, y + 1) - at(x - 1, y - 1) - 2 * at(x, y - 1) - at(x + 1, y - 1);
      const o = ((H - 1 - y) * W + x) * 4; // flipped, like the photograph's texture
      out[o] = clamp(Math.round(Math.hypot(gx, gy) * 255 * 1.6), 0, 255);
      out[o + 1] = Math.round(L[y * W + x] * 255);
      out[o + 3] = 255;
    }
  }
  const s = { data: out, width: W, height: H };
  statsCache.set(img, s);
  return s;
}

/* ------------------------------------------------------------------ blue noise */

let blueCache = null;
/**
  A 64 x 64 blue-noise threshold map (void and cluster: Gaussian energy on a torus, sigma 1.5), as
  RGBA bytes with the rank in every channel. Made once per page, in about 0.1 s.
*/
export function blueNoise() {
  if (blueCache) return blueCache;
  const n = 64, N = n * n, sigma = 1.5;
  const ker = new Float32Array(N);
  for (let y = 0; y < n; y++) for (let x = 0; x < n; x++) {
    const dx = Math.min(x, n - x), dy = Math.min(y, n - y);
    ker[y * n + x] = Math.exp(-(dx * dx + dy * dy) / (2 * sigma * sigma));
  }
  const splat = (E, i, s) => {
    const ix = i % n, iy = (i / n) | 0;
    for (let y = 0; y < n; y++) {
      const ky = ((y - iy + n) % n) * n, row = y * n;
      for (let x = 0; x < n; x++) E[row + x] += s * ker[ky + ((x - ix + n) % n)];
    }
  };
  const extreme = (E, bits, want, max) => {
    let best = -1, bv = max ? -Infinity : Infinity;
    for (let i = 0; i < N; i++) if (bits[i] === want && (max ? E[i] > bv : E[i] < bv)) { bv = E[i]; best = i; }
    return best;
  };
  const r = fx.rng('photo-kit:blue');
  const bits = new Uint8Array(N), E = new Float32Array(N);
  const m = Math.round(N * 0.1);
  for (let k = 0; k < m;) { const i = Math.floor(r() * N); if (!bits[i]) { bits[i] = 1; splat(E, i, 1); k++; } }
  // spread the starting points: move the tightest cluster into the largest void until it settles
  for (let guard = 0; guard < N; guard++) {
    const c = extreme(E, bits, 1, true); bits[c] = 0; splat(E, c, -1);
    const v = extreme(E, bits, 0, false);
    if (v === c) { bits[c] = 1; splat(E, c, 1); break; }
    bits[v] = 1; splat(E, v, 1);
  }
  const rank = new Uint16Array(N);
  // ranks below the start: take ones away from the tightest clusters
  const b1 = bits.slice(), E1 = E.slice();
  for (let k = m - 1; k >= 0; k--) { const c = extreme(E1, b1, 1, true); b1[c] = 0; splat(E1, c, -1); rank[c] = k; }
  // ranks above: fill the largest voids
  for (let k = m; k < N; k++) { const v = extreme(E, bits, 0, false); bits[v] = 1; splat(E, v, 1); rank[v] = k; }
  const data = new Uint8Array(N * 4);
  for (let i = 0; i < N; i++) { const v = Math.floor((rank[i] * 256) / N); data[i * 4] = data[i * 4 + 1] = data[i * 4 + 2] = v; data[i * 4 + 3] = 255; }
  blueCache = { data, width: n, height: n, filter: 'nearest', wrap: 'repeat', key: 'blue64' };
  return blueCache;
}

/* ------------------------------------------------------------------ GLSL */

export const PK_LIB = /* glsl */ `
#if __VERSION__ >= 300
#define PK_LOD(s, u, l) textureLod(s, u, l)
#define PK_FW(x) fwidth(x)
#define PK_FOR(i, n, most) for (int i = 0; i < int(n); i++)
#else
#ifdef PK_LOD_EXT
#define PK_LOD(s, u, l) texture2DLodEXT(s, u, l)
#else
#define PK_LOD(s, u, l) texture2D(s, u)
#endif
#ifdef GL_OES_standard_derivatives
#define PK_FW(x) fwidth(x)
#else
#define PK_FW(x) (0.0 * (x) + 0.03)
#endif
#define PK_FOR(i, n, most) for (int i = 0; i < most; i++) if (float(i) < (n))
#endif

// the photograph's window: object-fit cover at u_focus, zoomed about the window's middle
vec2 pk_vis() {
  float asp = u_res.x / u_res.y, ir = u_imgRes.x / max(1.0, u_imgRes.y);
  return asp > ir ? vec2(1.0, ir / asp) : vec2(asp / ir, 1.0);
}
// canvas pixels (y up) to the photograph's uv (y up)
vec2 pk_uv(vec2 px) {
  vec2 vis = pk_vis();
  vec2 lo = (1.0 - vis) * u_focus;
  vec2 c = lo + 0.5 * vis;
  return c + (lo + px / u_res * vis - c) / u_zoom;
}
// texels of the photograph's texture per canvas pixel
float pk_tpp() { return u_texRes.x * pk_vis().x / (u_res.x * u_zoom); }
// the mip level that averages a square of px canvas pixels
float pk_lod(float px) { return log2(max(px * pk_tpp(), 1.0)); }
// the photograph averaged over a square of px canvas pixels around canvas point p
vec3 pk_photo(vec2 p, float px) { return PK_LOD(u_img, pk_uv(p), pk_lod(px)).rgb; }
// the photograph at full detail (an explicit level: implicit ones are undefined inside branches)
vec3 pk_sharp(vec2 p) { return PK_LOD(u_img, pk_uv(p), log2(max(pk_tpp(), 1.0))).rgb; }
// OKLab lightness stretched over the photograph's own range: 0 its darkest, 1 its lightest
float pk_L(vec3 c) { return pow(max(dot(c * c, vec3(0.2126, 0.7152, 0.0722)), 1e-6), 0.3333333); }
float pk_tone(vec3 c) { return clamp((pk_L(c) - u_levels.x) / max(0.05, u_levels.y - u_levels.x), 0.0, 1.0); }
// the tone of colour c read at canvas point p over a footprint of foot px, after the object's own
// tone params when it has them: clarity (local contrast against the picture around it, so a cream
// lamp still parts from a white wall), exposure and contrast (a soft S curve)
float pk_shadeOf(vec3 c, vec2 p, float foot) {
  float t = pk_tone(c);
#ifdef PK_HAS_clarity
  float tb = pk_tone(pk_photo(p, foot * 9.0));
  t += u_clarity * 1.4 * (t - tb);
#endif
#ifdef PK_HAS_exposure
  t += u_exposure * 0.3;
#endif
  t = clamp(t, 0.0, 1.0);
#ifdef PK_HAS_contrast
  t = mix(t, t * t * (3.0 - 2.0 * t), u_contrast);
#endif
  // on dark paper the light parts are inked: hold the highlights back, so a pale photograph sits in a
  // dark (or strongly coloured) page as a lit print instead of glaring out of it as a white block
  if (u_paperLight < 0.5) t *= 0.8;
  return t;
}
// the tone as light (linear): screens, dots, lines and dither mix paper and ink as light, so a tone's
// share of ink is worked out on this scale, or the light parts print far too pale
float pk_lin(float t) { return pow(clamp(t, 0.0, 1.0), 2.0); }
// the share of ink a tone takes on this paper, as light (dark paper: the light parts are inked)
float pk_ink(float t) { return u_paperLight > 0.5 ? 1.0 - pk_lin(t) : pk_lin(t); }

// ---- the print, shared by the three objects. A point's state m runs 0 (the photograph itself) ..
// 0.5 (the full print) .. 1 (bare paper). Each print matches the photograph's average colour, so the
// photograph turns into it without a halo: only the texture comes in.
const vec3 PK_Y = vec3(0.2126, 0.7152, 0.0722);
// how far a canvas point lies inside the picture from its printed edge: 0 at that edge, 1 across the
// frame (side 0 left, 1 right, 2 bottom, 3 top) or at the middle (side 4: every edge, round corners)
float pk_inset(vec2 p) {
  vec2 uv = p / u_res;
#ifdef PK_HAS_side
  float sd = u_side;
#else
  float sd = 0.0;
#endif
  if (sd < 0.5) return uv.x;
  if (sd < 1.5) return 1.0 - uv.x;
  if (sd < 2.5) return uv.y;
  if (sd < 3.5) return 1.0 - uv.y;
  vec2 q = 1.0 - min(p, u_res - p) / (0.5 * min(u_res.x, u_res.y));
  return 1.0 - length(max(q, 0.0));
}
// the state at rest: the print takes the share u_print of the picture from its printed edge and thins
// toward bare paper at the very edge (u_fade); the light parts give way a little first and a faint
// noise keeps the boundary from reading as a ruled line. print 0: the plain photograph; 1: all print
float pk_rest(vec2 p, float tone) {
#ifdef PK_HAS_print
  if (u_print <= 0.001) return 0.0;
  if (u_print >= 0.999) return 0.5;
  float n = fx_vnoise(p / (min(u_res.x, u_res.y) * 0.2) + 7.0) - 0.5;
  float lead = u_paperLight > 0.5 ? tone : 1.0 - tone;
  float r = pk_inset(p) / u_print + 0.16 * n - 0.16 * (lead - 0.5);
#ifdef PK_HAS_fade
  float edge = 0.5 + 0.5 * u_fade;
#else
  float edge = 0.75;
#endif
  return edge * (1.0 - smoothstep(0.0, 1.0, r));
#else
  return 0.5;
#endif
}
// under the cursor the picture turns over: the plain photograph prints, the print develops
float pk_flip(float m) { return 0.5 * (1.0 - smoothstep(0.12, 0.42, m)); }
// colour c read at canvas point p over foot px, with the object's clarity, exposure and contrast
// applied to its lightness, its hue kept (all 0: c itself, so the print matches the photograph)
vec3 pk_steer(vec3 c, vec2 p, float foot) {
