    else if (v.length === 4) gl.uniform4f(l, v[0], v[1], v[2], v[3]);
  }

  /* ---------- pointer, trail and entry, eased per frame */
  function step(t, dt) {
    const now = performance.now();
    if (wander && now - ptr.user > 4000 && width > 0) {
      // touch screens have no hover: a slow loupe wanders through the picture now and then
      const c = (t % 14) / 14;
      ptr.tx = width * (0.5 + 0.3 * Math.sin(t * 0.21));
      ptr.ty = height * (0.5 + 0.26 * Math.sin(t * 0.29 + 1.3));
      ptr.th = c > 0.08 && c < 0.55 ? 0.9 : 0;
      if (!ptr.seen) { ptr.x = ptr.tx; ptr.y = ptr.ty; ptr.seen = true; }
    }
    if (dt > 0) {
      const k = 1 - Math.exp(-dt * 11);
      const px = ptr.x, py = ptr.y;
      ptr.x += (ptr.tx - ptr.x) * k;
      ptr.y += (ptr.ty - ptr.y) * k;
      const kv = 1 - Math.exp(-dt * 6);
      ptr.vx += ((ptr.x - px) / dt - ptr.vx) * kv;
      ptr.vy += ((ptr.y - py) / dt - ptr.vy) * kv;
      const rate = ptr.th > ptr.h ? 5.5 : 2.4;
      ptr.h += (ptr.th - ptr.h) * (1 - Math.exp(-dt * rate));
      if (Math.abs(ptr.th - ptr.h) < 0.002) ptr.h = ptr.th;
      if (trailN) {
        for (const q of trail) q.s *= Math.exp(-dt / 0.5);
        if (Math.hypot(ptr.x - trailLast.x, ptr.y - trailLast.y) > 10 && t - trailLast.t > 0.04 && (ptr.th > 0 || ptr.h > 0.05)) {
          const q = trail[trailHead];
          // a quick stroke marks its path at once, before the hover has eased in
          q.x = ptr.x; q.y = ptr.y; q.s = Math.max(ptr.h, ptr.th * 0.85) * clamp(Math.hypot(ptr.vx, ptr.vy) / 700, 0.3, 1);
          trailHead = (trailHead + 1) % trailN;
          trailLast = { x: ptr.x, y: ptr.y, t };
        }
      }
      if (inViewEnough) enterT += dt;
    }
  }
  const enterAmt = () => (reduced() || config.clock != null || entrySecs <= 0 ? 1 : clamp(enterT / entrySecs, 0, 1));

  function draw(t, dt) {
    if (fallbackOn || !ready) return;
    if (released) { if (!lc.visible) return; init(); if (fallbackOn || !gl) return; fit(false); }
    if (!gl || lost || !prog) return;
    holder.seen = performance.now();
    if (!finish()) { if (pending && !lc.running) setTimeout(() => lc.redraw(), 50); return; }
    step(t, dt);
    gl.viewport(0, 0, canvas.width, canvas.height);
    gl.useProgram(prog);
    if (dirty) {
      for (const [u, k] of Object.entries(PAL)) setU(u, color.rgb(palette[k]));
      setU('u_paperLight', color.lab(palette.bg)[0] >= color.lab(palette.ink)[0] ? 1 : 0);
      for (const k of paramKeys) setU('u_' + k, params[k]);
      for (const [k, v] of Object.entries(custom)) setU(k, v);
      setU('u_seed', seed);
      setU('u_fit', fitAmt());
      setU('u_imgRes', [img.naturalWidth, img.naturalHeight]);
      setU('u_texRes', [srcTex.width, srcTex.height]);
      const [fxp, fyp] = focus();
      setU('u_focus', [fxp, 1 - fyp]);
      setU('u_levels', info0.levels);
      bindTextures();
      dirty = false;
    }
    const cs = canvas.width / Math.max(1, width);
    setU('u_time', t);
    setU('u_res', [canvas.width, canvas.height]);
    setU('u_frame', [width, height]);
    setU('u_dpr', cs);
    setU('u_enter', enterAmt());
    setU('u_zoom', spec.zoom ? spec.zoom(t, params) : 1);
    setU('u_mouse', [ptr.x * cs, (height - ptr.y) * cs, ptr.h]);
    setU('u_vel', [ptr.vx * cs, -ptr.vy * cs]);
    if (trailN) {
      const l = locs['u_trail[0]'] || locs.u_trail;
      if (l) {
        const a = new Float32Array(trailN * 3);
        trail.forEach((q, i) => { a[i * 3] = q.x * cs; a[i * 3 + 1] = (height - q.y) * cs; a[i * 3 + 2] = q.s; });
        gl.uniform3fv(l, a);
      }
    }
    gl.drawArrays(gl.TRIANGLES, 0, 3);
    if (!shown) { shown = true; canvas.style.opacity = '1'; }
    if (dt > 0) {
      frames++; fpsT += dt;
      if (fpsT >= 1) { fps = frames / fpsT; frames = 0; fpsT = 0; }
      if (config.adaptive && lc.running) adapt(dt);
    }
  }

  function adapt(dt) {
    if (perf.warm < 60) { perf.warm++; return; }
    perf.n++; perf.sum += dt;
    if (perf.n < 90) return;
    const avg = perf.sum / perf.n;
    perf.n = perf.sum = 0;
    // under about 55 fps the canvas renders smaller, down to 0.6 of its scale (a crisp object keeps its own)
    if (avg > 1 / 55) {
      if (!crisp && scale > 0.62) { scale = Math.max(0.6, scale * 0.82); fit(false); }
    }
  }

  function fit(redraw) {
    width = el.clientWidth; height = el.clientHeight;
    if (fallbackOn || !canvas) return;
    const s = renderScale(width, height, { crisp, heavy: !!spec.heavy, maxScale: spec.maxScale || MAX_SCALE }) * (crisp ? 1 : scale);
    const W = Math.max(1, Math.round(width * s)), H = Math.max(1, Math.round(height * s));
    if (canvas.width !== W || canvas.height !== H) {
      px = s;
      canvas.width = W; canvas.height = H;
      // pixelated only where the screen shows each canvas px as whole device px; else a soft upscale
      const ratio = (window.devicePixelRatio || 1) / s;
      canvas.style.imageRendering = crisp && Math.abs(ratio - Math.round(ratio)) < 0.02 ? 'pixelated' : 'auto';
      rebuild();
    }
    if (redraw !== false) lc.redraw();
  }

  /* ---------- pointer events */
  const local = e => { const r = el.getBoundingClientRect(); return [e.clientX - r.left, e.clientY - r.top]; };
  function aim(x, y, h) {
    ptr.tx = x; ptr.ty = y; ptr.th = h; ptr.user = performance.now();
    if (!ptr.seen || ptr.h < 0.02) { ptr.x = x; ptr.y = y; ptr.seen = true; }
    lc.sync(); // a still picture starts its frames again
    if (!lc.running) { ptr.x = x; ptr.y = y; ptr.h = h; lc.redraw(); }
  }
  const onMove = e => { const [x, y] = local(e); aim(x, y, 1); };
  const onLeave = e => {
    if (e && e.pointerType && e.pointerType !== 'mouse') return; // a finger lifting: the hold timer ends it
    ptr.th = 0; ptr.user = performance.now(); if (!lc.running) { ptr.h = 0; for (const q of trail) q.s = 0; lc.redraw(); } };
  const onDown = e => {
    if (e.pointerType === 'mouse') return;
    const [x, y] = local(e);
    aim(x, y, 1);
    clearTimeout(ptr.touchTimer);
    ptr.touchTimer = setTimeout(onLeave, 1600);
  };
  el.addEventListener('pointermove', onMove, { passive: true });
  el.addEventListener('pointerleave', onLeave, { passive: true });
  el.addEventListener('pointerdown', onDown, { passive: true });

  const holder = {
    seen: 0,
    get visible() { return lc.visible; },
    // the CSS px of its frame inside the window
    shown() { const r = el.getBoundingClientRect(); return Math.max(0, Math.min(r.bottom, innerHeight) - Math.max(r.top, 0)) * Math.max(0, Math.min(r.right, innerWidth) - Math.max(r.left, 0)); },
    release() { if (canvas && !released) { teardown(); released = true; } },
  };

  const lc = lifecycle(el, {
    draw,
    idle: () => fallbackOn || (ready && quiet()),
    still: spec.still ?? 6,
    onShow() { clearTimeout(hideTimer); holder.seen = performance.now(); if (released && ready && !fallbackOn) { init(); fit(false); } },
    // off screen for 1.5 s: the context goes, so a long page never holds more than the screen shows
    onHide() { clearTimeout(hideTimer); hideTimer = setTimeout(() => { if (!lc.visible) holder.release(); }, 1500); },
  });

  // the entry runs once the object is a quarter on screen (the lifecycle starts drawing a little before)
  const io = new IntersectionObserver(es => { inViewEnough = es[es.length - 1].intersectionRatio >= 0.2 || es[es.length - 1].intersectionRect.height > 200; }, { threshold: [0, 0.2, 0.5] });
  io.observe(el);
  const ro = new ResizeObserver(() => fit(true));
  ro.observe(el);

  width = el.clientWidth; height = el.clientHeight;
  if (!src) useFallback('no-image');
  else {
    loadImage(src).then(im => {
      if (destroyed) return;
      img = im;
      info0 = analyse(im);
      ready = true;
      if (lc.visible) { init(); fit(true); }
      lc.sync();
    }).catch(err => { console.warn(err.message + ' (shown as a plain photograph: its host sends no CORS headers, or it is missing)'); if (!destroyed) useFallback('no-cors'); });
  }

  let destroyed = false;
  return {
    pause: () => lc.pause(),
    resume: () => lc.resume(),
    redraw: () => lc.redraw(),
    set(next) {
      for (const k of Object.keys(next || {})) given.add(k);
      params = resolveParams(schema, { ...params, ...next });
      rebuild();
      if (fallbackOn) useFallback(el.dataset.pkFallback || 'fallback');
      lc.redraw();
      return params;
    },
    setPalette(p) {
      palette = normalizePalette(p);
      el.style.backgroundColor = palette.bg;
      if (fb) greyLook(fb);
      rebuild();
      if (fallbackOn) useFallback(el.dataset.pkFallback || 'fallback');
      lc.redraw();
    },
    /** GPU time of one frame in ms, averaged over n frames drawn back to back (hover on: the loupe's cost too) */
    bench(n = 60, hover = true) {
      if (!gl || !prog || pending || fallbackOn) return null;
      const keep = { ...ptr };
      if (hover) { ptr.x = ptr.tx = width * 0.5; ptr.y = ptr.ty = height * 0.5; ptr.h = ptr.th = 1; }
      const px = new Uint8Array(4), t = lc.time;
      draw(t, 0);
      gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);
      const t0 = performance.now();
      for (let i = 0; i < n; i++) draw(t + i / 60, 0);
      gl.readPixels(0, 0, 1, 1, gl.RGBA, gl.UNSIGNED_BYTE, px);
      const ms = (performance.now() - t0) / n;
      Object.assign(ptr, keep);
      return Math.round(ms * 100) / 100;
    },
    /** restart the entry animation (demos) */
    replay() { enterT = 0; lc.sync(); lc.redraw(); },
    destroy() {
      destroyed = true;
      lc.destroy();
      io.disconnect();
      ro.disconnect();
      clearTimeout(ptr.touchTimer);
      clearTimeout(hideTimer);
      clearTimeout(deferTimer);
      el.removeEventListener('pointermove', onMove);
      el.removeEventListener('pointerleave', onLeave);
      el.removeEventListener('pointerdown', onDown);
      teardown();
      if (fb && fb !== imgEl) fb.remove();
      if (imgEl) imgEl.style.cssText = imgCss;
      delete el.dataset.pkFallback;
    },
    get canvas() { return canvas; },
    get info() {
      return { webgl: gl ? (gl2 ? 2 : 1) : 0, fallback: fallbackOn ? el.dataset.pkFallback : null, scale: px, live: livePK.size, size: canvas ? [canvas.width, canvas.height] : null, running: lc.running, fps: Math.round(fps * 10) / 10, levels: info0.levels, enter: enterAmt(), compileMs };
    },
  };
}

/** the three palette tones of a print, darkest first, as sRGB 0..1: paper and ink at the ends, the mid between */
export function printTones(P, midFrom = 'accent', midMix = 1) {
  const L = c => color.lab(c)[0];
  const light = L(P.bg) >= L(P.ink);
  const paper = P.bg, ink = P.ink;
  // the middle tone is the accent held between paper and ink in lightness, so the scale stays in order
  let mid = midFrom === 'muted' ? P.muted : P.accent;
  const lo = Math.min(L(paper), L(ink)), hi = Math.max(L(paper), L(ink));
  const Lm = clamp(L(mid), lo + 0.22 * (hi - lo), lo + 0.72 * (hi - lo));
  mid = color.mix(color.mix(paper, ink, 0.5), color.withLightness(mid, Lm), midMix);
  const order = light ? [ink, mid, paper] : [paper, mid, ink];
  const out = order.map(c => color.rgb(c));
  // where the middle tone sits between the darkest and the lightest, as light (0..1)
  out.midPos = Math.pow(clamp((color.lab(mid)[0] - lo) / Math.max(1e-3, hi - lo), 0, 1), 2);
  return out;
}

const escHTML = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[c]);
/**
  The credit a photograph needs, as HTML: the author linked to the source, the licence linked to its
  deed, where it came from, and "adapted" (a print changes the picture, which CC BY-SA asks to be
  said). p: an entry of the site's assets/img/credits.json (written by scripts/photos.mjs fetch), of the
  skill's photos.json, or of photo-kit/photos.json: { by, page, licence, licenceUrl, source }. The
  client's own photograph has no `by` and needs no credit: ''.
    photoCredit(p) -> 'Photo: <a href="...">LoMit</a>, <a href="...">CC BY-SA 4.0</a>, via Wikimedia Commons, adapted'
  It goes in the page's one credits line in the footer (photos.mjs credits --out <site> --adapted <id>
  writes the whole line, or creditsLine() below), never as a caption under the picture.
*/
export function photoCredit(p, { adapted = true, prefix = 'Photo: ' } = {}) {
  if (!p || !p.by) return '';
  const a = (href, text) => (href ? `<a href="${escHTML(href)}" target="_blank" rel="noopener">${escHTML(text)}</a>` : escHTML(text));
  const src = String(p.source || '').toLowerCase();
  // an Unsplash photograph is credited "on Unsplash" (its licence asks for no more); others name their licence
  if (src.includes('unsplash')) return `${prefix}${a(p.page, p.by)} on Unsplash${adapted ? ', adapted' : ''}`;
  const lic = p.licence ? `, ${a(p.licenceUrl, p.licence)}` : '';
  return `${prefix}${a(p.page, p.by)}${lic}${src.includes('commons') ? ', via Wikimedia Commons' : ''}${adapted ? ', adapted' : ''}`;
}
/**
  The footer's one credits line for the photographs a page shows (entries as above; those printed
  through a photo object marked adapted, by `adapted: true` on the entry or their id in `adapted`):
    creditsLine(list, { adapted: ['d88'] }) -> 'Photographs: A on Unsplash; B, CC BY-SA 4.0, via Wikimedia Commons, adapted.'
  '' when none needs a credit (the client's own photographs).
*/
export function creditsLine(list, { adapted = [] } = {}) {
  const parts = (list || []).filter(p => p && p.by).map(p => photoCredit(p, { prefix: '', adapted: p.adapted ?? adapted.includes(p.id ?? p.key ?? p.file) }));
  return parts.length ? `Photographs: ${parts.join('; ')}.` : '';
}
/**
  A site footer's credits, in the form scripts/photos.mjs credits prints (one short line that opens the
  list), for photographs that did not come through photos.mjs; a printed one is marked adapted:
    creditsBlock(list, { adapted: ['d88'] }) -> '<details class="credits"><summary>Photographs via Wikimedia Commons</summary><p>...</p></details>'
  '' when none needs a credit (the client's own photographs).
*/
export function creditsBlock(list, { adapted = [] } = {}) {
  const ps = (list || []).filter(p => p && p.by);
  if (!ps.length) return '';
  const srcOf = p => (/unsplash/i.test(p.source || '') ? 'Unsplash' : /commons|wikimedia/i.test(p.source || '') ? 'Wikimedia Commons' : String(p.source || 'the web'));
  const set = [...new Set(ps.map(srcOf))].sort();
  const a = (href, text) => (href ? `<a href="${escHTML(href)}">${escHTML(text)}</a>` : escHTML(text));
  const items = ps.map(p => {
    const lic = srcOf(p) === 'Unsplash' || !p.licence ? '' : `, ${a(p.licenceUrl, p.licence)}`;
    const via = set.length > 1 ? (srcOf(p) === 'Unsplash' ? ' on Unsplash' : `, via ${escHTML(srcOf(p))}`) : '';
    const ad = (p.adapted ?? adapted.includes(p.id ?? p.key ?? p.file)) ? ', adapted' : '';
    return `<p>${a(p.page, p.by)}${lic}${ad}${via}</p>`;
  });
  return `<details class="credits"><summary>Photographs via ${escHTML(set.join(' and '))}</summary>\n  ${items.join('\n  ')}\n</details>`;
}

objects/photo-halftone/object.js:
// photo-halftone: a photograph printed whole as a one-ink halftone, the way a good magazine or poster
// prints it: round dots of the page's ink (or its accent) on the page's surface as paper (so the frame
// reads as a sheet), on one 45 degree screen, small in the light and merging into round holes in the
// shadows. The print has its own tone curve, so a light (high-key) photograph keeps clean paper where
// it is near white and solid ink in its deepest shadows instead of a grey veil of dots; clarity and a
// dotted outline from the photograph's edge map keep a pale object on a pale wall. The canvas
// renders up to 2 canvas px per CSS px, so the dots stay crisp on a sharp screen.
// Under the cursor (a tap on a phone) a loupe: a round lens with a hairline rim and a soft shadow shows
// the photograph itself, in its own colours, a little magnified. At rest it is still (no frames run).
// No entry animation: the print is there from its first frame, never half developed.
import { photoGL } from '../photo-kit/photo.js';

const params = {
  pitch:    { default: 5,    min: 3,   max: 16,  step: 0.5 },  // dot spacing, CSS px (finer in small frames; never under 4 canvas px)
  angle:    { default: 45,   min: 0,   max: 90,  step: 1 },    // the screen's angle, degrees
  tint:     { default: 0,    min: 0,   max: 1,   step: 1 },    // the dots' colour: 0 the page's ink, 1 its accent
  ground:   { default: 1,    min: 0,   max: 1,   step: 1 },    // the paper: 1 the page's surface (the frame reads as a print on its own sheet), 0 the page itself
  clean:    { default: 0.1,  min: 0,   max: 0.4, step: 0.01 }, // ink shares under this print no dot at all: the light parts stay clean paper
  outline:  { default: 0.4,  min: 0,   max: 1,   step: 0.01 }, // dots along the photograph's edges, so a pale object keeps its outline on a pale wall
  magnify:  { default: 1.35, min: 1,   max: 3,   step: 0.05 }, // the loupe's magnification of the photograph under it
  radius:   { default: 120,  min: 60,  max: 260, step: 1 },    // the loupe, CSS px (smaller in small frames)
  clarity:  { default: 0.3,  min: 0,   max: 1,   step: 0.01 }, // local contrast, so a pale object parts from a pale wall
  contrast: { default: 0.1,  min: 0,   max: 1,   step: 0.01 },
  exposure: { default: 0,    min: -1,  max: 1,   step: 0.01 },
  focusX:   { default: 0.5,  min: 0,   max: 1,   step: 0.01 }, // the subject's place (else the <img>'s object-position)
  focusY:   { default: 0.5,  min: 0,   max: 1,   step: 0.01 },
};

const frag = /* glsl */ `
// the screen: a sum of cosines, 1 at a dot's middle and -1 between dots (one dot per unit of s)
float spot(vec2 s) { return 0.5 * (cos(6.2831853 * s.x) + cos(6.2831853 * s.y)); }
// the spot level that inks a share c of the cell: round dots below 50%, round holes above
float level(float c) {
  float a = min(c, 1.0 - c);
  float t = 1.0 - 3.1415927 * a + 2.2831853 * a * a;
  return c <= 0.5 ? t : -t;
}
// ink coverage of the screen at screen point s for a share c; px: canvas px per dot there. Edges are
// antialiased over one canvas px; a dot under about a pixel across prints its tint instead of a speck
float screenAt(vec2 s, float c, float px) {
  if (c <= 0.002) return 0.0;
  if (c >= 0.998) return 1.0;
  float v = spot(s);
  vec2 sn = sin(6.2831853 * s);
  float g = 3.1415927 * length(sn) / px;
  float edge = clamp((v - level(c)) / max(g, 1e-4) + 0.5, 0.0, 1.0);
  float r = sqrt(min(c, 1.0 - c) / 3.1415927) * px;
  return mix(c, edge, smoothstep(0.45, 0.95, r));
}
// the print's tone curve: the share of ink for tone t (0 the photograph's darkest, 1 its lightest).
// Coverage follows the tone as seen (a 50% grey prints a 50% dot), so a light photograph does not
// print as a grey veil; shares under u_clean print nothing, the deepest few per cent print solid, and a
// slight curve keeps the shadows open (a dark bowl of beans keeps its beans)
float inkShare(float t) {
  float c = u_paperLight > 0.5 ? 1.0 - t : t;
  return pow(clamp((c - u_clean) / max(0.1, 0.97 - u_clean), 0.0, 1.0), 1.12);
}

void main() {
  vec2 p = gl_FragCoord.xy;
  float pitch = max(4.0, u_pitch * u_fit * u_dpr);
  float a = radians(u_angle);
  vec2 s = mat2(cos(a), sin(a), -sin(a), cos(a)) * p / pitch;
  // the tone over most of a dot's cell, with the print's clarity, exposure and contrast
  float t = pk_shadeOf(pk_photo(p, pitch * 0.7), p, pitch);
  float c = inkShare(t);
#ifdef PK_STATS
  // the photograph's edges (its Sobel map), read over about a dot: a pale shade on a pale wall, a white
  // bowl on a white table keep a dotted outline where the tone alone would print nothing
  float lodS = log2(max(pitch * 0.6 * 512.0 * pk_vis().x / (u_res.x * u_zoom), 1.0));
  c = max(c, u_outline * smoothstep(0.1, 0.45, PK_LOD(u_stats, pk_uv(p), lodS).r));
#endif
  float k = screenAt(s, c, pitch);
  vec3 inkC = mix(u_ink, u_accent, u_tint);
  vec3 paperC = pk_paper();
  vec3 col = fx_srgb(mix(fx_lin(paperC), fx_lin(inkC), k));

  // the loupe: a round lens that grows in with the hover and shows the photograph itself
  float h = u_mouse.z;
  float e = h * h * (3.0 - 2.0 * h);
  if (e > 0.001) {
    float R = u_radius * u_fit * u_dpr * mix(0.4, 1.0, e);
    vec2 v = p - u_mouse.xy;
    float d = length(v);
    if (d < R + 2.0) {
      float mg = mix(1.0, u_magnify, e);
      float rr = d / R;
      vec2 q = u_mouse.xy + v / mg * (1.0 + 0.06 * rr * rr);   // a faint barrel toward the rim
      vec3 lensCol = PK_LOD(u_img, pk_uv(q), log2(max(pk_tpp() / mg, 1.0))).rgb;
      float inside = 1.0 - smoothstep(R - 0.75 * u_dpr, R + 0.75 * u_dpr, d);
      col = mix(col, lensCol, inside * e);
      float rim = 1.0 - smoothstep(0.35 * u_dpr, 1.1 * u_dpr, abs(d - R));
      col = mix(col, u_paperLight > 0.5 ? u_ink : vec3(1.0), rim * 0.35 * e);
    }
    // the lens's soft shadow on the print
    float sh = smoothstep(R + 16.0 * u_dpr, R, d) * step(R, d);
    col = mix(col, vec3(0.0), sh * 0.12 * e);
  }
  fxColor = vec4(fx_dither(col), 1.0);
}
`;

export default {
  id: 'photo-halftone',
  name: 'Halftone photograph',
  kind: 'photo',
  params,
  frag,
  mount(el, { palette, src, params: given, seed } = {}) {
    return photoGL(el, {
      name: 'photo-halftone', frag, schema: params, params: given, palette, src, seed,
      entry: 0, maxScale: 2, stats: true,
    });
  },
};

objects/photo-engraving/object.js:
// photo-engraving: a photograph printed whole as a hand-coloured engraving: diagonal lines in the page's
// ink over a light wash of the picture's own colours on the page's surface as paper, each line swelling
// where the picture is dark and tapering to a hairline in the light, bent over the forms (offset by the
// softened picture, so they curve round a shade or a shoulder). A part lighter than the paper prints as
// bare paper and a colour cast in the light parts is let go. Under the cursor the lines part around it
// as under a lens and the photograph shows through, while the picture itself stays put. At rest it is
// still (no frames run) and there is no entry: the plate is finished from its first frame. colour 0
// leaves out the wash. Lines thinner than a device pixel are drawn a pixel wide and lighter, so they
// taper instead of breaking into dashes.
import { photoGL } from '../photo-kit/photo.js';

const params = {
  ground:   { default: 1,    min: 0,   max: 1,   step: 1 },    // the paper: 1 the page's surface (the frame reads as a print on its own sheet), 0 the page itself
  colour:   { default: 1,    min: 0,   max: 1,   step: 0.01 }, // the wash of the photograph's own colours under the lines (0: ink lines on bare paper)
  pitch:    { default: 4.5,  min: 3,   max: 12,  step: 0.5 },  // line spacing, CSS px (finer in small frames; never under 3.5 canvas px)
  angle:    { default: 30,   min: -90, max: 90,  step: 1 },    // degrees from horizontal
  bend:     { default: 0.6,  min: 0,   max: 1,   step: 0.01 }, // how far the forms bend the lines (1: up to about twelve line widths)
  push:     { default: 0.7,  min: 0,   max: 1,   step: 0.01 }, // how far the lines part around the cursor
  radius:   { default: 160,  min: 60,  max: 420, step: 1 },    // the lens, CSS px (smaller in small frames)
  light:    { default: 0,    min: 0,   max: 1,   step: 0.01 }, // a slow light passing over the plate at rest (0: still, no frames at rest)
  speed:    { default: 1,    min: 0,   max: 2,   step: 0.01 },
  clarity:  { default: 0.2,  min: 0,   max: 1,   step: 0.01 }, // local contrast in the lines, so a pale object parts from a pale wall
  contrast: { default: 0.1,  min: 0,   max: 1,   step: 0.01 },
  exposure: { default: 0,    min: -1,  max: 1,   step: 0.01 },
  focusX:   { default: 0.5,  min: 0,   max: 1,   step: 0.01 },
  focusY:   { default: 0.5,  min: 0,   max: 1,   step: 0.01 },
};

const frag = /* glsl */ `
// coverage of a set of lines at phase ph (one line per unit; fw: phase per canvas px) with half width
// w in lines. A line under a pixel wide is drawn a pixel wide and lighter, so its ink is kept and it
// tapers smoothly instead of breaking up.
float lines(float ph, float w, float fw) {
  if (w <= 0.0005) return 0.0;
  float d = abs(fract(ph) - 0.5);
  float wd = max(w, 0.55 * fw);
  float cov = clamp((wd - d) / fw + 0.5, 0.0, 1.0) - clamp((-wd - d) / fw + 0.5, 0.0, 1.0);
  return cov * (w / wd);
}

void main() {
  vec2 p = gl_FragCoord.xy;
  // a big frame (a hero) takes slightly wider lines, so they still read as engraved at its size
  float big = clamp(sqrt(min(u_frame.x, u_frame.y) / 560.0), 1.0, 1.25);
  float pitch = max(3.5, u_pitch * u_fit * big * u_dpr);
  float a = radians(u_angle);
  vec2 along = vec2(cos(a), sin(a)), across = vec2(-sin(a), cos(a));

  vec3 photo = pk_sharp(p);
  float m = pk_rest(p, pk_tone(pk_photo(p, pitch * 2.0)));

  // the lens: the picture turns over under the cursor, and the lines (not the picture) are read from
  // points pulled toward it, so they part around it
  float R = u_radius * u_fit * u_dpr;
  vec2 v = p - u_mouse.xy;
  float lens = u_mouse.z * exp(-dot(v, v) / (R * R * 0.45));
  m = mix(m, pk_flip(m), smoothstep(0.05, 0.6, lens));
  vec2 q = p - v * lens * u_push * 0.55;

  // the forms bend the lines: offset by the picture softened at two sizes, several line widths
  float B = 0.7 * pk_tone(pk_photo(q, pitch * 18.0)) + 0.3 * pk_tone(pk_photo(q, pitch * 6.0)) - 0.5;
  float k = dot(q, across) / pitch + u_bend * 12.0 * B;
  float fw = max(PK_FW(k), 1e-4);

  // entry (on load only): each line is cut in along its length, from its own moment
  if (u_enter < 1.0) {
    float pos = clamp(dot(p / u_res - 0.5, along) / (abs(along.x) + abs(along.y)) + 0.5, 0.0, 1.0);
    float e = u_enter * 1.7 - 0.45 * fx_hash(vec2(floor(k), 3.0)) - 0.95 * pos;
    m = mix(1.0, m, clamp(e * 14.0, 0.0, 1.0));
  }
  if (m <= 0.002) { fxColor = vec4(fx_dither(photo), 1.0); return; }

  // the picture over half a line (outlines stay crisp), steered by the tone params
  vec3 ph = pk_steer(pk_photo(p, pitch * 0.5), p, pitch);
  vec3 lab = fx_oklab(ph);
  // the wash: the picture's own colour, lightened toward the paper (darkened on dark paper); the lines
  // in the ink carry the rest of the tone, so lines and wash average back to the photograph
  float Lp = u_paperLab.x;
  // (never past the paper: a part lighter than the paper prints as bare paper, not as a whiter sheet)
  float Lw = u_paperLight > 0.5 ? min(max(lab.x, mix(lab.x, Lp, 0.5)), Lp) : max(min(lab.x, mix(lab.x, Lp, 0.5)), Lp);
  // the wash keeps the picture's colour in its body and lets a cast go in its light parts, so a white
  // table under cool light stays the paper's white instead of a blue-grey sheet
  vec3 washLab = mix(u_paperLab, vec3(Lw, lab.yz * mix(1.05, 0.35, smoothstep(0.72, 0.94, lab.x))), u_colour);
  float thin = smoothstep(0.5, 1.0, m);
  vec3 wash = clamp(fx_rgb(mix(washLab, u_paperLab, thin)), 0.0, 1.0);
  float Yw = dot(fx_lin(clamp(fx_rgb(washLab), 0.0, 1.0)), PK_Y), Yc = dot(fx_lin(ph), PK_Y), Yi = dot(fx_lin(u_ink), PK_Y);
  float den = Yw - Yi;
  float c = abs(den) < 1e-3 ? 0.0 : clamp((Yw - Yc) / den, 0.0, 1.0);
  c *= 1.0 - thin;
  // the slow light (off by default): a broad soft band that crosses the plate and thins the lines
  if (u_light > 0.0) {
    float u = 0.7 * p.x / u_res.x + 0.3 * (1.0 - p.y / u_res.y);
    float band = (u - (fract(u_time * u_speed / 20.0) * 2.2 - 0.6)) / 0.32;
    c *= 1.0 - u_light * 0.16 * exp(-band * band);
  }
  vec3 engraved = mix(wash, u_ink, lines(k, 0.5 * c, fw));
  // the engraving comes in over the photograph it matches
  fxColor = vec4(fx_dither(mix(photo, engraved, smoothstep(0.0, 0.5, m))), 1.0);
}
`;

export default {
  id: 'photo-engraving',
  name: 'Engraved photograph',
  kind: 'photo',
  params,
  frag,
  mount(el, { palette, src, params: given, seed } = {}) {
    return photoGL(el, {
      name: 'photo-engraving', frag, schema: params, params: given, palette, src, seed, entry: 0, maxScale: 2,
      uniforms: ({ palette: P, params: p, color }) => ({ u_paperLab: color.lab(p.ground > 0.5 ? P.surface : P.bg) }),
      restMotion: p => p.light > 0 && p.speed > 0,
    });
  },
};

objects/photo-dither/object.js:
// photo-dither: a photograph printed whole as a three-colour dither of crisp square cells, like a riso
// print of it: the picture's deepest colour, its most colourful one and the page's surface as paper
// (k-means over the picture finds them), the tone spread over the photograph's own range and dithered as
// light by a blue-noise threshold (an even grain) or the 8 x 8 Bayer cross-hatch (retro). Its near-whites
// print as clean paper (clean), so a white wall carries no stray grain. Under the cursor, and along a
// quick stroke's fading trail, the photograph develops through the grain with a grainy rim. At rest it is
// still (no frames run) and there is no entry: the print is finished from its first frame. colour 0
// dithers in the page's ink and accent.
import { photoGL, blueNoise, photoPalette } from '../photo-kit/photo.js';

const params = {
  colour:   { default: 1,    min: 0,   max: 1,   step: 1 },    // 1 the photograph's deepest and most colourful colours, 0 the page's ink and accent
  ground:   { default: 1,    min: 0,   max: 1,   step: 1 },    // the paper: 1 the page's surface (the frame reads as a print on its own sheet), 0 the page itself
  clean:    { default: 0.1,  min: 0,   max: 0.3, step: 0.01 }, // the lightest share of tones prints as bare paper (no stray dots in a white wall)
  tones:    { default: 3,    min: 2,   max: 3,   step: 1 },    // 3: ink, a colour and paper; 2: ink and paper
  cell:     { default: 2,    min: 1,   max: 10,  step: 1 },    // dither cell, CSS px: 1 a fine grain; 3 and up coarse and retro
  pattern:  { default: 1,    min: 0,   max: 1,   step: 1 },    // 1 blue noise (an even grain), 0 Bayer 8 x 8 (a retro cross-hatch)
  radius:   { default: 150,  min: 60,  max: 420, step: 1 },    // the turned-over area, CSS px at a 560 px frame (scales with the frame)
  breathe:  { default: 0,    min: 0,   max: 1,   step: 0.01 }, // the threshold's slow breathing at rest (0: still, no frames at rest)
  speed:    { default: 1,    min: 0,   max: 2,   step: 0.01 },
  clarity:  { default: 0.15, min: 0,   max: 1,   step: 0.01 }, // local contrast in the grain
  contrast: { default: 0.1,  min: 0,   max: 1,   step: 0.01 },
  exposure: { default: 0,    min: -1,  max: 1,   step: 0.01 },
  focusX:   { default: 0.5,  min: 0,   max: 1,   step: 0.01 }, // the part of the photograph kept in frame
  focusY:   { default: 0.5,  min: 0,   max: 1,   step: 0.01 },
};

const frag = /* glsl */ `
float thr(vec2 cell) {
  // the map's 256 levels as thresholds strictly inside 0..1 (its top level read as 1.0 would ink a
  // grain of the middle colour in bare paper: a sparse dust over every white wall)
  if (u_pattern > 0.5) return PK_LOD(u_noise, (cell + 0.5) / 64.0, 0.0).r * (255.0 / 256.0) + 0.5 / 256.0;
  return fx_bayer(cell) + 0.5 / 64.0;
}
// colour c printed in ink, the middle colour and paper, its luminance dithered as light at threshold th
vec3 print3(vec3 c, float th) {
  vec3 P = pk_paper();
  float Yi = dot(fx_lin(u_inkC), PK_Y), Yp = dot(fx_lin(P), PK_Y), Ym = dot(fx_lin(u_midC), PK_Y);
  // the share of paper: the tone over the photograph's own range (its lightest prints as bare paper, so
  // a light photograph never prints as a grey veil), as light; the tones nearest the paper (the lightest
  // u_clean on light paper, the darkest on dark) print no dot, so a white wall has no stray grain
  float t = pk_tone(c);
  float s = u_paperLight > 0.5 ? pk_lin(clamp(t / (1.0 - u_clean), 0.0, 1.0)) : 1.0 - pk_lin(clamp((t - u_clean) / (1.0 - u_clean), 0.0, 1.0));
  float sm = clamp((Ym - Yi) / (Yp - Yi), 0.05, 0.95);
  if (u_tones < 2.5) return s > th ? P : u_inkC;
  if (s < sm) return s / sm > th ? u_midC : u_inkC;
  return (s - sm) / (1.0 - sm) > th ? P : u_midC;
}
// the state at rest (with the breathing, when on), and on load the photograph developing out of the grain
float stateAt(vec2 c, float cs) {
  float m = pk_rest(c, pk_tone(pk_photo(c, cs * 4.0)));
  if (u_breathe > 0.0 && m > 0.002) {
    float s = u_time * u_speed;
    m += u_breathe * (0.04 * sin(s * 0.55) + 0.08 * fx_noise(c / (u_res.y * 0.45) + vec2(s * 0.03, -s * 0.018)));
  }
  if (u_enter < 1.0) {
    float dev = clamp(u_enter * 1.7 - 0.7 * fx_vnoise(c / (u_res.y * 0.11) + 3.1), 0.0, 1.0);
    m = mix(0.8, m, dev * dev * (3.0 - 2.0 * dev));
  }
  return clamp(m, 0.0, 1.0);
}

void main() {
  vec2 p = gl_FragCoord.xy;
  float cs = max(1.0, floor(u_cell * max(u_fit, 0.7) * u_dpr + 0.5));
  // the turned-over area scales with the frame, so it reads the same in a card and in a hero
  float R = u_radius * u_dpr * clamp(min(u_frame.x, u_frame.y) / 560.0, 0.75, 1.5);
  float f = pk_reach(p, R);
  // a grainy rim: the turn-over is decided cell by cell against the coarse cell's threshold
  float cs2 = cs * 2.0;
  float over = f > 0.001 ? step(thr(floor(p / cs2) + 17.0), f * 1.5 - 0.15) : 0.0;
  float s = over > 0.5 ? cs2 : cs;
  vec2 cell = floor(p / s);
  vec2 c = (cell + 0.5) * s;
  float m = stateAt(c, s);
  if (over > 0.5) m = pk_flip(m);
  vec3 photo = pk_sharp(p);
  // the photograph dissolves into the dither cell by cell, then the cells drop out into the paper
  if (m <= 0.002 || thr(cell + vec2(51.0, 13.0)) > smoothstep(0.0, 0.5, m) * 1.002) { fxColor = vec4(photo, 1.0); return; }
  if (thr(cell + vec2(23.0, 37.0)) < smoothstep(0.5, 1.0, m)) { fxColor = vec4(pk_paper(), 1.0); return; }
  vec3 cc = pk_steer(pk_photo(c, s), c, s);
  fxColor = vec4(print3(cc, thr(cell)), 1.0);
}
`;

const FLAT = { data: new Uint8Array([128, 128, 128, 255]), width: 1, height: 1, filter: 'nearest', wrap: 'repeat', key: 'flat' };
// the print's ink and middle colour (sRGB 0..1): from the photograph's palette, or the page's ink and
// accent (colour 0, or a photograph that cannot be read). The ink is the picture's deepest colour (its
// lightest on dark paper), held well apart from the paper; the middle is its most colourful one, held
// between ink and paper in lightness, so the scale stays in order
function inks(image, P, p, color) {
  const paper = color.lab(p.ground > 0.5 ? P.surface : P.bg), light = color.lab(P.bg)[0] >= color.lab(P.ink)[0];
  const pal = p.colour > 0.5 && image ? photoPalette(image, 8) : null;
  let ink = color.lab(P.ink), mid = color.lab(P.accent);
  if (pal) {
    ink = (light ? pal[0] : pal[pal.length - 1]).slice();
    const chroma = c => Math.hypot(c[1], c[2]);
    const inner = pal.slice(1, -1).sort((a, b) => chroma(b) - chroma(a));
    mid = inner[0] && chroma(inner[0]) > 0.035 ? inner[0].slice() : [(ink[0] + paper[0]) / 2, (ink[1] + paper[1]) / 2, (ink[2] + paper[2]) / 2];
  }
  // the ink at least 0.55 from the paper in lightness; the middle between, a quarter of the way in from each
  ink[0] = light ? Math.min(ink[0], paper[0] - 0.55) : Math.max(ink[0], paper[0] + 0.55);
  const lo = Math.min(ink[0], paper[0]), hi = Math.max(ink[0], paper[0]);
  mid[0] = Math.min(hi - 0.25 * (hi - lo), Math.max(lo + 0.25 * (hi - lo), mid[0]));
  return { u_inkC: color.rgb(color.fromLab ? color.fromLab(ink) : ink), u_midC: color.rgb(color.fromLab ? color.fromLab(mid) : mid) };
}

export default {
  id: 'photo-dither',
  name: 'Dithered photograph',
  kind: 'photo',
  params,
  frag,
  mount(el, { palette, src, params: given, seed } = {}) {
    return photoGL(el, {
      name: 'photo-dither', frag, schema: params, params: given, palette, src, seed,
      crisp: true, trail: 8, entry: 0,
      restMotion: p => p.breathe > 0 && p.speed > 0,
      uniforms: ({ image, palette: P, params: p, color }) => inks(image, P, p, color),
      textures: ({ params: p }) => ({ u_noise: p.pattern > 0.5 ? blueNoise() : FLAT }),
    });
  },
};

objects/exploded-layers/object.js:
/*
  exploded-layers - a real photograph taken apart into four printed sheets standing in perspective:
  the photograph on top, then a halftone screen in the accent, an ordered dither in the ink and a
  plate of tone contours at the bottom; the halftone and the dither are printed on clear sheets. One
  canvas for all four. For a page that explains layers or passes: print and photo work, imaging and
  design software, a product shown as what it is made of. Pass the client's own photograph, or up to
  four (one per sheet, top first), and name the sheets in the client's words.

  At rest the sheets lie in a neat stack a card's thickness apart, the photograph on top and the
  three below as plain card, large and drawn once. Hover: they open apart and their prints come up,
  the stack leans toward the pointer, and with `names` each sheet gets a label on a leader line from the middle
  of its right edge (where the panel is 560 px wide or more). Touch: tap opens, tap closes.

  src: a photograph (a path, a URL, a photos.json or library entry) or an array of up to four.
  params: names (four labels, top sheet first; no labels without them), labels (0 hides them),
  focusX / focusY (cover crop centre), aspect (sheet width / height, default the photograph's,
  clamped 1.2..1.6), alt.
*/
import { stage, tones, photoURL, loadImage, levels, cover, fallbackImage, approach, clamp, smooth, mat4, color, paletteOf, MONO } from '../_scenes/kit.js';

export const DEFAULT_PHOTO = { id: 304, ratio: 1.5, alt: 'A hand on the faders of a mixing desk', by: 'Drew Patrick Miller', licence: 'Unsplash licence', licenceUrl: 'https://unsplash.com/license', page: 'https://unsplash.com/photos/_o6AAx9dl_Y' };

const vert = /* glsl */ `
in vec2 a_pos;
uniform mat4 u_mvp;
out vec2 v_uv;
void main() {
  v_uv = a_pos * 0.5 + 0.5;
  gl_Position = u_mvp * vec4(a_pos, 0.0, 1.0);
}
`;

const frag = /* glsl */ `
uniform sampler2D u_img;
uniform vec4 u_fit;
uniform vec2 u_lv, u_plate;      // levels; sheet size in screen px (for line widths and the edge)
uniform float u_mode, u_dark, u_alpha, u_edge, u_reveal;
uniform vec3 u_bg, u_surface, u_ink, u_muted, u_acc;
in vec2 v_uv;

vec2 iuv(vec2 uv) { return u_fit.zw + vec2(uv.x, 1.0 - uv.y) * u_fit.xy; }
float lum(vec3 c) { return clamp((dot(c, vec3(0.2126, 0.7152, 0.0722)) - u_lv.x) / max(u_lv.y - u_lv.x, 0.05), 0.0, 1.0); }

void main() {
  vec2 uv = v_uv;
  vec4 col = vec4(0.0);
  float edgeD = min(min(uv.x, 1.0 - uv.x) * u_plate.x, min(uv.y, 1.0 - uv.y) * u_plate.y);
  float edge = 1.0 - smoothstep(0.6, 1.6, edgeD);
  if (u_mode < 0.5) {
    // contours of the photograph's tone on a solid plate
    float l = lum(texture(u_img, iuv(uv), 2.5).rgb);
    float v = l * 9.0 + 0.5;
    float fw = max(fwidth(v), 1e-4);
    float line = 1.0 - smoothstep(0.5, 1.4, abs(fract(v + 0.5) - 0.5) / fw);
    vec3 c = mix(u_surface, u_dark > 0.5 ? u_muted : u_ink, line * 0.75);
    col = vec4(c, 1.0);
  } else if (u_mode < 1.5) {
    // ordered dither in the ink, on a clear sheet
    vec2 cells = vec2(132.0, 132.0 * u_plate.y / u_plate.x);
    vec2 cid = floor(uv * cells);
    vec2 cuv = (cid + 0.5) / cells;
    float l = lum(texture(u_img, iuv(cuv), 1.0).rgb);
    float ink = u_dark > 0.5 ? l : 1.0 - l;
    float th = fx_bayer(cid);
    float v = ink * 2.0;
    float lvl = floor(v) + step(th + 1.0 / 128.0, fract(v));
    vec3 c = lvl > 1.5 ? u_ink : u_muted;
    float a = lvl > 0.5 ? 1.0 : 0.0;
    col = vec4(c * a, a);
    col += vec4(u_surface, 1.0) * 0.16 * (1.0 - col.a);
  } else if (u_mode < 2.5) {
    // a halftone screen in the accent, on a clear sheet
    vec2 px = uv * u_plate;
    float cell = max(7.0, u_plate.x / 74.0);
    float an = 0.785398;
    vec2 q = mat2(cos(an), -sin(an), sin(an), cos(an)) * px / cell;
    float l = lum(texture(u_img, iuv(uv), 1.8).rgb);
    // the halftone is the shadow plate on any page: dots where the photograph is dark
    float ink = smoothstep(0.08, 1.0, (1.0 - l) * 0.9);
    float f = 0.5 * (cos(6.2831853 * q.x) + cos(6.2831853 * q.y));
    float g = f - (1.0 - 2.0 * ink);
    float aa = max(fwidth(g), 1e-4) * 0.8;
    float a = smoothstep(-aa, aa, g) * smoothstep(0.02, 0.06, ink);
    col = vec4(u_acc * a, a);
    col += vec4(u_surface, 1.0) * 0.16 * (1.0 - col.a);
  } else {
    // the photograph
    col = vec4(texture(u_img, iuv(uv)).rgb, 1.0);
  }
  // closed, the sheets under the photograph are plain card, so the stack's edges read as paper; their
  // prints come up as they open
  if (u_mode < 2.5) col = mix(vec4(u_surface, 1.0), col, u_reveal);
  // a hairline round each sheet, and a soft outer pixel instead of multisampling
  vec3 ec = mix(u_bg, u_ink, 0.38);
  col = mix(col, vec4(ec, 1.0), edge * u_edge);
  fxColor = col * u_alpha * smoothstep(0.0, 1.0, edgeD);
}
`;

export default {
  id: 'exploded-layers',
  name: 'Exploded layers',
  kind: 'scene',
  mount(el, { palette, src, params = {} } = {}) {
    const list = (Array.isArray(src) ? src : [src || DEFAULT_PHOTO]).filter(Boolean).slice(0, 4);
    if (!list.length) list.push(DEFAULT_PHOTO);
    // sheet i (0 the bottom plate, 3 the photograph on top) prints photograph (3 - i) of the list, or the first
    const photoOf = i => Math.min(3 - i, list.length - 1);
    const first = list[0];
    const alt = params.alt || first.alt || '';
    let given = palette || null;
    let T = tones(paletteOf(el, given));
    const imgs = new Array(list.length).fill(null), lvs = new Array(list.length).fill([0, 1]);
    let texes = new Array(list.length).fill(null);
    let prog = null, quad = null;
    let open = 0, yaw = 0, pitch = 0, tapOpen = false, last = '';
    const urls = list.map(p => photoURL(p, 1280));
    const aspect = clamp(params.aspect || first.ratio || 1.5, 1.2, 1.6);
    const names = Array.isArray(params.names) ? params.names.slice(0, 4) : null;

    // labels on leader lines, only with the client's names for the sheets
    const labels = names ? names.map((n, k) => {
      const d = document.createElement('div');
      d.className = 'scene-label';
      d.setAttribute('aria-hidden', 'true');
      d.innerHTML = '<i></i><u></u><span></span>';
      d.querySelector('span').textContent = n;
      Object.assign(d.style, { position: 'absolute', left: '0', top: '0', zIndex: '2', display: 'flex', alignItems: 'center', pointerEvents: 'none',
        font: `500 12px/1 ${MONO}`, letterSpacing: '0.02em', whiteSpace: 'nowrap', opacity: '0', willChange: 'transform, opacity' });
      Object.assign(d.querySelector('i').style, { display: 'block', width: '5px', height: '5px', borderRadius: '50%', margin: '0 0 0 -2.5px', flex: 'none' });
      Object.assign(d.querySelector('u').style, { display: 'block', height: '1px', width: '40px', margin: '0 10px 0 0', flex: 'none' });
      el.append(d);
      return d;
    }) : [];
    const style = () => {
      labels.forEach(d => {
        d.style.color = T.hex.ink;
        d.querySelector('i').style.background = T.hex.ink;
        d.querySelector('u').style.background = color.mix(T.hex.bg, T.hex.ink, 0.45);
