          // reaches furthest right on screen), a leader straight out to the label column
          const L = labels[3 - i];
          if (!L) continue;
          if (lab) {
            const toCss = p => [(p[0] * 0.5 + 0.5) * st.cssW, (1 - (p[1] * 0.5 + 0.5)) * st.cssH];
            const corners = [[1, -1], [1, 1], [-1, 1], [-1, -1]].map(q => toCss(mat4.apply(m, [q[0], q[1], 0])));
            let e = 0;
            for (let j = 1; j < 4; j++) {
              const cx = (corners[j][0] + corners[(j + 1) % 4][0]) / 2, bx = (corners[e][0] + corners[(e + 1) % 4][0]) / 2;
              if (cx > bx) e = j;
            }
            const p0 = corners[e], p1 = corners[(e + 1) % 4];
            // the edge's point 60% of the way toward its right-hand end, so it clears the sheet above
            const r0 = p0[0] > p1[0] ? p1 : p0, r1 = p0[0] > p1[0] ? p0 : p1;
            const x = r0[0] + (r1[0] - r0[0]) * 0.6, y = r0[1] + (r1[1] - r0[1]) * 0.6;
            const lx = Math.max(r1[0] + 24, st.cssW * 0.72);
            L.querySelector('u').style.width = `${Math.max(16, lx - x - 12)}px`;
            L.style.transform = `translate(${x}px, ${y - 6}px)`;
            L.style.opacity = String(clamp((open - 0.45) / 0.45, 0, 1));
          } else L.style.opacity = '0';
        }
        gl.disable(gl.BLEND);
      },
      fallback: () => fallbackImage(urls[0], alt, 'cover', first.focus || [0.5, 0.5]),
      failed() { labels.forEach(l => l.remove()); },
    });
    if (alt) { el.setAttribute('role', 'img'); el.setAttribute('aria-label', alt); }
    return {
      ready,
      destroy() { s.destroy(); labels.forEach(l => l.remove()); },
      pause: () => s.pause(),
      resume: () => s.resume(),
      setPalette(p) { if (p !== undefined) given = p; T = tones(paletteOf(el, given)); style(); s.redraw(); },
    };
  },
};

objects/dot-object/object.js:
/*
  dot-object - a real object rebuilt from dots. The object is cut out of a photograph taken on a plain
  ground (the ground, even a graded one, is modelled from the photograph's border and left out), and
  each dot takes the tone of the photograph where it sits, so the dots draw the object's form and not
  only its outline. Pass the client's own product shot on a plain ground.

  It is still at rest: the finished object, drawn once. Hover: under the pointer the dots take the
  photograph's own colour and swell until they almost touch, like a loupe over a print, so the real
  object shows through the dots; it eases back when the pointer leaves. Touch: the same under the
  finger.

  src: a photograph (a path, a URL, a photos.json or library entry) of one object on a plain ground
  that differs from it in lightness or colour. params: gap (CSS px between dots, default from the panel
  size), fit (share of the panel the object fills, default 0.78), threshold (0..1, how far from the
  ground colour counts as the object, default 0.5), radius (loupe radius in CSS px), focus ([x, y]
  for the fallback crop), alt.
*/
import { stage, tones, photoURL, loadImage, pixels, fallbackImage, clamp, approach, paletteOf } from '../_scenes/kit.js';

// a test picture with a ground that cuts out cleanly (bright petals on black); never shipped as a client's
export const DEFAULT_PHOTO = {
  id: 'commons-minimal-yellow-tulip', source: 'commons', ratio: 1.5, width: 4652, focus: [0.32, 0.5],
  alt: 'A yellow tulip streaked with red, on a black ground',
  by: 'Alistair Dent', licence: 'CC0', licenceUrl: 'https://creativecommons.org/publicdomain/zero/1.0/',
  url: 'https://upload.wikimedia.org/wikipedia/commons/f/f4/Minimal_yellow_tulip_%28Unsplash%29.jpg',
  page: 'https://commons.wikimedia.org/wiki/File:Minimal_yellow_tulip_(Unsplash).jpg',
};

const vert = /* glsl */ `
in vec2 a_pos;
in vec4 a_data;          // radius (CSS px), photograph colour rgb
uniform vec2 u_view;
uniform vec3 u_ptr;      // pointer x, y (CSS px), loupe amount 0..1
uniform float u_dpr, u_rad, u_gap;
out vec3 v_col;
out float v_r;
out float v_k;
void main() {
  vec2 p = a_pos / u_view * 2.0 - 1.0;
  gl_Position = vec4(p.x, -p.y, 0.0, 1.0);
  float d = distance(a_pos, u_ptr.xy);
  float k = u_ptr.z * (1.0 - smoothstep(u_rad * 0.45, u_rad, d));
  float r = mix(a_data.x, u_gap * 0.56, k * 0.85);
  v_r = r * u_dpr;
  v_k = k;
  v_col = a_data.yzw;
  gl_PointSize = max(1.0, r * 2.0 * u_dpr + 2.0);
}
`;
const frag = /* glsl */ `
uniform vec3 u_ink;
in vec3 v_col;
in float v_r;
in float v_k;
void main() {
  float size = v_r * 2.0 + 2.0;
  vec2 pc = (gl_PointCoord - 0.5) * size;
  float a = 1.0 - smoothstep(v_r - 0.7, v_r + 0.7, length(pc));
  if (a <= 0.0) discard;
  vec3 c = mix(u_ink, v_col, v_k);
  fxColor = vec4(c * a, a);
}
`;

// OKLab of an 8-bit sRGB pixel
const lin = v => { v /= 255; return v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); };
const LUT = new Float32Array(256).map((_, i) => lin(i));
function oklab(r, g, b) {
  r = LUT[r]; g = LUT[g]; b = LUT[b];
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const m = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  return [0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s, 1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s, 0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s];
}

/** cut the object out of its ground: { w, h, mask (0..1), tone (lightness 0..1), rgb, box: [x0, y0, x1, y1] } */
export function cutOut(img, threshold = 0.5) {
  const { data, width: w, height: h } = pixels(img, 360);
  const n = w * h, L = new Float32Array(n), A = new Float32Array(n), B = new Float32Array(n);
  for (let i = 0; i < n; i++) { const o = oklab(data[i * 4], data[i * 4 + 1], data[i * 4 + 2]); L[i] = o[0]; A[i] = o[1]; B[i] = o[2]; }
  const blur = (src, r) => {
    const tmp = new Float32Array(n), out = new Float32Array(n);
    for (let y = 0; y < h; y++) { let acc = 0; for (let x = -r; x <= r; x++) acc += src[y * w + clamp(x, 0, w - 1)]; for (let x = 0; x < w; x++) { tmp[y * w + x] = acc / (2 * r + 1); acc += src[y * w + clamp(x + r + 1, 0, w - 1)] - src[y * w + clamp(x - r, 0, w - 1)]; } }
    for (let x = 0; x < w; x++) { let acc = 0; for (let y = -r; y <= r; y++) acc += tmp[clamp(y, 0, h - 1) * w + x]; for (let y = 0; y < h; y++) { out[y * w + x] = acc / (2 * r + 1); acc += tmp[clamp(y + r + 1, 0, h - 1) * w + x] - tmp[clamp(y - r, 0, h - 1) * w + x]; } }
    return out;
  };
  const ring = [], m = Math.max(2, Math.round(Math.min(w, h) * 0.03));
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) if (x < m || y < m || x >= w - m || y >= h - m) ring.push(y * w + x);
  const med = arr => { const s = Float32Array.from(arr).sort(); return s[s.length >> 1]; };
  // a cut-out with a clear ground (a PNG): its alpha is the mask
  const clear = ring.filter(i => data[i * 4 + 3] < 16).length;
  const gL = med(ring.map(i => L[i]));
  if (clear > ring.length * 0.3) return finish(Float32Array.from({ length: n }, (_, i) => data[i * 4 + 3] / 255));
  // the ground: border pixels near the border's median colour (an object that runs off the edge is
  // not ground), modelled as a smooth surface: a Coons patch over the four borders, each border a
  // running median, so a backdrop that is lighter at the top or vignetted is still ground
  const gA = med(ring.map(i => A[i])), gB = med(ring.map(i => B[i]));
  const off = i => Math.hypot(L[i] - gL, A[i] - gA, B[i] - gB);
  const inlier = Math.max(0.05, med(ring.map(off)) * 3);
  const strip = (len, at) => {
    const raw = Array.from({ length: len }, (_, k) => at(k));
    const r = Math.max(3, Math.round(len * 0.12)), out = new Float32Array(len).fill(NaN);
    for (let k = 0; k < len; k++) {
      const win = raw.slice(Math.max(0, k - r), Math.min(len, k + r + 1)).filter(v => v === v);
      if (win.length) out[k] = med(win);
    }
    // a stretch with no ground at all takes its nearest neighbour's
    for (let k = 1; k < len; k++) if (out[k] !== out[k] && out[k - 1] === out[k - 1]) out[k] = out[k - 1];
    for (let k = len - 2; k >= 0; k--) if (out[k] !== out[k] && out[k + 1] === out[k + 1]) out[k] = out[k + 1];
    return out.map(v => (v === v ? v : 0));
  };
  const edge = (ch, idx) => { const v = idx.filter(i => off(i) < inlier).map(i => ch[i]); return v.length ? med(v) : NaN; };
  const G = [L, A, B].map((ch, c) => {
    const base = [gL, gA, gB][c];
    const fix = arr => (arr.every(v => v === 0) ? arr.fill(base) : arr);
    const top = fix(strip(w, x => edge(ch, Array.from({ length: m }, (_, j) => j * w + x))));
    const bot = fix(strip(w, x => edge(ch, Array.from({ length: m }, (_, j) => (h - 1 - j) * w + x))));
    const lef = fix(strip(h, y => edge(ch, Array.from({ length: m }, (_, j) => y * w + j))));
    const rig = fix(strip(h, y => edge(ch, Array.from({ length: m }, (_, j) => y * w + w - 1 - j))));
    const g = new Float32Array(n);
    const c00 = (top[0] + lef[0]) / 2, c10 = (top[w - 1] + rig[0]) / 2, c01 = (bot[0] + lef[h - 1]) / 2, c11 = (bot[w - 1] + rig[h - 1]) / 2;
    for (let y = 0; y < h; y++) {
      const v = y / (h - 1);
      for (let x = 0; x < w; x++) {
        const u = x / (w - 1);
        g[y * w + x] = (1 - v) * top[x] + v * bot[x] + (1 - u) * lef[y] + u * rig[y]
          - ((1 - u) * (1 - v) * c00 + u * (1 - v) * c10 + (1 - u) * v * c01 + u * v * c11);
      }
    }
    return g;
  });
  // a shadow on the ground keeps its hue and is only darker, so darker-than-ground counts for less
  // and chroma is compared relative to lightness; the object differs in lightness or in hue
  const dist = i => {
    const gl = G[0][i], gLs = Math.max(gl, 0.05), li = Math.max(L[i], 0.05);
    const dl = L[i] > gl ? (L[i] - gl) * 0.9 : (gl - L[i]) * 0.2;
    return Math.hypot(dl, (A[i] / li - G[1][i] / gLs) * gLs * 1.6, (B[i] / li - G[2][i] / gLs) * gLs * 1.6);
  };
  // spread of the ground, so a graded backdrop is still ground
  const spread = med(ring.map(dist));
  const t0 = 0.05 + spread * 2 + (threshold - 0.5) * 0.08, t1 = t0 + 0.06;
  const raw = new Float32Array(n);
  for (let i = 0; i < n; i++) raw[i] = clamp((dist(i) - t0) / (t1 - t0), 0, 1);
  // close small gaps (box blur) and fill holes: ground is what the border can reach
  // close small gaps and fill holes: ground is what the border can reach
  const closed = blur(raw, 2);
  const ground = new Uint8Array(n), stack = [];
  for (const i of ring) if (closed[i] < 0.45) { ground[i] = 1; stack.push(i); }
  while (stack.length) {
    const i = stack.pop(), x = i % w, y = (i / w) | 0;
    for (const j of [x > 0 ? i - 1 : -1, x < w - 1 ? i + 1 : -1, y > 0 ? i - w : -1, y < h - 1 ? i + w : -1]) {
      if (j >= 0 && !ground[j] && closed[j] < 0.45) { ground[j] = 1; stack.push(j); }
    }
  }
  return finish(Float32Array.from(ground, g => 1 - g));

  // the object's box, a softened mask and the tone (lightness with a little local contrast)
  function finish(mask) {
  let x0 = w, y0 = h, x1 = 0, y1 = 0, area = 0;
  for (let i = 0; i < n; i++) {
    if (mask[i] > 0.5) { const x = i % w, y = (i / w) | 0; area++; if (x < x0) x0 = x; if (x > x1) x1 = x; if (y < y0) y0 = y; if (y > y1) y1 = y; }
  }
  const soft = blur(mask, 1);
  const sm = blur(L, 1), wide = blur(L, 6), tone = new Float32Array(n);
  for (let i = 0; i < n; i++) tone[i] = sm[i] + 0.9 * (sm[i] - wide[i]);
  if (area < n * 0.01) { x0 = 0; y0 = 0; x1 = w - 1; y1 = h - 1; }
  // the object's own tonal range (4% and 96% inside the mask), so an object of one middle tone (an
  // orange flower, a grey device) still prints its form, not an even disc of dots
  const inside = [];
  for (let i = 0; i < n; i++) if (mask[i] > 0.5) inside.push(tone[i]);
  inside.sort((a, b) => a - b);
  let lo = inside.length ? inside[Math.floor(inside.length * 0.04)] : 0.15, hi = inside.length ? inside[Math.floor(inside.length * 0.96)] : 0.95;
  if (hi - lo < 0.3) { const m = (hi + lo) / 2; lo = m - 0.15; hi = m + 0.15; }
  return { w, h, mask: soft, tone, rgb: data, ground: gL, box: [x0, y0, x1 + 1, y1 + 1], levels: [lo, hi] };
  }
}

export default {
  id: 'dot-object',
  name: 'Dot object',
  kind: 'scene',
  mount(el, { palette, src, params = {} } = {}) {
    const photo = src || DEFAULT_PHOTO;
    const alt = params.alt || photo.alt || '';
    let given = palette || null;
    let T = tones(paletteOf(el, given));
    let cut = null, prog = null, buf = null;
    let N = 0, data = null, built = '', gap = 6, hover = 0, px = 0, py = 0;
    const url = photoURL(photo, 960);
    let resolveReady;
    const ready = new Promise(r => (resolveReady = r));

    function build(st) {
      if (!cut) return;
      const key = `${st.cssW}x${st.cssH}:${T.dark}`;
      if (key === built) return;
      built = key;
      const W = st.cssW, H = st.cssH;
      gap = params.gap || clamp(Math.min(W, H) / 100, 4.2, 7.5);
      const [bx0, by0, bx1, by1] = cut.box;
      const bw = bx1 - bx0, bh = by1 - by0;
      const fit = params.fit ?? 0.78;
      const sc = Math.min((W * fit) / bw, (H * fit) / bh);
      const ox = (W - bw * sc) / 2 - bx0 * sc, oy = (H - bh * sc) / 2 - by0 * sc;
      const pts = [];
      const rowH = gap * 0.866;
      const sample = (arr, x, y) => {
        x = clamp(x, 0, cut.w - 1.001); y = clamp(y, 0, cut.h - 1.001);
        const xi = x | 0, yi = y | 0, fx = x - xi, fy = y - yi, i = yi * cut.w + xi;
        return (arr[i] * (1 - fx) + arr[i + 1] * fx) * (1 - fy) + (arr[i + cut.w] * (1 - fx) + arr[i + cut.w + 1] * fx) * fy;
      };
      const lo = cut.box, [Lmin, Lmax] = cut.levels;
      for (let row = 0, y = rowH / 2; y < H; row++, y += rowH) {
        for (let x = (row % 2 ? gap / 2 : 0) + gap / 2; x < W; x += gap) {
          const ix = (x - ox) / sc, iy = (y - oy) / sc;
          if (ix < lo[0] - 2 || iy < lo[1] - 2 || ix > lo[2] + 2 || iy > lo[3] + 2) continue;
          const mk = sample(cut.mask, ix, iy);
          if (mk < 0.5) continue;
          const l = clamp((sample(cut.tone, ix, iy) - Lmin) / (Lmax - Lmin), 0, 1);
          const w = T.dark ? 0.3 + 0.7 * l : 0.2 + 0.8 * (1 - l);
          const o = (clamp(Math.round(iy), 0, cut.h - 1) * cut.w + clamp(Math.round(ix), 0, cut.w - 1)) * 4;
          pts.push(x, y, gap * 0.5 * 0.94 * Math.sqrt(w) * clamp((mk - 0.5) * 3, 0.35, 1), cut.rgb[o] / 255, cut.rgb[o + 1] / 255, cut.rgb[o + 2] / 255);
        }
      }
      N = pts.length / 6;
      data = new Float32Array(pts);
      if (st.gl) upload(st);
    }
    function upload(st) {
      const gl = st.gl;
      if (!buf) buf = st.buffer(data || new Float32Array(6), gl.STATIC_DRAW);
      else { gl.bindBuffer(gl.ARRAY_BUFFER, buf); gl.bufferData(gl.ARRAY_BUFFER, data, gl.STATIC_DRAW); }
    }

    let s;
    loadImage(url).then(im => {
      cut = cutOut(im, params.threshold ?? 0.5);
      if (s) { built = ''; if (s.gl) build(s); s.redraw(); }
      resolveReady();
    }).catch(err => { console.warn(err.message); s?.fail(); resolveReady(); });

    s = stage(el, {
      name: 'dots',
      alpha: false,
      init(gl, st) { prog = st.program(frag, vert); buf = null; built = ''; },
      resize() { built = ''; },
      loaded: () => !!cut,
      ready: () => N > 0,
      frame(gl, t, dt, st) {
        const P = st.pointer;
        const want = P.inside ? 1 : 0;
        const before = hover;
        hover = st.reduced || dt === 0 ? want : approach(hover, want, 7, dt);
        if (Math.abs(hover - want) < 0.002) hover = want;
        // the loupe follows the pointer a little behind it
        const nx = P.inside ? P.x : px, ny = P.inside ? P.y : py;
        const mx = dt > 0 && hover > 0.01 && before > 0.01 ? approach(px, nx, 18, dt) : nx, my = dt > 0 && hover > 0.01 && before > 0.01 ? approach(py, ny, 18, dt) : ny;
        const moved = Math.abs(mx - px) > 0.05 || Math.abs(my - py) > 0.05 || hover !== before;
        px = mx; py = my;
        build(st);
        if (!N || !buf) return;
        if (dt > 0 && !st.dirty && !moved) return;
        const bg = T.r[0];
        gl.clearColor(bg[0], bg[1], bg[2], 1);
        gl.clear(gl.COLOR_BUFFER_BIT);
        const W = st.cssW, H = st.cssH;
        const R = params.radius || clamp(Math.min(W, H) * 0.2, 70, 150);
        gl.enable(gl.BLEND);
        gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
        prog.use();
        prog.set('u_view', [W, H]).set('u_dpr', st.w / W).set('u_ink', T.r[3]).set('u_res', [st.w, st.h])
          .set('u_ptr', [px, py, hover]).set('u_rad', R).set('u_gap', gap);
        gl.bindBuffer(gl.ARRAY_BUFFER, buf);
        const ld = prog.attrib('a_data');
        gl.enableVertexAttribArray(0);
        gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 24, 0);
        gl.enableVertexAttribArray(ld);
        gl.vertexAttribPointer(ld, 4, gl.FLOAT, false, 24, 8);
        gl.drawArrays(gl.POINTS, 0, N);
        gl.disableVertexAttribArray(ld);
        gl.disable(gl.BLEND);
      },
      fallback: () => fallbackImage(url, alt, 'cover', params.focus || photo.focus || [0.5, 0.5]),
    });
    if (alt) { el.setAttribute('role', 'img'); el.setAttribute('aria-label', alt); }
    el.style.touchAction = 'pan-y';
    return {
      ready,
      destroy() { s.destroy(); },
      pause: () => s.pause(),
      resume: () => s.resume(),
      setPalette(p) { if (p !== undefined) given = p; T = tones(paletteOf(el, given)); built = ''; s.redraw(); },
    };
  },
};

objects/dither-sequence/object.js:
/*
  dither-sequence - two to six real photographs that belong together (a device from several sides, the
  stages of what the software makes, a game's scenes) printed with an ordered dither in the page palette,
  one canvas pixel per dither cell, and played like a slow loop of film. Each cut develops through the
  dither: the next photograph's darkest ink comes up first, cell by cell, along a thin accent front.
  Pass the client's own photographs.

  At rest it plays on its own: each frame holds (nothing is drawn while it holds), then wipes to the
  next. Hover: the pointer scrubs the sequence (left is the first frame, right the last) and a small
  pill shows where you are. Touch: drag. A photograph that fails to load is left out of the loop.

  src: an array of 2 to 6 photographs (paths, URLs, photos.json or library entries; each may carry its
  own focus [x, y]). params: cell (CSS px per dither cell), hold (seconds a frame stays, default 2.2),
  captions (one per frame; else the pill counts 01 / 04), focus (an array of [x, y], one per frame),
  fit ('cover' or 'contain': the whole photograph on the page's paper), autoplay (0 holds the first
  frame until hovered), drift (1 lets each frame drift slowly), alt.
*/
import { stage, tones, setTones, GLSL_PRINT, photoURL, loadImage, levels, cover, fallbackImage, clamp, color, paletteOf, MONO } from '../_scenes/kit.js';

// test pictures that belong together (four buildings, looking up), never shipped as a client's
const UNSPLASH = 'https://unsplash.com/license';
export const DEFAULT_SEQUENCE = [
  { id: 315, ratio: 1.4, focus: [0.5, 0.45], alt: 'Looking straight up a dark lightwell to a square of bright sky', by: 'Liam Andrew', licence: 'Unsplash licence', licenceUrl: UNSPLASH, page: 'https://unsplash.com/photos/W7CopGaHkEM' },
  { id: 951, ratio: 1.6, focus: [0.5, 0.5], alt: 'A building facade of red, yellow and white panels', by: 'Sérgio Rola', licence: 'Unsplash licence', licenceUrl: UNSPLASH, page: 'https://unsplash.com/photos/4aQY2CrXsa8' },
  { id: 942, ratio: 1.5, focus: [0.5, 0.6], alt: 'A white angular concrete building against a black sky', by: 'Carl Nenzen Loven', licence: 'Unsplash licence', licenceUrl: UNSPLASH, page: 'https://unsplash.com/photos/busqfOj6i80' },
  { id: 1081, ratio: 1.49, focus: [0.62, 0.5], alt: 'A stepped white building corner rising into a pale blue sky', by: 'Julien Moreau', licence: 'Unsplash licence', licenceUrl: UNSPLASH, page: 'https://unsplash.com/photos/688Fna1pwOQ' },
];

const frag = /* glsl */ `
${GLSL_PRINT}
uniform sampler2D u_ta, u_tb;
uniform vec4 u_fa, u_fb, u_ka, u_kb;   // fit (scale, offset); drift (zoom, pan x, pan y, -)
uniform vec2 u_la, u_lb;               // levels
uniform vec2 u_ca, u_cb;               // contain: the share of the frame the photograph fills (1, 1 = cover)
uniform float u_p, u_dark, u_cellPx;

vec2 uvOf(vec2 fc, vec4 fit, vec4 k, vec2 cn) {
  vec2 uv = vec2(fc.x / u_res.x, 1.0 - fc.y / u_res.y);
  uv = (uv - 0.5) / cn + 0.5;
  uv = (uv - 0.5) / k.x + 0.5 + k.yz;
  return fit.zw + uv * fit.xy;
}
float lum(vec3 c, vec2 lv) { return clamp((dot(c, vec3(0.2126, 0.7152, 0.0722)) - lv.x) / max(lv.y - lv.x, 0.05), 0.0, 1.0); }
// ink amount of one photograph at this cell, with a little local contrast so the dither keeps edges
float inkOf(sampler2D t, vec2 fc, vec4 fit, vec4 k, vec2 lv, vec2 cn) {
  vec2 uv = vec2(fc.x / u_res.x, 1.0 - fc.y / u_res.y);
  vec2 q = abs((uv - 0.5) / cn);
  if (max(q.x, q.y) > 0.5) return 0.0;   // outside a contained photograph: the paper
  float b = u_cellPx > 2.5 ? 1.0 : 0.5;
  float c = lum(texture(t, uvOf(fc, fit, k, cn), b).rgb, lv);
  vec2 o = vec2(3.0, 0.0);
  float s = lum(texture(t, uvOf(fc + o.xy, fit, k, cn), b + 1.5).rgb, lv) + lum(texture(t, uvOf(fc - o.xy, fit, k, cn), b + 1.5).rgb, lv)
          + lum(texture(t, uvOf(fc + o.yx, fit, k, cn), b + 1.5).rgb, lv) + lum(texture(t, uvOf(fc - o.yx, fit, k, cn), b + 1.5).rgb, lv);
  float l = clamp(c + 0.45 * (c - s * 0.25), 0.0, 1.0);
  // on a light page the shadows take ink, down to solid; on a dark page the light takes it, but a
  // bright photograph never prints as a solid light slab: its highlights stop short of full ink
  if (u_dark > 0.5) return smoothstep(0.12, 1.0, l) * 0.8;
  // (a pale sky stays paper, not a sparse grid of stray cells)
  return smoothstep(0.15, 0.97, 1.0 - l);
}

void main() {
  vec2 fc = gl_FragCoord.xy;
  float ink = inkOf(u_ta, fc, u_fa, u_ka, u_la, u_ca);
  bool front = false;
  if (u_p > 0.0) {
    float b = inkOf(u_tb, fc, u_fb, u_kb, u_lb, u_cb);
    // the cut: an ordered-dither wipe that crosses the frame on a slight diagonal; the next
    // photograph's deepest ink comes through a little ahead of the band
    vec2 uv = fc / u_res;
    float sweep = uv.x * 0.82 + (1.0 - uv.y) * 0.18;
    float thr = 0.8 * sweep + 0.14 * fx_bayer(fc) + 0.06 * (1.0 - b);
    float pp = u_p * 1.02;
    if (pp > thr) ink = b;
    // a thin accent line rides the leading edge of the wipe, once it is clear of the corner
    front = abs(0.8 * sweep - pp) < 0.4 / u_res.x && u_p > 0.03 && u_p < 0.97;
  }
  vec3 col = front ? printAccent(0.5, fc) : printInk(ink, fc);
  fxColor = vec4(col, 1.0);
}
`;

export default {
  id: 'dither-sequence',
  name: 'Dither sequence',
  kind: 'scene',
  mount(el, { palette, src, params = {} } = {}) {
    const list = (Array.isArray(src) ? (src.length ? src : DEFAULT_SEQUENCE) : src ? [src] : DEFAULT_SEQUENCE).slice(0, 6);
    const autoplay = params.autoplay !== 0;
    let given = palette || null;
    let T = tones(paletteOf(el, given));
    let prog = null;
    const imgs = new Array(list.length).fill(null), lvs = new Array(list.length).fill([0, 1]);
    let texes = new Array(list.length).fill(null);
    // the frames that loaded, in order (a failed photograph is left out, with its caption)
    let order = [];
    let pos = 0, target = 0, clock = 0, scrubbing = false, last = '';
    const hold = params.hold ?? 2.2, move = 1.5;
    const captionOf = k => (params.captions ? params.captions[k] || '' : null);

    // a small player pill: the caption of the frame and a timeline with one segment per photograph
    const ctl = document.createElement('div');
    ctl.className = 'scene-label';
    ctl.setAttribute('aria-hidden', 'true');
    Object.assign(ctl.style, { position: 'absolute', left: '14px', bottom: '14px', zIndex: '2', height: '28px', padding: '0 12px', display: 'none', alignItems: 'center', gap: '12px',
      borderRadius: '999px', pointerEvents: 'none', font: `500 11px/1 ${MONO}`, letterSpacing: '0.06em', textTransform: 'uppercase' });
    const cap = document.createElement('span');
    const bar = document.createElement('span');
    Object.assign(bar.style, { display: 'flex', gap: '4px', height: '2px' });
    ctl.append(cap, bar);
    el.append(ctl);
    let segs = [];
    const layoutPill = () => {
      bar.innerHTML = '';
      bar.style.width = `${Math.min(140, 30 * order.length)}px`;
      segs = order.map(() => {
        const sg = document.createElement('span');
        Object.assign(sg.style, { flex: '1', position: 'relative', borderRadius: '2px', overflow: 'hidden' });
        const f = document.createElement('i');
        Object.assign(f.style, { position: 'absolute', inset: '0', transformOrigin: 'left', transform: 'scaleX(0)' });
        sg.append(f); bar.append(sg);
        return [sg, f];
      });
      ctl.style.display = order.length > 1 && !s?.fallen ? 'flex' : 'none';
      style();
    };
    const style = () => {
      for (const [sg, f] of segs) { sg.style.background = color.mix(T.hex.bg, T.hex.ink, 0.2); f.style.background = T.hex.ink; }
      Object.assign(ctl.style, { color: T.hex.ink, background: T.hex.bg, boxShadow: '0 0 0 1px ' + color.mix(T.hex.bg, T.hex.ink, 0.12) });
    };

    let resolveReady;
    const ready = new Promise(r => (resolveReady = r));
    let s;
    const urls = list.map(p => photoURL(p, 1280));
    let settled = 0;
    urls.forEach((u, i) => loadImage(u).then(im => {
      imgs[i] = im; lvs[i] = levels(im);
      if (s && s.gl) texes[i] = s.texture(im, { mipmap: true });
    }).catch(err => console.warn(err.message)).finally(() => {
      if (++settled < urls.length) return;
      order = imgs.map((im, k) => (im ? k : -1)).filter(k => k >= 0);
      if (!order.length) s?.fail();
      else {
        layoutPill(); s?.syncPause(); s?.redraw();
        if (!params.alt) { const al = order.map(k => list[k].alt).filter(Boolean).join('; '); if (al) el.setAttribute('aria-label', al); }
      }
      resolveReady();
    }));

    s = stage(el, {
      name: 'photographs',
      cell: st => params.cell || clamp(Math.min(st.cssW, st.cssH) / 320, 2, 3),
      loops: () => autoplay && order.length > 1,
      // a wipe needs no more than 30 frames a second; a hold needs none
      fps: () => 30,
      init(gl, st) {
        prog = st.program(frag);
        texes = imgs.map(im => (im ? st.texture(im, { mipmap: true }) : null));
        last = '';
      },
      loaded: () => order.length > 0,
      ready: () => order.length > 0 && !!texes[order[0]],
      pointer(kind, st) {
        const N = order.length;
        if (kind === 'enter' || kind === 'down') scrubbing = true;
        if (kind === 'leave') { scrubbing = false; clock = 0; target = Math.round(pos); }
        if (st.reduced && st.pointer.inside && N) { pos = target = Math.floor(st.pointer.u * N * 0.999); }
      },
      frame(gl, t, dt, st) {
        const N = order.length;
        if (!N) return;
        const P = st.pointer;
        if (!st.reduced && dt > 0 && N > 1) {
          if (scrubbing && P.inside) {
            // the pointer picks a place on the timeline; the picture follows at a steady pace.
            // Each frame holds for most of its stretch and wipes to the next near its end
            const at = P.u * N * 0.9999, seg = Math.floor(at), fr = at - seg;
            const snapped = seg + (seg < N - 1 ? Math.min(1, Math.max(0, (fr - 0.68) / 0.3)) : 0);
            const want = Math.floor((pos + 0.0001) / N) * N + snapped;
            const d = want - pos, sp = 2.4 * dt;
            pos += Math.sign(d) * Math.min(Math.abs(d), sp + Math.abs(d) * 4 * dt);
          } else if (autoplay) {
            clock += dt;
            if (clock > hold + move) { clock = 0; target = Math.floor(target + 0.001) + 1; }
            const d = target - pos;
            pos += Math.sign(d) * Math.min(Math.abs(d), dt / move);
          }
        }
        if (pos > N * 50) { pos -= N * 40; target -= N * 40; }
        const k = Math.floor(pos), f = pos - k;
        const ia = ((k % N) + N) % N, ib = (ia + 1) % N;
        const p = f < 1e-4 ? 0 : Math.min(1, Math.max(0, (f - 0.02) / 0.96));
        const pe = p * p * (3 - 2 * p);
        const drift = params.drift === 1 && !st.reduced;
        // a hold: nothing changes, nothing is drawn
        const key = `${ia}:${ib}:${pe.toFixed(4)}`;
        if (dt > 0 && !st.dirty && !drift && key === last) return;
        last = key;
        segs.forEach(([, fill], i) => { fill.style.transform = `scaleX(${i <= ia ? 1 : i === ib ? pe : 0})`; });
        const at = pe > 0.5 ? ib : ia;
        const c = captionOf(order[at]) ?? String(at + 1).padStart(2, '0') + ' / ' + String(N).padStart(2, '0');
        if (cap.textContent !== c) cap.textContent = c;
        const A = order[ia], B = order[ib];
        const ta = texes[A], tb = texes[B] || ta;
        if (!ta) return;
        const contain = params.fit === 'contain';
        const fitOf = j => {
          const im = imgs[j], ia_ = im.naturalWidth / im.naturalHeight;
          const fo = (params.focus && params.focus[j]) || (list[j] && list[j].focus) || [0.5, 0.5];
          if (contain) return { fit: [1, 1, 0, 0], cn: (st.w / st.h) > ia_ ? [ia_ / (st.w / st.h), 1] : [1, (st.w / st.h) / ia_] };
          return { fit: cover(st.w, st.h, ia_, fo[0], fo[1], 1), cn: [1, 1] };
        };
        const kOf = j => {
          if (!drift) return [1, 0, 0, 0];
          const a = t * 0.11 + j * 2.1;
          return [1.035 + 0.015 * Math.sin(a), 0.006 * Math.sin(a * 0.8 + 1), 0.005 * Math.cos(a * 0.7), 0];
        };
        const fa = fitOf(A), fb = fitOf(B);
        prog.use();
        setTones(gl, prog, T);
        ta.bind(0); tb.bind(1);
        prog.int('u_ta', 0).int('u_tb', 1);
        prog.set('u_res', [st.w, st.h]).set('u_time', t).set('u_seed', 5).set('u_cellPx', st.k)
          .set('u_fa', fa.fit).set('u_fb', fb.fit).set('u_ca', fa.cn).set('u_cb', fb.cn).set('u_ka', kOf(A)).set('u_kb', kOf(B))
          .set('u_la', lvs[A]).set('u_lb', lvs[B]).set('u_p', pe).set('u_dark', T.dark ? 1 : 0);
        st.fullscreen();
      },
      fallback: () => fallbackImage(urls[order[0] ?? 0], params.alt || list[0].alt || '', 'cover', list[order[0] ?? 0]?.focus || [0.5, 0.5]),
      failed() { ctl.style.display = 'none'; },
    });
    const alt = params.alt || list.map(p => p.alt).filter(Boolean).join('; ');
    if (alt) { el.setAttribute('role', 'img'); el.setAttribute('aria-label', alt); }
    el.style.touchAction = 'pan-y';
    return {
      ready,
      destroy() { s.destroy(); ctl.remove(); },
      pause: () => s.pause(),
      resume: () => s.resume(),
      setPalette(p) { if (p !== undefined) given = p; T = tones(paletteOf(el, given)); style(); s.redraw(); },
    };
  },
};

objects/_scenes/auto.js:
/*
  _scenes/auto.js - mounts every [data-scene] on the page, so a page needs no script of its own for
  its scene objects. Load it once, after system.js (README.md beside it has the whole contract):

    <div class="frame frame--square">
      <div data-scene="product-turntable" data-scene-params='{"form":"chair"}'></div>
    </div>
    <div class="panel">
      <div data-scene="split-reveal" data-scene-src="assets/img/raw-scan.jpg" aria-label="A scanned print, half of it screened"></div>
    </div>
    <script type="module" src="assets/objects/_scenes/auto.js"></script>

  data-scene          the object's id: product-turntable | dot-object | split-reveal |
                      dither-sequence | exploded-layers
  data-scene-src      the client's photograph: a page-relative path or URL, or JSON: one entry
                      { src, alt, by, page, licence, licenceUrl, focus } or an array of them
                      (dither-sequence: 2 to 6 frames; exploded-layers: up to 4 sheets, top first)
  data-scene-params   JSON params (each object's meta.json lists them)
  data-scene-palette  JSON { bg, surface, ink, muted, accent }; without it the scene prints in the page
                      tokens, on the ground of the box it sits in
  data-scene-loop     in a group (the same [data-scene-group], else the same section), the one scene
                      that moves by itself; the others hold still until the pointer reaches them.
                      Without it the first looping scene of the group moves.
  aria-label          what the picture shows (else the photograph's alt)

  The controllers: (await import('.../auto.js')).scenes, a Map from element to controller
  (pause(), resume(), setPalette(p | null), destroy()). On a theme change call setPalette(null)
  on each: it reads the page tokens again.
*/
export const scenes = new Map();
const IDS = ['product-turntable', 'dot-object', 'split-reveal', 'dither-sequence', 'exploded-layers'];
const LOOPING = new Set(['product-turntable', 'dither-sequence']);
const claimed = new WeakSet();
const json = (s, d = {}) => { try { return s ? JSON.parse(s) : d; } catch (_) { console.warn('scenes: bad JSON', s); return d; } };
const srcOf = s => {
  if (!s) return undefined;
  s = s.trim();
  return s[0] === '{' || s[0] === '[' ? json(s, undefined) : s;
};

export async function mountAll(root = document) {
  const els = [...root.querySelectorAll('[data-scene]')].filter(el => !claimed.has(el));
  els.forEach(el => claimed.add(el));
  // one moving scene per group
  const groups = new Map();
  for (const el of els) {
    if (!LOOPING.has(el.dataset.scene)) continue;
    const g = el.closest('[data-scene-group]') || el.closest('section') || document.body;
    if (!groups.has(g)) groups.set(g, []);
    groups.get(g).push(el);
  }
  const moving = new Set();
  for (const [g, list] of groups) {
    const before = [...scenes.keys()].some(el => g.contains(el) && el.dataset.sceneMoving === '1');
    if (!before) moving.add(list.find(el => el.hasAttribute('data-scene-loop')) || list[0]);
  }
  await Promise.all(els.map(async el => {
    const id = el.dataset.scene;
    if (!IDS.includes(id)) { console.warn('scenes: unknown object', id); return; }
    try {
      const obj = (await import(new URL(`../${id}/object.js`, import.meta.url).href)).default;
      const params = json(el.dataset.sceneParams);
      if (LOOPING.has(id) && params.autoplay == null) params.autoplay = moving.has(el) ? 1 : 0;
      if (params.autoplay) el.dataset.sceneMoving = '1';
      if (el.getAttribute('aria-label') && params.alt == null) params.alt = el.getAttribute('aria-label');
      const opts = { params, src: srcOf(el.dataset.sceneSrc) };
      if (el.dataset.scenePalette) opts.palette = json(el.dataset.scenePalette);
      scenes.set(el, obj.mount(el, opts));
    } catch (e) { console.warn('scenes:', id, e); }
  }));
  return scenes;
}

if (typeof document !== 'undefined') {
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', () => mountAll(), { once: true });
  else mountAll();
}
export default { mountAll, scenes };

