function resolve(schema, given = {}) {
  const out = {};
  for (const [k, d] of Object.entries(schema)) {
    let v = given[k];
    if (d.options) { out[k] = typeof v === 'number' ? d.options[v] || d.default : d.options.includes(v) ? v : d.default; continue; }
