    float g = (ign(floor(px / max(u_cell, 1.0)) + 11.0) - 0.5) * 0.04 * a.a;
    vec3 c = max(a.rgb + g, 0.0);
    o = u_alpha > 0.5 ? vec4(c, clamp(a.a, 0.0, 1.0)) : vec4(c + u_paper * (1.0 - clamp(a.a, 0.0, 1.0)), 1.0);
