    },
    release() { hold = false; sync(); },
    /** a still frame at time t (seconds) with the pointer at (mx, my) -1..1 and hover 0..1, for tests (after ready()) */
    pose({ t = state.t, mx = 0, my = 0, hover = 0, step, kick } = {}) {
