/* picture-develops: the frame holds the photograph (cover) and, while developing, one canvas of the
   halftone print over it. The photograph settles from a slight zoom when the print clears. The frame
   rules also hold without script (no .mo-pd yet): the photograph fills the frame the page sized. */
:is(.mo-pd, [data-moment="picture-develops"]) { position: relative; overflow: hidden; isolation: isolate; }
:is(.mo-pd, [data-moment="picture-develops"]) > img { display: block; width: 100%; height: 100%; object-fit: cover; }
.mo-pd.is-live > img { transform: scale(1.05); }
.mo-pd.is-developing > img, .mo-pd.is-done > img { transition: transform 1400ms cubic-bezier(.16, 1, .3, 1); }
.mo-pd.is-done > img { transform: none; }
.mo-pd > .mo-pd__print { position: absolute; inset: 0; z-index: 1; width: 100%; height: 100%; display: block; background: var(--surface); border-radius: inherit; }
.mo-pd.is-developing > img { transform: none; }
@media (prefers-reduced-motion: reduce) { .mo-pd > img { transform: none !important; } .mo-pd > .mo-pd__print { display: none; } }
/* the film look: armed just before it scrolls in, the picture waits as a faint print whose shapes
   already read (moment.js then runs the develop on the picture itself); done, failed or still it is
   the photograph */
.mo-pd--film.is-armed > img { filter: grayscale(1) contrast(.55) brightness(1.32); transform: scale(1.06); }
.mo-pd--film:is(.is-done, .mo-safe, [data-moment-still]) > img { filter: none; transform: none; }
