.mo-cl .mo-cl__band { position: relative; z-index: 1; width: 100%; padding: clamp(96px, 16vh, 160px) 0 clamp(40px, 7vh, 72px); color: #fff;
  background: linear-gradient(to top, rgb(0 0 0 / .62), rgb(0 0 0 / .28) 55%, rgb(0 0 0 / 0)); --ink: #fff; --muted: rgb(255 255 255 / .8); --action: #fff; --action-ink: #111; }
/* the closing words on the page's own left edge: the container as everywhere else on the page */
