main > .section--hero > .container.demo-split { align-content: center; }
.demo-split > .demo-photo { aspect-ratio: auto !important; width: 100%; height: 100%; max-height: min(100%, 62svh); min-height: 0; }
.demo-split > .frame { max-height: 100%; min-height: 0; }
.demo-statement { align-content: start; }
/* a phone: the section grows with its split (system.css), so the split keeps its content height as its least */
@media (max-width: 639px) { main > :is(.section, .section--hero) > .container.demo-split { min-height: auto; } }
/* a phone hero: its picture or window takes what the first screen leaves under the words (size containment keeps
   its own height out of the hero's, so it never pushes the hero past the screen), and at least 220px, so on a short
   phone the hero grows by what the words need and no more */
@media (max-width: 639px) {
  main > .section--hero > .container.demo-split { grid-template-rows: auto minmax(0, 1fr); align-content: stretch; }
  main > .section--hero > .container.demo-split > .demo-photo { height: 100%; max-height: none; min-height: 220px; contain: size; }
  main > .section--hero > .container:not(.demo-split) > :is(.hero-photo, .frame) { flex: 1 1 0; aspect-ratio: auto; min-height: 220px; contain: size; }
  main > .section--hero > .container:not(.demo-split) > .frame { align-items: flex-start; }
  /* the window keeps the rows that fit whole: one, under its title (a row cut by the frame reads as a fault) */
  main > .section--hero > .container:not(.demo-split) > .frame .dw__row:nth-of-type(n+2) { display: none; }
}

/* a drawn window in a hero frame beside the text (1024-1279): the side list goes, so the rows keep one line
   each and the window stays shorter than its frame (it was cut at the frame's top and foot at 1024x768) */
@media (max-width: 1279px) { .frame .dw__body { grid-template-columns: 1fr; min-height: 0; } .frame .dw__side { display: none; } .frame .dw__row:nth-of-type(n+3) { display: none; } }

