  /** [r,g,b] 0..1 or hex -> '#rrggbb' */
  hex: c => rgbToHex(toRgb(c)),
  /** -> [L,a,b] OKLab */
  lab,
  /** OKLab -> hex (gamut-mapped by reducing chroma) */
  fromLab,
  /** -> [L, C, hue degrees] OKLCH */
  lch,
  fromLch,
  /** perceptual mix in OKLab, t = 0 gives a, 1 gives b */
  mix(a, b, t = 0.5) {
    const A = lab(a), B = lab(b);
