  ridgeline: { focus: [0.4, 0.6] }, 'gradient-mesh': { angle: [-60, 60] }, 'silk-folds': { angle: [-60, 60] },
  'line-engraving': { angle: [0, 180] }, 'halftone-screen': { angle: [15, 75] }, 'painterly-landscape': { horizon: [0.4, 0.5], hillY: [0.04, 0.22] },
