effects/pick.js:
/*
  pick.js - deals effects at random for one page. One ES module, no dependencies; the same code runs
  in `node scripts/effects.mjs pick` and in the browser (gallery.html).

    import { pick } from './assets/effects/pick.js';
    const index = await fetch('./assets/effects/index.json').then(r => r.json());
    const { picks } = pick(index.effects, { palette: 'dark', slots: ['hero', 'card', 'band'], history: ['caustics'] });
    // picks: [{ slot: 'hero', id: '...' }, ...]

  One effect per slot (hero = the hero or a large split frame, card = a card group, band = a wide band
  or the closing call to action, footer). Only effects made for the palette kind (meta.palettes) and
  for that slot are dealt (without a palette kind the ground is unknown, so only effects made for all
  three kinds are dealt); never the same id twice on one page, nor the last id of the history first;
  an id used in the last 20 picks of the history is less likely, and so is a second effect of a family
  already dealt. Two effects that list each other in meta.avoidWith never share a page (ids passed in
  exclude count as already on it, as in a second pick after the lead).
  Effects that follow the pointer (motion "interactive") are left out unless interactive is true.
  quiet: true leaves out the focal grounds (meta "focal": true, a ground with its own subject such as a
  sphere, a beam or peaks) and the pattern and dither families (rules, grids, contours, dots, halftone, ASCII:
  cards.md bans a pattern behind UI), for a slot that carries a big UI window, a screenshot or text.

  Chosen on purpose: an effect with meta "random": false (a literal subject such as the dotted globe,
  or a grade for the client's own photograph) is never dealt. A page that needs one names it in its
  slot, 'hero:dotted-globe' (or { slot: 'hero', id: 'dotted-globe' }); it is still refused on a
  palette kind or a slot it is not made for, and the page rules hold for it too: never the same id
  named twice, never two named effects that list each other in avoidWith, never one that clashes with
  an id passed in exclude (or is one).
*/

export const SLOTS = ['hero', 'card', 'band', 'footer'];
export const KINDS = ['light', 'dark', 'colour'];
/** the families a quiet slot (UI, a screenshot or text on top) never gets */
const QUIET_OUT = ['pattern', 'dither'];

const kindOf = k => (k === 'color' ? 'colour' : k);
/** true when the effect may be dealt at random (meta "random": false marks one chosen on purpose) */
export const dealable = e => e.random !== false;
/** true when the effect is made for this palette kind (meta.palettes); no kind fits every effect */
export const fitsKind = (e, kind) => !kind || (Array.isArray(e.palettes) && e.palettes.includes(kindOf(kind)));
/** true when a and b must not share a page (either lists the other in meta.avoidWith) */
export const clashes = (a, b) => !!(a && b) && ((a.avoidWith || []).includes(b.id) || (b.avoidWith || []).includes(a.id));

/** the effects that match the filters (on, palette, motion, family, cost, exclude, noInteractive, dealable, quiet) */
export function filterEffects(list, a = {}) {
  let out = list;
  if (a.dealable) out = out.filter(dealable);
  if (a.noInteractive) out = out.filter(e => e.motion !== 'interactive');
  if (a.quiet) out = out.filter(e => !e.focal && !QUIET_OUT.includes(e.family));
  if (a.on) out = out.filter(e => (e.bestOn || []).includes(a.on));
  if (a.palette) out = out.filter(e => fitsKind(e, a.palette));
  if (a.motion) out = out.filter(e => e.motion === a.motion);
  if (a.family) out = out.filter(e => e.family === a.family);
  if (a.cost) out = out.filter(e => e.cost === a.cost);
  if (a.exclude) { const ex = Array.isArray(a.exclude) ? a.exclude : String(a.exclude).split(','); out = out.filter(e => !ex.includes(e.id)); }
  return out;
}

function strHash(s) {
  let h = 2166136261 >>> 0;
  for (const ch of String(s)) { h ^= ch.codePointAt(0); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
/** seeded random 0..1 (mulberry32 over a string hash of the seed) */
export function random(seed) {
  let a = strHash(seed) || 1;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

// 'hero' | 'hero:dotted-globe' | { slot, id } -> { slot, id | null }
function parseSlot(s) {
  if (s && typeof s === 'object') return { slot: s.slot, id: s.id || null };
  const [slot, id] = String(s).split(':').map(x => x.trim());
  return { slot, id: id || null };
}

/**
  effects: index.json's effects. opts: { palette, slots: [...] | count + on, seed, history: [ids, oldest
  first], interactive, quiet, exclude, motion, family, cost }. A slot may name its effect ('hero:dotted-globe').
  Returns { seed, slots, picks: [{ slot, id, named? }], notes }. Throws an Error with a plain message
  when nothing fits.
*/
export function pick(effects, opts = {}) {
  const palette = kindOf(opts.palette);
  if (palette && !KINDS.includes(palette)) throw new Error(`pick: unknown palette "${opts.palette}" (light, dark, colour)`);
  const parsed = opts.slots && opts.slots.length ? opts.slots.map(parseSlot) : null;
  const slots = parsed ? parsed.map(s => s.slot) : null;
  if (slots) for (const s of slots) if (!SLOTS.includes(s)) throw new Error(`pick: slot "${s}" (use ${SLOTS.join(', ')})`);
  const byId = new Map(effects.map(e => [e.id, e]));
  // effects named on purpose: they must exist and be made for this palette kind and slot
  const named = parsed ? parsed.map(({ slot, id }) => {
    if (!id) return null;
    const e = byId.get(id);
    if (!e) throw new Error(`pick: no effect "${id}"`);
    if (!fitsKind(e, palette)) throw new Error(`pick: "${id}" is made for ${e.palettes.join(', ')} pages, not ${palette}`);
    if (!(e.bestOn || []).includes(slot)) throw new Error(`pick: "${id}" is made for ${e.bestOn.join(', ')}, not ${slot}`);
    return e;
  }) : null;
  const exIds = (opts.exclude ? (Array.isArray(opts.exclude) ? opts.exclude : String(opts.exclude).split(',')) : []).map(id => String(id).trim()).filter(Boolean);
  if (named) {
    // the page rules hold for named effects too: once per page, no avoidWith pair, none excluded
    const given = named.filter(Boolean);
    given.forEach((e, i) => {
      if (given.findIndex(o => o.id === e.id) !== i) throw new Error(`pick: "${e.id}" is named twice; a page shows each effect once`);
      if (exIds.includes(e.id)) throw new Error(`pick: "${e.id}" is named and also excluded`);
      for (const o of given.slice(i + 1)) if (clashes(e, o)) throw new Error(`pick: "${e.id}" and "${o.id}" never share a page (avoidWith)`);
      for (const id of exIds) { const o = byId.get(id); if (clashes(e, o)) throw new Error(`pick: "${e.id}" never shares a page with "${id}", which is already on it (avoidWith)`); }
    });
  }
  const count = slots ? slots.length : Math.max(1, parseInt(opts.count ?? 1, 10) || 1);
  const base = { ...opts, palette, on: undefined, noInteractive: !opts.interactive, dealable: true };
  let pool = filterEffects(effects, slots ? base : { ...base, on: opts.on });
  // no palette kind: the ground is unknown, so only an effect made for every kind may be dealt
  if (!palette) pool = pool.filter(e => KINDS.every(k => fitsKind(e, k)));
  const allNamed = named && named.every(Boolean);
  if (!pool.length && !allNamed) throw new Error('pick: no effects match these filters');
  const fitsSlot = n => e => !slots || e.bestOn.includes(slots[n]);
  const seed = opts.seed != null && opts.seed !== '' ? String(opts.seed) : `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
  const rand = random(seed);
  const history = (opts.history || []).map(p => (typeof p === 'string' ? p : p && p.id)).filter(Boolean);
  const recent = history.slice(-20);
  const fixed = named ? named.filter(Boolean) : [];
  // excluded ids are the ones an earlier pick already put on the page (or banned): their avoidWith holds too
  const earlier = exIds.map(id => byId.get(id)).filter(Boolean);
  const out = [];
  const notes = [];
  // the effects already on the page: dealt so far plus every named one
  const onPage = () => [...out.map(id => byId.get(id)), ...fixed.filter(e => !out.includes(e.id))];
  for (let n = 0; n < count; n++) {
    if (named && named[n]) { out.push(named[n].id); continue; }
    const prev = out.length ? out[out.length - 1] : history[history.length - 1];
    const slotPool = pool.filter(fitsSlot(n));
    if (!slotPool.length) throw new Error(`pick: no effect fits slot "${slots[n]}"${palette ? ` on a ${palette} page` : ''}`);
    const page = onPage();
    const ok = e => !page.some(p => clashes(p, e)) && !earlier.some(p => clashes(p, e));
    const taken = new Set(page.map(e => e.id));
    const fits = slotPool.filter(ok);
    if (!fits.length) throw new Error(`pick: every effect for slot "${slots ? slots[n] : opts.on || n + 1}" clashes with one already on the page (avoidWith)`);
    let cands = fits.filter(e => e.id !== prev && !taken.has(e.id));
    if (!cands.length) {
      // every effect for this slot is on the page already: one repeats with its own seed, and says so
      cands = fits.filter(e => e.id !== prev);
      if (cands.length) notes.push(`pick: every effect for slot ${n + 1} (${slots ? slots[n] : opts.on || 'any'}) is on the page already, so one repeats`);
    }
    if (!cands.length) { notes.push(`pick: only "${fits[0].id}" fits slot ${n + 1}, so it repeats`); cands = fits; }
    const weights = cands.map(e => {
      const uses = recent.filter(id => id === e.id).length;
      let wt = Math.pow(0.35, uses);
      const at = recent.lastIndexOf(e.id);
      if (at >= 0 && at >= recent.length - 5) wt *= 0.5;
      const famUses = page.filter(p => p.family === e.family).length;
      wt *= Math.pow(0.3, famUses);
      return wt;
    });
    const total = weights.reduce((s, x) => s + x, 0);
    let r = rand() * total, i = 0;
    while (i < weights.length - 1 && (r -= weights[i]) > 0) i++;
    out.push(cands[i].id);
  }
  return {
    seed, slots,
    picks: out.map((id, i) => ({ slot: slots ? slots[i] : opts.on || null, id, ...(named && named[i] ? { named: true } : {}) })),
    notes,
  };
}

export default { pick, filterEffects, random, dealable, fitsKind, clashes, SLOTS, KINDS };

effects/spotlight-cone/effect.js:
// spotlight-cone: one stage light from a lamp out of frame above. A slanted cone through uneven,
// drifting haze, its edge going softer the further the light travels, lands as a soft pool on the
// floor that spills a little light around it. On light pages the room stays at the page's own
// lightness and only the corners away from the light dim slightly. The cone keeps away from text.
import { shader, color } from '../fx.js';

const params = {
  x:         { default: 0.5,  min: 0,    max: 1,    step: 0.01 },  // where the pool lands, 0 left .. 1 right
  lean:      { default: 0.3,  min: 0,    max: 0.8,  step: 0.01 },  // how far the lamp sits to the side (height units)
  width:     { default: 0.22, min: 0.08, max: 0.5,  step: 0.01 },  // half width of the light at the floor (height units)
  poolY:     { default: 0.8,  min: 0.5,  max: 0.95, step: 0.01 },  // the floor where the pool lands, 0 top .. 1 bottom
  haze:      { default: 0.45, min: 0,    max: 1,    step: 0.01 },  // light seen in the air
  edge:      { default: 0.5,  min: 0.1,  max: 1,    step: 0.01 },  // softness of the cone edge (grows with distance)
  intensity: { default: 1,    min: 0,    max: 1.5,  step: 0.01 },
  breathe:   { default: 0,    min: 0,    max: 1,    step: 0.01 },  // slow rise and fall of the light
  speed:     { default: 0.12, min: 0,    max: 1,    step: 0.01 },  // drift of the haze
  calm:      { default: 0.4,  min: 0,    max: 1,    step: 0.01 },  // keep the light off the text and dim it there
  calmX:     { default: 0.2,  min: 0,    max: 1,    step: 0.01 },
  calmY:     { default: 0.3,  min: 0,    max: 1,    step: 0.01 },
};

const frag = /* glsl */ `
float calmMask(vec2 uv) {
  vec2 d = (uv - vec2(u_calmX, u_calmY)) * vec2(u_res.x / u_res.y, 1.0);
  vec2 R = vec2(0.3 + 0.3 * u_calm, 0.14 + 0.1 * u_calm);
  return 1.0 - smoothstep(0.75, 1.35, length(d / R));
}

void main() {
  vec2 uv = fx_uv();
  float asp = u_res.x / u_res.y;
  vec2 P = vec2(uv.x * asp, uv.y);
  float t = u_time * u_speed * 0.15 + u_seed * 0.021;

  vec2 pool = vec2(u_cx * asp, u_poolY);
  vec2 lamp = vec2(pool.x + u_leanS, -0.4);         // out of frame, above
  vec2 ax = normalize(pool - lamp);
  float D = length(pool - lamp);
  vec2 v = P - lamp;
  float d = dot(v, ax);                              // distance along the light
  float pr = dot(v, vec2(-ax.y, ax.x));              // distance across it
  float k = clamp(d / D, 0.0, 1.2);
  float w = u_width * d / D;
  float rel = abs(pr) / max(w, 1e-3);
  // the penumbra widens with distance: crisp near the lamp, very soft by the floor
  float pen = u_edge * mix(0.12, 0.75, k);
  float cone = smoothstep(1.0 + pen, 1.0 - pen, rel) * step(0.0, d);

  // haze: brighter near the lamp and through the middle of the cone, uneven and drifting
  float thick = sqrt(max(0.0, 1.0 - min(rel * rel, 1.0)));
  // slow smoke: warped noise, stretched a little along the light
  vec2 hp = vec2(pr * 3.4, d * 1.5 - t) + u_seed * 0.01;
  hp += 0.7 * vec2(fx_noise(hp * 0.9 + vec2(t * 0.3, 0.0)), fx_noise(hp * 0.9 + vec2(5.2, -t * 0.25)));
  float nz = fx_fbm(hp);
  float nz2 = fx_noise(vec2(pr * 10.0 - t * 0.8, d * 5.0 + t * 0.5) + 31.0);
  float hz = u_haze * (0.28 + 0.85 * exp(-k * 2.4)) * mix(0.5, 1.0, thick);
  hz *= 0.25 + 1.25 * smoothstep(-0.5, 0.55, nz) + 0.18 * nz2;
  // the cone ends on the floor
  float ph = u_width * 0.26;
  float aboveFloor = 1.0 - smoothstep(u_poolY - ph * 0.6, u_poolY + ph * 1.2, uv.y);
  float air = cone * hz * aboveFloor;

  // the pool: a soft ellipse flattened by perspective, brightest in the middle
  vec2 pq = vec2((P.x - pool.x) / (u_width * 1.12), (uv.y - u_poolY) / ph);
  float pe = length(pq);
  float poolL = exp(-pe * pe * 1.3) * 0.8 + exp(-pe * pe * 0.45) * 0.18;
  poolL *= 0.9 + 0.1 * fx_noise(pq * 1.7 + t * 0.4 + 9.0);
  float spill = exp(-pe * 0.75) * 0.14 * smoothstep(u_poolY - ph * 5.0, u_poolY, uv.y);
  // a little light bounces off the floor onto the wall behind
  vec2 bq = (P - pool) / vec2(u_width * 3.0, 0.45);
  float bounce = exp(-dot(bq, bq)) * 0.07;
  // where the light enters the frame it is brightest
  float entry = cone * exp(-max(uv.y, 0.0) * 9.0) * 0.35;

  float br = 1.0 + u_breathe * 0.14 * sin(u_time * 0.5 + u_seed);
  float cm = 1.0 - 0.7 * calmMask(uv) * smoothstep(0.0, 0.4, u_calm);
  float L = (air * 0.85 + poolL + spill + bounce + entry) * u_intensity * br * cm;

  // the room: the floor a touch lighter than the wall, corners dimmer
  vec3 ground = u_ground;
  ground.x += u_floor * smoothstep(u_poolY - ph * 3.0, u_poolY + ph * 3.0, uv.y);
  vec2 vq = uv - vec2(u_cx, 0.6);
  ground.x -= u_vig * min(1.0, dot(vq, vq) * 1.6);

  float m = 1.0 - exp(-L * 1.2);
  vec3 col = mix(ground, u_light, m);
  col = mix(col, u_hot, smoothstep(0.55, 0.95, m) * 0.5);
  col.x += fx_grain(gl_FragCoord.xy, floor(u_time * 24.0)) * 0.006 * (0.5 + m);
  fxColor = vec4(fx_dither(fx_rgb(col)), 1.0);
}
`;

export function tones(P) {
  const { bg, ink, accent } = P;
  const [Lb] = color.lab(bg);
  const tinted = color.chroma(bg) < 0.035 && color.chroma(accent) > 0.035 && !(color.lch(accent)[2] >= 262 && color.lch(accent)[2] <= 338);
  if (Lb < 0.6) {
    // dark: the light is a white tinted by the palette
    const base = color.adjust(bg, { l: 0.9 - Lb, c: 0.3 });
    const light = tinted ? color.mix(base, color.withLightness(accent, 0.88), 0.16) : base;
    return {
      ground: color.darken(bg, Math.min(0.03, Lb * 0.1)),
      light,
      hot: color.mix(light, color.withLightness(ink, 0.99), 0.6),
      floor: 0.012, vig: 0.04,
    };
  }
  // light page: the room stays within a few points of the page lightness (no added colour), only
  // the corners away from the light dim; the light goes toward white
  return {
    ground: color.darken(bg, Math.min(0.03, Lb * 0.03)),
    light: color.fromLch([Math.min(0.995, Lb + 0.09), color.chroma(bg) * 0.6, color.lch(bg)[2]]),
    hot: color.fromLch([Math.min(0.998, Lb + 0.1), color.chroma(bg) * 0.35, color.lch(bg)[2]]),
    floor: 0.008, vig: 0.025,
  };
}

// where the pool lands: the asked x, moved to the far side of the text (calm) when the two would meet
export function poolX(prm) {
  let x = prm.x;
  if (prm.calm > 0.05 && Math.abs(x - prm.calmX) < 0.34) x = prm.calmX < 0.5 ? prm.calmX + 0.42 : prm.calmX - 0.42;
  return Math.min(0.78, Math.max(0.22, x));
}

function uniforms({ palette, params: prm, width, height }) {
  const k = tones(palette);
  const x = poolX(prm);
  // the lamp leans in from the side with more room
  const lean = (x < 0.5 ? 1 : -1) * prm.lean;
  return { u_ground: color.labVec(k.ground), u_light: color.labVec(k.light), u_hot: color.labVec(k.hot), u_floor: k.floor, u_vig: k.vig, u_cx: x, u_leanS: lean };
}

export default {
  id: 'spotlight-cone',
  name: 'Stage spotlight',
  family: 'light',
  params,
  mount(el, { palette, params: given, seed }) {
    return shader(el, {
      frag,
      schema: params,
      params: given,
      palette,
      seed,
      uniforms,
      still: 2,
      fallback: ({ palette: P, params: prm }) => {
        const k = tones(P);
        const x = poolX(prm) * 100, y = prm.poolY * 100;
        return `radial-gradient(${prm.width * 110}% ${prm.width * 40}% at ${x}% ${y}%, ${color.mix(k.ground, k.hot, 0.75)}, transparent 100%), `
          + `radial-gradient(${prm.width * 90}% ${y}% at ${x}% 0%, ${color.mix(k.ground, k.light, 0.3)}, transparent 80%), ${k.ground}`;
      },
    });
  },
};

effects/soft-light-bars/effect.js:
// soft-light-bars: a few soft, nearly upright bars of light of uneven width, grouped unevenly to one
// side of the text, like light through slats landing on a wall. One broad pool of light lands on the
// group and drifts slowly along it; each bar breathes on its own slow cycle; elsewhere the bars fall
// into the ground. Flat cores with blurred edges and a faint bloom, a fine grainy dissolve at the
// edges, still grain. On light grounds the light cannot be lighter than the page, so the pool shades
// the wall between the bars instead. Every colour is a step of the palette.
import { shader, color, grainCSS } from '../fx.js';

const params = {
  speed:    { default: 0.5,  min: 0, max: 2,   step: 0.01 }, // breathing and drift speed (0.5 is real time)
  bars:     { default: 0,    min: 0, max: 7,   step: 1 },    // number of bars, 4 to 7; 0 lets the seed choose
  tilt:     { default: 0.5,  min: 0, max: 1,   step: 0.01 }, // lean: 0 upright, 0.5 a seeded 2 to 14 degrees, 1 twice that
  softness: { default: 0.6,  min: 0, max: 1,   step: 0.01 }, // edge blur
  glow:     { default: 0.8,  min: 0, max: 1.5, step: 0.01 }, // brightness of the light
  breathe:  { default: 0.5,  min: 0, max: 1,   step: 0.01 }, // depth of each bar's slow breathing
  haze:     { default: 0.5,  min: 0, max: 1,   step: 0.01 }, // the pool in the air between the bars (a shade on light grounds)
  stipple:  { default: 0.4,  min: 0, max: 1,   step: 0.01 }, // grainy dissolve at the bar edges
  grain:    { default: 0.5,  min: 0, max: 1,   step: 0.01 }, // still film grain
  calm:     { default: 0.55, min: 0, max: 1,   step: 0.01 }, // keep the area around the text empty
  calmX:    { default: 0.25, min: 0, max: 1,   step: 0.01 }, // calm area centre, 0 left .. 1 right
  calmY:    { default: 0.7,  min: 0, max: 1,   step: 0.01 }, // calm area centre, 0 top .. 1 bottom
};

const frag = /* glsl */ `
// five-stop ramp in OKLab: ground, low, mid, high, and the hottest stop only at the top
vec3 ramp(float v, vec3 k0, vec3 k1, vec3 k2, vec3 k3, vec3 k4) {
  vec3 c = mix(k0, k1, clamp(v / 0.22, 0.0, 1.0));
  c = mix(c, k2, clamp((v - 0.22) / 0.28, 0.0, 1.0));
  c = mix(c, k3, clamp((v - 0.5) / 0.3, 0.0, 1.0));
  return mix(c, k4, clamp((v - 0.8) / 0.2, 0.0, 1.0));
}

// one bar at x (measured across the bars); b = (centre, half width, phase, strength). A flat core
// with a blurred edge, as light through a slat, plus a faint bloom around it
float bar(float x, vec4 b, float t, float jit, float e) {
  if (b.y <= 0.0) return 0.0;
  float om = 0.39 + 0.24 * fract(b.z * 0.731);                  // one breath in about 10 to 16 s
  float hw = b.y * (1.0 + 0.06 * u_breathe * sin(t * om * 0.61 + b.z * 1.7));
  float d = abs(x - b.x) + jit;
  float core = 1.0 - smoothstep(hw - 0.5 * e, hw + e, d);
  float bw = (d / (hw + 2.5 * e));
  float bloom = 0.12 * exp(-bw * bw);
  float breath = 1.0 - u_breathe * 0.4 * (0.5 - 0.5 * cos(t * om + b.z));
  return (core + bloom * (1.0 - core)) * breath * b.w;
}

void main() {
  vec2 uv = fx_uv();
  vec2 p = fx_p();
  // small phase offset per seed keeps t small, so sin() stays smooth on mediump GPUs
  float t = u_time * u_speed * 2.0 + mod(u_seed, 97.0) * 0.71;
  // q.x runs across the bars, q.y along them
  vec2 q = vec2(p.x * u_rot.x - p.y * u_rot.y, p.x * u_rot.y + p.y * u_rot.x);

  // the pool drifts slowly along the bars and back (one way in about 6 s), with a smaller sideways sway
  vec2 pc = u_pool.xy + vec2(0.012 * sin(t * 0.29 + 1.3), u_drift * sin(t * 0.52));
  vec2 d = (q - pc) / u_pool.zw;
  float pool = exp(-dot(d, d));

  // a little uneven light along the bars, flowing very slowly
  float n = fx_noise(vec2(q.x * 1.1 + 4.3, q.y * 1.4 - t * 0.03));
  float light = (u_floor + (1.0 - u_floor) * pool) * (1.0 + 0.3 * n);

  // a fine, still jitter of the edge on a CSS-pixel lattice: the grainy dissolve
  vec2 cpx = gl_FragCoord.xy / max(u_dpr, 1.0);
  float jit = (fx_vnoise(cpx * 1.7) + fx_vnoise(cpx * 1.7 + vec2(13.1, 57.7)) - 1.0) * 0.012 * u_stipple;
  float e = 0.02 + 0.045 * u_softness;
  float m = 1.0;
  m *= 1.0 - bar(q.x, u_b0, t, jit, e);
  m *= 1.0 - bar(q.x, u_b1, t, jit, e);
  m *= 1.0 - bar(q.x, u_b2, t, jit, e);
  m *= 1.0 - bar(q.x, u_b3, t, jit, e);
  m *= 1.0 - bar(q.x, u_b4, t, jit, e);
  m *= 1.0 - bar(q.x, u_b5, t, jit, e);
  m *= 1.0 - bar(q.x, u_b6, t, jit, e);
  float v = (1.0 - m) * light * u_glow * 1.1;

  // the calm area stays empty for text, and the light falls to the ground at the frame edges
  float cm = fx_calm(uv, vec2(u_calmX, u_calmY), 0.35 + 0.45 * u_calm);
  float quiet = clamp(1.6 * u_calm, 0.0, 1.0) * cm;
  v *= 1.0 - quiet;
  float fe = smoothstep(-0.05, 0.32, uv.y) * smoothstep(-0.05, 0.32, 1.0 - uv.y)
           * smoothstep(-0.05, 0.12, uv.x) * smoothstep(-0.05, 0.12, 1.0 - uv.x);
  v = clamp(v * (0.45 + 0.55 * fe), 0.0, 1.0);

  // bars far from the pool lean toward the companion colour (dark grounds only)
  float hb = smoothstep(0.15, 1.0, abs(q.x - pc.x) / u_spanB) * u_bAmt;
  vec3 col = mix(ramp(v, u_a0, u_a1, u_a2, u_a3, u_a4), ramp(v, u_a0, u_q1, u_q2, u_q3, u_q4), hb);
  // the pool in the air between the bars: a lift of the ground on dark grounds, a shade of the wall on
  // light ones, a deeper ground on colour fields; always a step of the ground itself. On light grounds
  // and colour fields it stays inside the group (the window), so it reads as the slats' shadow, not a stain
  float win = smoothstep(u_win.x - 0.1, u_win.x + 0.01, q.x) * (1.0 - smoothstep(u_win.y - 0.01, u_win.y + 0.1, q.x));
  float hzm = mix(1.0, win, u_win.z);
  col = mix(col, u_hz.xyz, min(1.0, 2.0 * u_haze) * u_hz.w * pool * hzm * fe * (1.0 - quiet) * (1.0 - smoothstep(0.0, 0.45, v)));

  // still grain on lightness, on the same soft one-CSS-pixel lattice (so DPR scaling never blurs it
  // into a different texture), quieter near white and black
  float g = fx_vnoise(cpx * 0.9 + 17.0) + fx_vnoise(cpx * 0.9 + vec2(71.3, 29.9)) - 1.0;
  float amp = u_grainAmp * u_grain * (1.0 - 0.6 * smoothstep(0.86, 1.0, col.x)) * (0.5 + 0.5 * smoothstep(0.0, 0.22, col.x));
  col.x += g * amp;

  fxColor = vec4(fx_dither(fx_rgb(col)), 1.0);
}
`;

/* ------------------------------------------------------------------ colours */

const smooth = (a, b, x) => { const k = Math.min(1, Math.max(0, (x - a) / (b - a))); return k * k * (3 - 2 * k); };
const lerp = (a, b, k) => a + (b - a) * k;

// no violet, lavender or mauve: hues 272..338 with chroma above 0.02, and for pale tints a wider band
// (262..345), where blue turns periwinkle and pink turns mauve
const banned = (L, C, h) => C > 0.02 && (L > 0.7 ? h > 262 && h < 345 : h > 272 && h < 338);
function guard(c) {
  let [L, C, h] = color.lch(c);
  if (C <= 0.02) return color.hex(c);
  // blue reads periwinkle as it gets pale, so pale blues lean toward sky blue, step by step
  if (h > 248 && h < 272 && L > 0.6) h -= (h - 248) * smooth(0.6, 0.75, L);
  if (banned(L, C, h)) h = h < 303 ? (L > 0.7 ? 250 : 265) : (L > 0.7 ? 350 : 342);
  return color.fromLch([L, C, h]);
}
const labLch = ([L, a, b]) => [L, Math.hypot(a, b), ((Math.atan2(b, a) * 180) / Math.PI + 360) % 360];
const hueGap = (a, b) => { const d = Math.abs(a - b) % 360; return d > 180 ? 360 - d : d; };
// the GPU blends these colours in OKLab: no point of a blend may fall in the band either (only the
// ground's own colour is allowed, close to the ground, when the page's ground itself sits in the band)
function blendsClean(pairs, bg) {
  const G = color.lch(bg), gBad = banned(...G);
  for (const [x, y] of pairs) {
    const A = color.lab(x), B = color.lab(y);
    for (let i = 1; i < 8; i++) {
      const s = labLch(A.map((v, j) => v + (B[j] - v) * (i / 8)));
      if (banned(...s) && !(gBad && s[1] <= G[1] + 0.012 && Math.abs(s[0] - G[0]) < 0.12 && hueGap(s[2], G[2]) < 12)) return false;
    }
  }
  return true;
}
// the companion: the hue turned to the side that stays out of the band
function companion(c, deg = 35) {
  const [L, C, h] = color.lch(c);
  let hb = (h + deg) % 360;
  if (banned(L, C, hb) || banned(0.5, C, hb)) hb = (h + 360 - deg) % 360;
  return guard(color.fromLch([L, C * 0.8, hb]));
}

// the colour of the light on a dark ground: the accent, unless it would turn violet (then a clean white),
// sits far from the ground's hue (then light in the ground's own hue) or is too muted (then lifted to a
// pale light, so it never reads as a dim brown)
function darkLight(P, mode) {
  const { bg, ink, accent } = P;
  const [, Cb, hb] = color.lch(bg), [La, Ca, ha] = color.lch(accent);
  const white = () => (Cb > 0.012 ? color.fromLch([0.88, 0.025, hb]) : color.fromLch([0.9, 0.014, 85]));
  if (mode === 'white') return guard(white());
  if (mode === 'ground') return Cb > 0.012 ? guard(color.fromLch([0.8, Math.min(0.09, Math.max(0.04, Cb * 1.5)), hb])) : guard(white());
  if (Ca < 0.02 || banned(0.5, Ca, ha)) return guard(white());
  if (Cb >= 0.03 && color.hueDistance(bg, accent) > 60) return darkLight(P, 'ground');
  if (Ca < 0.07) return guard(color.fromLch([Math.max(La, 0.82), Math.min(Ca, 0.05), ha]));
  return guard(La < 0.58 ? color.fromLch([0.58, Ca, ha]) : accent);
}

function rampDark(P, lc) {
  const { bg, ink } = P;
  // a neon accent is held to a calmer chroma, so the bars glow rather than shout
  let [L, C, h] = color.lch(lc);
  if (C > 0.17) { C = 0.17; lc = color.fromLch([L, C, h]); }
  const lo = color.fromLch([L * 0.6, C * 0.8, h]), hi = color.fromLch([Math.min(0.95, L + 0.1), C * 0.75, h]);
  // the hottest stop whitens toward the ink, or toward plain white when the ink has another hue
  const [, Ci, hi2] = color.lch(ink);
  const hot = Ci < 0.03 || hueGap(hi2, h) < 40 ? ink : '#ffffff';
  return [bg, color.mix(bg, lo, 0.6), color.mix(bg, lc, 0.8), lc, color.mix(hi, hot, 0.45)].map((c, i) => (i ? guard(c) : c));
}

function tones(P, kind) {
  const { bg, accent } = P;
  const [Lb, Cb, hb] = color.lch(bg), [, Ca, ha] = color.lch(accent);
  const G = color.lab(bg);
  let A, B = null, hz, hzAmt, bAmt = 0, win = 0.5;

  if (kind === 'dark') {
    // try the light colour with its companion, then without, then in the ground's hue, then white
    const tries = [[null, true], [null, false], ['ground', false], ['white', false]];
    hz = guard(color.fromLch([Math.max(Lb + 0.05, 0.13), Cb, hb]));
    hzAmt = 0.85;
    for (const [mode, withB] of tries) {
      const lc = darkLight(P, mode);
      A = rampDark(P, lc);
      B = withB ? rampDark(P, companion(lc)) : null;
      const pairs = [];
      for (let i = 0; i < 4; i++) pairs.push([A[i], A[i + 1]], [hz, A[i + 1]]);
      if (B) for (let i = 0; i < 4; i++) pairs.push([B[i], B[i + 1]], [A[i + 1], B[i + 1]], [hz, B[i + 1]]);
      if (blendsClean(pairs, bg)) break;
    }
    bAmt = B ? 0.4 : 0;
  } else if (kind === 'colour') {
    // light in the ground's own hue over a strong ground; on bright fields a cream-white core and a
    // deeper ground between the bars, so the light still stands out of the colour
    const bright = smooth(0.62, 0.78, Lb);
    const Lc = Lb + lerp(Math.min(0.42, 0.9 - Lb) * 0.85, Math.min(0.97 - Lb, 0.19), bright);
    let Cc = Cb * lerp(0.5, 0.45, bright);
    for (let k = 0; k < 4; k++) {
      const core = color.fromLch([Lc, Cc, hb]);
      const st = s => color.fromLch([lerp(Lb, Lc, s), lerp(Cb, Cc, s * 0.8), hb]);
      A = [bg, st(0.25), st(0.55), core, color.mix(core, '#ffffff', 0.45)].map((c, i) => (i ? guard(c) : c));
      // a deeper yellow turns olive, so yellow fields deepen toward amber instead
      const hh = hb > 55 && hb < 115 ? hb - 16 : hb;
      hz = guard(color.fromLch([Math.max(0.06, Lb - lerp(0.07, 0.09, bright)), Cb * (hh !== hb ? 1.1 : 1), hh]));
      const pairs = [];
      for (let i = 0; i < 4; i++) pairs.push([A[i], A[i + 1]], [hz, A[i + 1]]);
      if (blendsClean(pairs, bg)) break;
      Cc *= 0.5;
    }
    hzAmt = lerp(0.7, 0.85, bright);
    win = 1;
  } else {
    // a light ground: the bars are daylight, as much lighter than the wall as there is room for, and the
    // pool shades the wall between them, more so the closer the wall is to white (one smooth rule, so
    // two near-equal off-whites always look alike)
    const far = Cb >= 0.03 && Ca >= 0.03 && color.hueDistance(bg, accent) > 60;
    // the light is tinted like daylight: by the accent when it is a natural light hue (amber to teal),
    // otherwise by the wall's own hue, or a faint warm white (a pink or blue glimmer reads as a stripe)
    let tint;
    if (Ca > 0.03 && ha >= 40 && ha <= 200 && !far) tint = [0.022, ha];
    else if (Cb >= 0.012) tint = [Math.min(0.025, Cb), hb];
    else tint = [0.012, 85];
    // the shadow is cool, as daylight shadow is: the accent's hue when that is a green, teal or blue, a
    // clean cool grey otherwise (a warm or pink shadow on a pale wall reads as a stain)
    const cool = Ca > 0.03 && ha >= 150 && ha <= 262 && !far;
    let sh = [0.016, cool ? ha : 245];
    const lift = Math.min(0.12, Math.max(0, 0.985 - Lb));
    const shade = 0.03 + 0.05 * smooth(0.88, 0.98, Lb);
    const ab = ([c, h]) => [c * Math.cos((h * Math.PI) / 180), c * Math.sin((h * Math.PI) / 180)];
    for (let k = 0; k < 3; k++) {
      const T = ab(tint), S = ab(sh);
      const st = s => guard(color.fromLab([Math.min(1, Lb + lift * s), lerp(G[1], T[0], s), lerp(G[2], T[1], s)]));
      A = [bg, st(0.3), st(0.6), st(0.85), st(1)];
      hz = guard(color.fromLab([Lb - shade, G[1] * 0.55 + S[0], G[2] * 0.55 + S[1]]));
      const pairs = [];
      for (let i = 0; i < 4; i++) pairs.push([A[i], A[i + 1]], [hz, A[i + 1]]);
      if (blendsClean(pairs, bg)) break;
      tint = k === 0 && Cb >= 0.012 ? [Math.min(0.025, Cb), hb] : [0.01, 85];
      sh = [0.012, 230];
    }
    hzAmt = 1;
    win = 1;
  }
  return { A, B: B || A, hz, hzAmt, bAmt, win, grain: kind === 'dark' ? 0.035 : 0.04 };
}

/* ------------------------------------------------------------------ composition */

// pack k bars into [a, b] (positions across the bars, in frame heights), grouped unevenly: gaps a little
// wider than the blur, one break that splits a group, and a free offset so they never hug both ends
function pack(k, a, b, r, edge, maxGap) {
  const room = b - a;
  for (; k > 0; k--) {
    const hw = Array.from({ length: k }, () => 0.022 + 0.05 * Math.pow(r(), 1.4));
    const gaps = Array.from({ length: k - 1 }, () => 2 * edge * (1 + 1.6 * r()) + 0.02);
    if (k >= 3) { const i = Math.floor(r() * (k - 1)); gaps[i] *= 1.6 + r(); }
    for (let i = 0; i < gaps.length; i++) gaps[i] = Math.min(gaps[i], maxGap);
    let len = 2 * edge + hw.reduce((s, w) => s + 2 * w, 0) + gaps.reduce((s, g) => s + g, 0);
    let f = 1;
    if (len > room) { f = room / len; if (f < 0.7) continue; len = room; }
    let x = a + (room - len) * (0.15 + 0.7 * r()) + edge * f;
    return hw.map((w, i) => {
      const c = x + w * f;
      x += 2 * w * f + (gaps[i] || 0) * f;
      return [c, w * f, r() * 6.283, 0.65 + 0.35 * r()];
    });
  }
  return [];
}

// bars, tilt and pool from the seed; shared by the shader and the CSS fallback
function scene({ params: prm, rng: r, width, height }) {
  const asp = width && height ? width / height : 16 / 9;
  const side = r() < 0.5 ? -1 : 1;
  const deg = Math.min(22, (2 + 12 * r()) * prm.tilt * 2);
  const theta = (side * deg * Math.PI) / 180;
  const cs = Math.cos(theta), sn = Math.sin(theta);
  const half = (asp * cs + Math.abs(sn)) / 2;                    // half the frame, measured across the bars
  const edge = 0.02 + 0.045 * prm.softness;
  const toQ = (x, y) => [x * cs - y * sn, x * sn + y * cs];
  const [qc] = toQ((prm.calmX - 0.5) * asp, 0.5 - prm.calmY);

  // the text sits in the widest gap: no bar's blurred edge comes within 0.12 frame widths of it (plus the
  // lean over the height of a text block)
  const keep = 0.12 * asp + 0.12 * Math.abs(sn) + 0.03 * r();
  const L = [-half + 0.02, qc - keep], R = [qc + keep, half - 0.02];
  const lenL = Math.max(0, L[1] - L[0]), lenR = Math.max(0, R[1] - R[0]);
  const poolRight = Math.abs(lenR - lenL) < 0.15 * asp ? r() < 0.5 : lenR > lenL;
  const [PS, OS] = poolRight ? [R, L] : [L, R];
  const n = prm.bars >= 1 ? Math.max(4, Math.round(prm.bars)) : 4 + Math.floor(r() * 4);
  const otherLen = OS[1] - OS[0];
  let nOther = otherLen > 0.3 ? Math.round(n * (0.15 + 0.25 * r()) * Math.min(1, otherLen / (PS[1] - PS[0] + 1e-3) * 1.5)) : 0;
  nOther = Math.min(nOther, n - 2);
  const maxGap = 1.6 * keep;
  const main = pack(n - nOther, PS[0], PS[1], r, edge, maxGap);
  const rest = pack(nOther, OS[0], OS[1], r, edge, maxGap);
  const bars = [...main, ...rest].slice(0, 7);

  // the pool lands on the main group, across from the text along the bars too
  const g0 = main.length ? main[0][0] - main[0][1] : PS[0], g1 = main.length ? main[main.length - 1][0] + main[main.length - 1][1] : PS[1];
  const pqx = (g0 + g1) / 2 + (r() - 0.5) * 0.08;
  const cy = prm.calmY;
  const py = cy > 0.6 ? 0.22 + 0.2 * r() : cy < 0.4 ? 0.58 + 0.2 * r() : 0.32 + 0.3 * r();
  const yP = 0.5 - py, xP = (pqx + yP * sn) / cs;
  const [, pqy] = toQ(xP, yP);
  const rx = Math.max((g1 - g0) / 2 + 0.14, 0.32) * (1 + 0.25 * r());
  const ry = 0.3 + 0.16 * r();
  return { asp, theta, cs, sn, half, edge, bars, pool: [pqx, pqy, rx, ry], drift: 0.03 + 0.03 * r(), px: xP / asp + 0.5, py, group: [g0 - edge, g1 + edge] };
}

function uniforms(ctx) {
  const S = scene(ctx);
  const T = tones(ctx.palette, ctx.kind);
  const u = {
    u_rot: [S.cs, S.sn],
    u_pool: S.pool,
    u_drift: S.drift,
    u_floor: 0.06,
    u_spanB: S.half,
    u_bAmt: T.bAmt,
    u_grainAmp: T.grain,
    u_hz: [...color.labVec(T.hz), T.hzAmt],
    u_win: [S.group[0], S.group[1], T.win],
  };
  for (let i = 0; i < 7; i++) u['u_b' + i] = S.bars[i] || [0, 0, 0, 0];
  T.A.forEach((c, i) => { u['u_a' + i] = color.labVec(c); });
  T.B.forEach((c, i) => { if (i) u['u_q' + i] = color.labVec(c); });
  return u;
}

/* ------------------------------------------------------------------ CSS fallback */

function rampAt(k, v) {
  const st = [0, 0.22, 0.5, 0.8, 1];
  v = Math.max(0, Math.min(1, v));
  for (let i = 0; i < 4; i++) if (v <= st[i + 1]) return color.mix(k[i], k[i + 1], (v - st[i]) / (st[i + 1] - st[i]));
  return k[4];
}
const alpha = (hex, a) => hex + Math.round(Math.max(0, Math.min(1, a)) * 255).toString(16).padStart(2, '0');

// the same bars as soft stops of one angled linear gradient (five stops per edge follow the shader's
// smooth edge, so no Mach bands), lit by the pool, held to the pool by a veil of the ground
function fallback(ctx) {
  const P = ctx.palette, prm = ctx.params, bg = P.bg;
  const S = scene(ctx);
  const T = tones(P, ctx.kind);
  const deg = 90 + (S.theta * 180) / Math.PI;
  const rad = (deg * Math.PI) / 180;
  const line = Math.abs(S.asp * Math.sin(rad)) + Math.abs(Math.cos(rad)); // gradient line, in heights
  const pct = x => 50 + (x / line) * 100;
  const e = S.edge;
  const stops = [];
  let last = -1e9;
  const push = (c, x) => { const v = Math.max(last, pct(x)); last = v; stops.push(`${c} ${v.toFixed(2)}%`); };
  const prof = [[1, 0], [0.625, 0.16], [0.25, 0.5], [-0.125, 0.84], [-0.5, 1]];   // (offset in blurs, alpha)
  for (const [c, h, , w] of [...S.bars].sort((a, b) => a[0] - b[0])) {
    const dx = (c - S.pool[0]) / S.pool[2];
    const v = w * prm.glow * 1.1 * (0.06 + 0.94 * Math.exp(-dx * dx));
    const col = color.hex(rampAt(T.A, v));
    for (const [o, a] of prof) push(alpha(col, a), c - h - o * e);
    for (const [o, a] of [...prof].reverse()) push(alpha(col, a), c + h + o * e);
  }
  const at = `${(S.px * 100).toFixed(1)}% ${(S.py * 100).toFixed(1)}%`;
  const rw = ((S.pool[2] * 1.8) / S.asp) * 100, rh = S.pool[3] * 1.8 * 100;
  const hz = color.hex(color.mix(bg, T.hz, Math.min(1, 2 * prm.haze) * T.hzAmt));
  const calmA = Math.min(1, 1.6 * prm.calm) * 0.95;
  // the shade (light grounds, colour fields) stays inside the group like the shader's window; the lift of
  // a dark ground is a soft pool
  const [w0, w1] = S.group;
  const air = T.win >= 1
    ? `linear-gradient(${deg.toFixed(2)}deg, ${alpha(hz, 0)} ${pct(w0 - 0.1).toFixed(2)}%, ${alpha(hz, 0.5)} ${pct(w0 - 0.045).toFixed(2)}%, ${hz} ${pct(w0 + 0.01).toFixed(2)}%, ${hz} ${pct(w1 - 0.01).toFixed(2)}%, ${alpha(hz, 0.5)} ${pct(w1 + 0.045).toFixed(2)}%, ${alpha(hz, 0)} ${pct(w1 + 0.1).toFixed(2)}%)`
    : `radial-gradient(${rw.toFixed(1)}% ${rh.toFixed(1)}% at ${at}, ${hz}, ${alpha(hz, 0.5)} 45%, ${alpha(hz, 0)} 100%)`;
  return [
    grainCSS(ctx.kind === 'dark' ? 0.05 : 0.07),
    `radial-gradient(42% 55% at ${(prm.calmX * 100).toFixed(1)}% ${(prm.calmY * 100).toFixed(1)}%, ${alpha(bg, calmA)}, ${alpha(bg, calmA * 0.5)} 40%, ${alpha(bg, 0)} 80%)`,
    `radial-gradient(${rw.toFixed(1)}% ${rh.toFixed(1)}% at ${at}, ${alpha(bg, 0)} 20%, ${alpha(bg, 0.55)} 55%, ${alpha(bg, 0.9)} 80%, ${bg} 100%)`,
    `linear-gradient(${deg.toFixed(2)}deg, ${stops.join(', ')})`,
    air,
    bg,
  ].join(', ');
}

export default {
  id: 'soft-light-bars',
  name: 'Soft light bars',
  family: 'light',
  params,
  mount(el, { palette, params: given, seed }) {
    return shader(el, {
      frag,
      schema: params,
      params: given,
      palette,
      seed,
      uniforms,
      still: 5,
      fps: 30,          // the motion is slow; half the frames look the same and cost half
      maxDpr: 1.5,      // a soft field; the grain and stipple sit on a CSS-pixel lattice, so no gain from more
      fallback: ctx => fallback({ ...ctx, width: ctx.width || el.clientWidth, height: ctx.height || el.clientHeight }),
    });
  },
};

effects/silk-folds/effect.js:
// silk-folds: a satin surface in one page colour with two or three large soft folds. The folds are a
// few low sines across a rotated axis whose spacing and phase bend with slow noise; the sheen is
// anisotropic (narrower across the folds than along them) and broad, so it lies over each crest like
// light on satin. All shading is done in OKLab: the light raises lightness and lowers chroma at a fixed
// hue, and colours outside sRGB lose chroma, never hue (so a blue cloth never turns violet).
import { shader, color } from '../fx.js';

const params = {
  tone:   { default: 0,    min: 0,   max: 2,   step: 1 },     // 0 auto (accent, or the ground when the accent is too pale), 1 accent, 2 ground
  scale:  { default: 1,    min: 0.4, max: 2.5, step: 0.01 },  // size of the folds
  folds:  { default: 0.6,  min: 0,   max: 1,   step: 0.01 },  // depth of the folds
  sheen:  { default: 0.6,  min: 0,   max: 1,   step: 0.01 },  // strength of the satin highlight
  speed:  { default: 0.05, min: 0,   max: 0.4, step: 0.005 }, // how fast the cloth moves
  grain:  { default: 0.02, min: 0,   max: 0.1, step: 0.005 }, // fine grain against banding
  angle:  { default: 25,   min: -90, max: 90,  step: 1 },     // direction of the folds, 0 vertical
  calm:   { default: 0.5,  min: 0,   max: 1,   step: 0.01 },  // smooth, quiet cloth where text sits
  calmX:  { default: 0.25, min: 0,   max: 1,   step: 0.01 },
  calmY:  { default: 0.7,  min: 0,   max: 1,   step: 0.01 },
};

const frag = /* glsl */ `
// gradient noise with its analytic derivative: (value, d/dx, d/dy)
vec3 nd(vec2 p) {
  vec2 i = floor(p), f = fract(p);
  vec2 u = f * f * f * (f * (f * 6.0 - 15.0) + 10.0);
  vec2 du = 30.0 * f * f * (f * (f - 2.0) + 1.0);
  vec2 ga = fx_grad(i), gb = fx_grad(i + vec2(1.0, 0.0)), gc = fx_grad(i + vec2(0.0, 1.0)), gd = fx_grad(i + vec2(1.0, 1.0));
  float va = dot(ga, f), vb = dot(gb, f - vec2(1.0, 0.0)), vc = dot(gc, f - vec2(0.0, 1.0)), vd = dot(gd, f - vec2(1.0, 1.0));
  float k4 = va - vb - vc + vd;
  float v = va + u.x * (vb - va) + u.y * (vc - va) + u.x * u.y * k4;
  vec2 d = ga + u.x * (gb - ga) + u.y * (gc - ga) + u.x * u.y * (ga - gb - gc + gd) + du * (u.yx * k4 + vec2(vb, vc) - va);
  return vec3(v, d);
}

// OKLab -> linear sRGB
vec3 labLin(vec3 lab) {
  vec3 lms = vec3(lab.x + 0.3963377774 * lab.y + 0.2158037573 * lab.z,
                  lab.x - 0.1055613458 * lab.y - 0.0638541728 * lab.z,
                  lab.x - 0.0894841775 * lab.y - 1.2914855480 * lab.z);
  lms = lms * lms * lms;
  return vec3(dot(lms, vec3(4.0767416621, -3.3077115913, 0.2309699292)),
              dot(lms, vec3(-1.2684380046, 2.6097574011, -0.3413193965)),
              dot(lms, vec3(-0.0041960863, -0.7034186147, 1.7076147010)));
}
bool inside(vec3 c) { return all(greaterThanEqual(c, vec3(-0.001))) && all(lessThanEqual(c, vec3(1.001))); }
// OKLab -> sRGB, keeping lightness and hue: chroma is reduced until the colour fits
vec3 toRGB(vec3 lab) {
  lab.x = clamp(lab.x, 0.0, 1.0);
  vec3 c = labLin(lab);
  if (!inside(c)) {
    float lo = 0.0, hi = 1.0;
    for (int i = 0; i < 7; i++) {
      float k = 0.5 * (lo + hi);
      if (inside(labLin(vec3(lab.x, lab.yz * k)))) lo = k; else hi = k;
    }
    c = labLin(vec3(lab.x, lab.yz * lo));
  }
  return fx_srgb(c);
}

void main() {
  vec2 uv = fx_uv();
  vec2 p = fx_p() / u_scale;
  float t = u_time * u_speed + u_seed * 0.0173;

  // fold frame: a runs across the folds, b along them
  float ang = radians(u_angle);
  vec2 T = vec2(sin(ang), cos(ang));
  vec2 A = vec2(T.y, -T.x);
  float a = dot(p, A), b = dot(p, T);

  // calm area: flatter cloth, no sheen, a lightness the page text reads on
  float m = fx_calm(uv, vec2(u_calmX, u_calmY), 0.45 + 0.45 * u_calm) * u_calm;
  float mm = smoothstep(0.0, 0.5, m);
  float depth = (0.12 + 0.32 * u_folds) * (1.0 - 0.8 * mm);

  // uneven spacing: the across coordinate is stretched and squeezed by slow noise
  vec3 wv = nd(vec2(a * 0.9 + 5.0, b * 0.35 - t * 0.6));
  float aw = a + 0.2 * wv.x;
  float dawA = 1.0 + 0.2 * 0.9 * wv.y, dawB = 0.2 * 0.35 * wv.z;

  // folds gather a little toward one end, like hanging cloth
  float fan = 1.0 + 0.36 * b;
  float af = aw * fan;
  vec2 dAF = vec2(fan * dawA, fan * dawB + 0.36 * aw);   // (d/da, d/db)

  // slow bends of each fold, from noise along the fold and time
  vec3 w1 = nd(vec2(b * 0.75 + 3.1, a * 0.3 + t * 2.0));
  vec3 w2 = nd(vec2(b * 1.1 - 7.3, a * 0.45 - t * 1.6 + 5.0));
  float ph1 = 2.1 * w1.x, ph2 = 2.4 * w2.x;
  vec2 dph1 = 2.1 * vec2(0.3 * w1.z, 0.75 * w1.y);
  vec2 dph2 = 2.4 * vec2(0.45 * w2.z, 1.1 * w2.y);

  float f1 = 7.4, f2 = 12.9, f3 = 3.9;
  float s1 = f1 * af + ph1 + t * 1.7;
  float s2 = f2 * af + ph2 - t * 1.2 + 1.3;
  float s3 = f3 * af + 0.8 * ph2 + 2.2;
  // the second fold set comes and goes along the cloth, so the folds are not a row of equal stripes
  float k2 = 0.22 + 0.3 * (0.5 + 0.5 * w1.x);
  float h = sin(s1) + k2 * sin(s2) + 0.6 * sin(s3);
  vec2 dh = cos(s1) * (f1 * dAF + dph1) + k2 * cos(s2) * (f2 * dAF + dph2) + 0.6 * cos(s3) * (f3 * dAF + 0.8 * dph2);
  float hs = h - 0.12 * h * h;
  dh *= 1.0 - 0.24 * h;

  vec2 g = (A * dh.x + T * dh.y) * depth / 4.6;
  vec3 n = normalize(vec3(-g, 1.0));

  // light from the upper left, the viewer straight ahead
  vec3 L = normalize(vec3(-0.5, 0.62, 0.6));
  vec3 V = vec3(0.0, 0.0, 1.0);
  vec3 H = normalize(L + V);
  float diff = clamp((dot(n, L) + 0.25) / 1.25, 0.0, 1.0);
  diff = diff * diff * (3.0 - 2.0 * diff);

  // anisotropic sheen, broad: wider across the folds than a thin line, long along them
  vec3 X = normalize(vec3(A, 0.0) - n * dot(vec3(A, 0.0), n));
  vec3 Y = normalize(cross(n, X));
  float hx = dot(H, X), hy = dot(H, Y), hn = max(dot(H, n), 0.05);
  float spec = exp(-(hx * hx / 0.034 + hy * hy / 0.9) / (hn * hn));
  float broad = exp(-(hx * hx / 0.14 + hy * hy / 1.8) / (hn * hn));
  float sk = u_sheen * (1.0 - mm);

  float ao = 0.84 + 0.16 * smoothstep(-1.4, 0.8, hs);

  // shading in OKLab: lightness follows the light, chroma a little; the sheen lifts lightness and
  // gives up chroma at the same hue
  float I = mix(u_shadowK, 1.0, diff) * ao;
  float Lc = u_base.x * mix(0.62, 1.08, I);
  vec2 ab = u_base.yz * mix(0.82, 1.0, I);
  float sh = clamp(spec * 0.62 + broad * 0.28, 0.0, 1.0) * sk;
  Lc += (u_sheenL - Lc) * sh;
  ab *= 1.0 - 0.55 * sh;
  // a violet-leaning blue turns toward azure as the sheen lightens it (0 for every other hue)
  float tu = u_turn * sh;
  ab = mat2(cos(tu), sin(tu), -sin(tu), cos(tu)) * ab;
  // calm: lightness moves to the readable tone, keeping a trace of the shading
  Lc = mix(Lc, u_calmL + (Lc - u_base.x) * 0.15, mm);
  ab = mix(ab, u_calmAB, mm);
  vec3 col = toRGB(vec3(Lc, ab));
  col += fx_grain(gl_FragCoord.xy, floor(u_time * 24.0)) * u_grain * 0.3;
  fxColor = vec4(fx_dither(col), 1.0);
}
`;

// a light tint of a blue that leans violet (OKLCH hue 255..300) reads periwinkle or lavender, and one
// of a purple-magenta (300..340) reads orchid: turn them toward azure and pink. Deep shades keep hue.
function cool(c) {
  const [L, C, h] = color.lch(c);
  if (C < 0.03 || L < 0.55) return c;
  if (h > 255 && h < 300) return color.fromLch([L, C, Math.max(238, h - 26)]);
  if (h >= 300 && h < 340) return color.fromLch([L, C, Math.min(352, h + 20)]);
  return c;
}
// how far (radians) the sheen turns the hue of a violet-leaning blue toward azure as it lightens
function sheenTurn(c) {
  const [, C, h] = color.lch(c);
  if (C < 0.03 || h <= 250 || h >= 340) return 0;
  if (h < 300) return -((Math.min(18, h - 238) * Math.PI) / 180);
  return (Math.min(16, 352 - h) * Math.PI) / 180;
}

function tones(P, prm, kind) {
  const { bg, ink, muted, accent } = P;
  const La = color.lab(accent)[0];
  // auto: the accent, unless it is too pale to carry shadows (a yellow, a pastel), or the page is a
  // colour with dark text (a mustard page): then the page colour, which that text already reads on
  const darkText = color.lab(ink)[0] < color.lab(bg)[0];
  const useGround = prm.tone >= 1.5 || (prm.tone < 0.5 && color.chroma(bg) > 0.04 && (La > 0.82 || (kind === 'colour' && darkText)));
  let base = useGround ? bg : accent;
  if (kind === 'light' && !useGround) {
    // on a light page the cloth is a muted tint of the accent, not a full-strength panel of it (made
    // from the accent alone: mixed with a page colour of another hue it would turn grey or mauve)
    const Lm = color.lab(color.mix(bg, accent, 0.42))[0];
    const Ca = color.chroma(accent);
    base = cool(color.fromLch([Math.min(0.8, Math.max(0.68, Lm)), Math.min(0.11, Math.max(Ca * 0.55, Math.min(Ca, 0.05))), color.lch(accent)[2]]));
  }
  const [L] = color.lab(base);
  // keep the cloth in a range where both the shadows and the sheen can show; on a dark page a
  // deeper shade of the colour, so the cloth does not glare
  const top = kind === 'dark' ? 0.5 : 0.8;
  if (L > top) base = color.withLightness(base, top);
  if (L < 0.3) base = color.withLightness(base, 0.3);
  const Lb = color.lab(base)[0];
  // the readable tone for the calm area: the cloth's lightness moved away from the page text
  const dir = color.lab(ink)[0] > Lb ? -1 : 1;
  let calm = base;
  const mutedGoal = Math.min(4.5, color.contrast(bg, muted) * 0.95);
  for (let i = 0; i < 40 && (color.contrast(calm, ink) < 5.5 || color.contrast(calm, muted) < mutedGoal); i++) calm = color.lighten(calm, dir * 0.012);
  // the calm tone keeps the cloth's hue, turned out of lavender if lifting it made it periwinkle
  const calmLab = color.lab(cool(calm));
  return {
    base,
    turn: sheenTurn(base),
    calmL: calmLab[0],
    calmAB: [calmLab[1], calmLab[2]],
    shadowK: kind === 'dark' ? 0.26 : 0.34,
    sheenL: Math.min(0.96, Lb + (kind === 'dark' ? 0.32 : 0.24)),
  };
}

function uniforms({ palette, params, kind }) {
  const t = tones(palette, params, kind);
  return { u_base: color.labVec(t.base), u_calmL: t.calmL, u_calmAB: t.calmAB, u_shadowK: t.shadowK, u_sheenL: t.sheenL, u_turn: t.turn };
}

export default {
  id: 'silk-folds',
  name: 'Silk folds',
  family: 'material',
  params,
  mount(el, { palette, params: given, seed }) {
    return shader(el, {
      frag,
      schema: params,
      params: given,
      palette,
      seed,
      uniforms,
      still: 6,
      fallback: ({ palette: P, params: prm, kind }) => {
        const b = tones(P, prm, kind).base;
        const lo = color.darken(b, 0.1), hi = color.adjust(b, { l: 0.1, c: 0.7 });
        return `linear-gradient(${115 + prm.angle}deg, ${lo} 0%, ${b} 24%, ${hi} 36%, ${b} 50%, ${lo} 64%, ${b} 80%, ${hi} 92%, ${b} 100%)`;
      },
    });
  },
};

