// ruled-grounds: a fine dot ruling on a grainy tonal ground. Every dot sits on a whole device pixel, every
// n-th node carries a small cross, and the ruling thins out toward the text and fades before the edges.
// A wide soft light wanders slowly across the far side and brings the dots it passes forward (stronger,
// a touch larger, leaning to the accent), so the ground reads as lit paper, never as blinking.
import { shader, color, grainCSS } from '../fx.js';

const params = {
  cell:  { default: 16,   min: 12, max: 28, step: 1 },    // dot pitch in CSS px (snapped to whole device px)
  major: { default: 4,    min: 0,  max: 8,  step: 1 },    // every n-th node carries a small cross; under 3 none
  ink:   { default: 0.5,  min: 0,  max: 1,  step: 0.01 }, // strength of the ruling
  focus: { default: 0.6,  min: 0,  max: 1,  step: 0.01 }, // how much the wandering light brings the dots forward
  speed: { default: 0.8,  min: 0,  max: 2,  step: 0.01 }, // 1 = one sweep across in 25 s
  reach: { default: 0.5,  min: 0,  max: 1,  step: 0.01 }, // how far the ruling reaches toward the text side
  grain: { default: 0.5,  min: 0,  max: 1,  step: 0.01 }, // still paper grain on the ground
  calm:  { default: 0.5,  min: 0,  max: 1,  step: 0.01 }, // clear the ruling and the light where text sits
  calmX: { default: 0.25, min: 0,  max: 1,  step: 0.01 },
  calmY: { default: 0.7,  min: 0,  max: 1,  step: 0.01 },
};

const frag = /* glsl */ `
void main() {
  vec2 uv = fx_uv();
  vec2 hs = vec2(u_res.x / u_res.y, 1.0);
  vec2 p = uv * hs;                                    // height units, y down
  float dpr = max(1.0, u_dpr);
  float c = max(8.0, floor(u_cell * dpr + 0.5));       // pitch in whole device px
  // nodes sit on pixel centres, one of them in the middle of the frame
  vec2 rel = gl_FragCoord.xy - (floor(0.5 * u_res) + 0.5);
  vec2 k = floor(rel / c + 0.5);                       // the nearest node
  vec2 d = rel - k * c;                                // whole device px from it

  // where the ruling shows: thinner toward the text, gone before the edges and in the calm area
  float s = length(p - u_calmP) / u_span;              // 0 at the text, 1 at the far corner
  float dens = mix(smoothstep(0.08, 0.85, s), 1.0, u_floor);
  vec2 e = min(uv, 1.0 - uv) * hs;
  float edge = smoothstep(0.0, 0.12, min(e.x, e.y));
  float calm = min(1.0, u_calm * 1.6) * fx_calm(uv, vec2(u_calmX, u_calmY), 0.25 + 0.35 * u_calm);
  float field = dens * edge * (1.0 - calm);

  // the focus: a wide soft light on a slow open path across the far side, never behind the text
  float tt = u_time * u_speed * 0.2513 + u_ph.x;
  vec2 lp = u_pc + vec2(u_amp.x * sin(tt), u_amp.y * sin(tt * 0.647 + u_ph.y));
  vec2 dl = p - lp;
  float g = exp(-dot(dl, dl) / (u_pr * u_pr)) * (1.0 - calm);
  float lit = u_focus * g;

  // a round dot, anti-aliased by its coverage of this pixel; a little larger in the light
  float r = (0.6 + 0.35 * lit) * dpr + 0.3;
  float a = clamp(r + 0.5 - length(d), 0.0, 1.0) * u_aDot;
  // a small cross on every n-th node, in whole device pixels
  if (u_major > 2.5) {
    vec2 m = abs(k - u_major * floor(k / u_major + 0.5));
    if (m.x < 0.5 && m.y < 0.5) {
      float lo = -floor((u_lw - 1.0) * 0.5), hi = lo + u_lw - 1.0;
      float hb = step(lo - 0.5, d.y) * step(d.y, hi + 0.5) * step(abs(d.x), u_arm + 0.5);
      float vb = step(lo - 0.5, d.x) * step(d.x, hi + 0.5) * step(abs(d.y), u_arm + 0.5);
      a = max(a, max(hb, vb) * u_aMark);
    }
  }
  // faint everywhere, brought forward under the light (about three times at the default focus)
  a = min(a * field * (1.0 - 0.8 * u_focus + 2.6 * lit), 0.55);

  // the ground: a tonal ramp from the text side to the far corner, lifted where the light is
  vec3 col = mix(u_kNear, u_kFar, smoothstep(0.0, 1.0, s));
  col = mix(col, u_kPool, min(0.85, lit * 1.3));
  vec3 lc = mix(u_kLine, u_kGlow, min(1.0, g) * 0.7);
  col = mix(col, lc, a);

  // still grain on lightness, softer near white and black
  float amp = u_grainAmp * (1.0 - 0.6 * smoothstep(0.86, 1.0, col.x)) * (1.0 - 0.5 * smoothstep(0.22, 0.0, col.x));
  col.x += fx_grain(gl_FragCoord.xy, 0.0) * amp;

  fxColor = vec4(fx_dither(fx_rgb(col)), 1.0);
}
`;

// the violet guard: no derived colour, and no mix the shader makes between two of them, may land in the
// violet or lavender band (OKLCH hue 274-336 with any real chroma)
const inBand = c => { const [, C, h] = color.lch(c); return C > 0.025 && h > 274 && h < 336; };
const clean = (a, b) => { for (let i = 1; i <= 10; i++) if (inBand(color.mix(a, b, i / 10))) return false; return true; };
// the ground's own hue at another lightness, nearly grey (a hue at the band's edge leans a little bluer)
const step = (bg, L, cmax = 0.02) => {
  const [, C, h] = color.lch(bg);
  return color.fromLch([Math.min(1, Math.max(0, L)), Math.min(C, cmax), h > 262 && h < 276 ? 262 : h]);
};

// every colour is the palette's own: the ink for the ruling, steps of the ground for the ramp, and the
// accent for the light only when it sits with the ground
function tones(P, kind) {
  const { bg, surface, ink, accent } = P;
  const Lb = color.lab(bg)[0], Li = color.lab(ink)[0];
  const up = Li > Lb ? 1 : -1;                         // toward the ink
  const neutral = color.chroma(bg) < 0.02;
  const line = clean(bg, ink) ? ink : step(bg, Li);
  const accOk = color.chroma(accent) > 0.03 && !inBand(accent) && clean(bg, accent) && (neutral || color.hueDistance(bg, accent) < 55);
  let T;
  if (kind === 'dark') {
    const lift = color.lighten(color.mix(bg, surface, 0.7), 0.008);
    T = {
      near: bg, aDot: 0.3, grain: 0.018,
      far: accOk ? color.mix(lift, accent, 0.05) : lift,
      pool: accOk ? color.lighten(color.mix(bg, accent, 0.2), 0.015) : step(bg, Lb + 0.07, 0.03),
      glow: accOk ? color.adjust(accent, { l: 0.06, c: 0.85 }) : color.lighten(line, 0.03),
    };
  } else if (kind === 'colour') {
    T = {
      near: bg, aDot: 0.3, grain: 0.02,
      far: color.lighten(bg, -0.03 * up),
      pool: color.withLightness(color.saturate(bg, 1.05), Lb + 0.08 * up),
      glow: accOk ? color.adjust(accent, { l: 0.04 * up, c: 0.85 }) : color.lighten(line, 0.02 * up),
    };
  } else {
    // light: the light is a paler sheen on the paper (tinted by the accent when it fits) under darker dots
    const white = Lb > 0.97;
    const deep = color.mix(bg, ink, 0.055);
    const sheen = Math.min(0.995, Lb + 0.035);
    T = {
      near: white ? bg : color.lighten(bg, 0.012), aDot: 0.28, grain: 0.02,
      far: accOk ? color.mix(deep, accent, 0.03) : deep,
      pool: accOk ? color.withLightness(color.mix(bg, accent, 0.1), sheen) : color.withLightness(bg, sheen),
      glow: accOk ? color.darken(accent, 0.04) : line,
    };
  }
  T.line = line;
  for (const k of ['far', 'pool', 'glow']) if (!clean(bg, T[k]) || inBand(T[k])) T[k] = k === 'glow' ? line : step(bg, color.lab(T[k])[0]);
  return T;
}

// composition shared by the shader and the CSS stand-in (positions in height units, y down)
function geometry(prm, r, asp) {
  const C = [prm.calmX * asp, prm.calmY];
  const corners = [[0, 0], [asp, 0], [0, 1], [asp, 1]];
  // the corner farthest from the text; a tie (text in the middle) goes to the lower right
  const far = c => Math.hypot(c[0] - C[0], c[1] - C[1]) + 0.002 * c[1] + 0.001 * c[0];
  const corner = corners.reduce((a, b) => (far(b) > far(a) ? b : a));
  const span = Math.max(0.4, Math.hypot(corner[0] - C[0], corner[1] - C[1]));
  // the light wanders across the side away from the text
  const pc = [asp * 0.5 + (asp * 0.5 - C[0]) * 0.35, Math.min(0.7, Math.max(0.3, 0.5 + (0.5 - C[1]) * 0.5))];
  const ph = [r() * 6.283, r() * 6.283];
  return { C, corner, span, pc, amp: [0.28 * asp, 0.12], pr: 0.38 + 0.06 * r(), ph };
}
const lightAt = (g, prm, t) => {
  const tt = t * prm.speed * 0.2513 + g.ph[0];
  return [g.pc[0] + g.amp[0] * Math.sin(tt), g.pc[1] + g.amp[1] * Math.sin(tt * 0.647 + g.ph[1])];
};

function uniforms({ palette, params, rng, kind, dpr, width, height }) {
  const asp = width && height ? width / height : 16 / 9;
  const g = geometry(params, rng, asp);
  const T = tones(palette, kind);
  const s = 0.4 + 1.2 * params.ink;
  const D = Math.max(1, dpr || 1);
  const u = {
    u_calmP: g.C,
    u_span: g.span,
    u_floor: 0.25 + 0.6 * params.reach,
    u_pc: g.pc,
    u_amp: g.amp,
    u_pr: g.pr,
    u_ph: g.ph,
    u_aDot: Math.min(0.5, T.aDot * s),
    u_aMark: Math.min(0.5, T.aDot * s * 0.8),
    u_lw: Math.max(1, Math.floor(D + 0.3)),            // one CSS px in whole device px
    u_arm: Math.max(2, Math.round(3 * D)),             // cross arm, 3 CSS px
    u_grainAmp: T.grain * (0.4 + 1.2 * params.grain),
  };
  for (const key of ['near', 'far', 'pool', 'line', 'glow']) u['u_k' + key[0].toUpperCase() + key.slice(1)] = color.labVec(T[key]);
  return u;
}

// the CSS stand-in: the same ramp, light (where it stands in the still frame), dots, crosses, calm area and grain
function fallback({ palette: P, params: prm, kind, rng, width, height }) {
  const asp = width && height ? width / height : 16 / 9;
  const g = geometry(prm, rng, asp);
  const T = tones(P, kind);
  const s = 0.4 + 1.2 * prm.ink;
  const rgba = (c, a) => { const [r, gg, b] = color.rgb(c).map(v => Math.round(v * 255)); return `rgba(${r},${gg},${b},${a.toFixed(3)})`; };
  const pct = (x, y) => `${((x / asp) * 100).toFixed(1)}% ${(y * 100).toFixed(1)}%`;
  const c = prm.cell;
  const dot = color.mix(T.near, T.line, Math.min(0.5, T.aDot * s * 0.9));
  const at = pct(g.C[0], g.C[1]);
  const ang = (Math.atan2(g.corner[0] - g.C[0], -(g.corner[1] - g.C[1])) * 180) / Math.PI;
  const R = 0.3 + 0.4 * prm.calm;
  const L = lightAt(g, prm, 6);
  const layers = [
    grainCSS(0.05),
    `radial-gradient(${((R / asp) * 100).toFixed(1)}% ${(R * 100).toFixed(1)}% at ${at}, ${rgba(T.near, Math.min(1, prm.calm * 1.6))} 35%, transparent 100%)`,
    `linear-gradient(${ang.toFixed(1)}deg, ${rgba(T.near, 0.75 - 0.6 * prm.reach)}, transparent 75%)`,
    `radial-gradient(ellipse 58% 60% at 50% 50%, transparent 72%, ${rgba(P.bg, 0.92)} 100%)`,
  ];
  if (prm.major > 2.5) {
    const M = c * prm.major, h = M / 2;
    const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='${M}' height='${M}'><path d='M${h - 3} ${h + 0.5}h7M${h + 0.5} ${h - 3}v7' stroke='${color.mix(T.near, T.line, Math.min(0.5, T.aDot * s * 0.8))}' stroke-width='1' shape-rendering='crispEdges'/></svg>`;
    layers.push(`url("data:image/svg+xml,${encodeURIComponent(svg)}") calc(50% - ${h}px) calc(50% - ${h}px) / ${M}px ${M}px`);
  }
  layers.push(
    `radial-gradient(circle at 50% 50%, ${dot} 0.8px, transparent 1.3px) 50% 50% / ${c}px ${c}px`,
    `radial-gradient(${((g.pr * 1.6 / asp) * 100).toFixed(1)}% ${(g.pr * 160).toFixed(1)}% at ${pct(L[0], L[1])}, ${rgba(T.pool, prm.focus * 0.8)}, transparent 72%)`,
    `linear-gradient(${ang.toFixed(1)}deg, ${T.near}, ${color.mix(T.near, T.far, 0.5)} 55%, ${T.far})`,
  );
  return `${layers.join(', ')}, ${P.bg}`;
}

export default {
  id: 'ruled-grounds',
  name: 'Ruled dot ground',
  family: 'pattern',
  params,
  mount(el, { palette, params: given, seed }) {
    return shader(el, {
      frag,
      schema: params,
      params: given,
      palette,
      seed,
      uniforms,
      fallback,
      crisp: true,   // dots and crosses on whole device pixels, never resampled
      maxDpr: 3,     // so 3x and 2.6x screens are drawn 1:1, never pixel-upscaled
      fps: 30,       // the light moves a few pixels a frame; 30 frames are plenty
      still: 6,
    });
  },
};

effects/ridgeline/effect.js:
// ridgeline: stacked lines drawn back to front (WebGL, or a 2D canvas without it). Each line is flat at
// the sides and rises into a few clean peaks inside an envelope; it is filled below with the ground, so
// the lines in front really hide the ones behind, in the page's ink, with one line picked out in the
// accent like a highlighted series. The peaks sit on the side away from the calm area (the text).
// The WebGL context is made when the panel first comes into view and given back when it leaves; a lost
// context or a failed shader swaps in a fresh canvas drawn with the 2D path.
import { lifecycle, color, config, rng as makeRng, normalizePalette, resolveParams } from '../fx.js';

const params = {
  lines:      { default: 36,   min: 12,  max: 90,  step: 1 },     // number of lines
  peak:       { default: 0.38, min: 0,   max: 1,   step: 0.01 },  // height of the peaks
  envelope:   { default: 0.35, min: 0.1, max: 1,   step: 0.01 },  // width of the peaked middle
  noiseScale: { default: 2.6,  min: 0.5, max: 8,   step: 0.1 },   // how many peaks along a line
  lineWidth:  { default: 1.2,  min: 0.5, max: 3,   step: 0.1 },   // line width in CSS px
  speed:      { default: 0.03, min: 0,   max: 0.3, step: 0.005 }, // how fast the peaks roll forward
  span:       { default: 0.84, min: 0.3, max: 1,   step: 0.01 },  // share of the width the lines cover
  focus:      { default: 0.5,  min: 0.2, max: 0.8, step: 0.01 },  // where the peaks sit, 0 left .. 1 right
  highlight:  { default: 1,    min: 0,   max: 1,   step: 0.01 },  // one line in the accent (0 for none)
  calm:       { default: 0.8,  min: 0,   max: 1,   step: 0.01 },  // clear the lines where text sits
  calmX:      { default: 0.25, min: 0,   max: 1,   step: 0.01 },
  calmY:      { default: 0.7,  min: 0,   max: 1,   step: 0.01 },
};

// seeded 2D gradient noise, about -0.7..0.7
function makeNoise(seed) {
  const r = makeRng(seed);
  const p = Array.from({ length: 256 }, (_, i) => i);
  for (let i = 255; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [p[i], p[j]] = [p[j], p[i]]; }
  const perm = new Int32Array(512);
  for (let i = 0; i < 512; i++) perm[i] = p[i & 255];
  const gx = new Float64Array(256), gy = new Float64Array(256);
  for (let i = 0; i < 256; i++) { const a = r() * Math.PI * 2; gx[i] = Math.cos(a); gy[i] = Math.sin(a); }
  return (x, y) => {
    const xf0 = Math.floor(x), yf0 = Math.floor(y);
    const xf = x - xf0, yf = y - yf0;
    const X = xf0 & 255, Y = yf0 & 255;
    const pY = perm[Y], pY1 = perm[Y + 1];
    const a = perm[X + pY], b = perm[X + 1 + pY], c = perm[X + pY1], d = perm[X + 1 + pY1];
    const u = xf * xf * xf * (xf * (xf * 6 - 15) + 10), v = yf * yf * yf * (yf * (yf * 6 - 15) + 10);
    const na = gx[a] * xf + gy[a] * yf, nb = gx[b] * (xf - 1) + gy[b] * yf;
    const nc = gx[c] * xf + gy[c] * (yf - 1), nd = gx[d] * (xf - 1) + gy[d] * (yf - 1);
    const x1 = na + (nb - na) * u, x2 = nc + (nd - nc) * u;
    return x1 + (x2 - x1) * v;
  };
}

function prepareHost(el, palette) {
  const cs = getComputedStyle(el);
  if (cs.position === 'static') el.style.position = 'relative';
  if (cs.isolation !== 'isolate') el.style.isolation = 'isolate';
  const bg = cs.backgroundColor;
  if (el.dataset.fxOwnBg || !bg || bg === 'transparent' || /rgba\(.*,\s*0\)$/.test(bg)) {
    el.style.backgroundColor = palette.bg;
    el.dataset.fxOwnBg = '1';
    return true;
  }
  return false;
}

// WebGL path: each line is a ground-coloured fill strip (curve down to its base) followed by an
// anti-aliased stroke strip, all in one triangle strip in painter's order, so the GPU does the hiding.
// a_info: x kind (0 fill, 1 stroke), yz position across the stroke (-1..1; a disc at sharp corners
// uses both), w the line's tone (0..1 toward the ink; 2..3 toward the accent). Strokes carry coverage
// only and their colour is pre-mixed with the ground, so where pieces of one line overlap nothing gets
// brighter.
const VS = 'attribute vec2 a_pos; attribute vec4 a_info; uniform vec2 u_res; varying vec4 v_info;' +
  'void main() { vec2 c = a_pos / u_res * 2.0 - 1.0; gl_Position = vec4(c.x, -c.y, 0.0, 1.0); v_info = a_info; }';
const FS = 'precision mediump float; uniform vec3 u_ink, u_ground, u_acc; uniform float u_hw, u_w; varying vec4 v_info;' +
  'void main() { if (v_info.x < 0.5) { gl_FragColor = vec4(u_ground, 1.0); return; }' +
  ' float d = length(v_info.yz) * u_hw;' +
  ' float a = clamp(max(u_w, 1.0) * 0.5 + 0.5 - d, 0.0, 1.0) * min(u_w, 1.0);' +
  ' vec3 c = v_info.w > 1.5 ? mix(u_ground, u_acc, v_info.w - 2.0) : mix(u_ground, u_ink, v_info.w);' +
  ' gl_FragColor = vec4(c * a, a); }';

function makeGL(canvas) {
  let gl = null;
  try { gl = canvas.getContext('webgl', { alpha: true, premultipliedAlpha: true, antialias: false, depth: false, stencil: false }); } catch (_) { gl = null; }
  if (!gl) return null;
  const sh = (type, src) => { const s = gl.createShader(type); gl.shaderSource(s, src); gl.compileShader(s); return s; };
  const prog = gl.createProgram();
  gl.attachShader(prog, sh(gl.VERTEX_SHADER, VS));
  gl.attachShader(prog, sh(gl.FRAGMENT_SHADER, FS));
  gl.bindAttribLocation(prog, 0, 'a_pos');
  gl.bindAttribLocation(prog, 1, 'a_info');
  gl.linkProgram(prog);
  if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {
    if (!gl.isContextLost()) console.warn('ridgeline: ' + gl.getProgramInfoLog(prog));
    gl.getExtension('WEBGL_lose_context')?.loseContext();
    return null;
  }
  const u = n => gl.getUniformLocation(prog, n);
  return { gl, prog, buf: gl.createBuffer(), uRes: u('u_res'), uInk: u('u_ink'), uGround: u('u_ground'), uAcc: u('u_acc'), uHw: u('u_hw'), uW: u('u_w') };
}

export default {
  id: 'ridgeline',
  name: 'Ridgeline',
  family: 'pattern',
  params,
  mount(el, { palette, params: given, seed }) {
    let P = normalizePalette(palette);
    let prm = resolveParams(params, given);
    const ownBg = prepareHost(el, P);
    const noise = makeNoise(seed ?? 1);
    const hiPick = makeRng(`ridge-hi:${seed ?? 1}`)();
    // the drawing surface: made when first seen, its WebGL context given back when out of view
    let canvas = null, glr = null, ctx = null, everShown = false;
    let useGL = !config.forceFallback;
    let W = 1, H = 1, dpr = 1, acc = P.accent;
    let xs = null, xn = null, env = null, k0 = 0, k1 = 0, ys = null;
    // shape rows cached by depth: a line's profile depends only on its noise depth z, and every line
    // passes through the same depths as the peaks roll forward, so each row is computed once
    const DZ = 0.05;
    let rows = new Map();
    let vb = new Float32Array(1 << 16), vn = 0, joinNext = false;

    function accent() {
      // the highlight needs to show on the ground: a faint accent is pulled toward the ink
      acc = color.contrast(P.bg, P.accent) >= 2 ? P.accent : color.mix(P.accent, P.ink, 0.55);
    }
    // the peaks lean away from the calm area, so the text keeps the flat ends of the lines
    const focusAt = () => Math.min(0.72, Math.max(0.28, prm.focus + (0.5 - prm.calmX) * 0.36 * prm.calm));
    const envAt = x => { const d = (x - focusAt()) / (prm.envelope * 0.42); return Math.exp(-0.275 * d * d * d * d - 0.3 * d * d); };

    function newCanvas() {
      const c = document.createElement('canvas');
      c.className = 'fx-canvas';
      c.setAttribute('aria-hidden', 'true');
      Object.assign(c.style, {
        position: 'absolute', inset: '0', width: '100%', height: '100%', display: 'block', zIndex: '-1',
        pointerEvents: 'none', opacity: everShown ? '1' : '0', transition: 'opacity .5s ease', borderRadius: 'inherit',
      });
      el.insertBefore(c, el.firstChild);
      return c;
    }
    function dropSurface() {
      if (glr) { try { glr.gl.getExtension('WEBGL_lose_context')?.loseContext(); } catch (_) { /* gone */ } }
      if (canvas) canvas.remove();
      canvas = null; glr = null; ctx = null;
    }
    function makeSurface() {
      dropSurface();
      canvas = newCanvas();
      if (useGL) {
        glr = makeGL(canvas);
        if (glr) {
          const mine = canvas;
          canvas.addEventListener('webglcontextlost', e => {
            e.preventDefault();
            if (canvas !== mine) return;
            // a lost context: carry on in 2D on a fresh canvas (this canvas can no longer give a 2D context)
            useGL = false;
            setTimeout(() => { if (canvas === mine) { makeSurface(); fit(); lc.redraw(); } }, 0);
          });
        } else {
          // the shader failed: the canvas already holds a WebGL context, so 2D needs a fresh one
          useGL = false;
          canvas.remove();
          canvas = newCanvas();
        }
      }
      if (!glr) ctx = canvas.getContext('2d');
      applyMask();
    }

    function fit() {
      dpr = Math.min(window.devicePixelRatio || 1, useGL ? config.maxDpr : Math.min(1.5, config.maxDpr));
      const w = Math.max(1, Math.round(el.clientWidth * dpr)), h = Math.max(1, Math.round(el.clientHeight * dpr));
      if (canvas && (w !== canvas.width || h !== canvas.height)) { canvas.width = w; canvas.height = h; }
      if (w !== W || h !== H || !xs) { W = w; H = h; layout(); } else applyMask();
    }
    // x samples shared by every line: dense inside the peaked middle, sparse on the flat sides
    function layout() {
      const xL = W * (0.5 - prm.span / 2), xR = W * (0.5 + prm.span / 2);
      const fine = (3 * dpr) / Math.max(1, xR - xL), coarse = (26 * dpr) / Math.max(1, xR - xL);
      const pts = [];
      for (let x = 0; x < 1; x += envAt(x) > 0.004 ? fine : coarse) pts.push(x);
      pts.push(1);
      const n = pts.length;
      xn = Float32Array.from(pts);
      xs = new Float32Array(n);
      env = new Float32Array(n);
      ys = new Float32Array(n);
      k0 = n; k1 = 0;
      for (let k = 0; k < n; k++) {
        xs[k] = xL + (xR - xL) * xn[k];
        env[k] = envAt(xn[k]);
        if (env[k] > 0.004) { k0 = Math.min(k0, k); k1 = k; }
      }
      k0 = Math.max(0, k0 - 1); k1 = Math.min(n - 1, k1 + 1);
      rows = new Map();
      applyMask();
    }
    // the line ends fade and the calm area clears through a CSS mask, so no gradient is painted each frame
    function applyMask() {
      if (!canvas) return;
      const l = (0.5 - prm.span / 2) * 100, r = (0.5 + prm.span / 2) * 100, f = prm.span * 5;
      const lin = `linear-gradient(to right, transparent ${l}%, #000 ${l + f}%, #000 ${r - f}%, transparent ${r}%)`;
      let img = lin;
      if (prm.calm > 0) {
        const R = (0.3 + 0.36 * prm.calm) * el.clientHeight;
        const a = Math.min(1, prm.calm * 1.25);
        const stops = [0, 0.35, 0.5, 0.65, 0.8, 1].map(q => {
          const k = q <= 0.35 ? 1 : 1 - (q - 0.35) / 0.65;
          return `rgba(0,0,0,${(1 - a * k * k * (3 - 2 * k)).toFixed(3)}) ${(q * 100).toFixed(0)}%`;
        }).join(', ');
        img = `${lin}, radial-gradient(circle ${R.toFixed(1)}px at ${prm.calmX * 100}% ${prm.calmY * 100}%, ${stops})`;
      }
      const st = canvas.style;
      st.maskImage = st.webkitMaskImage = img;
      st.maskComposite = 'intersect';
      st.webkitMaskComposite = 'source-in';
      st.maskRepeat = st.webkitMaskRepeat = 'no-repeat';
    }
    const fbm = (x, y) => noise(x, y) + 0.5 * noise(x * 2.03 + 17.1, y * 1.7 + 3.3);
    // one row: for every x sample, the peak shape v and the small wobble s at depth q * DZ
    function row(q) {
      let r = rows.get(q);
      if (r) return r;
      const m = xn.length, z = q * DZ, ns = prm.noiseScale * 2.6;
      r = new Float32Array(m * 2);
      for (let k = 0; k < m; k++) {
        const x = xn[k] * ns;
        if (env[k] <= 0.004) { r[2 * k + 1] = noise(x, z); continue; }
        const s = fbm(x, z);
        // smooth swells, a few narrow ridged spikes where a second noise crosses zero, a little grain
        let v = Math.max(0, s + 0.18);
        v = v * v * 1.7;
        // a smooth absolute value: the tips stay sharp but are never true cusps
        const nn = noise(x * 1.2 + 33.1, z * 1.1 + 5.3) * 1.45;
        const rn = 1 - Math.sqrt(nn * nn + 0.0025);
        v += rn * rn * rn * rn * rn * rn * 0.45 * (0.3 + Math.max(0, s + 0.3));
        v += noise(x * 4.3 + 91.7, z * 2.2) * 0.022;
        r[2 * k] = v;
        r[2 * k + 1] = s;
      }
      rows.set(q, r);
      return r;
    }

    /* ---- WebGL path ---- */
    function vert(x, y, kind, ax, ay, tone) {
      if (vn + 18 > vb.length) { const nb = new Float32Array(vb.length * 2); nb.set(vb); vb = nb; }
      if (joinNext) {
        // a degenerate pair links this strip to the previous one
        if (vn >= 6) { for (let i = 0; i < 6; i++) vb[vn + i] = vb[vn - 6 + i]; vn += 6; }
        vb[vn++] = x; vb[vn++] = y; vb[vn++] = kind; vb[vn++] = ax; vb[vn++] = ay; vb[vn++] = tone;
        joinNext = false;
      }
      vb[vn++] = x; vb[vn++] = y; vb[vn++] = kind; vb[vn++] = ax; vb[vn++] = ay; vb[vn++] = tone;
    }
    function glLine(base, lw, tone) {
      const hw = lw / 2 + 1;
      const m = xs.length;
      joinNext = vn > 0;
      for (let k = k0; k <= k1; k++) { vert(xs[k], ys[k], 0, 0, 0, 0); vert(xs[k], base + lw * 1.5, 0, 0, 0, 0); }
      joinNext = true;
      const pair = (k, nx, ny) => {
        vert(xs[k] + nx * hw, ys[k] + ny * hw, 1, 1, 0, tone);
        vert(xs[k] - nx * hw, ys[k] - ny * hw, 1, -1, 0, tone);
      };
      for (let k = 0; k < m; k++) {
        // directions of the segments into and out of this point
        let ix = 0, iy = 0, ox = 0, oy = 0;
        if (k > 0) { ix = xs[k] - xs[k - 1]; iy = ys[k] - ys[k - 1]; const l = Math.hypot(ix, iy) || 1; ix /= l; iy /= l; }
        if (k < m - 1) { ox = xs[k + 1] - xs[k]; oy = ys[k + 1] - ys[k]; const l = Math.hypot(ox, oy) || 1; ox /= l; oy /= l; }
        if (k === 0) { ix = ox; iy = oy; }
        if (k === m - 1) { ox = ix; oy = iy; }
        if (ix * ox + iy * oy < 0.3) {
          // a sharp corner (a peak's tip): end the strip square to the way in, put a round dot on the
          // corner, and start again square to the way out, so no miter folds over itself
          pair(k, -iy, ix);
          joinNext = true;
          const x = xs[k], y = ys[k];
          vert(x - hw, y - hw, 1, -1, -1, tone); vert(x + hw, y - hw, 1, 1, -1, tone);
          vert(x - hw, y + hw, 1, -1, 1, tone); vert(x + hw, y + hw, 1, 1, 1, tone);
          joinNext = true;
          pair(k, -oy, ox);
        } else {
          // a gentle bend: a short miter keeps the width even
          let tx = ix + ox, ty = iy + oy;
          const tl = Math.hypot(tx, ty) || 1;
          tx /= tl; ty /= tl;
          const sc = 1 / Math.max(0.6, tx * ix + ty * iy);
          pair(k, -ty * sc, tx * sc);
        }
      }
    }
    function glFlush(lw) {
      const g = glr.gl;
      if (g.isContextLost()) return;
      g.viewport(0, 0, canvas.width, canvas.height);
      g.clearColor(0, 0, 0, 0);
      g.clear(g.COLOR_BUFFER_BIT);
      g.useProgram(glr.prog);
      g.enable(g.BLEND);
      g.blendFunc(g.ONE, g.ONE_MINUS_SRC_ALPHA);
      g.bindBuffer(g.ARRAY_BUFFER, glr.buf);
      g.bufferData(g.ARRAY_BUFFER, vb.subarray(0, vn), g.DYNAMIC_DRAW);
      g.enableVertexAttribArray(0);
      g.vertexAttribPointer(0, 2, g.FLOAT, false, 24, 0);
      g.enableVertexAttribArray(1);
      g.vertexAttribPointer(1, 4, g.FLOAT, false, 24, 8);
      g.uniform2f(glr.uRes, canvas.width, canvas.height);
      g.uniform3fv(glr.uInk, color.rgb(P.ink));
      g.uniform3fv(glr.uGround, color.rgb(P.bg));
      g.uniform3fv(glr.uAcc, color.rgb(acc));
      g.uniform1f(glr.uHw, lw / 2 + 1);
      g.uniform1f(glr.uW, lw);
      g.drawArrays(g.TRIANGLE_STRIP, 0, vn / 6);
    }
    /* ---- canvas 2D path (no WebGL) ---- */
    function ctxLine(base, lw, alpha, hi) {
      const m = xs.length;
      ctx.beginPath();
      ctx.moveTo(xs[k0], ys[k0]);
      for (let k = k0 + 1; k <= k1; k++) ctx.lineTo(xs[k], ys[k]);
      ctx.lineTo(xs[k1], base + lw * 1.5);
      ctx.lineTo(xs[k0], base + lw * 1.5);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.moveTo(xs[0], ys[0]);
      for (let k = 1; k < m; k++) ctx.lineTo(xs[k], ys[k]);
      ctx.globalAlpha = hi > 0 ? 1 : alpha;
      ctx.strokeStyle = hi > 0 ? color.mix(P.ink, acc, hi) : P.ink;
      ctx.stroke();
      ctx.globalAlpha = 1;
    }

    function draw(t) {
      if (!canvas || !xs) return;
      if (canvas.width !== W || canvas.height !== H) { canvas.width = W; canvas.height = H; }
      const n = prm.lines;
      const rise = prm.peak * H * 0.52;
      const top = H * 0.1 + rise * 0.62, bottom = H * 0.9;
      const gap = (bottom - top) / Math.max(1, n - 1);
      const lw0 = prm.lineWidth * dpr;
      const tt = t * prm.speed * 9;
      const m = xs.length;
      // the highlighted line: one in the front half
      const hiLine = prm.highlight > 0 ? Math.round(n * (0.55 + 0.25 * hiPick)) : -1;
      if (glr) vn = 0;
      else if (ctx) {
        ctx.clearRect(0, 0, W, H);
        ctx.lineJoin = 'bevel';
        ctx.lineCap = 'butt';
        ctx.fillStyle = P.bg;
      } else return;
      for (let i = 0; i < n; i++) {
        const base = top + i * gap;
        const z = i * 0.26 - tt;
        const room = Math.max(gap * 2, base - H * 0.04);
        // some lines carry a stronger signal than others
        const gain = 0.4 + 0.8 * Math.max(0, Math.min(1, 0.5 + 1.3 * noise(i * 0.09 + 40.3, tt * 0.22 + 7.1)));
        const zq = z / DZ, q = Math.floor(zq), f = zq - q;
        const ra = row(q), rb = row(q + 1);
        for (let k = 0; k < m; k++) {
          const v = ra[2 * k] + (rb[2 * k] - ra[2 * k]) * f;
          const w = ra[2 * k + 1] + (rb[2 * k + 1] - ra[2 * k + 1]) * f;
          // peaks ease off as they near the top edge, so the back lines never leave the frame
          const up = rise * gain * env[k] * v + rise * 0.006 * w;
          ys[k] = base - (up > 0 ? room * (1 - Math.exp(-up / room)) : up);
        }
        const alpha = 0.66 + 0.34 * (i / Math.max(1, n - 1));
        const hi = i === hiLine ? prm.highlight : 0;
        const lw = hi > 0 ? lw0 * (1 + 0.4 * hi) : lw0;
        if (glr) glLine(base, lw, hi > 0 ? 2 + hi : alpha);
        else { ctx.lineWidth = lw; ctxLine(base, lw, alpha, hi); }
      }
      if (glr) glFlush(lw0);
      const qLo = Math.floor(-tt / DZ) - 2, qHi = Math.ceil(((n - 1) * 0.26 - tt) / DZ) + 3;
      if (rows.size > (qHi - qLo) + 40) for (const q of rows.keys()) if (q < qLo || q > qHi) rows.delete(q);
      if (!everShown) { everShown = true; canvas.style.opacity = '1'; }
    }

    accent();
    const lc = lifecycle(el, {
      draw, still: 6, fps: 60,
      onShow() { if (!canvas) { makeSurface(); fit(); } },
      // out of view: give the WebGL context back (pages with many panels never hold them all)
      onHide() { if (glr) dropSurface(); },
    });
    const ro = new ResizeObserver(() => { fit(); lc.redraw(); });
    ro.observe(el);
    fit();

    return {
      pause: () => lc.pause(),
      resume: () => lc.resume(),
      redraw: () => lc.redraw(),
      set(next) { prm = resolveParams(params, { ...prm, ...next }); layout(); lc.redraw(); return prm; },
      setPalette(p) { P = normalizePalette(p); accent(); if (ownBg) el.style.backgroundColor = P.bg; lc.redraw(); },
      destroy() {
        lc.destroy();
        ro.disconnect();
        dropSurface();
        if (ownBg) el.style.backgroundColor = P.bg;
      },
      get canvas() { return canvas; },
      get info() { return { webgl: glr ? 1 : 0, canvas: canvas ? (glr ? 'webgl' : '2d') : null, fallback: glr || !canvas ? null : '2d', scale: 1, dpr, size: canvas ? [canvas.width, canvas.height] : null, running: lc.running }; },
    };
  },
};

effects/prism-dispersion/effect.js:
// prism-dispersion: a soft white beam crosses a dark room and, at one point, breaks into a widening fan
// of colour that lands as a glowing spectrum on a far wall, like light thrown through a glass prism.
// The spectrum is a band of hues around the page accent (never violet), seen faintly in the hazy air
// and brightly where it lands. The split sits in an upper side of the frame and the light lands on the
// opposite, lower side, so centred content never hides both; a text block (calm) dims the light.
import { shader, color } from '../fx.js';

const params = {
  splitX:    { default: 0.28, min: 0.05,  max: 0.95, step: 0.01 },  // where the beam splits, 0 left .. 1 right (the middle is skipped)
  splitY:    { default: 0.4,  min: 0,     max: 1,    step: 0.01 },  // height of the split in the upper half, 0 high .. 1 lower
  bend:      { default: 30,   min: 0,     max: 60,   step: 1 },     // how far the prism turns the light, degrees
  fanSpread: { default: 0.42, min: 0.2,   max: 0.7,  step: 0.01 },  // fan width in radians
  hueSpread: { default: 55,   min: 20,    max: 70,   step: 1 },     // the spectrum spans the accent hue +- this, degrees
  beamWidth: { default: 0.006, min: 0.002, max: 0.03, step: 0.001 }, // beam width (height units)
  haze:      { default: 0.5,  min: 0,     max: 1,    step: 0.01 },  // how much the light shows in the air
  intensity: { default: 1,    min: 0,     max: 1.5,  step: 0.01 },
  sway:      { default: 0.02, min: 0,     max: 0.08, step: 0.005 }, // slow sway of the light, radians
  calm:      { default: 0.4,  min: 0,     max: 1,    step: 0.01 },  // dim the light where text sits
  calmX:     { default: 0.25, min: 0,     max: 1,    step: 0.01 },
  calmY:     { default: 0.78, min: 0,     max: 1,    step: 0.01 },
};

const frag = /* glsl */ `
vec3 spec(float u) {
  float x = clamp(u, -1.0, 1.0) * 2.0 + 2.0;
  vec3 c = mix(u_r0, u_r1, clamp(x, 0.0, 1.0));
  c = mix(c, u_r2, clamp(x - 1.0, 0.0, 1.0));
  c = mix(c, u_r3, clamp(x - 2.0, 0.0, 1.0));
  return mix(c, u_r4, clamp(x - 3.0, 0.0, 1.0));
}
vec2 rot(vec2 v, float a) { float c = cos(a), s = sin(a); return vec2(c * v.x - s * v.y, s * v.x + c * v.y); }
// 1 inside an ellipse the size of a text block around the calm point, fading out beyond it
float calmMask(vec2 uv) {
  vec2 d = (uv - vec2(u_calmX, u_calmY)) * vec2(u_res.x / u_res.y, 1.0);
  vec2 R = vec2(0.3 + 0.3 * u_calm, 0.14 + 0.1 * u_calm);
  return 1.0 - smoothstep(0.75, 1.35, length(d / R));
}

void main() {
  vec2 uv = fx_uv();
  float asp = u_res.x / u_res.y;
  float px = 1.0 / u_res.y;
  vec2 P = vec2(uv.x * asp, uv.y);
  vec2 S = vec2(u_S.x * asp, u_S.y);
  vec2 Lp = vec2(u_L.x * asp, u_L.y);
  float t = u_time;
  float sw = u_sway * sin(t * 0.19 + u_seed);

  vec2 fd = rot(normalize(Lp - S), sw);          // centre of the fan
  float D = length(Lp - S);                      // distance to the wall
  vec2 fn = vec2(-fd.y, fd.x);
  vec2 din = rot(fd, -u_side * radians(u_bend)); // the incoming beam, turned less than the fan
  vec2 dn = vec2(-din.y, din.x);
  vec2 v = P - S;
  float r = length(v);
  float w0 = max(u_beamWidth, 1.3 * px);

  // the entry beam, with dust drifting through it
  float ai = dot(v, din), pi = dot(v, dn);
  float before = smoothstep(0.006, -0.01, ai);
  float dust = 0.7 + 0.3 * smoothstep(-0.6, 0.6, fx_noise(vec2(ai * 7.0 - t * 0.3, 2.3)));
  float beam = (exp(-pi * pi / (w0 * w0)) * 0.85 + exp(-pi * pi / (w0 * w0 * 40.0)) * 0.1) * before * dust;

  // the fan: hue across it, white where the colours still overlap near the split
  float al = dot(v, fd), pp = dot(v, fn);
  float alp = max(al, 0.0);
  float hs = tan(0.5 * u_fanSpread);
  float hw = w0 + alp * hs;
  float u = pp / hw * u_side;
  float sep = alp * hs / (alp * hs + 3.0 * w0);
  float prof = exp(-u * u * u * u * 1.3);   // flat across the colours, soft at the sides
  float start = smoothstep(-0.004, 0.012, al);
  float stop = 1.0 - smoothstep(D - 0.04, D + 0.015, al);
  float thin = pow(w0 / hw, 0.3);               // the light thins as it spreads
  float air = 0.7 + 0.45 * fx_fbm(vec2(al * 2.6 - t * 0.04, pp * 5.0 + t * 0.02) + u_seed * 0.01);
  float fanI = prof * start * stop * thin * air * u_haze * 1.5;

  // where it lands: a soft spectrum on the wall, a little wider than the fan, and the wall lit around it
  float hwL = w0 + D * hs;
  float uL = pp / hwL * u_side;
  float land = exp(-pow((al - D) / (0.035 + 0.05 * hwL), 2.0)) * exp(-uL * uL * uL * uL * 1.6);
  land *= 0.85 + 0.15 * fx_noise(vec2(uL * 2.0, t * 0.1 + 5.0));
  vec2 lq = rot(P - Lp, 0.0);
  float bloom = exp(-dot(lq, lq) / (0.05 + 0.6 * hwL * hwL)) + 0.35 * exp(-dot(lq, lq) / 0.35);

  float split = exp(-r * r / 0.0005) * 0.75 + exp(-r * r / 0.01) * 0.16;
  float scatter = exp(-pi * pi / 0.012) * before * 0.1 + exp(-r * r / 0.05) * 0.08;

  float cm = 1.0 - 0.75 * calmMask(uv) * smoothstep(0.0, 0.5, u_calm);
  float k = u_intensity * cm;

  // the room: the page ground with a faint, slow haze
  vec3 col = u_ground;
  col.x += u_amb * (fx_fbm(P * 1.1 + vec2(t * 0.01, 0.0) + u_seed * 0.03) + 0.2 * (1.0 - uv.y));
  col = mix(col, u_glowA, clamp(scatter * u_haze * 2.0 + bloom * 0.35, 0.0, 1.0) * k * u_lit);
  vec3 fanCol = mix(u_hot, spec(u), sep);
  // the wall around the light: lit, with only a little of the colour (a dim saturated tint reads as mud)
  vec3 wallC = spec(clamp(uL, -1.0, 1.0) * 0.7);
  wallC.yz *= 0.45;
  col = mix(col, mix(u_glowA, wallC, 0.5), clamp(bloom * 0.32, 0.0, 1.0) * k);
  col = mix(col, fanCol, clamp(fanI, 0.0, 0.9) * k);
  col = mix(col, spec(uL), clamp(land * 0.9, 0.0, 0.92) * k);
  col = mix(col, u_beam, clamp(beam, 0.0, 1.0) * k * u_lit);
  col = mix(col, u_hot, clamp(split, 0.0, 1.0) * k * u_lit);
  col.x += fx_grain(gl_FragCoord.xy, floor(u_time * 24.0)) * 0.006;
  fxColor = vec4(fx_dither(fx_rgb(col)), 1.0);
}
`;

const hd = (a, b) => { const d = Math.abs((((a - b) % 360) + 360) % 360); return d > 180 ? 360 - d : d; };
// the centre hue nearest the accent whose span (centre +- s) stays clear of violet and lavender (262..338 in OKLCH)
function spectrumCentre(h, s) {
  const lo = 262, hi = 338;
  const clear = c => { for (let k = -s; k <= s; k += 2) { const x = (((c + k) % 360) + 360) % 360; if (x >= lo && x <= hi) return false; } return true; };
  if (clear(h)) return h;
  const a = lo - s - 1, b = hi + s + 1;
  return hd(h, a) <= hd(h, b) ? a : b;
}

export function tones(P, prm) {
  const { bg, ink, accent } = P;
  const [Lb, Cb, hb] = color.lch(bg);
  const [, Ca, ha] = color.lch(accent);
  const dark = Lb < 0.6;
  const s = prm.hueSpread;
  // a grey accent: the spectrum follows the background hue, quietly
  const grey = Ca < 0.03;
  const centre = spectrumCentre(grey ? hb : ha, grey ? Math.min(s, 30) : s);
  const C = grey ? 0.06 : Math.min(0.15, Math.max(0.085, Ca * 1.3));
  const Lmid = dark ? 0.82 : Math.max(0.45, Lb - 0.14);
  const ramp = [-1, -0.5, 0, 0.5, 1].map(u => color.fromLch([Lmid - (dark ? 0.06 : 0.03) * Math.abs(u), C * (1 - 0.15 * Math.abs(u)), centre + u * s]));
  if (dark) {
    const ground = color.darken(bg, Math.min(0.03, Lb * 0.1));
    const pale = color.adjust(bg, { l: 0.95 - Lb, c: 0.2 });
    return {
      ground, ramp, dark,
      beam: color.mix(pale, color.withLightness(ink, 0.97), 0.5),
      hot: color.withLightness(color.mix(pale, ramp[2], 0.15), 0.97),
      glowA: color.mix(ground, color.mix(pale, ramp[2], 0.3), 0.35),
      amb: 0.02, lit: 1,
    };
  }
  // a light ground (not what it is made for): the beam does not show on a pale wall, only the
  // spectrum it throws, a shade darker than the page so text in the page ink stays readable
  return {
    ground: bg, ramp, dark,
    beam: bg, hot: color.mix(bg, ramp[2], 0.4), glowA: color.mix(bg, ramp[2], 0.25),
    amb: 0.006, lit: 0,
  };
}

// the frame: the split high on one side, the light landing low on the other; when the page's text
// (calm) sits where it would land, the picture is mirrored
function layout(prm) {
  let left = prm.splitX < 0.5;
  const d = Math.min(0.3, Math.max(0.12, left ? prm.splitX : 1 - prm.splitX)); // distance from the near edge
  const ys = 0.12 + 0.3 * prm.splitY;
  if (prm.calm > 0.05) {
    const lx = left ? 0.78 : 0.22;
    if (Math.abs(prm.calmX - lx) < 0.3 && Math.abs(prm.calmY - 0.8) < 0.35) left = !left;
  }
  return { S: [left ? d : 1 - d, ys], L: [left ? 0.78 : 0.22, 0.76], side: left ? 1 : -1 };
}

function uniforms({ palette, params: prm }) {
  const k = tones(palette, prm);
  const g = layout(prm);
  return {
    u_ground: color.labVec(k.ground), u_beam: color.labVec(k.beam), u_hot: color.labVec(k.hot), u_glowA: color.labVec(k.glowA),
    u_r0: color.labVec(k.ramp[0]), u_r1: color.labVec(k.ramp[1]), u_r2: color.labVec(k.ramp[2]), u_r3: color.labVec(k.ramp[3]), u_r4: color.labVec(k.ramp[4]),
    u_amb: k.amb, u_lit: k.lit, u_S: g.S, u_L: g.L, u_side: g.side,
  };
}

export default {
  id: 'prism-dispersion',
  name: 'Prism light',
  family: 'light',
  params,
  mount(el, { palette, params: given, seed }) {
    return shader(el, {
      frag,
      schema: params,
      params: given,
      palette,
      seed,
      uniforms,
      still: 2,
      fallback: ({ palette: P, params: prm }) => {
        const k = tones(P, prm);
        const g = layout(prm);
        const [sx, sy] = g.S.map(v => v * 100), [lx, ly] = g.L.map(v => v * 100);
        return `radial-gradient(5% 8% at ${sx}% ${sy}%, ${k.hot}, transparent 70%), `
          + `radial-gradient(11% 20% at ${lx + 2.5 * g.side}% ${ly - 3}%, ${k.ramp[1]}, transparent 80%), `
          + `radial-gradient(11% 20% at ${lx - 2.5 * g.side}% ${ly + 3}%, ${k.ramp[3]}, transparent 80%), `
          + `radial-gradient(30% 40% at ${lx}% ${ly}%, ${k.glowA}, transparent 75%), ${k.ground}`;
      },
    });
  },
};

effects/painterly-landscape/effect.js:
// painterly-landscape: a soft, defocused landscape in the page colours, painted in broad dabs: a sky that
// lightens toward the horizon, hazy far hills, a middle ridge and a near hill whose crest catches the light.
// The ground for a UI window on a feature card. Light palettes get a pale day sky, dark ones a dusk that is
// light only near the horizon, colour palettes a sky of the page colour over a field.
// The picture is soft, so it renders at about half resolution; the film grain is a full-resolution CSS layer.
import { shader, color, grainCSS } from '../fx.js';

const params = {
  horizon: { default: 0.45, min: 0.3,  max: 0.7,  step: 0.01 }, // far horizon, 0 top .. 1 bottom
  slope:   { default: 14,   min: 0,    max: 30,   step: 1 },    // how steeply the near hill rises, degrees
  side:    { default: 0,    min: -1,   max: 1,    step: 1 },    // side the hill rises toward: -1 left, 1 right, 0 away from the calm area
  hillY:   { default: 0.12, min: -0.1, max: 0.35, step: 0.01 }, // near hill below the horizon at the centre
  blur:    { default: 0.6,  min: 0,    max: 1,    step: 0.01 }, // defocus of edges and dabs
  brush:   { default: 0.6,  min: 0,    max: 1,    step: 0.01 }, // strength of the brush dabs
  grain:   { default: 0.03, min: 0,    max: 0.1,  step: 0.005 },// film grain (a CSS layer)
  drift:   { default: 0.02, min: 0,    max: 0.2,  step: 0.005 },// how fast the light and the dabs move
  calm:    { default: 0.4,  min: 0,    max: 1,    step: 0.01 }, // a quiet patch of the page ground where text sits
  calmX:   { default: 0.5,  min: 0,    max: 1,    step: 0.01 },
  calmY:   { default: 0.55, min: 0,    max: 1,    step: 0.01 },
};

const frag = /* glsl */ `
// soft steps: plateaus joined by soft edges, so noise reads as separate dabs of paint
float dabs(float n, float k, float soft) {
  float q = n * k;
  return (floor(q) + smoothstep(0.5 - soft, 0.5 + soft, fract(q))) / k;
}
// brush dabs along direction d: long in d, narrow across it; about -1..1. off moves them in their own
// frame (off.x along the stroke), so a drift never shears them
float strokes(vec2 p, vec2 d, float len, float wid, vec2 off, float soft) {
  vec2 r = vec2(dot(p, d), dot(p, vec2(-d.y, d.x))) + off;
  float n = fx_noise(vec2(r.x * len, r.y * wid)) + 0.5 * fx_noise(vec2(r.x * len * 2.3, r.y * wid * 2.2) + 5.3);
  return dabs(n, 2.5, soft);
}

void main() {
  vec2 uv = fx_uv();
  float asp = u_res.x / u_res.y;
  vec2 p = vec2((uv.x - 0.5) * asp, uv.y);              // x centred, both in height units, y down
  float t = u_time * u_drift + u_seed * 0.0137;
  vec2 so = vec2(u_seed * 0.0213, u_seed * 0.0119);
  float bl = 0.25 + 0.75 * u_blur;
  float soft = 0.1 + 0.32 * u_blur;
  float hz = u_horizon;

  // the calm patch where text sits: wide, with a ragged edge like a cloud shadow or a bank of mist
  vec2 cd = (uv - vec2(u_calmX, u_calmY)) * vec2(asp * 0.45, 1.0);
  float cr = (0.2 + 0.32 * u_calm) * (1.0 + 0.4 * fx_fbm(p * vec2(1.4, 4.5) + so + vec2(t, 0.0)));
  float calm = (1.0 - smoothstep(cr * 0.45, cr, length(cd))) * min(1.0, u_calm * 2.5);
  float bk = u_brush * (1.0 - 0.85 * calm);

  // sky: deep at the top, lighter toward the horizon, a broad glow on the open side
  float sy = clamp(uv.y / hz, 0.0, 1.0);
  vec3 col = mix(u_skyTop, u_skyMid, smoothstep(0.0, 0.75, sy));
  col = mix(col, u_skyLow, pow(smoothstep(0.3, 1.0, sy), 1.5));
  vec2 sun = u_sun + vec2(0.16 * sin(t * 2.1), 0.0);
  vec2 ds = (p - sun) * vec2(0.45, 1.0);
  float glow = exp(-dot(ds, ds) * 5.0);
  col = mix(col, u_glow, glow * 0.65);
  // sky dabs: long and nearly level, a touch lighter and warmer where they catch the glow
  float sk = strokes(p, normalize(vec2(1.0, 0.1 * sin(p.x * 1.3 + so.x))), 1.2, 7.5, so + vec2(t * 0.5, 0.0), soft);
  col = mix(col, u_glow, clamp(sk, 0.0, 1.0) * 0.22 * bk * (0.3 + 0.7 * sy));
  col.x -= clamp(-sk, 0.0, 1.0) * 0.035 * bk;

  // far hills: a hazy band at the horizon, almost in focus
  float farY = hz + 0.035 * fx_fbm(vec2(p.x * 1.8 + 3.1, 1.7) + so) + 0.01 * fx_noise(vec2(p.x * 7.0, 4.0) + so);
  float wf = 0.003 + 0.01 * bl;
  vec3 farCol = mix(u_far, u_skyLow, 0.3 * glow);
  col = mix(col, farCol, smoothstep(farY - wf, farY + wf, uv.y));

  // a middle ridge, rising gently on the other side, a step deeper
  float hm = hz + 0.07 + u_dir * 0.1 * p.x + 0.035 * fx_fbm(vec2(p.x * 1.4 + 9.1, 2.3) + so);
  float wm = 0.005 + 0.025 * bl;
  vec3 midCol = mix(u_mid, u_near, smoothstep(hm, hm + 0.35, uv.y) * 0.5);
  float ms = strokes(p, normalize(vec2(1.0, u_dir * 0.1)), 2.2, 15.0, so + 3.0 + vec2(t * 0.1, 0.0), soft);
  midCol = mix(midCol, u_far, clamp(ms, 0.0, 1.0) * 0.35 * bk);
  col = mix(col, midCol, smoothstep(hm - wm, hm + wm, uv.y));

  // the near hill: one long diagonal, the most defocused plane, its crest lit
  float ta = tan(radians(u_slope));
  float hy = hz + u_hillY - u_dir * ta * p.x + 0.065 * fx_fbm(vec2(p.x * 1.1 + 7.3, 4.2) + so);
  float wn = 0.008 + 0.05 * bl;
  float near = smoothstep(hy - wn, hy + wn * 0.6, uv.y);
  float into = clamp((uv.y - hy) / 0.45, 0.0, 1.0);
  float sx = (p.x - sun.x) * 0.6;
  float lit = 0.6 + 0.4 * exp(-sx * sx);
  vec3 nearCol = mix(u_nearLit, u_near, smoothstep(0.0, 0.5, into / lit));
  nearCol = mix(nearCol, u_deep, smoothstep(0.4, 1.0, into));
  // brush: dabs along the slope that trade lit and shade tones, so the grass reads as paint
  vec2 dv = normalize(vec2(1.0, -u_dir * ta));
  float b = 0.7 * strokes(p, dv, 2.4, 15.0, so + 7.0 + vec2(t * 0.12, 0.0), soft)
          + 0.45 * strokes(p, normalize(dv + vec2(0.0, 0.3 * u_dir)), 5.0, 28.0, so + 11.0, soft);
  nearCol = mix(nearCol, u_nearLit, clamp(b, 0.0, 1.0) * 0.6 * bk * (1.0 - 0.6 * into));
  nearCol = mix(nearCol, u_deep, clamp(-b, 0.0, 1.0) * 0.5 * bk);
  col = mix(col, nearCol, near);

  // soft fall-off toward the lower corners, like a lens
  vec2 v = (uv - vec2(0.5, 0.42)) * vec2(1.0, 1.2);
  col.x -= 0.05 * smoothstep(0.4, 1.0, length(v));

  // the calm patch: lightness held on the page ground's side of the text colour (darker under light
  // text, lighter under dark text), colour drawn toward the ground
  float held = u_capDir > 0.0 ? max(col.x, u_cap) : min(col.x, u_cap);
  float lift = abs(held - col.x);
  col.x = mix(col.x, held, calm);
  col.yz = mix(col.yz, u_ground.yz, calm * min(0.85, 0.45 + 2.5 * lift));
  fxColor = vec4(fx_dither(fx_rgb(col)), 1.0);
}
`;

const L = c => color.lab(c)[0];
const at = (c, l) => color.withLightness(c, Math.min(0.98, Math.max(0.04, l)));
const sat = (c, k) => color.saturate(c, k);

// every tone is a mix, shade or tint of the page colours
function tones(P, kind) {
  const { bg, ink, muted, accent } = P;
  const acc = color.chroma(accent) > 0.03 ? accent : color.mix(ink, muted, 0.4);
  const Lb = L(bg);
  if (kind === 'dark') {
    // dusk: a deep sky that lights up only near the horizon, hills as dark shapes with a lit crest
    return {
      skyTop: color.mix(bg, acc, 0.05),
      skyMid: sat(color.mix(bg, acc, 0.18), 0.9),
      skyLow: sat(at(color.mix(acc, ink, 0.3), Math.max(0.72, Lb + 0.5)), 0.85),
      glow: at(color.mix(ink, acc, 0.35), Math.max(0.84, Lb + 0.6)),
      far: sat(at(color.mix(acc, muted, 0.55), Lb + 0.3), 0.5),
      mid: sat(at(color.mix(muted, acc, 0.3), Lb + 0.14), 0.45),
      nearLit: sat(at(color.mix(acc, muted, 0.35), Lb + 0.26), 0.6),
      near: sat(at(color.mix(bg, muted, 0.4), Lb + 0.07), 0.6),
      deep: at(bg, Lb + 0.01),
      ground: bg,
    };
  }
  if (kind === 'colour') {
    // a sky of the page colour, blue-ish far hills in its deeper shade, a field of the accent when it
    // sits far in hue (yellow on cobalt), else a deep shade of the ground
    const accFar = color.chroma(acc) > 0.04 && color.hueDistance(bg, acc) > 55;
    const light = L(ink) > Lb ? ink : sat(color.lighten(bg, Math.min(0.16, 0.98 - Lb)), 0.5);
    const field = accFar ? acc : color.lighten(bg, -0.2);
    const Ll = Math.min(0.8, Math.max(L(field), Lb + 0.12));
    return {
      skyTop: color.lighten(bg, -0.06),
      skyMid: bg,
      skyLow: color.mix(bg, light, 0.45),
      glow: color.mix(bg, light, 0.72),
      far: sat(color.mix(bg, light, 0.22), 0.8),
      mid: sat(color.lighten(bg, -0.1), 0.85),
      nearLit: sat(at(field, Ll), 0.82),
      near: sat(at(field, Ll - 0.24), 0.85),
      deep: color.mix(at(field, Ll - 0.38), color.lighten(bg, -0.2), 0.35),
      ground: bg,
    };
  }
  // light: a pale, almost neutral sky (no accent in it), hazy far hills, a hill of the accent whose crest
  // is lit warm; the hill sits at least a quarter of the lightness scale below the sky
  const cool = sat(color.mix(bg, ink, 0.12), 0.25);
  const Ls = Math.min(0.97, Lb + 0.05);
  const Llit = Math.min(Ls - 0.28, Math.max(0.52, L(acc) + 0.12));
  return {
    skyTop: at(cool, Lb - 0.07),
    skyMid: sat(color.lighten(bg, 0.02), 0.35),
    skyLow: sat(at(bg, Ls), 0.5),
    glow: at(bg, Math.min(0.99, Lb + 0.09)),
    far: sat(at(color.mix(bg, acc, 0.3), Ls - 0.12), 0.5),
    mid: sat(at(color.mix(bg, acc, 0.6), Ls - 0.22), 0.75),
    nearLit: sat(at(color.mix(acc, bg, 0.3), Llit), 1.3),
    near: sat(at(acc, Llit - 0.14), 1.05),
    deep: sat(at(acc, Llit - 0.25), 0.95),
    ground: bg,
  };
}

function uniforms({ palette, params, rng, kind, width, height }) {
  const k = tones(palette, kind);
  const asp = width && height ? width / height : 1.6;
  const r = rng;
  const coin = r() < 0.5 ? -1 : 1;
  // the hill rises away from the calm area (where text sits); a centred calm area lets the seed choose
  const dir = params.side !== 0 ? Math.sign(params.side) : Math.abs(params.calmX - 0.5) > 0.12 ? (params.calmX < 0.5 ? 1 : -1) : coin;
  // the calm patch keeps the ground on the far side of the text colour from the ink
  const inkLight = color.lab(palette.ink)[0] > color.lab(palette.bg)[0];
  const Lg = color.lab(palette.bg)[0];
  const u = {
    u_dir: dir, u_sun: [-dir * asp * (0.16 + 0.14 * r()), params.horizon - 0.06 - 0.06 * r()],
    u_cap: inkLight ? Lg + (kind === 'dark' ? 0.08 : 0.03) : Lg - 0.02, u_capDir: inkLight ? -1 : 1,
  };
  for (const [name, c] of Object.entries(k)) u['u_' + name] = color.labVec(c);
  return u;
}

// film grain as a CSS layer at full resolution, blended soft-light so it shades both ways
function grainLayer(amount) {
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='220' height='220'><filter id='g'><feTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/><feColorMatrix type='saturate' values='0'/><feComponentTransfer><feFuncA type='table' tableValues='1 1'/></feComponentTransfer></filter><rect width='100%' height='100%' filter='url(%23g)'/></svg>`;
  const url = `url("data:image/svg+xml,${svg.replace(/</g, '%3C').replace(/>/g, '%3E').replace(/ /g, '%20')}")`;
  const d = document.createElement('div');
  d.className = 'fx-grain';
  d.setAttribute('aria-hidden', 'true');
  Object.assign(d.style, {
    position: 'absolute', inset: '0', zIndex: '-1', pointerEvents: 'none', borderRadius: 'inherit',
    backgroundImage: url, mixBlendMode: 'soft-light', opacity: String(Math.min(1, amount * 9)),
  });
  return d;
}

export default {
  id: 'painterly-landscape',
  name: 'Painterly landscape',
  family: 'mesh',
  params,
  mount(el, { palette, params: given, seed }) {
    const ctrl = shader(el, {
      frag,
      schema: params,
      params: given,
      palette,
      seed,
      uniforms,
      maxDpr: 0.6,
      still: 4,
      fallback: ({ palette: P, kind, params: prm, rng }) => {
        const k = tones(P, kind);
        const h = prm.horizon * 100;
        const dir = prm.side !== 0 ? Math.sign(prm.side) : Math.abs(prm.calmX - 0.5) > 0.12 ? (prm.calmX < 0.5 ? 1 : -1) : rng() < 0.5 ? -1 : 1;
        const ang = 180 + dir * (8 + prm.slope * 0.8);
        // a still landscape: the near hill as an angled band over sky and far hills
        return `${grainCSS(0.05)}, linear-gradient(${ang}deg, transparent ${h + prm.hillY * 100 - 2}%, ${k.nearLit} ${h + prm.hillY * 100 + 4}%, ${k.near} ${h + prm.hillY * 100 + 22}%, ${k.deep}), linear-gradient(${k.skyTop}, ${k.skyMid} ${h * 0.6}%, ${k.skyLow} ${h - 1}%, ${k.far} ${h + 1}%, ${k.mid} ${h + 9}%)`;
      },
    });
    let grain = null;
    const sync = p => {
      if (el.dataset.fxFallback || p.grain <= 0) { grain?.remove(); grain = null; return; }
      // above the canvas (which fx.shader puts first), under the content
      if (!grain) { grain = grainLayer(p.grain); const cv = el.querySelector(':scope > canvas.fx-canvas'); el.insertBefore(grain, cv ? cv.nextSibling : el.firstChild); }
      grain.style.opacity = String(Math.min(1, p.grain * 9));
    };
    sync({ grain: (given && given.grain != null) ? +given.grain : params.grain.default });
    return {
      pause: () => ctrl.pause(),
      resume: () => ctrl.resume(),
      redraw: () => ctrl.redraw(),
      set(next) { const p = ctrl.set(next); sync(p); return p; },
      setPalette: p => ctrl.setPalette(p),
      destroy() { ctrl.destroy(); grain?.remove(); grain = null; },
      get canvas() { return ctrl.canvas; },
      get info() { return ctrl.info; },
    };
  },
};

effects/orb-sphere/effect.js:
// orb-sphere: one sphere with a slowly turning nebula inside. The sphere normal is rebuilt per pixel,
// so the nebula is 3D noise on a turning sphere (true rotation), the rim is a fresnel edge, and specks
// of light sit on the near and far shell (they cross in opposite directions).
// Two grounds, chosen by the page text: on pages with light text the orb glows in a dark field (the
// page ground, or a deep tone of a colour ground); on pages with dark text the field is the page
// ground itself and the orb is a dark glass ball with a soft halo, so the text keeps its contrast.
// The orb is placed on the side away from the calm area (where the page puts its text).
import { shader, color, paletteKind } from '../fx.js';

const params = {
  size:          { default: 0.36, min: 0.12, max: 0.6, step: 0.01 },  // radius, share of the shorter side
  rim:           { default: 0.8,  min: 0,    max: 1.5, step: 0.01 },  // brightness of the fresnel edge
  innerContrast: { default: 0.5,  min: 0,    max: 1,   step: 0.01 },  // how strongly the nebula shows
  stars:         { default: 60,   min: 0,    max: 200, step: 1 },     // specks of light inside
  glow:          { default: 0.35, min: 0,    max: 1,   step: 0.01 },  // soft light around the orb
  speed:         { default: 0.05, min: 0,    max: 0.4, step: 0.005 }, // turning speed; 0.05 is about 25 s a turn
  pulse:         { default: 0,    min: 0,    max: 1,   step: 0.01 },  // gentle breathing of size and glow
  orbX:          { default: 0.5,  min: 0,    max: 1,   step: 0.01 },  // wanted orb centre, 0 left .. 1 right
  orbY:          { default: 0.5,  min: 0,    max: 1,   step: 0.01 },  // wanted orb centre, 0 top .. 1 bottom
  calm:          { default: 0.5,  min: 0,    max: 1,   step: 0.01 },  // keep the orb and glow off this area
  calmX:         { default: 0.25, min: 0,    max: 1,   step: 0.01 },
  calmY:         { default: 0.7,  min: 0,    max: 1,   step: 0.01 },
};

const frag = /* glsl */ `
// float hash for the 3D lattice (no sine, so no streaks on coarse GPUs), -1..1
vec3 orb_h3(vec3 p) {
  p = fract(p * vec3(0.1031, 0.1030, 0.0973));
  p += dot(p, p.yxz + 33.33);
  return fract((p.xxy + p.yxx) * p.zyx) * 2.0 - 1.0;
}
// 3D gradient noise, about -0.8..0.8
float orb_noise(vec3 p) {
  vec3 i = floor(p), f = fract(p);
  vec3 u = f * f * (3.0 - 2.0 * f);
  float a = dot(orb_h3(i), f);
  float b = dot(orb_h3(i + vec3(1.0, 0.0, 0.0)), f - vec3(1.0, 0.0, 0.0));
  float c = dot(orb_h3(i + vec3(0.0, 1.0, 0.0)), f - vec3(0.0, 1.0, 0.0));
  float d = dot(orb_h3(i + vec3(1.0, 1.0, 0.0)), f - vec3(1.0, 1.0, 0.0));
  float e = dot(orb_h3(i + vec3(0.0, 0.0, 1.0)), f - vec3(0.0, 0.0, 1.0));
  float g = dot(orb_h3(i + vec3(1.0, 0.0, 1.0)), f - vec3(1.0, 0.0, 1.0));
  float h = dot(orb_h3(i + vec3(0.0, 1.0, 1.0)), f - vec3(0.0, 1.0, 1.0));
  float k = dot(orb_h3(i + vec3(1.0, 1.0, 1.0)), f - vec3(1.0, 1.0, 1.0));
  return mix(mix(mix(a, b, u.x), mix(c, d, u.x), u.y), mix(mix(e, g, u.x), mix(h, k, u.x), u.y), u.z) * 1.6;
}
float orb_fbm(vec3 p) {
  float s = orb_noise(p);
  s += 0.5 * orb_noise(p * 2.03 + vec3(1.7, 9.2, 3.1));
  s += 0.25 * orb_noise(p * 4.07 + vec3(8.3, 2.8, 5.4));
  return s / 1.75;
}
vec3 orb_rot(vec3 n, float a, float tilt) {
  // tilt the axis toward the viewer a little, then turn around it
  float ct = cos(tilt), st = sin(tilt);
  n = vec3(n.x, ct * n.y - st * n.z, st * n.y + ct * n.z);
  float c = cos(a), s = sin(a);
  return vec3(c * n.x + s * n.z, n.y, -s * n.x + c * n.z);
}
// specks of light on a unit sphere: one candidate per cell of a cube map, px = pixels per cell.
// Most are fine points of varied brightness; a few are larger, softer and dimmer.
float orb_stars(vec3 d, float grid, float thr, float px, float t, float salt) {
  vec3 a = abs(d);
  vec2 uv; float face;
  if (a.x >= a.y && a.x >= a.z) { uv = d.yz / a.x; face = d.x > 0.0 ? 1.0 : 2.0; }
  else if (a.y >= a.z) { uv = d.zx / a.y; face = d.y > 0.0 ? 3.0 : 4.0; }
  else { uv = d.xy / a.z; face = d.z > 0.0 ? 5.0 : 6.0; }
  vec2 g = uv * grid;
  vec2 cell = floor(g);
  vec2 key = cell + vec2(face * 53.0 + salt, face * 29.0 - salt);
  float h = fx_hash(key);
  if (h < thr) return 0.0;
  vec2 pos = 0.22 + 0.56 * fx_hash2(key + 17.0);
  float dist = length(g - cell - pos) * px;
  float sz = fract(h * 37.0);
  float big = step(0.88, sz);
  float r = mix(mix(0.45, 1.05, sz / 0.88), mix(1.7, 2.8, (sz - 0.88) / 0.12), big) * u_dpr;
  float tw = 0.62 + 0.38 * sin(t * (0.6 + 1.4 * fract(h * 91.0)) + h * 60.0);
  float b = mix(0.22, 1.0, pow(fract(h * 13.0), 1.7)) * mix(1.0, 0.42, big);
  return exp(-dist * dist / (r * r)) * tw * b;
}
vec3 orb_tone(vec3 c) {
  // soft shoulder above 0.62 (linear), so the rim turns toward white instead of clipping
  vec3 k = max(c - 0.62, 0.0);
  return min(c, vec3(0.62)) + 0.38 * (1.0 - exp(-k / 0.38));
}

void main() {
  vec2 uv = fx_uv();
  float t = u_time;
  float S = min(u_res.x, u_res.y);
  float br = u_pulse * sin(t * 1.25);
  float R = u_size * u_orbS * S * (1.0 + 0.018 * br);
  // the centre is placed on the CPU (away from the calm area, inside the frame where it fits)
  vec2 c = vec2(u_orbC.x, 1.0 - u_orbC.y) * u_res;
  vec2 q = (gl_FragCoord.xy - c) / R;
  float r = length(q);
  float px = 1.0 / R;

  // the field and the orb's halo, kept off the calm area
  float calmM = 1.0 - u_calm * fx_calm(uv, vec2(u_calmX, u_calmY), 0.3 + 0.35 * u_calm);
  float d = max(r - 1.0, 0.0);
  vec3 field;
  if (u_light > 0.5) {
    // light ground: the page ground itself, tinted softly toward the orb's light near it
    float h2 = exp(-d * 2.0) * 0.55 + exp(-d * 7.0) * 0.45;
    field = mix(u_kGround, u_kGlow, clamp(h2 * u_glow * 1.15 * (1.0 + 0.3 * br) * calmM, 0.0, 1.0));
  } else {
    float halo = exp(-d * 2.6) * 0.5 + exp(-d * 9.0) * 0.5;
    field = orb_tone(u_kGround + u_kGlow * halo * u_glow * (1.0 + 0.3 * br) * calmM);
  }
  vec3 col = field;

  if (r < 1.0 + 2.0 * px) {
    float z = sqrt(max(1.0 - r * r, 0.0));
    vec3 n = vec3(q, z);
    float ang = t * u_speed * 5.0 + u_seed * 0.0123;
    vec3 nr = orb_rot(n, ang, 0.38);
    vec3 so = vec3(u_seed * 0.0173, u_seed * 0.0071, u_seed * 0.0119);
    so = so - floor(so / 61.0) * 61.0;

    // nebula: large shapes and a warped finer layer, sampled on the turning surface
    float A = orb_fbm(nr * 1.55 + so);
    float B = orb_fbm(nr * 3.3 + vec3(A * 1.6) + so.zxy);
    float neb = smoothstep(-0.2, 0.75, A * 0.7 + B * 0.55);
    float wisp = smoothstep(0.2, 0.68, B) * neb;

    float fres = pow(1.0 - z, 3.0);
    float limb = pow(1.0 - z, 10.0);
    vec3 inside = u_kDeep * (0.6 + 0.8 * (1.0 - z));
    float body = (0.18 + 1.25 * u_innerContrast);
    inside += u_kTone * (neb * neb * 0.42 + wisp * wisp * 0.9) * body * mix(0.45, 1.0, 1.0 - z * z);

    // specks of light: the near shell bright, the far shell dim and turning the other way across
    float pxCell = R / u_grid * mix(0.55, 1.0, z);
    float st = orb_stars(nr, u_grid, u_thr, pxCell, t, 0.0);
    vec3 nb = orb_rot(vec3(q, -z), ang, 0.38);
    float sb = orb_stars(nb, u_grid, u_thr, pxCell, t, 311.0);
    inside += u_kStar * (st + 0.4 * sb * (1.0 - 0.5 * neb));

    // fresnel rim (tinted) and a thin bright limb: the edge is brighter than the centre
    inside += (u_kTone * fres * 0.75 + u_kRim * limb * 0.9) * u_rim * (1.0 + 0.15 * br);
    // a small window reflection, upper left, so the dark ball reads as glass
    vec2 hq = mat2(0.8, -0.6, 0.6, 0.8) * (q - vec2(-0.4, 0.46)) * vec2(1.0, 2.1);
    float hl = exp(-dot(hq, hq) * 30.0);
    inside += u_kRim * (hl * 0.9 + exp(-dot(hq, hq) * 5.0) * 0.12) * u_spec;
    // on a light ground the lower limb catches light bounced up from the ground
    inside += u_kGround * u_light * 0.2 * smoothstep(0.2, -0.95, q.y) * fres;

    float edge = smoothstep(1.0 + 0.75 * px, 1.0 - 0.75 * px, r);
    col = mix(field, orb_tone(inside), edge);
  }

  fxColor = vec4(fx_dither(fx_srgb(col)), 1.0);
}
`;

const lin = c => color.rgb(c).map(v => (v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)));
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const lc = (c, L, C) => { const [, , h] = color.lch(c); return color.fromLch([L, C, h]); };
// blues lightened at a fixed hue drift toward lavender: keep their hue at 248 and their chroma modest
function noLavender(c) {
  const [L, C, h] = color.lch(c);
  if (C < 0.02 || h < 248 || h > 284) return color.hex(c);
  return color.fromLch([L, L > 0.6 ? Math.min(C, 0.12) : C, 248]);
}

// every colour comes from the palette: the orb takes the accent hue (a colour ground's own hue when its
// accent clashes); the field is the page ground (dark-text pages) or its darkest tone (light-text pages)
function tones(P) {
  const kind = paletteKind(P);
  const { bg, ink, accent } = P;
  const light = color.lab(ink)[0] < color.lab(bg)[0];
  const Ca = color.chroma(accent);
  let hue = accent;
  if (light) hue = Ca >= 0.04 ? accent : color.chroma(ink) >= 0.04 ? ink : color.chroma(bg) >= 0.04 ? bg : accent;
  else if (kind === 'colour' && (color.hueDistance(bg, accent) > 55 || Ca < 0.03)) hue = bg;
  const C = color.chroma(hue);
  // yellows and yellow-greens turn olive or brown when darkened: there the body stays near the ink
  // and the light is kept high, so the colour reads as light on dark instead of mud
  const h = color.lch(hue)[2];
  const olive = C > 0.04 && h > 75 && h < 140;
  // the orb's light: a lively light step of the hue, at least some chroma so a muted accent still glows
  const tone = noLavender(C > 0.02 ? lc(hue, olive ? 0.82 : 0.74, clamp(C * 1.1, 0.1, 0.16)) : color.withLightness(hue, 0.76));
  let ground, deep, glow;
  if (light) {
    ground = bg;
    // a deep glass of the hue with some of the page ink in it
    deep = color.mix(ink, lc(hue, 0.3, clamp(C, 0.04, 0.08)), olive ? 0.3 : 0.75);
    // the halo tints the ground toward the orb's light; when the two hues are far apart that mix
    // turns grey, so the ground only lightens
    glow = color.chroma(bg) > 0.04 && color.hueDistance(bg, tone) > 70 ? color.mix(bg, '#ffffff', 0.5) : color.mix(bg, tone, 0.55);
  } else {
    ground = kind === 'dark' ? bg : lc(bg, 0.2, clamp(color.chroma(bg) * 0.55, 0.04, 0.1));
    deep = color.mix(ground, lc(hue, 0.3, Math.min(C, 0.08)), olive ? 0.12 : 0.3);
    glow = color.mix(ground, tone, 0.55);
  }
  return {
    kind, light, ground, tone, deep, glow,
    rim: noLavender(color.mix('#ffffff', tone, 0.3)),
    star: color.mix('#ffffff', tone, 0.12),
  };
}

/*
  Where the orb goes (px, y down): the wanted spot (orbX, orbY) if the orb clears the calm area there;
  otherwise the nearest spot that clears it, inside the frame if possible, then cropped by the frame
  edge (a planet rising into the corner); failing all that, the spot farthest from the calm area.
*/
function placeOrb(prm, w, h) {
  const R0 = prm.size * Math.min(w, h);
  const want = [prm.orbX * w, prm.orbY * h];
  const inside = (m) => {
    const lo = [m, m], hi = [w - m, h - m];
    return p => [hi[0] > lo[0] ? clamp(p[0], lo[0], hi[0]) : w / 2, hi[1] > lo[1] ? clamp(p[1], lo[1], hi[1]) : h / 2];
  };
  const start = inside(R0 * 1.12)(want);
  if (prm.calm <= 0.05) return [...start, 1];
  const cc = [prm.calmX * w, prm.calmY * h];
  // clearance around the calm centre: text runs wider than it is tall
  const rc = (0.3 + 0.35 * prm.calm) * h;
  const clearFor = R => p => ((p[0] - cc[0]) / (R + 0.9 * rc)) ** 2 + ((p[1] - cc[1]) / (R + 0.5 * rc)) ** 2;
  if (clearFor(R0)(start) >= 1) return [...start, 1];
  // the nearest clear spot: whole orb in frame first (a little smaller if need be), then cropped by the edge
  let far = start, farD = clearFor(R0)(start);
  for (const [s, m] of [[1, 1.12], [0.84, 1.12], [0.7, 1.12], [1, 0.25]]) {
    const R = R0 * s, f = inside(R * m), clear = clearFor(R);
    let best = null, bestE = Infinity;
    for (let i = 0; i <= 32; i++) for (let j = 0; j <= 20; j++) {
      const p = f([w * i / 32, h * j / 20]);
      const dd = clear(p);
      if (dd >= 1) { const e = Math.hypot(p[0] - want[0], p[1] - want[1]); if (e < bestE) { bestE = e; best = p; } }
      if (s === 1 && dd > farD + 1e-3) { farD = dd; far = p; }
    }
    if (best) return [...best, s];
  }
  return [...far, 1];
}

function uniforms({ palette, params, width, height }) {
  const k = tones(palette);
  const grid = 11;
  // stars spread over the near and far shell: 6 faces * grid^2 cells
  const p = Math.min(0.5, params.stars / (6 * grid * grid) * 1.25);
  const w = width || 800, h = height || 500;
  const [cx, cy, s] = placeOrb(params, w, h);
  return {
    u_orbS: s,
    u_kGround: lin(k.ground),
    u_kDeep: lin(k.deep),
    u_kTone: lin(k.tone),
    u_kGlow: lin(k.glow),
    u_kRim: lin(k.rim),
    u_kStar: lin(k.star),
    u_light: k.light ? 1 : 0,
    u_spec: k.light ? 0.3 : 0,
    u_orbC: [cx / w, cy / h],
    u_grid: grid,
    u_thr: params.stars <= 0 ? 2 : 1 - p,
  };
}

// CSS stand-in: a soft body with an offset highlight, a thin rim and a glow that fades outward, in px
function fallback({ palette: P, params: prm, width, height }) {
  const k = tones(P);
  const w = width || 800, h = height || 500;
  const [cx, cy, s] = placeOrb(prm, w, h);
  const R = prm.size * s * Math.min(w, h);
  const f = v => `${v.toFixed(1)}px`;
  const at = `${f(cx)} ${f(cy)}`;
  const g0 = k.light ? color.mix(k.ground, k.glow, 0.55 * prm.glow * 1.6) : color.mix(k.ground, k.glow, Math.min(1, prm.glow * 1.3));
  const g1 = color.mix(k.ground, g0, 0.4);
  const deepC = color.mix(k.deep, k.tone, k.light ? 0.06 : 0.1);
  const deepE = color.mix(k.deep, k.tone, 0.32);
  const rim = color.mix(deepE, k.rim, Math.min(1, 0.45 + 0.35 * prm.rim));
  const hl = color.mix(k.deep, k.rim, 0.3);
  return [
    // the lit side (light ground: a glass reflection; dark field: the glow inside)
    `radial-gradient(circle ${f(R * 0.42)} at ${f(cx - R * 0.34)} ${f(cy - R * 0.4)}, ${hl}${k.light ? 'cc' : '55'}, ${hl}00)`,
    `radial-gradient(circle ${f(R * 0.55)} at ${f(cx + R * 0.22)} ${f(cy + R * 0.18)}, ${color.mix(k.deep, k.tone, 0.3)}99, ${k.deep}00)`,
    `radial-gradient(circle at ${at}, ${deepC} 0, ${k.deep} ${f(R * 0.62)}, ${deepE} ${f(R * 0.93)}, ${rim} ${f(R - 1)}, ${g0} ${f(R + 0.6)}, ${g1} ${f(R * 1.3)}, ${k.ground}00 ${f(R * 2.1)})`,
    k.ground,
  ].join(', ');
}

export default {
  id: 'orb-sphere',
  name: 'Light orb',
  family: 'light',
  params,
  mount(el, { palette, params: given, seed }) {
    return shader(el, { frag, schema: params, params: given, palette, seed, uniforms, still: 6, fallback });
  },
};

effects/line-engraving/effect.js:
// line-engraving: tone carried by dense parallel lines that swell in the shadows and thin to hairlines
// in the light, bending around the form, like a banknote or an etched plate. One ink on paper.
// Drawn once; it only moves when drift is above 0.
import { shader, color, rng, resolveParams } from '../fx.js';

const params = {
  pitch:     { default: 6,    min: 4,   max: 14,  step: 0.5 },  // line spacing, CSS px
  minWidth:  { default: 0.1,  min: 0,   max: 0.5, step: 0.01 }, // hairline in the light, share of the pitch
  maxWidth:  { default: 0.9,  min: 0.3, max: 1,   step: 0.01 }, // line in the deepest shadow
  angle:     { default: 20,   min: 0,   max: 180, step: 1 },    // line direction, degrees
  bend:      { default: 0.6,  min: 0,   max: 1.5, step: 0.01 }, // how far the lines follow the form
  source:    { default: 1,    min: -1,  max: 1,   step: 1 },    // 1 rolling hills (the default, a quiet ground), 0 a big sphere (focal), -1 the seed picks
  cross:     { default: 0.5,  min: 0,   max: 1,   step: 0.01 }, // cross-hatching in the darkest part
  guilloche: { default: 0,    min: 0,   max: 1,   step: 0.01 }, // a faint rosette of fine curves around the form
  size:      { default: 1,    min: 0.5, max: 1.6, step: 0.01 }, // size of the form
  accent:    { default: 0,    min: 0,   max: 1,   step: 1 },    // 1 prints in the accent instead of the ink
  drift:     { default: 0,    min: 0,   max: 0.2, step: 0.005 },// 0 is a still plate; above 0 the light wanders
  calm:      { default: 0.5,  min: 0,   max: 1,   step: 0.01 }, // empties the text area
  calmX:     { default: 0.25, min: 0,   max: 1,   step: 0.01 },
  calmY:     { default: 0.6,  min: 0,   max: 1,   step: 0.01 },
};

const frag = /* glsl */ `
// box-filtered coverage of a line of half-width w around v = 0 (v: 0 at the centre, 1 between lines)
float lineCov(float v, float w, float aa) {
  float lo = max(-w, v - aa), hi = min(w, v + aa);
  return clamp((hi - lo) / (2.0 * aa), 0.0, 1.0);
}
float hatch(float s, float gs, float w) {
  float v = abs(fract(s) - 0.5) * 2.0;
  float aa = max(2.0 * gs / u_dpr, 1e-4);   // v units per device pixel
  return lineCov(v, w, aa);
}

float hillH(vec2 p, float t) { return fx_fbm(p * 1.15 + vec2(t, 0.3 * t) + u_seed * 0.007); }

void main() {
  vec2 q = gl_FragCoord.xy / u_dpr;                 // CSS px, y up
  vec2 p = fx_p();
  vec2 uv = fx_uv();
  float Hpx = u_res.y / u_dpr;                      // frame height, CSS px
  float t = u_time * u_drift;
  float pitch = u_pitch;

  vec2 c = u_form.xy;
  float R = u_form.z, Rpx = R * Hpx;
  float ph = u_lightA + 0.5 * sin(t * 5.0);
  vec3 L = normalize(vec3(cos(ph), sin(ph), 0.85));

  float h = 0.0;            // height field the lines wrap around
  vec2 gh = vec2(0.0);      // its gradient per CSS px
  float a = 0.0;            // ink amount 0..1 (on dark paper the ink is the light)
  float pres = 0.0;         // where lines exist at all
  float bendPx = u_bend * 0.4;
  vec2 r = (p - c) / R;
  float rr = dot(r, r);

  if (u_mode < 0.5) {
    if (rr < 1.0) {
      h = 1.0 - rr;                                   // lines wrap the form and stay finite at the rim
      gh = -2.0 * r / Rpx;
      vec3 n = vec3(r, sqrt(1.0 - rr));
      float lam = max(dot(n, L), 0.0);
      float spec = pow(max(dot(reflect(-L, n), vec3(0.0, 0.0, 1.0)), 0.0), 8.0);
      float lit = 0.06 + 0.66 * lam + 0.3 * spec;
      float rim = pow(1.0 - n.z, 2.5);
      // bounce light keeps the shadow rim on paper; on dark paper it lit the shadow side as brightly
      // as the lit side and the disc read flat
      lit += (u_sub > 0.5 ? 0.12 : 0.02) * rim * (1.0 - lam);
      // the limb darkens on paper, so the round edge reads even on the lit side
      a = clamp(u_sub > 0.5 ? 1.0 - lit + 0.4 * rim * lam : lit, 0.0, 1.0);
      pres = 1.0;
    } else if (u_sub > 0.5) {
      vec2 sc = c + vec2(-L.x * 0.55 * R, -0.97 * R);  // cast shadow on the floor
      vec2 e = (p - sc) / (R * vec2(1.35, 0.25));
      float sh = exp(-dot(e, e) * 1.1);
      a = 0.85 * sh;
      pres = smoothstep(0.04, 0.3, sh);
    }
    bendPx *= Rpx;
  } else {
    // rolling hills: lines ride over a soft height field, lit from the side
    float e = 1.5 / Hpx;
    float h0 = hillH(p, t);
    float hx = hillH(p + vec2(e, 0.0), t), hy = hillH(p + vec2(0.0, e), t);
    gh = vec2(hx - h0, hy - h0) / 1.5;
    h = h0;
    vec3 n = normalize(vec3(-gh * Hpx * 0.35, 1.0));
    float lit = clamp(0.5 + 1.4 * dot(n.xy, L.xy) + 0.25 * h0, 0.0, 1.0);
    a = u_sub > 0.5 ? 1.0 - lit : lit;
    // the hills rise away from the calm area
    float s = dot(p - u_calmP, u_dir) / u_span;
    pres = smoothstep(0.05, 0.6, s + 0.15 * h0);
    a *= pres;
    bendPx *= Hpx * 0.5;
  }

  // the text area stays clean paper
  float m = fx_calm(uv, vec2(u_calmX, u_calmY), 0.3 + 0.55 * u_calm) * u_calm;
  pres *= 1.0 - min(1.0, 1.8 * m);

  // main lines: displaced by the height field so they bend around the form
  vec2 d1 = vec2(cos(u_angR), sin(u_angR));
  float s1 = (dot(q, d1) + bendPx * h) / pitch;
  float g1 = length(d1 + bendPx * gh) / pitch;
  float w1 = mix(u_minWidth, u_maxWidth, a) * pres;
  float cov = hatch(s1, g1, w1);

  // cross-hatching in the deepest shadow, at its own angle, bent less. Only on paper: on dark paper
  // the ink is the light, and crossing lines chopped the highlight into dark dashes
  if (u_cross > 0.0 && u_sub > 0.5) {
    vec2 d2 = vec2(cos(u_angR + 1.05), sin(u_angR + 1.05));
    float s2 = (dot(q, d2) + 0.6 * bendPx * h) / pitch;
    float g2 = length(d2 + 0.6 * bendPx * gh) / pitch;
    float w2 = u_maxWidth * 0.75 * u_cross * smoothstep(0.62, 1.0, a) * pres;
    float c2 = hatch(s2, g2, w2);
    cov = 1.0 - (1.0 - cov) * (1.0 - c2);
  }

  // guilloche: a rosette of fine interlaced curves in a ring around the form
  if (u_guilloche > 0.0 && u_mode < 0.5) {
    vec2 rq = q - (c * Hpx + 0.5 * vec2(u_res.x, u_res.y) / u_dpr);
    float rho = length(rq), th = atan(rq.y, rq.x);
    float amp = 0.05 * Rpx, mm = 18.0, sp = max(pitch * 1.7, 0.045 * Rpx);
    float band = smoothstep(1.07, 1.14, rho / Rpx) * (1.0 - smoothstep(1.32, 1.45, rho / Rpx)) * (1.0 - min(1.0, 1.8 * m));
    float gA = sqrt(1.0 + pow(amp * mm * cos(mm * th) / max(rho, 1.0), 2.0)) / sp;
    float cA = hatch((rho + amp * sin(mm * th)) / sp, gA, 0.11 * band);
    float cB = hatch((rho + amp * sin(mm * th + 3.14159)) / sp, gA, 0.11 * band);
    float gl = 1.0 - (1.0 - cA) * (1.0 - cB);
    cov = 1.0 - (1.0 - cov) * (1.0 - gl * u_guilloche);
  }

  vec3 b = u_base * mix(vec3(1.0), u_T, cov);
  vec3 col = fx_srgb(u_sub > 0.5 ? b : 1.0 - b);
  fxColor = vec4(fx_dither(col), 1.0);
}
`;

const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const lin = c => color.rgb(c).map(v => (v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)));

function inkOf(P, prm) {
  const { bg } = P;
  const Lp = color.lab(bg)[0];
  const sub = color.lab(P.ink)[0] < Lp;
  let ink = prm.accent >= 0.5 ? P.accent : P.ink;
  const L = color.lab(ink)[0];
  if (sub && L > Lp - 0.12) ink = color.withLightness(ink, Math.max(0.2, Lp - 0.35));
  if (!sub && L < Lp + 0.12) ink = color.withLightness(ink, Math.min(0.95, Lp + 0.35));
  return { sub, ink };
}

// where things go, in centred height units (y up); shared by the shader and the CSS fallback
function layout(params, r, asp, seed) {
  // its own stream, so neighbouring seeds (and the other effects on the page) do not pick alike
  const pick = rng(`line-engraving:pick:${seed}`)();
  const mode = params.source >= 0 ? Math.round(params.source) : pick < 0.28 ? 0 : 1;
  const C = [(params.calmX - 0.5) * asp, 0.5 - params.calmY];
  // the sphere is big and sits across the frame from the calm area, running off the far edge
  const R = clamp(0.46 * params.size * (0.92 + 0.16 * r()), 0.2, 0.75);
  const sx = C[0] > 0.08 * asp ? -1 : C[0] < -0.08 * asp ? 1 : (r() < 0.5 ? -1 : 1);
  const fx = sx * (asp / 2 - R * (0.5 + 0.25 * r()));
  const fy = Math.abs(C[1]) > 0.12 ? -Math.sign(C[1]) * (0.5 - R * (0.55 + 0.25 * r())) : (r() - 0.5) * 0.3;
  const lightA = Math.atan2(C[1] - fy + 0.35, C[0] - fx) + (r() - 0.5) * 0.3;
  // the hills rise from the calm area toward its far corner
  const corners = [[-asp / 2, -0.5], [asp / 2, -0.5], [-asp / 2, 0.5], [asp / 2, 0.5]];
  const far = corners.reduce((a, b) => (Math.hypot(b[0] - C[0], b[1] - C[1]) > Math.hypot(a[0] - C[0], a[1] - C[1]) ? b : a));
  const span = Math.max(0.3, Math.hypot(far[0] - C[0], far[1] - C[1]));
  return { mode, C, R, fx, fy, lightA, far, span };
}

function uniforms({ palette, params, seed, rng: r, width, height }) {
  const k = inkOf(palette, params);
  const P = lin(palette.bg);
  const base = k.sub ? P : P.map(v => 1 - v);
  const T = lin(k.ink).map((v, i) => (k.sub ? clamp(v / Math.max(P[i], 1e-4), 0, 1) : clamp((1 - v) / Math.max(1 - P[i], 1e-4), 0, 1)));
  const L = layout(params, r, width && height ? width / height : 4 / 3, seed);
  return {
    u_base: base, u_sub: k.sub ? 1 : 0, u_T: T, u_mode: L.mode,
    u_form: [L.fx, L.fy, L.R], u_lightA: L.lightA, u_angR: (params.angle + 90) * Math.PI / 180, // the lines' normal
    u_calmP: L.C, u_dir: [(L.far[0] - L.C[0]) / L.span, (L.far[1] - L.C[1]) / L.span], u_span: L.span,
  };
}

// CSS fallback: an SVG of line screens whose width steps with the tone, laid out like the shader (the
// sphere across from the calm area, or the hills rising away from it)
const svgUrl = s => `url("data:image/svg+xml,${encodeURIComponent(s)}")`;
const f1 = v => +v.toFixed(1);
function fallback({ palette: P, params: prm, seed, rng: r, width, height }) {
  const W = Math.max(40, Math.round(width || 800)), H = Math.max(40, Math.round(height || 600));
  const { sub, ink } = inkOf(P, prm);
  const L = layout(prm, r, W / H, seed);
  const px = (x, y) => [f1(W / 2 + x * H), f1(H / 2 - y * H)];
  const pitch = Math.max(4, prm.pitch);
  const N = 6;
  let grad;
  if (L.mode === 0) {
    const [cx, cy] = px(L.fx, L.fy);
    const [hx, hy] = px(L.fx + Math.cos(L.lightA) * L.R * 0.45, L.fy + Math.sin(L.lightA) * L.R * 0.45);
    grad = (id, stops) => `<radialGradient id="${id}" gradientUnits="userSpaceOnUse" cx="${cx}" cy="${cy}" r="${f1(L.R * H)}" fx="${hx}" fy="${hy}">${stops}</radialGradient>`;
  } else {
    const [x1, y1] = px(L.C[0], L.C[1]);
    const [x2, y2] = px(L.far[0], L.far[1]);
    grad = (id, stops) => `<linearGradient id="${id}" gradientUnits="userSpaceOnUse" x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}">${stops}</linearGradient>`;
  }
  let defs = '', body = '';
  for (let i = 0; i < N; i++) {
    const t = (i + 0.5) / N;
    let a = L.mode === 0 ? (sub ? 0.1 + 0.85 * t : 0.85 - 0.6 * t) : Math.max(0, (t - 0.15) / 0.85) * (sub ? 0.9 : 0.75);
    if (a < 0.04) continue;
    const w = f1(Math.max(0.6, pitch * (prm.minWidth + (prm.maxWidth - prm.minWidth) * a) * 0.9));
    const s = i / N, e = (i + 1) / N;
    const stop = (o, v) => `<stop offset="${Math.min(1, Math.max(0, o)).toFixed(3)}" stop-color="${v ? '#fff' : '#000'}"/>`;
    defs += `<pattern id="p${i}" width="${pitch}" height="${pitch}" patternUnits="userSpaceOnUse" patternTransform="rotate(${-prm.angle})"><rect y="${f1((pitch - w) / 2)}" width="${pitch}" height="${w}" fill="${ink}"/></pattern>`;
    defs += grad(`g${i}`, stop(s - 0.002, 0) + stop(s, 1) + stop(e, 1) + stop(e + 0.002, 0));
    defs += `<mask id="m${i}"><rect width="${W}" height="${H}" fill="url(#g${i})"/></mask>`;
    body += `<rect width="${W}" height="${H}" fill="url(#p${i})" mask="url(#m${i})"/>`;
  }
  return `${svgUrl(`<svg xmlns="http://www.w3.org/2000/svg" width="${W}" height="${H}" viewBox="0 0 ${W} ${H}"><defs>${defs}</defs>${body}</svg>`)} center / 100% 100% no-repeat, ${P.bg}`;
}

// a still plate draws once; with drift above 0 it runs, slowly
function holdStill(c, read) {
  let user = false, cur = read();
  const sync = () => ((user || cur.drift <= 0) ? c.pause() : c.resume());
  sync();
  return {
    pause() { user = true; sync(); },
    resume() { user = false; sync(); },
    set(next) { cur = c.set(next); sync(); return cur; },
    setPalette: p => c.setPalette(p),
    redraw: () => c.redraw(),
    destroy: () => c.destroy(),
    get canvas() { return c.canvas; },
    get info() { return { ...c.info, still: user || cur.drift <= 0 }; },
  };
}

export default {
  id: 'line-engraving',
  name: 'Line engraving',
  family: 'dither',
  params,
  mount(el, { palette, params: given, seed }) {
    const c = shader(el, {
      frag,
      schema: params,
      params: given,
      palette,
      seed,
      uniforms,
      crisp: true,
      maxDpr: 3,
      fps: 30,
      still: 0,
      fallback,
    });
    return holdStill(c, () => resolveParams(params, given));
  },
};

effects/halftone-screen/effect.js:
// halftone-screen: a big soft form (a gradient hill, slow noise or a lit sphere) printed as a rotated
// screen of round dots whose area follows the tone, like a zoomed-in magazine print. One ink on paper,
// or two at their own screen angles. The seed picks the form unless `source` names one; the
// panel-filling ones come up most often.
import { shader, color, rng } from '../fx.js';

const params = {
  cell:      { default: 10,   min: 5,   max: 24,  step: 0.5 },  // screen cell, CSS px
  angle:     { default: 30,   min: 0,   max: 90,  step: 1 },    // screen angle, degrees
  source:    { default: -1,   min: -1,  max: 2,   step: 1 },    // -1 the seed picks, 0 sphere, 1 gradient hill, 2 slow noise
  secondInk: { default: 0,    min: 0,   max: 1,   step: 1 },    // 1 adds the accent on its own screen, 45 degrees on
  contrast:  { default: 1.4,  min: 0.6, max: 3,   step: 0.01 }, // empties the highlights, merges the shadows
  gooey:     { default: 0,    min: 0,   max: 1,   step: 0.01 }, // dots melt into their neighbours
  size:      { default: 1,    min: 0.5, max: 1.6, step: 0.01 }, // size of the form
  drift:     { default: 0.02, min: 0,   max: 0.2, step: 0.005 },// slow wandering of the light; 0 is still
  calm:      { default: 0.5,  min: 0,   max: 1,   step: 0.01 }, // empties the text area
  calmX:     { default: 0.25, min: 0,   max: 1,   step: 0.01 },
  calmY:     { default: 0.6,  min: 0,   max: 1,   step: 0.01 },
};

const frag = /* glsl */ `
vec2 rot(vec2 v, float a) { float c = cos(a), s = sin(a); return vec2(c * v.x - s * v.y, s * v.x + c * v.y); }
float smin(float a, float b, float k) { float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0); return mix(b, a, h) - k * h * (1.0 - h); }

vec2 formC() { float t = u_time * u_drift; return u_form.xy + 0.012 * vec2(sin(t * 3.0), cos(t * 2.3)); }

// ink amount 0..1 (share of the cell the dot covers) at p, centred height units, y up. kind 0 is the
// form or field, kind 1 the sphere's cast shadow. On dark paper the ink is the light.
float amount(vec2 p, float kind) {
  float t = u_time * u_drift;
  float a = 0.0;
  float calmK = 1.0, cK = 1.0;
  if (u_mode < 0.5) {
    vec2 c = formC();
    float R = u_form.z;
    float ph = u_lightA + 0.5 * sin(t * 5.0);
    vec3 L = normalize(vec3(cos(ph), sin(ph), 0.9));
    if (kind > 0.5) {
      vec2 sc = c + vec2(-L.x * 0.55 * R, -0.96 * R);
      vec2 e = (p - sc) / (R * vec2(1.25, 0.24));
      a = 0.55 * exp(-dot(e, e) * 1.3);
    } else {
      vec2 r = (p - c) / R;
      float l = length(r);
      if (l > 0.995) r *= 0.995 / l;          // cells across the rim take the tone just inside it
      vec3 n = vec3(r, sqrt(max(1.0 - dot(r, r), 0.0)));
      float lam = max(dot(n, L), 0.0);
      float spec = pow(max(dot(reflect(-L, n), vec3(0.0, 0.0, 1.0)), 0.0), 4.0);   // wide and soft
      // the lit body reaches about 0.85 and the highlight is wide and soft, so the lit side keeps fine
      // dots and only a small spot is bare paper (no bowling ball, no paper hole)
      float lit = 0.05 + 0.72 * lam + 0.18 * spec;
      float rim = pow(1.0 - n.z, 2.5);
      // on paper the limb darkens a little so the round edge reads on the lit side too
      a = u_sub > 0.5 ? 1.0 - lit + 0.25 * rim * lam : lit + 0.04 * rim * (1.0 - lam);
    }
    calmK = 0.5;                               // the form sits away from the text already
    cK = 0.5;                                  // and its tones are not pushed as hard
  } else if (u_mode < 1.5) {
    float s = dot(p - u_calmP, u_dir) / u_span;
    s += 0.18 * fx_noise(p * 1.3 + vec2(t * 2.0, 2.0)) + 0.06 * fx_noise(p * 3.1 - t);
    a = smoothstep(0.08, 1.0, s);
  } else {
    float s = dot(p - u_calmP, u_dir) / u_span;
    float n = fx_fbm(p * 1.25 + vec2(t * 2.0, -t * 1.4) + u_seed * 0.01);
    a = smoothstep(0.1, 0.75, n * 0.75 + s * 0.85 - 0.12);
  }
  vec2 uv = vec2(p.x * u_res.y / u_res.x + 0.5, 0.5 - p.y);
  float m = fx_calm(uv, vec2(u_calmX, u_calmY), 0.3 + 0.55 * u_calm) * u_calm * calmK;
  a *= 1.0 - min(1.0, 1.8 * m);
  // the deepest tone keeps paper gaps between the dots (on dark paper a wider margin, or it goes solid)
  return clamp((a - 0.42) * mix(1.0, u_contrast, cK) + 0.42, 0.0, 1.0) * u_cap;
}

// dot radius in cell units for an ink share: area-true up to touching dots, then closing the gaps
float dotR(float a) { return a <= 0.002 ? -1.0 : (a < 0.785 ? sqrt(a * 0.31831) : 0.5 + (a - 0.785) * 0.963); }
vec2 cellP(vec2 cell, float ang) { vec2 cq = rot((cell + 0.5) * u_cellPx, -ang); return (cq * u_dpr - 0.5 * u_res) / u_res.y; }

// signed distance (cell units) to the dot of one cell; the dot carries the tone of its centre
float dotD(vec2 g, vec2 cell, float ang, float second, float kind) {
  float a = amount(cellP(cell, ang), kind);
  // duotone: the accent plate carries the whole form, lighter; the ink plate only the shadows
  if (second > 0.5) a = min(0.7, 0.85 * a);
