  float k = u_gooey * 0.6;
  vec2 f = fract(g) - 0.5;
  vec2 sx = vec2(f.x < 0.0 ? -1.0 : 1.0, 0.0), sy = vec2(0.0, f.y < 0.0 ? -1.0 : 1.0);
