  HT_FOR(j, u_gooey > 0.0 ? 4.0 : 1.0, 4) {
    vec2 o = j == 0 ? vec2(0.0) : j == 1 ? sx : j == 2 ? sy : sx + sy;
    float dj = dotD(g, cell + o, ang, second, kind);
