        head: rgbArr(dark ? color.mix(sig, '#ffffff', 0.5) : sig),
        // lit cells: a tint of the signal colour
        cell: rgbArr(sig),
        halo: rgbArr(color.mix(P.bg, '#ffffff', 0.85)),
        dark, kind,
        lineK: dark ? 1.3 : 1,
