    const iMin = () => -Math.floor(w / 2 / prm.cell), iMax = () => Math.floor(w / 2 / prm.cell);
    const jMin = () => -Math.floor(h / 2 / prm.cell), jMax = () => Math.floor(h / 2 / prm.cell);

