      g.fillStyle = rgba(cols.line, 1);
      for (let i = iMin() - 1; i <= iMax() + 1; i++) g.fillRect(snap(gx(i)) - (lw >> 1), 0, lw, H);
      for (let j = jMin() - 1; j <= jMax() + 1; j++) g.fillRect(0, snap(gy(j)) - (lw >> 1), W, lw);
