        if (a.trail.length > 16) a.trail.shift();
        a.nodes++;
        const m = maskAt(gx(a.x), gy(a.y));
        if (m >= 0.3) lightUp(a, a.dx ? a.x - a.dx : px0, a.dy ? a.y - a.dy : py0, a.x, a.y, now - move / Math.max(1e-6, prm.speed / prm.cell));
        // where the grid fades the pulse ends, so it never runs on unseen
        if (a.nodes >= a.life || m < 0.3) {
          a.state = 'fade'; a.flash = m < 0.3 ? 0 : 1; a.fx = a.x; a.fy = a.y;
          break;
        }
        if (rand() < prm.turnChance) {
          const s = rand() < 0.5 ? 1 : -1;
          [a.dx, a.dy] = a.dx ? [0, s] : [s, 0];
        }
      }
    }
    function count() {
      const n = Math.round(prm.pulses);
      if (n <= 0) return 0;
      return Math.max(n, Math.min(Math.round(n * 2.5), Math.round(n * (w * h) / (480 * 300))));
    }
    function setCount() {
      const n = count();
      while (agents.length > n) agents.pop();
      while (agents.length < n) {
        // start mid-flight: each pulse already some way along its run, its trace already behind it
        const a = {};
        for (let tries = 0; tries < 4; tries++) {
          spawn(a);
          const T = (0.25 + 0.6 * rand()) * a.life * prm.cell / prm.speed;
          for (let s = 0; s < T && a.state === 'run'; s += 1 / 30) step(a, 1 / 30, clock - T + s);
          if (a.state === 'run' && maskAt(gx(a.x), gy(a.y)) > 0.35) break;
        }
        agents.push(a);
      }
    }

    const px = x => snap(gx(x)) + (lineW() % 2 ? 0.5 : 0);
    const py = y => snap(gy(y)) + (lineW() % 2 ? 0.5 : 0);

    function drawTraces() {
      const k = prm.trace;
      if (k <= 0) { traces.clear(); return; }
      const c = prm.cell * dpr, lw = lineW();
      for (const [key, tr] of traces) {
        const age = (clock - tr.born) / TRACE_LIFE;
        if (age >= 1) { traces.delete(key); continue; }
        const f = Math.pow(1 - Math.max(0, age), 2);
        if (tr.n) {
          const m = maskAt(gx(tr.i), gy(tr.j));
          const X = px(tr.i), Y = py(tr.j), s = (1.5 + 1.2 * k) * dpr;
          ctx.fillStyle = rgba(cols.head, f * m * (0.55 + 0.45 * k));
          ctx.fillRect(Math.round(X - s), Math.round(Y - s), Math.round(s * 2), Math.round(s * 2));
        } else {
          const m = maskAt(gx(tr.i + 0.5), gy(tr.j + 0.5));
          const X = snap(gx(tr.i)) + lw, Y = snap(gy(tr.j)) + lw;
          ctx.fillStyle = rgba(cols.cell, f * m * k * (cols.dark ? 0.2 : 0.15));
          ctx.fillRect(X, Y, Math.round(c) - lw, Math.round(c) - lw);
        }
      }
    }

    function drawPulse(a) {
      const lw = lineW();
      const tailC = prm.tail;
      if (a.flash > 0) {
        const m = maskAt(gx(a.fx), gy(a.fy));
        const s = (10 + 8 * prm.glow) * dpr;
        ctx.globalAlpha = a.flash * a.flash * m * (0.35 + 0.65 * prm.glow);
        if (haloS) ctx.drawImage(haloS, px(a.fx) - s * 1.6, py(a.fy) - s * 1.6, s * 3.2, s * 3.2);
        ctx.drawImage(glowS, px(a.fx) - s, py(a.fy) - s, s * 2, s * 2);
        ctx.globalAlpha = 1;
      }
      if (a.state === 'wait' || a.tail <= 0) return;
      // walk back from the head along the trail for the tail length
      const pts = [[a.x, a.y]];
      let left = a.tail / prm.cell;
      for (let k = a.trail.length - 1; k >= 0 && left > 0; k--) {
        const [x0, y0] = pts[pts.length - 1];
        const [x1, y1] = a.trail[k];
        const d = Math.abs(x1 - x0) + Math.abs(y1 - y0);
        if (d < 1e-6) continue;
        if (d >= left) { pts.push([x0 + (x1 - x0) * left / d, y0 + (y1 - y0) * left / d]); left = 0; break; }
        pts.push([x1, y1]);
        left -= d;
      }
      const total = a.tail / prm.cell - left;
      if (total <= 1e-4) return;
      const strong = cols.dark ? 1 : 1.25;
      // on light grounds: a light halo under the whole tail first
      if (haloS && prm.glow > 0) {
        ctx.lineCap = 'round';
        ctx.strokeStyle = rgba(cols.halo, 0.55 * prm.glow * maskAt(gx(a.x), gy(a.y)));
        ctx.lineWidth = 7 * dpr;
        ctx.beginPath();
        ctx.moveTo(px(pts[0][0]), py(pts[0][1]));
        for (let k = 1; k < pts.length; k++) ctx.lineTo(px(pts[k][0]), py(pts[k][1]));
        ctx.stroke();
      }
      ctx.lineCap = 'butt';
      let s0 = 0;
      for (let k = 0; k < pts.length - 1; k++) {
        const [x0, y0] = pts[k], [x1, y1] = pts[k + 1];
        const d = Math.abs(x1 - x0) + Math.abs(y1 - y0);
        const s1 = s0 + d;
        const a0 = Math.min(1, strong * Math.pow(1 - s0 / tailC, 1.4) * maskAt(gx(x0), gy(y0)));
        const a1 = Math.min(1, strong * Math.pow(Math.max(0, 1 - s1 / tailC), 1.4) * maskAt(gx(x1), gy(y1)));
        const X0 = px(x0), Y0 = py(y0), X1 = px(x1), Y1 = py(y1);
        const gr = ctx.createLinearGradient(X0, Y0, X1, Y1);
        gr.addColorStop(0, rgba(cols.acc, a0));
        gr.addColorStop(1, rgba(cols.acc, a1));
        ctx.beginPath();
        ctx.moveTo(X0, Y0);
        ctx.lineTo(X1, Y1);
        // a soft wide stroke under the crisp one, so the signal glows a little along its length
        ctx.strokeStyle = gr;
        ctx.globalAlpha = (cols.dark ? 0.22 : 0.16) * prm.glow;
        ctx.lineWidth = lw * 5;
        ctx.stroke();
        ctx.globalAlpha = 1;
        ctx.lineWidth = lw * (cols.dark ? 1 : 1.5);
        ctx.stroke();
        s0 = s1;
      }
      if (a.state === 'run') {
        const m = maskAt(gx(a.x), gy(a.y));
        const grow = Math.min(1, a.tail / (prm.tail * prm.cell * 0.35));
        const X = px(a.x), Y = py(a.y);
        if (prm.glow > 0) {
          const s = (10 + 10 * prm.glow) * dpr;
          ctx.globalAlpha = m * grow * prm.glow;
          if (haloS) ctx.drawImage(haloS, X - s * 1.4, Y - s * 1.4, s * 2.8, s * 2.8);
          ctx.drawImage(glowS, X - s, Y - s, s * 2, s * 2);
          ctx.globalAlpha = 1;
        }
        ctx.fillStyle = rgba(cols.head, m * grow);
        ctx.beginPath();
        ctx.arc(X, Y, 1.7 * dpr, 0, Math.PI * 2);
        ctx.fill();
      }
    }

    function draw(t, dt) {
      if (dt > 0) { clock += dt; for (const a of agents) step(a, dt, clock); }
      ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.clearRect(0, 0, pulseC.width, pulseC.height);
      drawTraces();
      for (const a of agents) drawPulse(a);
      if (!shown) { shown = true; gridC.style.opacity = '1'; pulseC.style.opacity = '1'; }
    }

    function fit() {
      dpr = Math.min(window.devicePixelRatio || 1, 2);
      w = Math.max(1, el.clientWidth); h = Math.max(1, el.clientHeight);
      const W = Math.round(w * dpr), H = Math.round(h * dpr);
      for (const c of [gridC, pulseC]) if (c.width !== W || c.height !== H) { c.width = W; c.height = H; }
      drawGrid();
    }

    colours();
    fit();
    setCount();
    const lc = lifecycle(el, { draw, still: 3, fps: 60 });
    const ro = new ResizeObserver(() => { fit(); setCount(); lc.redraw(); });
    ro.observe(el);

    return {
      pause: () => lc.pause(),
      resume: () => lc.resume(),
      redraw: () => lc.redraw(),
      set(next) {
        prm = resolveParams(params, { ...prm, ...next });
        drawGrid();
        setCount();
        lc.redraw();
        return prm;
      },
      setPalette(p) { P = normalizePalette(p); if (ownBg) el.style.backgroundColor = P.bg; colours(); drawGrid(); lc.redraw(); },
      destroy() { lc.destroy(); ro.disconnect(); gridC.remove(); pulseC.remove(); if (ownBg) el.style.backgroundColor = P.bg; },
      get canvas() { return pulseC; },
      get info() { return { webgl: 0, canvas: '2d', fallback: null, scale: 1, dpr, size: [pulseC.width, pulseC.height], running: lc.running, pulses: agents.length, active: agents.filter(a => a.state === 'run').length, traces: traces.size }; },
    };
  },
};

effects/grain-gradient/effect.js:
// grain-gradient: a soft tonal ramp and three blobs of the page colours, mixed in OKLab, under fine
// film grain and a grainy dissolve between the colours (the sand-print look).
import { shader, color, fallbackCSS } from '../fx.js';

const params = {
  speed:       { default: 0.5,  min: 0, max: 2, step: 0.01 },  // how fast the shapes drift
  softness:    { default: 0.45, min: 0, max: 1, step: 0.01 },  // size and edge softness of the blobs
  warp:        { default: 0.6,  min: 0, max: 1, step: 0.01 },  // slow organic bending of the shapes
  grain:       { default: 0.6,  min: 0, max: 1, step: 0.01 },  // film grain strength
  scatter:     { default: 0.5,  min: 0, max: 1, step: 0.01 },  // grainy dissolve between colours
  tint:        { default: 0.5,  min: 0, max: 1, step: 0.01 },  // how much accent enters
  contrast:    { default: 0.55, min: 0, max: 1, step: 0.01 },  // how far the colours move from the background
  calm:        { default: 0.5,  min: 0, max: 1, step: 0.01 },  // flatten the area where text sits
  calmX:       { default: 0.25, min: 0, max: 1, step: 0.01 },  // calm area centre, 0 left .. 1 right
  calmY:       { default: 0.7,  min: 0, max: 1, step: 0.01 },  // calm area centre, 0 top .. 1 bottom
  grainMotion: { default: 1,    min: 0, max: 1, step: 1 },     // 1 grain moves like film, 0 still grain
};

const frag = /* glsl */ `
float blobW(vec2 p, vec4 b, float t) {
  vec2 c = b.xy + 0.13 * vec2(sin(t + b.w), cos(t * 0.83 + b.w * 1.7));
  float r = length(p - c) / (b.z * (0.6 + 0.7 * u_softness));
  // flat core, then an edge from firm (exponent 6) to soft (exponent 2)
  return exp(-pow(r, 6.0 - 4.0 * u_softness) * 1.2);
}

// grainy dissolve in weight space: a blend weight is pushed up or down by this grain's own random
// value, most in the middle of a transition and not at all in flat areas, so colours meet in a fine
// stipple (the printed, sprayed edge) instead of a smooth fade
float dissolve(float w, float z) {
  return clamp(w + z * u_dissolve * 4.0 * w * (1.0 - w), 0.0, 1.0);
}

void main() {
  vec2 uv = fx_uv();
  vec2 p = fx_p();
  float t = u_time * u_speed * 0.12 + u_seed * 0.37;

  // grains are one CSS pixel (whole device pixels), so the texture looks the same at any DPR
  float gc = max(1.0, floor(u_dpr + 0.5));
  vec2 gp = floor(gl_FragCoord.xy / gc);
  float z = fx_hash(gp + vec2(17.0, 3.0)) + fx_hash(gp + vec2(511.0, 97.0)) - 1.0;

  // slow organic bend of the whole field
  vec2 q = p * 1.1 + u_seed * 0.0123;
  vec2 w = vec2(fx_noise(q + vec2(0.0, t * 0.9)), fx_noise(q * 1.1 + vec2(5.2, 1.3) - vec2(t * 0.7, 0.0)));
  p += w * 0.5 * u_warp;

  // tonal ramp: near colour at the calm side, far colour across the frame
  float s = dot(p - u_calmP, u_dir) / u_span;
  s += 0.22 * fx_noise(p * 1.6 + vec2(t * 0.5, 3.1));
  vec3 col = mix(u_kNear, u_kFar, dissolve(smoothstep(-0.1, 0.75, s), z));

  // blobs, painted in OKLab; each blob takes a different slice of the grain's randomness
  col = mix(col, u_k1, dissolve(blobW(p, u_b1, t), fract(z * 7.31 + 0.5) * 2.0 - 1.0));
  col = mix(col, u_k2, dissolve(blobW(p, u_b2, t * 0.9), fract(z * 3.17 + 0.25) * 2.0 - 1.0));
  col = mix(col, u_k0, dissolve(blobW(p, u_b0, t * 1.1), z));

  // calm area for text
  float m = fx_calm(uv, vec2(u_calmX, u_calmY), 0.35 + 0.4 * u_calm) * u_calm;
  col = mix(col, u_kNear, m);

  // film grain on lightness (24 frames a second when it moves)
  float frame = u_grainMotion > 0.5 ? floor(u_time * 24.0) : 0.0;
  // softer near pure white and black, where clipped grain reads as dirt
  float amp = u_grainAmp * u_grain * (1.0 - 0.6 * smoothstep(0.86, 1.0, col.x)) * (1.0 - 0.5 * smoothstep(0.22, 0.0, col.x));
  col.x += fx_grain(gp, frame) * amp;

  fxColor = vec4(fx_dither(fx_rgb(col)), 1.0);
}
`;

// every colour is a mix, shade or tint of a palette colour; no hue is invented
function tones(P, prm, kind) {
  const { bg, surface, ink, accent } = P;
  const c = prm.contrast, tn = prm.tint;
  const neutral = color.chroma(bg) < 0.035;
  // an accent that will not turn muddy when mixed with the background
  const acc = neutral || color.hueDistance(bg, accent) < 55 ? accent : color.withLightness(color.saturate(bg, 1.1), color.lab(accent)[0]);
  const [Lb] = color.lab(bg), [Li] = color.lab(ink);
  const away = Li > Lb ? -1 : 1; // the lightness direction that adds contrast to the ink
  const near = color.saturate(color.lighten(bg, away * (0.012 + 0.03 * c)), 1.1);
  if (kind === 'dark') {
    return {
      grain: 0.04,
      near,
      far: color.mix(bg, surface, 0.7 + 0.3 * c),
      k: [
        color.mix(bg, acc, 0.28 + 0.45 * tn),                       // glow
        color.mix(bg, acc, 0.1 + 0.2 * tn),                         // soft glow
        color.lighten(color.mix(surface, acc, 0.08 + 0.1 * tn), 0.015 + 0.04 * c), // tinted haze
      ],
    };
  }
  if (kind === 'colour') {
    return {
      grain: 0.05,
      near,
      far: color.lighten(bg, -away * (0.04 + 0.08 * c)),
      k: [
        color.mix(bg, acc, 0.25 + 0.45 * tn),                       // accent light
        color.mix(bg, ink, 0.06 + 0.1 * c),                         // pale
        color.saturate(color.lighten(bg, away * (0.035 + 0.06 * c)), 1.08), // deep field
      ],
    };
  }
  // light: a tone between ink and accent gives rich, clean shades instead of grey ones; mixing toward
  // a near-neutral ink loses chroma, so the shades get it back (the printed-pigment look, not grey)
  const tone = color.mix(ink, acc, 0.45 + 0.55 * tn);
  return {
    grain: 0.06,
    near,
    far: color.saturate(color.mix(bg, tone, 0.08 + 0.14 * c), 1.15),
    k: [
      color.saturate(color.mix(bg, acc, 0.22 + 0.5 * tn), 1.25),    // accent
      color.saturate(color.lighten(color.mix(bg, acc, 0.1), 0.03), 1.3), // pale light
      color.saturate(color.mix(bg, tone, 0.3 + 0.35 * c), 1.4),     // deep
    ],
  };
}

function uniforms({ palette, params, rng, kind, width, height }) {
  const r = rng;
  const set = tones(palette, params, kind);
  const asp = width && height ? width / height : 4 / 3;
  // geometry in centred height units, y up (the space of fx_p())
  const calm = [(params.calmX - 0.5) * asp, 0.5 - params.calmY];
  const corners = [[-asp / 2, -0.5], [asp / 2, -0.5], [-asp / 2, 0.5], [asp / 2, 0.5]];
  const far = corners.reduce((a, b) => (Math.hypot(b[0] - calm[0], b[1] - calm[1]) > Math.hypot(a[0] - calm[0], a[1] - calm[1]) ? b : a));
  const span = Math.max(0.3, Math.hypot(far[0] - calm[0], far[1] - calm[1]));
  const dir = [(far[0] - calm[0]) / span, (far[1] - calm[1]) / span];
  const perp = [-dir[1], dir[0]];
  // a point along the calm-to-far axis, kept inside the frame
  const at = (along, side) => [
    Math.max(-asp / 2 + 0.12, Math.min(asp / 2 - 0.12, calm[0] + dir[0] * span * along + perp[0] * side)),
    Math.max(-0.38, Math.min(0.38, calm[1] + dir[1] * span * along + perp[1] * side)),
  ];
  const side = r() < 0.5 ? -1 : 1;
  const b0 = at(0.7 + 0.2 * r(), side * (0.05 + 0.2 * r()));       // accent, across from the calm area
  const b1 = at(0.3 + 0.2 * r(), -side * (0.2 + 0.25 * r()));      // pale light, near the middle
  const b2 = at(0.6 + 0.3 * r(), -side * (0.15 + 0.3 * r()));      // deep, beside the accent
  const u = {
    u_kNear: color.labVec(set.near),
    u_kFar: color.labVec(set.far),
    u_grainAmp: set.grain,
    // scatter 0..1 -> dissolve strength; 0.5 gives a visible stipple only where colours meet
    u_dissolve: 0.36 * params.scatter,
    u_calmP: calm,
    u_dir: dir,
    u_span: span,
    u_b0: [...b0, 0.38 + 0.12 * r(), r() * 6.283],
    u_b1: [...b1, 0.36 + 0.12 * r(), r() * 6.283],
    u_b2: [...b2, 0.3 + 0.12 * r(), r() * 6.283],
  };
  set.k.forEach((k, i) => { u['u_k' + i] = color.labVec(k); });
  return u;
}

export default {
  id: 'grain-gradient',
  name: 'Grain gradient',
  family: 'grain',
  params,
  mount(el, { palette, params: given, seed }) {
    return shader(el, {
      frag,
      schema: params,
      params: given,
      palette,
      seed,
      uniforms,
      still: 4,
      fallback: ({ palette: P, params: prm, kind }) => {
        const k = tones(P, prm, kind).k;
        return fallbackCSS({ ...P, accent: k[0] }, { at: `${(1 - prm.calmX) * 100}% ${(1 - prm.calmY) * 100}%`, tint: 1 });
      },
    });
  },
};

effects/gradient-mesh/effect.js:
// gradient-mesh: a gradient mesh. Twelve colour points (a 4 x 3 grid, jittered and turned) in six
// tones of the page palette blend with Gaussian weights in OKLab into separate colour islands; a slow
// warp folds the plane and the fold is lit, so the folds read. With `lines` set, the warped grid that
// shapes it is drawn over it in thin lines with small points at the joins, like a mesh in a design
// tool, bunching where the surface folds. By default there is no grid.
import { shader, color } from '../fx.js';

const params = {
  speed:    { default: 0.06, min: 0,   max: 0.4, step: 0.01 }, // drift; 0.06 gives cycles of about 30 s
  lines:    { default: 0,    min: 0,   max: 16,  step: 1 },    // grid lines across the height; 0 (the default) for none, 6 to 10 for a design-tool mesh
  warp:     { default: 0.65, min: 0,   max: 1,   step: 0.01 }, // how deeply the plane folds
  relief:   { default: 0.5,  min: 0,   max: 1,   step: 0.01 }, // light and shade on the folds
  softness: { default: 0.55, min: 0,   max: 1,   step: 0.01 }, // 0 distinct islands .. 1 long blends
  joins:    { default: 1,    min: 0,   max: 1,   step: 1 },    // small points where the grid lines meet
  angle:    { default: -12,  min: -90, max: 90,  step: 1 },    // turns the mesh, degrees
  tint:     { default: 0.6,  min: 0,   max: 1,   step: 0.01 }, // how strong the accent islands are
  calm:     { default: 0.4,  min: 0,   max: 1,   step: 0.01 }, // quieter area of the ground where text sits
  calmX:    { default: 0.25, min: 0,   max: 1,   step: 0.01 },
  calmY:    { default: 0.7,  min: 0,   max: 1,   step: 0.01 },
};

const N = 12;
const ADD = Array.from({ length: N }, (_, i) => `  MESH_ADD(u_q${i}, u_k${i}, ${i}.0)`).join('\n');

const frag = /* glsl */ `
// the warp in two octaves; its slopes are taken from the broad octave only (half the cost)
vec2 warpLo(vec2 q, float t) {
  return vec2(fx_noise(q * 0.85 + vec2(0.0, t * 0.13)), fx_noise(q * 0.85 + vec2(5.2, 1.3) - vec2(t * 0.11, 0.0)));
}
vec2 warpHi(vec2 q, float t) {
  return 0.45 * vec2(fx_noise(q * 1.9 + vec2(3.7, -t * 0.17)), fx_noise(q * 1.9 + vec2(-2.1 + t * 0.15, 6.4)));
}
#define MESH_ADD(Q, K, I) { vec2 c_ = Q.xy + Q.w * vec2(sin(t * (0.83 + 0.07 * I) + Q.z), sin(t * (0.61 + 0.09 * I) + Q.z * 1.7 + 1.3)); vec2 e_ = pw - c_; float w_ = exp(-dot(e_, e_) * is2); acc += w_ * K; ws += w_; }

void main() {
  vec2 uv = fx_uv();
  vec2 p = fx_p();
  float t = u_time * u_speed * 3.4 + u_seed * 0.0731;
  vec2 so = vec2(u_seed * 0.0131, u_seed * 0.0217);
  float px = 1.0 / u_res.y;                      // one canvas pixel in height units

  // the fold: a slow warp of the plane, and its slopes (for the light and for even line widths)
  float e = 0.02;
  float k = u_warp * 0.42;
  vec2 wl = warpLo(p + so, t);
  vec2 w = wl + warpHi(p + so, t);
  vec2 wx = (warpLo(p + so + vec2(e, 0.0), t) - wl) / e;
  vec2 wy = (warpLo(p + so + vec2(0.0, e), t) - wl) / e;
  vec2 pw = p + w * k;

  // Gaussian weights: smooth islands, no plateaus or seams
  float sg = u_sigma * (0.6 + 0.8 * u_softness);
  float is2 = 1.0 / (2.0 * sg * sg);
  vec3 acc = vec3(0.0);
  float ws = 1e-6;
${ADD}
  vec3 col = acc / ws;

  // light on the folds: the warp's slope along a light direction
  float slope = dot(wx * 0.6 + wy * 0.8, vec2(-0.8, 0.6));
  float rl = clamp(slope * u_relief * 1.4, -1.0, 1.0);
  col = mix(col, u_hi, max(rl, 0.0) * 0.4);
  col = mix(col, u_lo, max(-rl, 0.0) * 0.3);

  // the calm area for text: toward the ground colour, keeping a trace of the mesh
  // (wide, since text runs sideways)
  vec2 cd = (uv - vec2(u_calmX, u_calmY)) * vec2(u_res.x / u_res.y * 0.55, 1.0);
  float cr = 0.24 + 0.36 * u_calm;
  float m = (1.0 - smoothstep(cr * 0.4, cr, length(cd))) * min(1.0, u_calm * 2.2);
  col = mix(col, u_ground, m * 0.9);

  // the mesh: lines of the warped, turned grid, a constant width in pixels wherever the grid stretches
  if (u_lines > 0.5) {
    vec2 g = vec2(dot(pw, u_rot), dot(pw, vec2(-u_rot.y, u_rot.x))) * u_lines + so * 3.0;
    // gradients of the two grid coordinates (per height unit)
    mat2 J = mat2(1.0 + k * wx.x, k * wx.y, k * wy.x, 1.0 + k * wy.y);   // columns: d(pw)/dx, d(pw)/dy
    vec2 gu = vec2(dot(J[0], u_rot), dot(J[1], u_rot)) * u_lines;
    vec2 gv = vec2(dot(J[0], vec2(-u_rot.y, u_rot.x)), dot(J[1], vec2(-u_rot.y, u_rot.x))) * u_lines;
    vec2 f = abs(fract(g + 0.5) - 0.5);
    vec2 dpx = f / vec2(length(gu), length(gv)) / px;               // distance to the nearest line, px
    float lw = 0.55 * u_dpr;
    float line = max(1.0 - smoothstep(lw - 0.5, lw + 0.7, dpx.x), 1.0 - smoothstep(lw - 0.5, lw + 0.7, dpx.y));
    float rj = 1.9 * u_dpr;
    float join = u_joins * (1.0 - smoothstep(rj - 0.7, rj + 0.7, length(dpx)));
    float show = 1.0 - m;
    col = mix(col, u_line, line * u_lineA * show);
    col = mix(col, u_line, join * min(1.0, u_lineA * 3.2) * show);
  }
  fxColor = vec4(fx_dither(fx_rgb(col)), 1.0);
}
`;

const L = c => color.lab(c)[0];
const at = (c, l) => color.withLightness(c, Math.min(0.98, Math.max(0.04, l)));
const sat = (c, k) => color.saturate(c, k);

// the tones of the mesh: [ground, highlight, accent, accent light, deep, middle], the fold light and
// shade, and the line colour. Every one a mix, tint or shade of the page colours; an accent far in hue
// from a coloured ground is kept out of the blends (they would pass through grey).
function tones(P, prm, kind) {
  const { bg, surface, ink, muted, accent } = P;
  const tn = prm.tint;
  const Lb = L(bg);
  const neutral = color.chroma(bg) < 0.035;
  const far = !neutral && color.chroma(accent) > 0.035 && color.hueDistance(bg, accent) > 55;
  if (kind === 'dark') {
    const acc = far ? at(sat(bg, 1.8), 0.6) : accent;
    const La = Math.max(0.55, L(acc));
    const k = [
      color.mix(bg, surface, 0.4),                                   // ground
      sat(color.mix(acc, ink, 0.55), 0.8),                           // ice, the highlight
      sat(at(acc, La - 0.04 * (1 - tn)), 1.05),                      // accent
      sat(at(color.mix(acc, muted, 0.3), Lb + 0.3), 0.9),            // slate accent
      sat(at(acc, Lb + 0.07), 1.2),                                  // deep accent
      sat(at(color.mix(bg, acc, 0.5), Lb + 0.18), 1.0),              // middle
    ];
    return { k, hi: color.mix(acc, ink, 0.75), lo: at(bg, Math.max(0.02, Lb - 0.03)), ground: k[0], line: color.mix(ink, acc, 0.25), lineA: 0.2 };
  }
  if (kind === 'colour') {
    const light = L(ink) > Lb ? ink : sat(color.lighten(bg, Math.min(0.2, 0.98 - Lb)), 0.5);
    const acc = far ? color.mix(bg, light, 0.3) : accent;
    const k = [
      bg,                                                            // ground
      color.mix(bg, light, 0.72),                                    // pale highlight
      sat(color.mix(bg, acc, 0.45 + 0.35 * tn), 1.05),               // accent or a light step
      sat(color.lighten(bg, 0.07), 1.1),                             // bright ground
      sat(color.lighten(bg, -0.16), 1.0),                            // deep
      color.mix(bg, light, 0.35),                                    // middle
    ];
    return { k, hi: color.mix(bg, light, 0.85), lo: color.lighten(bg, -0.22), ground: bg, line: light, lineA: 0.24 };
  }
  const acc = far ? at(sat(bg, 1.4), Lb - 0.25) : accent;
  const La = Math.min(Lb - 0.25, Math.max(0.42, L(acc)));
  const k = [
    sat(color.lighten(bg, 0.02), 1.05),                              // ground
    sat(at(bg, Math.min(0.985, Lb + 0.085)), 0.6),                   // highlight, near white
    sat(at(acc, La + 0.05 * (1 - tn)), 1.05),                        // accent
    sat(color.mix(bg, acc, 0.42), 1.25),                             // accent light
    sat(at(acc, La - 0.12), 1.0),                                    // deep accent (a shade, not ink: no mud)
    sat(color.lighten(bg, -0.075), 1.7),                             // a deeper step of the ground
  ];
  return { k, hi: at(bg, Math.min(0.99, Lb + 0.1)), lo: sat(at(acc, La - 0.16), 0.9), ground: k[0], line: color.mix(ink, acc, 0.3), lineA: 0.16 };
}

// the tone of each grid point: the ground near the calm area, then the others dealt so that no two
// neighbours share a tone
const DEAL = [1, 2, 5, 3, 4, 2, 1, 5, 3, 2, 4, 1];
function uniforms({ palette, params, rng, kind, width, height }) {
  const r = rng;
  const T = tones(palette, params, kind);
  const asp = width && height ? width / height : 4 / 3;
  const a = (params.angle * Math.PI) / 180;
  const C = 4, R = 3, sx = (asp * 1.2) / C, sy = 1.2 / R;
  const pts = [];
  for (let j = 0; j < R; j++) for (let i = 0; i < C; i++) {
    let x = ((i + 0.5) / C - 0.5) * asp * 1.2 + (r() - 0.5) * sx * 0.5;
    let y = ((j + 0.5) / R - 0.5) * 1.2 + (r() - 0.5) * sy * 0.5;
    [x, y] = [x * Math.cos(a) - y * Math.sin(a), x * Math.sin(a) + y * Math.cos(a)];
    pts.push([x, y]);
  }
  const calm = [(params.calmX - 0.5) * asp, 0.5 - params.calmY];
  const dist = s => Math.hypot(s[0] - calm[0], s[1] - calm[1]);
  const off = Math.floor(r() * DEAL.length);
  const tone = pts.map((s, n) => DEAL[(n + off) % DEAL.length]);
  // the point nearest the calm area holds the ground, and so does a close neighbour of it
  const near = pts.map((s, n) => n).sort((m, n) => dist(pts[m]) - dist(pts[n]));
  tone[near[0]] = 0;
  if (dist(pts[near[1]]) < 0.35) tone[near[1]] = 0;
  // the grid is turned a little off the mesh angle, so its lines never run square to the frame
  const ga = a * 0.5 + (r() - 0.5) * 0.3;
  const u = {
    u_sigma: Math.min(sx, sy) * 0.4,
    u_rot: [Math.cos(ga), Math.sin(ga)],
    u_hi: color.labVec(T.hi), u_lo: color.labVec(T.lo), u_ground: color.labVec(T.ground),
    u_line: color.labVec(T.line), u_lineA: T.lineA,
  };
  pts.forEach((s, n) => {
    u['u_q' + n] = [s[0], s[1], r() * 6.283, 0.05 + 0.05 * r()];
    u['u_k' + n] = color.labVec(T.k[tone[n]]);
  });
  return u;
}

export default {
  id: 'gradient-mesh',
  name: 'Gradient mesh',
  family: 'mesh',
  params,
  mount(el, { palette, params: given, seed }) {
    return shader(el, {
      frag,
      schema: params,
      params: given,
      palette,
      seed,
      uniforms,
      maxDpr: 1.25,
      still: 6,
      fallback: ({ palette: P, params: prm, kind }) => {
        const T = tones(P, prm, kind);
        const k = T.k;
        const cx = Math.round(prm.calmX * 100), cy = Math.round(prm.calmY * 100);
        const ln = color.mix(k[0], T.line, T.lineA);
        const cell = prm.lines > 0 ? Math.round(400 / prm.lines) : 0;
        const grid = cell ? `repeating-linear-gradient(0deg, ${ln} 0 1px, transparent 1px ${cell}px), repeating-linear-gradient(90deg, ${ln} 0 1px, transparent 1px ${cell}px), ` : '';
        // a still patchwork of the mesh tones under a straight grid, the ground where the calm area is
        return `${grid}radial-gradient(38% 50% at ${cx}% ${cy}%, ${k[0]}, transparent 75%), radial-gradient(40% 55% at ${100 - cx}% ${100 - cy}%, ${k[2]}, transparent 72%), radial-gradient(36% 48% at ${(cx + 50) % 100}% ${cy}%, ${k[1]}, transparent 72%), radial-gradient(42% 50% at ${100 - cx}% ${cy}%, ${k[4]}, transparent 72%), radial-gradient(40% 52% at ${cx}% ${100 - cy}%, ${k[3]}, transparent 72%), ${k[5]}`;
      },
    });
  },
};

effects/god-rays/effect.js:
// god-rays: shafts of light fan down through haze from a source at or above the top edge. The rays
// are uneven (noise along the angle, so they widen with distance) and come in bundles with dark gaps,
// fade with distance, drift slowly without turning, and a few soft out-of-focus motes float in the
// light. The light is a little warmer near its source. On light pages the room stays at the page's
// lightness and the gaps between the shafts fall into a soft shade. Text sits in a calm area.
import { shader, color } from '../fx.js';

const params = {
  originX:   { default: 0.3,  min: -0.2, max: 1.2, step: 0.01 },  // light source, 0 left .. 1 right
  originY:   { default: -0.2, min: -0.8, max: 0.2, step: 0.01 },  // source height; below 0 is above the frame
  tilt:      { default: 22,   min: -60,  max: 60,  step: 1 },     // fan direction, degrees from straight down (+ right)
  spread:    { default: 60,   min: 10,   max: 140, step: 1 },     // fan width in degrees
  density:   { default: 0.35, min: 0,    max: 1,   step: 0.01 },  // how many rays
  intensity: { default: 0.7,  min: 0,    max: 1.5, step: 0.01 },  // brightness of the light
  falloff:   { default: 1.2,  min: 0,    max: 4,   step: 0.01 },  // how fast the light fades with distance
  speed:     { default: 0.04, min: 0,    max: 0.4, step: 0.005 }, // how fast the rays change
  dust:      { default: 0.3,  min: 0,    max: 1,   step: 0.01 },  // soft motes floating in the light
  tint:      { default: 0.5,  min: 0,    max: 1,   step: 0.01 },  // how much the accent colours the light
  calm:      { default: 0.5,  min: 0,    max: 1,   step: 0.01 },  // dim the light where text sits
  calmX:     { default: 0.22, min: 0,    max: 1,   step: 0.01 },
  calmY:     { default: 0.72, min: 0,    max: 1,   step: 0.01 },
};

const frag = /* glsl */ `
// one layer of out-of-focus motes: at most one soft disc per cell, sizes from small to large (the large
// ones dimmer and blurrier), drifting down; each disc stays inside its cell
float motes(vec2 P, float cells, vec2 drift, float amount, float off) {
  vec2 q = P * cells + drift;
  vec2 id = floor(q), f = fract(q);
  float h = fx_hash(id + off);
  float h2 = fract(h * 47.13 + 0.31), h3 = fract(h * 91.7 + 0.77), h4 = fract(h * 13.7 + 0.5);
  vec2 c = 0.3 + 0.4 * vec2(h2, h3);
  float rad = 0.07 + 0.21 * h4;
  float dd = length(f - c);
  float disc = pow(1.0 - smoothstep(0.0, rad, dd), 1.4 + 2.0 * h4);
  float tw = 0.6 + 0.4 * sin(u_time * (0.25 + 0.6 * h2) + h * 40.0);
  return step(1.0 - amount, h) * tw * disc * (1.0 - 0.55 * h4);
}
// 1 inside an ellipse the size of a text block around the calm point
float calmMask(vec2 uv) {
  vec2 d = (uv - vec2(u_calmX, u_calmY)) * vec2(u_res.x / u_res.y, 1.0);
  vec2 R = vec2(0.3 + 0.3 * u_calm, 0.14 + 0.1 * u_calm);
  return 1.0 - smoothstep(0.6, 1.6, length(d / R));
}

void main() {
  vec2 uv = fx_uv();
  float asp = u_res.x / u_res.y;
  vec2 P = vec2(uv.x * asp, uv.y);                 // height units, y down
  vec2 d = P - vec2(u_ox * asp, u_originY);
  float r = length(d);
  float a = atan(d.x, d.y);                        // 0 straight down, positive to the right
  float t = u_time * u_speed + u_seed * 0.0137;
  float ra = a - radians(u_tiltE);
  float hs = radians(u_spread) * 0.5;
  float fan = 1.0 - smoothstep(hs * 0.3, hs, abs(ra));

  // rays: gradient noise along the angle, sharpened, and a finer octave for thin rays; a slower gate
  // groups them into bundles with dark gaps, as light through leaves or a window frame
  float k1 = mix(3.0, 18.0, u_density);
  float s1 = fx_noise(vec2(ra * k1 + u_seed * 0.071, t + r * 0.22));
  float s2 = fx_noise(vec2(ra * (k1 * 2.3 + 5.0) - 3.7, t * 1.5 - r * 0.32 + 9.1));
  float gate = smoothstep(-0.3, 0.35, fx_noise(vec2(ra * k1 * 0.3 + 17.0, t * 0.4)));
  float wide = pow(clamp(0.5 + 0.85 * s1, 0.0, 1.0), 2.0);
  float thin = pow(clamp(0.5 + 0.95 * s2, 0.0, 1.0), 4.0);
  float shafts = (wide * 0.9 + thin * 0.45 * (0.35 + 0.65 * wide)) * mix(0.3, 1.0, gate);
  // haze is uneven along each ray, so shafts break and thin out
  shafts *= 0.62 + 0.38 * smoothstep(-0.5, 0.5, fx_noise(vec2(ra * k1 * 0.6 + 4.0, r * 1.7 - t * 0.6)));

  float rTop = max(-u_originY, 0.0);
  float far = max(r - rTop, 0.0);
  float att = exp(-far * u_falloff * 0.75);
  float haze = exp(-far * u_falloff * 1.1) * (1.0 - smoothstep(hs * 0.3, hs * 1.8, abs(ra)));
  float glow = exp(-r * r / 0.06);
  float near = smoothstep(0.0, 0.18, r);         // keep the convergence point soft

  float cm = calmMask(uv) * smoothstep(0.0, 0.5, u_calm);
  float lit = shafts * fan * att * near;
  float L = (lit * 1.05 + haze * 0.42 + glow * 0.6) * u_intensity * u_gain;

  // motes: a few large blurred ones near the eye and finer ones further back, seen only in the light
  vec2 fall = vec2(0.0, -u_time * (0.01 + u_speed * 0.08));
  float dz = motes(P, 6.0, fall * 6.0 + vec2(0.3 * sin(t * 2.0), 0.0), 0.16, 91.0)
           + motes(P + vec2(3.1, 7.7), 15.0, fall * 9.0, 0.22, 17.0) * 0.8;
  L += dz * (lit + glow * 0.4 + haze * 0.3) * u_dust * 3.2 * u_intensity * u_gain;
  L *= 1.0 - 0.85 * cm;

  // composite in OKLab: on light pages the gaps between the shafts fall into a soft shade of the page;
  // the light is warmer near its source and cooler as it travels
  vec3 ground = mix(u_gFar, u_gNear, exp(-r * 0.9));
  // slow, large clouds of haze in the room, lit a little more toward the source
  ground.x += u_air * fx_fbm(P * 0.9 + vec2(t * 0.6, -t * 0.3) + 5.0) * (0.4 + 0.6 * exp(-far * 1.2));
  float shadeA = 1.4 * fan * att * near * (1.0 - clamp(shafts, 0.0, 1.0)) * u_shadeK * (1.0 - 0.85 * cm);
  ground = mix(ground, u_shade, clamp(shadeA, 0.0, 1.0));
  vec3 lightC = mix(u_lightFar, u_lightNear, exp(-far * 1.3));
  float m = 1.0 - exp(-L * 1.3);
  vec3 col = mix(ground, lightC, m);
  col = mix(col, u_hot, smoothstep(0.55, 1.0, m) * 0.6);
  col.x += fx_grain(gl_FragCoord.xy, floor(u_time * 24.0)) * 0.007;
  fxColor = vec4(fx_dither(fx_rgb(col)), 1.0);
}
`;

// the accent only when it will not turn muddy against the background
const fits = (bg, c) => color.chroma(bg) < 0.035 || color.chroma(c) < 0.035 || color.hueDistance(bg, c) < 55;
const warm = c => { const [, C, h] = color.lch(c); return C > 0.035 && h >= 25 && h <= 115; };

export function tones(P, prm) {
  const { bg, ink, accent } = P;
  const [Lb, Cb, hb] = color.lch(bg);
  const acc = fits(bg, accent) ? accent : null;
  // the warm end of the light: a warm accent if the palette has one, else the ink
  const warmSrc = warm(accent) ? accent : ink;
  const [, Cw, hw] = color.lch(warmSrc);
  if (Lb < 0.6) {
    // dark or deep ground: pale light tinted by the accent
    const base = color.adjust(bg, { l: 0.92 - Lb, c: 0.35 });
    const light = acc ? color.mix(base, color.withLightness(acc, 0.84), 0.2 + 0.6 * prm.tint) : base;
    return {
      gFar: color.darken(bg, Math.min(0.06, Lb * 0.18)),
      gNear: acc ? color.mix(bg, acc, 0.05 + 0.06 * prm.tint) : color.lighten(bg, 0.02),
      lightFar: light,
      lightNear: color.mix(light, color.fromLch([0.95, Math.min(0.035, Cw), hw]), 0.45),
      hot: color.mix(light, color.withLightness(ink, 0.97), 0.55),
      shade: bg, shadeK: 0, air: 0.022,
      gain: 1,
    };
  }
  // light ground: the room stays at the page's lightness; the gaps between the shafts take a soft
  // shade of the page and the shafts a warm white of it
  const base = color.fromLch([Math.min(0.995, Lb + 0.1), Cb * 0.5, hb]);
  const light = acc ? color.mix(base, color.withLightness(acc, 0.95), 0.12 * prm.tint) : base;
  return {
    gFar: color.darken(bg, 0.012),
    gNear: bg,
    lightFar: light,
    lightNear: color.mix(light, color.fromLch([Math.min(0.995, Lb + 0.1), Math.min(0.05, Cw * 0.5), hw]), 0.35),
    hot: color.fromLch([Math.min(0.998, Lb + 0.12), Cb * 0.3, hb]),
    shade: color.fromLch([Lb - 0.12, Cb * 1.1 + 0.004, hb]),
    shadeK: 1, air: 0.008,
    gain: 1.6,
  };
}

// the source keeps away from a text block near the top, and the fan leans into the frame
export function aim(prm) {
  let ox = prm.originX;
  if (prm.calm > 0.05 && prm.calmY < 0.45 && Math.abs(ox - prm.calmX) < 0.35) ox = prm.calmX < 0.5 ? Math.max(ox, prm.calmX + 0.45) : Math.min(ox, prm.calmX - 0.45);
  const tilt = ox > 0.6 ? -Math.abs(prm.tilt) : ox < 0.4 ? Math.abs(prm.tilt) : prm.tilt;
  return { ox, tilt };
}

function uniforms({ palette, params }) {
  const k = tones(palette, params);
  const g = aim(params);
  return {
    u_ox: g.ox, u_tiltE: g.tilt,
    u_gFar: color.labVec(k.gFar), u_gNear: color.labVec(k.gNear), u_lightFar: color.labVec(k.lightFar), u_lightNear: color.labVec(k.lightNear),
    u_hot: color.labVec(k.hot), u_shade: color.labVec(k.shade), u_shadeK: k.shadeK, u_air: k.air, u_gain: k.gain,
  };
}

export default {
  id: 'god-rays',
  name: 'God rays',
  family: 'light',
  params,
  mount(el, { palette, params: given, seed }) {
    return shader(el, {
      frag,
      schema: params,
      params: given,
      palette,
      seed,
      uniforms,
      still: 6,
      fallback: ({ palette: P, params: prm }) => {
        const k = tones(P, prm);
        const at = `${aim(prm).ox * 100}% ${prm.originY * 100}%`;
        return `radial-gradient(60% 90% at ${at}, ${k.lightNear}, transparent 75%), linear-gradient(${k.gNear}, ${k.gFar})`;
      },
    });
  },
};

effects/fluted-glass/effect.js:
// fluted-glass: a pane of reeded glass over a soft colour field. Every rib is a small cylinder lens that
// shows a narrow, mirrored slice of what is behind it, with a thin highlight on its lit side and a dark
// seam where two ribs meet. The field behind is part of the same shader, so it is one pass.
import { shader, color, fallbackCSS } from '../fx.js';

const params = {
  ribWidth:   { default: 28,   min: 10, max: 80,  step: 1 },    // CSS px
  angle:      { default: 0,    min: -45, max: 45, step: 1 },    // rib angle in degrees, 0 vertical
  distortion: { default: 0.5,  min: 0,  max: 1,   step: 0.01 }, // how far each rib bends the view
  highlight:  { default: 0.15, min: 0,  max: 1,   step: 0.01 }, // thin light line on each rib
  shadow:     { default: 0.16, min: 0,  max: 1,   step: 0.01 }, // dark seam between ribs
  background: { default: 0,    min: 0,  max: 1,   step: 1 },    // 0 a soft mesh of the page colours, 1 one bold shape
  blur:       { default: 0.1,  min: 0,  max: 1,   step: 0.01 }, // frost: softens the view through the glass
  speed:      { default: 0.03, min: 0,  max: 0.3, step: 0.005 },// how fast the field behind moves
  clear:      { default: 0,    min: 0,  max: 0.6, step: 0.01 }, // share of the width on the calm side with no glass
  calm:       { default: 0.4,  min: 0,  max: 1,   step: 0.01 }, // flatten the field where text sits
  calmX:      { default: 0.25, min: 0,  max: 1,   step: 0.01 },
  calmY:      { default: 0.7,  min: 0,  max: 1,   step: 0.01 },
};

const frag = /* glsl */ `
float sq(float x) { return x * x; }

// a soft shape: flat core, edge from firm to soft; c.xy centre, c.z vertical stretch, r radius
float shape(vec2 p, vec3 c, float r, float firm) {
  float d = length((p - c.xy) * vec2(1.0, c.z)) / r;
  return 1.0 - smoothstep(firm, 1.0, d);
}
vec3 moveShape(vec4 b, float t) {
  return vec3(b.xy + 0.16 * vec2(sin(t + b.w), cos(t * 0.8 + b.w * 1.7)), 1.0 + 0.12 * sin(t * 0.6 + b.w));
}

// the field behind the glass, in OKLab; q in centred height units (y up), already warped
vec3 field(vec2 q, vec3 c0, vec3 c1, vec3 c2) {
  float s = dot(q - u_calmP, u_dir) / u_span;
  vec3 col = mix(u_kNear, u_kFar, smoothstep(-0.05, 0.9, s));
  float bold = step(0.5, u_background);
  // the main shape, a smaller deeper one overlapping its edge, and a pale glint; their edges are
  // firm enough for the ribs to break them visibly
  col = mix(col, u_k0, shape(q, c0, u_b0.z, mix(u_firm0, 0.86, bold)));
  col = mix(col, u_k1, shape(q, c1, u_b1.z, 0.55) * (1.0 - bold * 0.4) * 0.92);
  col = mix(col, u_k2, shape(q, c2, u_b2.z, 0.35) * (1.0 - bold) * 0.85);
  return col;
}

void main() {
  vec2 css = gl_FragCoord.xy / u_dpr;                   // CSS px, y up
  vec2 res = u_res / u_dpr;
  vec2 uv = fx_uv();
  float t = u_time * u_speed * 1.6 + u_seed * 0.21;
  float a = radians(u_angle);
  vec2 across = vec2(cos(a), -sin(a));                  // perpendicular to the ribs
  float x = dot(css, across);
  float W = max(4.0, u_ribWidth);
  float u = fract(x / W);
  float cu = u - 0.5;

  // glass or clear: the clear part sits on the calm side
  float edgeX = u_calmX < 0.5 ? res.x * u_clear : res.x * (1.0 - u_clear);
  float sideD = u_calmX < 0.5 ? css.x - edgeX : edgeX - css.x;   // > 0 inside the glass
  float glass = u_clear > 0.001 ? smoothstep(-0.5, 0.5, sideD) : 1.0;

  // cylinder lens: the slope of the rib surface grows toward its edges, and so does the bend
  float slope = cu / sqrt(0.3 - cu * cu);
  float bend = -u_distortion * 4.2 * slope * W * glass;
  vec2 sp = css + across * bend;
  vec2 p = (sp - 0.5 * res) / res.y;
  // slow organic warp of the field, once per pixel (the blur taps share it)
  p += 0.08 * vec2(fx_noise(p * 1.3 + vec2(t * 0.6, 0.0)), fx_noise(p * 1.3 + vec2(4.1, -t * 0.5)));
  vec3 c0 = moveShape(u_b0, t), c1 = moveShape(u_b1, t * 1.1), c2 = moveShape(u_b2, t * 0.9);
  vec3 col;
  if (u_blur > 0.001) {
    vec2 o = across * (u_blur * W * 0.6) / res.y;
    col = 0.5 * (field(p + o, c0, c1, c2) + field(p - o, c0, c1, c2));
  } else col = field(p, c0, c1, c2);

  // calm area: the field flattens toward the near tone
  float m = fx_calm(uv, vec2(u_calmX, u_calmY), 0.4 + 0.45 * u_calm) * u_calm;
  col = mix(col, u_kNear, m * 0.85);

  // light on the ribs: a soft roll across each rib, a thin line on the lit side, a seam where ribs meet
  float roll = -slope * 0.5;
  float hl = exp(-sq((u - 0.16) / 0.055)) + 0.35 * exp(-sq((u - 0.05) / 0.03));
  float seam = exp(-sq((1.0 - u) / 0.075)) + exp(-sq(u / 0.04)) * 0.5;
  float calmRib = 1.0 - 0.6 * m;
  float lightAmt = (roll * 0.018 * (0.4 + u_highlight) + hl * u_highlight * 0.3) * glass * calmRib;
  float shadowAmt = (seam * u_shadow * 0.15 + max(0.0, -roll) * u_shadow * 0.03) * glass * calmRib;
  col.x += lightAmt * u_lightK - shadowAmt;
  col.yz *= 1.0 - 0.25 * hl * u_highlight * glass;

  // the edge of the pane when part is clear: a bright bevel and a soft shadow beside it
  if (u_clear > 0.001) {
    float bev = exp(-sq(sideD / 1.2));
    float sh = exp(-max(0.0, -sideD) / 10.0) * step(sideD, 0.0);
    col.x += bev * 0.06 - sh * 0.025 * u_shadow * 3.0;
  }

  col.x += fx_grain(gl_FragCoord.xy, 0.0) * 0.006;
  fxColor = vec4(fx_dither(fx_rgb(col)), 1.0);
}
`;

// a tone of c at lightness L; a light blue that leans violet is turned toward azure and a light
// purple-magenta toward pink, so no tint reads periwinkle, lavender or orchid
function lit(c, L, ck = 1) {
  let [, C, h] = color.lch(c);
  if (C > 0.03 && L >= 0.5) {
    if (h > 250 && h < 300) h = Math.max(236, h - 26);
    else if (h >= 300 && h < 340) h = Math.min(352, h + 20);
  }
  return color.fromLch([L, C * ck, h]);
}

// every colour is a tint or shade of the accent or the page background; the ink is never mixed in
// (an ink mixed into a colour field is what turns it khaki)
function tones(P, prm, kind) {
  const { bg, ink, accent } = P;
  const bold = prm.background > 0.5;
  const [Lb] = color.lab(bg), [Li] = color.lab(ink);
  const away = Li > Lb ? -1 : 1;
  const near = color.lighten(bg, away * 0.015);
  if (kind === 'dark') {
    // a lit accent, a deeper shade of it and a pale glint, on the dark page
    const La = color.lab(accent)[0];
    return {
      near, far: color.mix(bg, accent, 0.08), lightK: 1.15,
      k: [color.mix(bg, lit(accent, Math.max(0.55, Math.min(0.7, La))), bold ? 0.85 : 0.6), color.mix(bg, lit(accent, 0.4, 0.9), 0.75), color.mix(bg, lit(accent, 0.86, 0.5), 0.55)],
    };
  }
  if (kind === 'colour') {
    // the accent as one firm shape, and a deeper and a lighter tone of the page colour
    const Lbg = Lb;
    return {
      near, far: color.lighten(bg, -away * 0.05), lightK: 1.1,
      k: [accent, lit(bg, Math.max(0.2, Lbg - 0.14), 1.0), lit(bg, Math.min(0.9, Lbg + 0.2), 0.9)],
    };
  }
  // light: the accent mixed half back into the page (a full accent through ribs reads as a barcode),
  // a deeper accent shade that is small, and a white glint
  return {
    near, far: color.mix(bg, accent, 0.06), lightK: 1.0,
    // (the half-strength accent is a lighter, softer accent, not a mix with the page: a page of another
    // hue would turn it grey or mauve)
    k: [bold ? accent : lit(accent, color.lab(color.mix(bg, accent, 0.5))[0], 0.62), color.mix(bg, lit(accent, Math.min(0.5, color.lab(accent)[0]), 0.9), 0.62), color.mix(bg, '#ffffff', 0.7)],
  };
}

function uniforms({ palette, params, rng, kind, width, height }) {
  const r = rng;
  const set = tones(palette, params, kind);
  const asp = width && height ? width / height : 4 / 3;
  const calm = [(params.calmX - 0.5) * asp, 0.5 - params.calmY];
  // the shapes sit across from the calm area
  const far = [calm[0] < 0 ? asp / 2 : -asp / 2, calm[1] < 0 ? 0.5 : -0.5];
  const span = Math.max(0.3, Math.hypot(far[0] - calm[0], far[1] - calm[1]));
  const dir = [(far[0] - calm[0]) / span, (far[1] - calm[1]) / span];
  const sx = calm[0] < 0 ? 1 : -1;
  const clamp = (v, a) => Math.max(-a, Math.min(a, v));
  const bold = params.background > 0.5;
  const b0 = bold
    ? [clamp(sx * asp * (0.16 + 0.08 * r()), asp / 2 - 0.25), 0.04 + 0.12 * (r() - 0.5), 0.36 + 0.06 * r(), r() * 6.283]
    : [clamp(sx * asp * (0.16 + 0.1 * r()), asp / 2 - 0.15), 0.06 + 0.16 * (r() - 0.5), 0.36 + 0.08 * r(), r() * 6.283];
  // the deeper shape sits on the main one's edge, toward the middle; the glint on its far side
  const b1 = [b0[0] - sx * (0.18 + 0.1 * r()), b0[1] + (r() < 0.5 ? 1 : -1) * (0.2 + 0.08 * r()), 0.2 + 0.08 * r(), r() * 6.283];
  const b2 = [clamp(b0[0] + sx * (0.22 + 0.12 * r()), asp / 2), b0[1] - 0.26 - 0.1 * r(), 0.2 + 0.07 * r(), r() * 6.283];
  return {
    u_kNear: color.labVec(set.near),
    u_kFar: color.labVec(set.far),
    u_k0: color.labVec(set.k[0]),
    u_k1: color.labVec(set.k[1]),
    u_k2: color.labVec(set.k[2]),
    u_lightK: set.lightK,
    // a main shape far in hue from the field (a navy shape on mustard) gets a firm edge: a wide soft
    // edge between two far hues is a band of grey
    u_firm0: color.hueDistance(palette.bg, set.k[0]) > 80 ? 0.8 : 0.45,
    u_calmP: calm,
    u_dir: dir,
    u_span: span,
    u_b0: b0,
    u_b1: b1,
    u_b2: b2,
  };
}

export default {
  id: 'fluted-glass',
  name: 'Fluted glass',
  family: 'material',
  params,
  mount(el, { palette, params: given, seed }) {
    return shader(el, {
      frag,
      schema: params,
      params: given,
      palette,
      seed,
      uniforms,
      still: 5,
      fallback: ({ palette: P, params: prm, kind }) => {
        const k = tones(P, prm, kind).k;
        const ribs = `repeating-linear-gradient(${90 + prm.angle}deg, rgba(255,255,255,0.07) 0 1px, transparent 1px ${prm.ribWidth - 2}px, rgba(0,0,0,0.08) ${prm.ribWidth - 1}px ${prm.ribWidth}px)`;
        return `${ribs}, ${fallbackCSS({ ...P, accent: k[0] }, { at: `${(1 - prm.calmX) * 100}% 45%`, tint: 1 })}`;
      },
    });
  },
};

effects/film-light-leak/effect.js:
// film-light-leak: light bleeding in from one edge or corner of a dark or coloured frame, the way a film
// is fogged when the camera back leaks. From the edge where the light struck (an optional burn hugs it)
// the exposure falls off through a deep fringe (warm when the palette has a warm colour) and the
// glow into the ground, with a near-white core, fine moving film grain and a slight vignette. It
// breathes slowly. The seed picks the edge away from the text unless `edge` names one.
import { shader, color, grainCSS, rng } from '../fx.js';

const params = {
  edge:      { default: -1,   min: -1,   max: 4,    step: 1 },    // -1 the seed picks; 0 right, 1 left, 2 top, 3 bottom, 4 corner
  intensity: { default: 0.8,  min: 0,    max: 1.5,  step: 0.01 }, // exposure of the leak
  spread:    { default: 0.45, min: 0.1,  max: 1,    step: 0.01 }, // how far it reaches into the frame
  halation:  { default: 0.3,  min: 0,    max: 1,    step: 0.01 }, // the wider, deeper fringe around it
  burn:      { default: 0,    min: 0,    max: 1,    step: 0.01 }, // a burn along the frame edge; 0 by default (a hard strip reads as a glitch)
  grain:     { default: 0.04, min: 0,    max: 0.1,  step: 0.005 },// film grain, 0.04 is 4%
  vignette:  { default: 0.25, min: 0,    max: 1,    step: 0.01 },
  breathe:   { default: 12,   min: 6,    max: 20,   step: 0.5 },  // seconds per slow breath
  warp:      { default: 0.65, min: 0,    max: 1,    step: 0.01 }, // how organic the leak's edge is
  calm:      { default: 0.5,  min: 0,    max: 1,    step: 0.01 }, // holds the light back from the text area
  calmX:     { default: 0.25, min: 0,    max: 1,    step: 0.01 },
  calmY:     { default: 0.6,  min: 0,    max: 1,    step: 0.01 },
};

const frag = /* glsl */ `
void main() {
  vec2 uv = fx_uv();
  vec2 p = fx_p();
  float t = u_time;

  // a slow organic bend, so the edge of the light is never a clean ellipse
  float wt = t * 0.03 + u_seed * 0.011;
  vec2 w = vec2(fx_fbm(p * 0.95 + vec2(wt, 2.3)), fx_fbm(p * 0.95 + vec2(5.1, -wt * 0.8)));
  vec2 q = p + w * 0.34 * u_warp;

  // distance from the source on the edge: stretched along the edge, measured into the frame
  float sp = 0.12 + 0.75 * u_spread;
  vec2 rel = q - u_src;
  float along = dot(rel, u_axis);
  float into = max(dot(rel, u_in), 0.0);
  float d = length(vec2(along * u_stretch, into)) / sp;
  // a second, smaller bloom further along the edge, so the light is never one clean ellipse
  vec2 rel2 = q - u_src - u_axis * (u_lobe + 0.04 * sin(t * 0.07));
  float d2 = length(vec2(dot(rel2, u_axis) * 1.2, max(dot(rel2, u_in), 0.0))) / (sp * 0.5);

  // slow breaths, incommensurate sines so it never loops visibly
  float br = 1.0 + 0.13 * sin(FX_TAU * t / u_breathe) + 0.05 * sin(FX_TAU * t / (u_breathe * 1.618) + 1.3);
  float br2 = 1.0 + 0.18 * sin(FX_TAU * t / (u_breathe * 1.31) + 2.1);

  float m = fx_calm(uv, vec2(u_calmX, u_calmY), 0.3 + 0.55 * u_calm) * u_calm;
  // a broad bloom, a smaller one beside it, and a hot band hugging the edge where the film was struck
  float band = exp(-into / (0.02 + 0.04 * u_spread)) * exp(-along * along * 6.0);
  float E = u_intensity * u_gain * (6.0 * exp(-d * 2.7) * br + 3.0 * exp(-d2 * 2.5) * br2 + 3.5 * band * br) * (1.0 - 0.9 * m);
  // light bleeds into the frame in soft streaks, long across the frame and narrow along the edge
  float rays = fx_noise(vec2(along * 7.0 + u_seed * 0.01, into * 0.7 - t * 0.01));
  E *= 1.0 + 0.8 * rays * smoothstep(0.0, 0.2, into);
  float H = u_halation * (exp(-d * 1.05) + 0.4 * exp(-d2 * 1.1)) * br * (1.0 - 0.8 * m);

  // grain lives in the exposure, before the curve, so it is strongest in the mid tones like film
  float frame = floor(t * 24.0);
  float g = fx_grain(gl_FragCoord.xy, frame);
  E = max(E * (1.0 + g * u_grain * 3.0), 0.0);
  float e = E / (1.0 + E);                                   // filmic shoulder: a soft, blown-out core

  // the ground darkens a little toward the corners (lens vignette); the leak exposes on top of it
  vec2 vc = (uv - 0.5) * vec2(u_res.x / u_res.y, 1.0) / (0.5 * max(u_res.x / u_res.y, 1.0));
  vec3 col = u_ground;                                        // OKLab
  col.x *= 1.0 - u_vignette * u_vig * 0.6 * smoothstep(0.35, 1.25, length(vc));
  col = mix(col, u_halo, clamp(H, 0.0, 1.0) * 0.75);
  col = mix(col, u_deep, smoothstep(u_ramp.x, u_ramp.y, e));
  col = mix(col, u_glow, smoothstep(u_ramp.y - 0.12, u_ramp.z, e));
  col = mix(col, u_hot, smoothstep(u_ramp.z - 0.1, u_ramp.w, e));

  // the burn: an uneven band along the frame edge near the source with a crisp inner boundary, its
  // own colour at the boundary and blown out against the edge
  if (u_burn > 0.0) {
    // depth into the frame from the struck edge (from both edges at a corner)
    vec2 hf2 = vec2(0.5 * u_res.x / u_res.y, 0.5);
    vec2 de = hf2 - abs(p);
    float dE = u_corner > 0.5 ? min(de.x, de.y) : dot(p - u_src, u_in);
    vec2 r0 = p - u_src;
    float near = exp(-dot(r0, r0) / (sp * sp * 1.1)) * br;
    float n = fx_noise(vec2((p.x + p.y) * 2.2 + u_seed * 0.013, t * 0.015)) + 0.25 * fx_noise(vec2((p.x - p.y) * 6.0, 3.0 + u_seed * 0.007));
    float bw = max(0.0, (0.05 + 0.13 * (n + 0.3)) * near * u_burn) * (1.0 - m);
    float px = 2.4 / u_res.y;
    // the band fades out where it thins, so it never stops in a hard end partway along the edge
    float b = (1.0 - smoothstep(bw - px, bw + px, dE)) * smoothstep(px, px * 8.0, bw);
    // blown out against the edge, a saturated fringe just inside the crisp boundary
    float fr = smoothstep(bw * 0.4, bw * 0.95, dE);
    col = mix(col, mix(u_hot, u_burnC, fr), b * 0.95);
  }

  // fine monochrome grain on top, re-seeded every frame, softer in the blown-out core
  col.x += g * u_grain * u_grainAmp * (1.0 - 0.6 * smoothstep(0.85, 1.0, col.x));

  fxColor = vec4(fx_dither(fx_rgb(col)), 1.0);
}
`;

// reds, oranges, golds and yellows (OKLCH hue), with some colour in them
const isWarm = c => { const [, C, h] = color.lch(c); return C > 0.05 && (h < 112 || h > 345); };
// keeps pale tints out of the lavender band
const guard = ([L, C, h]) => (h > 262 && h < 322 ? [L, Math.min(C, 0.018), h] : [L, C, h]);

// the ramp: ground, a wide halo, a deep fringe, the glow, a near-white core, and the burn colour; all
// from the palette (a warm palette colour leads the fringe and the burn; a warm glow shifts toward red
// in the fringe and toward yellow in the core, as a real leak does)
function tones(P) {
  const { bg, ink, muted, accent } = P;
  const [Lb, Cb, hb] = color.lch(bg);
  const coloured = Cb > 0.07;
  const own = coloured && color.hueDistance(bg, accent) >= 55;
  let glow = own ? color.withLightness(color.saturate(bg, 2), Math.min(0.86, Lb + 0.16)) : accent;
  const [Lg0, Cg0] = color.lch(glow);
  if (!own && Lg0 < Lb + 0.22) glow = color.withLightness(glow, Math.min(0.88, Lb + 0.26));
  glow = color.adjust(glow, { c: Cg0 < 0.06 ? 1 : 1.12 });
  const [L2, C2, h2] = color.lch(glow);
  // a warm palette colour lighter than the ground, for the fringe and the burn
  // (not on a coloured ground: a warm fringe over, say, blue passes through olive on its way)
  const warm = coloured ? null : [accent, ink, muted].find(c => isWarm(c) && color.lab(c)[0] > Lb + 0.1) || null;
  const mid = Lb + (L2 - Lb) * 0.5;
  let deep, hot, burnC;
  if (isWarm(glow)) {
    // the fringe leans toward red (hue about 28), from either side, so a pink glow never turns violet
    const toRed = ((28 - h2 + 540) % 360) - 180;
    const hr = (h2 + Math.sign(toRed) * Math.min(18, Math.abs(toRed)) + 360) % 360;
    deep = color.fromLch([mid, Math.min(0.2, C2 * 1.25), hr]);
    hot = color.fromLch([Math.max(0.95, L2 + 0.06), 0.055, h2 > 300 ? (h2 + 24) % 360 : Math.min(h2 + 24, 100)]);
    burnC = color.fromLch([Math.min(0.8, L2 + 0.04), Math.min(0.22, C2 * 1.3), (h2 + Math.sign(toRed) * Math.min(8, Math.abs(toRed)) + 360) % 360]);
  } else if (warm) {
    const [Lw, Cw, hw] = color.lch(warm);
    deep = color.fromLch([mid, Math.min(0.2, Math.max(Cw, 0.08) * 1.2), hw]);
    hot = color.fromLch(guard(own ? [0.96, Math.min(0.05, Cb * 0.35), hb] : [Math.max(0.95, L2 + 0.06), 0.03, h2]));
    burnC = color.fromLch([Math.max(Lw, Lb + 0.3), Math.min(0.22, Math.max(Cw, 0.09) * 1.15), hw]);
  } else {
    // a cool palette: the fringe leans toward the ground's own hue, deeper and more saturated
    const hd = Cb > 0.02 ? hb : h2;
    let dh = ((hd - h2 + 540) % 360) - 180;
    dh = Math.max(-20, Math.min(20, dh));
    let hf = (h2 + dh + 360) % 360;
    if (hf > 262 && hf < 322 && !(h2 > 262 && h2 < 322)) hf = h2;   // never lean into violet
    deep = color.fromLch([mid, Math.min(0.2, C2 * 1.3), hf]);
    hot = color.fromLch(guard(own ? [0.96, Math.min(0.05, Cb * 0.35), hb] : [Math.max(0.95, L2 + 0.06), Math.min(0.035, C2 * 0.25), h2]));
    burnC = color.fromLch([Math.min(0.78, L2), Math.min(0.2, C2 * 1.3), h2]);
  }
  const [Ld] = color.lab(deep);
  const halo = color.adjust(color.withLightness(deep, Lb + (Ld - Lb) * 0.55), { c: 1.15 });
  return {
    ground: bg, halo, deep, glow, hot, burnC, coloured, light: Lb > 0.6,
    ramp: own ? [0.04, 0.3, 0.6, 0.84] : [0.03, 0.42, 0.7, 0.92],
  };
}

// the edge farthest from the text, or the corner farthest from it; a fixed edge when given
function pickEdge(params, r, asp, seed) {
  const C = [(params.calmX - 0.5) * asp, 0.5 - params.calmY];
  if (params.edge >= 0) return { e: Math.round(params.edge), C };
  const dist = [asp / 2 - C[0], C[0] + asp / 2, 0.5 - C[1], C[1] + 0.5];   // right, left, top, bottom
  const best = Math.max(...dist);
  const ok = [0, 1, 2, 3].filter(i => dist[i] >= best * 0.7);
  // its own stream, so neighbouring seeds do not all pick the same edge
  const r2 = rng(`film-light-leak:edge:${seed}`);
  if (r2() < 0.3) return { e: 4, C };
  return { e: ok[Math.floor(r2() * ok.length)], C };
}

function uniforms({ palette, params, seed, rng: r, width, height }) {
  const T = tones(palette);
  const asp = width && height ? width / height : 4 / 3;
  const hx = asp / 2, hy = 0.5;
  const { e, C } = pickEdge(params, r, asp, seed);
  // along the edge, the source keeps to the half away from the text
  const j = (r() - 0.5) * 0.6;
  const awayY = Math.abs(C[1]) > 0.08 ? -Math.sign(C[1]) * 0.18 : 0;
  const awayX = Math.abs(C[0]) > 0.1 * asp ? -Math.sign(C[0]) * 0.18 * asp : 0;
  let src, axis, inn, stretch = 1.05;
  if (e === 1) { src = [-hx, j * 0.6 + awayY]; axis = [0, 1]; inn = [1, 0]; }
  else if (e === 2) { src = [j * asp * 0.5 + awayX, hy]; axis = [1, 0]; inn = [0, -1]; }
  else if (e === 3) { src = [j * asp * 0.5 + awayX, -hy]; axis = [1, 0]; inn = [0, 1]; }
  else if (e === 4) {
    // the corner farthest from the text area
    const sx = C[0] <= 0 ? 1 : -1, sy = C[1] <= 0 ? 1 : -1;
    src = [sx * hx, sy * hy]; inn = [-sx * Math.SQRT1_2, -sy * Math.SQRT1_2]; axis = [-inn[1], inn[0]]; stretch = 0.8;
  } else { src = [hx, j * 0.6 + awayY]; axis = [0, 1]; inn = [-1, 0]; }
  return {
    u_ground: color.labVec(T.ground),
    u_halo: color.labVec(T.halo),
    u_deep: color.labVec(T.deep),
    u_glow: color.labVec(T.glow),
    u_hot: color.labVec(T.hot),
    u_burnC: color.labVec(T.burnC),
    u_ramp: T.ramp,
    // a coloured ground needs more light to read, less grain (it turns to coloured noise there) and a
    // lighter vignette (darkening a saturated ground turns it muddy)
    u_gain: T.coloured ? 1.45 : 1,
    u_grainAmp: T.coloured ? 0.55 : T.light ? 0.9 : 1.2,
    u_vig: T.coloured ? 0.35 : 1,
    u_src: src,
    u_axis: axis,
    u_in: inn,
    u_stretch: stretch, u_corner: e === 4 ? 1 : 0,
    u_lobe: (r() < 0.5 ? -1 : 1) * (0.24 + 0.12 * r()),
  };
}

export default {
  id: 'film-light-leak',
  name: 'Film light leak',
  family: 'grain',
  params,
  mount(el, { palette, params: given, seed }) {
    return shader(el, {
      frag,
      schema: params,
      params: given,
      palette,
      seed,
      uniforms,
      fps: 30,
      still: 4,
      fallback: ({ palette: P, params: prm, seed: s, rng: r, width, height }) => {
        const T = tones(P);
        const asp = width && height ? width / height : 4 / 3;
        const { e, C } = pickEdge(prm, r, asp, s);
        const at = ['100% 50%', '0% 50%', '50% 0%', '50% 100%', `${C[0] <= 0 ? 100 : 0}% ${C[1] <= 0 ? 0 : 100}%`][e] || '100% 50%';
        return `${grainCSS(0.06, 1)}, radial-gradient(45% 70% at ${at}, ${T.hot}, ${T.glow} 22%, ${T.deep} 45%, transparent 75%), ${P.bg}`;
      },
    });
  },
};

effects/edge-glow/effect.js:
// edge-glow: light runs around the edge of a card or prompt box. A bright head travels the border
// (measured by arc length, at a steady speed in px per second, capped on small boxes) with a long tail
// that fades evenly behind it; the whole border keeps a faint idle glow, and the head throws a soft
// wash of its colour into the box as it passes. By default the element itself is the card (inset 0):
// put the content straight inside it. With inset > 0 the effect draws its own card that many px inside
// the element and the glow also blooms outward into that margin.
import { shader, color } from '../fx.js';

const params = {
  radius:      { default: 14,   min: 0,    max: 48,  step: 1 },     // corner radius, CSS px (match the element's)
  width:       { default: 1.4,  min: 0.5,  max: 3,   step: 0.1 },   // border width, CSS px
  glow:        { default: 26,   min: 0,    max: 48,  step: 1 },     // glow spread, CSS px
  bloom:       { default: 0.6,  min: 0,    max: 1,   step: 0.01 },  // glow strength
  segment:     { default: 0.4,  min: 0.1,  max: 0.7, step: 0.01 },  // length of the tail, share of the edge
  speed:       { default: 140,  min: 20,   max: 400, step: 5 },     // CSS px per second (at most a quarter lap per second)
  count:       { default: 1,    min: 1,    max: 2,   step: 1 },     // one head, or two on opposite sides
  idle:        { default: 0.35, min: 0,    max: 1,   step: 0.01 },  // the faint glow along the rest of the border
  wash:        { default: 0.5,  min: 0,    max: 1,   step: 0.01 },  // light the head throws into the box
  inset:       { default: 0,    min: 0,    max: 80,  step: 1 },     // 0: the element is the card; else the card edge, CSS px inside
  fill:        { default: 0,    min: 0,    max: 1,   step: 1 },     // 1 fills the card with the surface colour, 0 with the page colour
};

const frag = /* glsl */ `
const float FX_PI = 3.14159265359;
float sdRR(vec2 q, vec2 b, float r) {
  vec2 d = abs(q) - b + r;
  return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0) - r;
}
// arc-length position of the nearest edge point, clockwise from the left end of the top side (y down)
float arcPos(vec2 q, vec2 b, float r, out float per) {
  vec2 c = max(b - r, vec2(0.0));
  float qa = 0.5 * FX_PI * r;
  per = 4.0 * (c.x + c.y) + 4.0 * qa;
  vec2 a = abs(q);
  bool inX = a.x <= c.x;
  bool inY = a.y <= c.y;
  if (inX && inY) {
    if (b.y - a.y < b.x - a.x) inY = false; else inX = false;
  }
  if (inX) return q.y < 0.0 ? q.x + c.x : 2.0 * c.x + 2.0 * c.y + 2.0 * qa + (c.x - q.x);
  if (inY) return q.x > 0.0 ? 2.0 * c.x + qa + (q.y + c.y) : 4.0 * c.x + 2.0 * c.y + 3.0 * qa + (c.y - q.y);
  vec2 cc = sign(q) * c;
  float th = atan(q.y - cc.y, q.x - cc.x);
  if (q.x > 0.0 && q.y < 0.0) return 2.0 * c.x + r * (th + 0.5 * FX_PI);
  if (q.x > 0.0) return 2.0 * c.x + 2.0 * c.y + qa + r * th;
  if (q.y > 0.0) return 4.0 * c.x + 2.0 * c.y + 2.0 * qa + r * (th - 0.5 * FX_PI);
  return 4.0 * c.x + 4.0 * c.y + 3.0 * qa + r * (th + FX_PI);
}
// the edge point at arc length s (the inverse of arcPos)
vec2 pointAt(float s, vec2 b, float r) {
  vec2 c = max(b - r, vec2(0.0));
  float qa = 0.5 * FX_PI * r;
  float s1 = 2.0 * c.x, s2 = s1 + qa, s3 = s2 + 2.0 * c.y, s4 = s3 + qa;
  float s5 = s4 + 2.0 * c.x, s6 = s5 + qa, s7 = s6 + 2.0 * c.y;
  float rr = max(r, 1e-3);
  if (s < s1) return vec2(-c.x + s, -b.y);
  if (s < s2) { float th = -0.5 * FX_PI + (s - s1) / rr; return vec2(c.x, -c.y) + r * vec2(cos(th), sin(th)); }
  if (s < s3) return vec2(b.x, -c.y + (s - s2));
  if (s < s4) { float th = (s - s3) / rr; return c + r * vec2(cos(th), sin(th)); }
  if (s < s5) return vec2(c.x - (s - s4), b.y);
  if (s < s6) { float th = 0.5 * FX_PI + (s - s5) / rr; return vec2(-c.x, c.y) + r * vec2(cos(th), sin(th)); }
  if (s < s7) return vec2(-b.x, c.y - (s - s6));
  float th = FX_PI + (s - s7) / rr;
  return -c + r * vec2(cos(th), sin(th));
}
// the tail: full at the head, fading evenly (linearly) over L behind it, a short fade in front
float segWin(float s, float head, float per, float L) {
  float ds = mod(s - head + 0.5 * per, per) - 0.5 * per;
  float tail = clamp(1.0 + ds / L, 0.0, 1.0);
  float front = 1.0 - smoothstep(0.0, 0.04 * L + 6.0, ds);
  return tail * front;
}

void main() {
  float dpr = u_dpr;
  vec2 px = vec2(gl_FragCoord.x, u_res.y - gl_FragCoord.y);
  vec2 q = px - 0.5 * u_res;
  float hw = 0.5 * u_width * dpr;
  float ins = min(u_inset * dpr, 0.45 * min(u_res.x, u_res.y));
  // with inset 0 the line sits just inside the element's own edge, so none of it is clipped
  float pad = max(ins, hw + 0.5);
  vec2 b = max(0.5 * u_res - pad, vec2(4.0));
  float rr = min(max(u_radius * dpr - (pad - ins), 0.0), min(b.x, b.y));
  float d = sdRR(q, b, rr);

  float per;
  float s = arcPos(q, b, rr, per);
  // steady px per second, at most a quarter lap per second on small boxes
  float v = min(u_speed, 0.25 * per / dpr) * dpr;
  float head = mod(u_time * v + u_seed * 37.0, per);
  float L = u_segment * per;
  float win = segWin(s, head, per, L);
  float h2 = mod(head + 0.5 * per, per);
  if (u_count > 1.5) win = max(win, segWin(s, h2, per, L));
  vec3 segCol = mix(u_cA, u_cB, win);

  float stroke = 1.0 - smoothstep(hw - 0.75, hw + 0.75, abs(d));
  float outside = smoothstep(-0.6, 0.6, d);
  float g = max(u_glow * dpr, 1.0);
  float dout = max(d, 0.0), din = max(-d, 0.0);
  float bloomOut = 0.55 * exp(-dout / (g * 0.35)) + 0.45 * exp(-dout * dout / (g * g) * 2.0);
  float edgeD = min(min(px.x, u_res.x - px.x), min(px.y, u_res.y - px.y));
  bloomOut *= smoothstep(0.0, max(ins * 0.85, 1.0), edgeD) * step(0.5, ins);
  float bloomIn = exp(-din / (g * 0.3)) * (1.0 - outside);
  float glowA = (bloomOut * outside + bloomIn) * u_bloom;

  // the wash: soft light thrown into the box around the head (and the middle of its tail)
  float R = 0.32 * min(b.x, b.y) + 3.0 * g;
  vec2 hp = pointAt(head, b, rr);
  vec2 tp = pointAt(mod(head - 0.3 * L + per, per), b, rr);
  float wsh = exp(-dot(q - hp, q - hp) / (R * R)) + 0.45 * exp(-dot(q - tp, q - tp) / (R * R));
  if (u_count > 1.5) {
    vec2 hp2 = pointAt(h2, b, rr);
    wsh += exp(-dot(q - hp2, q - hp2) / (R * R));
  }
  wsh *= u_wash * (1.0 - outside) * 0.6;

  vec3 col = mix(u_cardFill, u_bg, outside);
  col = mix(col, u_glowC, clamp(wsh, 0.0, 1.0) * u_glowK);
  // idle: the whole border holds a faint line and glow
  col = mix(col, u_glowC, clamp(glowA * u_idle * 0.5, 0.0, 1.0) * u_glowK);
  col = mix(col, u_line, stroke * (0.35 + 0.65 * u_idle));
  // the moving light: glow and line along the tail, white-hot at the head
  col = mix(col, u_glowC, clamp(win * (0.4 + 0.6 * win) * glowA * 1.4, 0.0, 1.0) * u_glowK);
  // the line swells a little toward the head
  float hwH = hw * (1.0 + 0.8 * smoothstep(0.6, 1.0, win));
  float strokeH = 1.0 - smoothstep(hwH - 0.75, hwH + 0.75, abs(d));
  col = mix(col, segCol, strokeH * win);
  col = mix(col, u_hot, strokeH * smoothstep(0.8, 1.0, win) * 0.9);
  col.x += fx_grain(gl_FragCoord.xy, floor(u_time * 24.0)) * 0.005;
  fxColor = vec4(fx_dither(fx_rgb(col)), 1.0);
}
`;

// a neighbour hue of c, turned away from violet
function neighbour(c, deg = 40) {
  const h = color.lch(c)[2];
  const dist = x => { const d = Math.abs(((x % 360) + 360) % 360 - 305) % 360; return d > 180 ? 360 - d : d; };
  const turn = dist(h + deg) >= dist(h - deg) ? deg : -deg;
  return color.adjust(c, { h: turn });
}

// true when mixing ground into c in OKLab passes through violet or lavender (hue 275..335)
function crossesViolet(ground, c) {
  for (let t = 0.1; t < 1; t += 0.1) {
    const [, C, h] = color.lch(color.mix(ground, c, t));
    if (C > 0.012 && h >= 275 && h <= 335) return true;
  }
  return false;
}
// turn c's hue away from violet, a step at a time, until its mix with the ground stays clear of it
function clearOfViolet(ground, c) {
  const h = color.lch(c)[2];
  const dir = h >= 305 || h < 125 ? 1 : -1;
  for (let i = 0; i < 6 && crossesViolet(ground, c); i++) c = color.adjust(c, { h: 15 * dir });
  return c;
}

export function tones(P, prm) {
  const { bg, surface, ink, accent } = P;
  const [Lb] = color.lab(bg);
  const fill = prm.fill >= 0.5 ? surface : bg;
  // a grey accent: the light takes the ink instead, so it still reads as light, not as a smudge;
  // an accent whose mix with the ground would pass through lavender is turned a little away from it
  const src = clearOfViolet(fill, color.chroma(accent) < 0.03 ? color.withLightness(ink, 0.75) : accent);
  if (Lb < 0.6) {
    // dark: the tail is the accent, the head a lighter neighbour, white-hot at the tip
    const a = color.withLightness(color.saturate(src, 1.1), Math.max(0.68, color.lab(src)[0]));
    const b2 = clearOfViolet(fill, color.lighten(neighbour(a), 0.1));
    return {
      bg, fill, a, b: b2,
      line: color.mix(fill, ink, 0.3),
      hot: color.mix(b2, color.withLightness(ink, 0.98), 0.6),
      glow: color.mix(a, b2, 0.5),
      glowK: 1,
    };
  }
  // light: a saturated, mid-light accent line, and a glow that tints the ground toward a light
  // tint of the accent (never a darkened shadow colour)
  const [, Cs, hs] = color.lch(src);
  const Cl = Math.min(0.2, Math.max(Cs * 1.4, 0.13));
  const a = color.fromLch([0.6, Cl, hs]);
  const b2 = clearOfViolet(fill, color.withLightness(neighbour(a), 0.7));
  const tint = color.fromLch([Math.min(0.96, Math.max(Lb - 0.02, 0.8)), Math.min(0.13, Cl * 0.7), hs]);
  return {
    bg, fill, a: b2, b: a,
    line: color.mix(fill, ink, 0.22),
    hot: color.withLightness(color.saturate(a, 1.1), 0.6),
    glow: clearOfViolet(fill, tint),
    glowK: 1,
  };
}

function uniforms({ palette, params }) {
  const k = tones(palette, params);
  return {
    u_bg: color.labVec(k.bg), u_cardFill: color.labVec(k.fill), u_line: color.labVec(k.line),
    u_cA: color.labVec(k.a), u_cB: color.labVec(k.b), u_hot: color.labVec(k.hot), u_glowC: color.labVec(k.glow), u_glowK: k.glowK,
  };
}

export default {
  id: 'edge-glow',
  name: 'Edge glow',
  family: 'light',
  params,
  mount(el, { palette, params: given, seed }) {
    return shader(el, {
      frag,
      schema: params,
      params: given,
      palette,
      seed,
      uniforms,
      still: 1.5,
      fallback: ({ palette: P, params: prm }) => {
        const k = tones(P, prm);
        const i = prm.inset;
        const glow = `radial-gradient(45% 55% at 26% ${i}px, ${color.mix(k.fill, k.glow, 0.7)}, transparent 70%)`;
        // inset 0: the element (and its own rounded corners) is the card; otherwise a flat inner card
        if (!i) return `${glow}, ${k.fill}`;
        return `${glow}, linear-gradient(${k.fill}, ${k.fill}) center / calc(100% - ${2 * i}px) calc(100% - ${2 * i}px) no-repeat, `
          + `linear-gradient(${k.line}, ${k.line}) center / calc(100% - ${2 * i - 2}px) calc(100% - ${2 * i - 2}px) no-repeat, ${k.bg}`;
      },
    });
  },
};

effects/duotone-grade/effect.js:
// duotone-grade: a photograph graded into two or three page tones (shadow, middle, highlight) mixed in
// OKLab, darker (or paler) where text sits, with a faint vignette and still film grain. It is meant for
// the section's own photo: an <img data-fx-photo>, else a direct child <img> or <picture> (never an icon
// nested in a card on top), else the URL in data-fx-src. The <img> stays in the page for its alt text
// and layout, hidden while the graded frame shows. Without a photo it draws a stand-in in the shader (no
// CPU work, no texture): sun through a pane, blinds, an arch or a soft beam, chosen by the seed and
// kept clear of the text. Still by default; drift > 0 adds a slow push-in with the grain on the picture.
import { shader, color, grainCSS, paletteKind, rng, config } from '../fx.js';

const params = {
  tones:    { default: 3,    min: 2,  max: 3, step: 1 },    // 2 duotone, 3 adds a middle tone
  contrast: { default: 0.45, min: 0,  max: 1, step: 0.01 }, // soft S curve on the photo
  exposure: { default: 0,    min: -1, max: 1, step: 0.01 }, // darker .. lighter overall
  grain:    { default: 0.4,  min: 0,  max: 1, step: 0.01 }, // still film grain, 0 off
  drift:    { default: 0,    min: 0,  max: 1, step: 0.01 }, // slow push-in, 0 a still photo (no loop)
  ink:      { default: 0,    min: 0,  max: 1, step: 1 },    // 1 tones with the ink colour instead of the accent
  scrim:    { default: 0.5,  min: 0,  max: 1, step: 0.5 },  // text area: 0 darker (light text), 1 paler (dark text), 0.5 for the page's ink
  calm:     { default: 0.6,  min: 0,  max: 1, step: 0.01 }, // strength and size of that area
  calmX:    { default: 0.2,  min: 0,  max: 1, step: 0.01 }, // text area centre, 0 left .. 1 right
  calmY:    { default: 0.75, min: 0,  max: 1, step: 0.01 }, // text area centre, 0 top .. 1 bottom
};

const frag = /* glsl */ `
#ifdef FX_PHOTO
uniform sampler2D u_img;
#else
float edge2(vec2 w, vec2 pw) {
  return smoothstep(-pw.x, pw.x, w.x) * smoothstep(-pw.x, pw.x, 1.0 - w.x) * smoothstep(-pw.y, pw.y, w.y) * smoothstep(-pw.y, pw.y, 1.0 - w.y);
}
// 1 on a bar of half width h around c, soft edge e
float bar(float x, float c, float h, float e) { return 1.0 - smoothstep(h - e, h + e, abs(x - c)); }

// The stand-in photograph: sun through an opening lies on a plaster wall. s: x 0..aspect, y 0..1 down.
// Returns the tonal position, 0 deepest .. 1 brightest.
float lightStudy(vec2 s) {
  vec4 P = u_patch;                                        // x0, y0, width, height before the slant
  float sl = u_shape.y;
  vec2 m = vec2(s.x - P.x, s.y - P.y - sl * (s.x - P.x));  // patch space, height units
  vec2 w = m / P.zw;                                       // 0..1 inside the patch
  vec2 c = vec2(P.x + 0.5 * P.z, P.y + 0.5 * P.w + 0.5 * sl * P.z);

  // the wall: a broad spill of bounced light around the patch, a little darker low down, plaster
  vec2 dc = (s - c) / (P.zw * vec2(1.5, 1.3) + 0.25);
  float wall = 0.34 + 0.15 * exp(-dot(dc, dc)) - 0.05 * s.y;
  wall += 0.03 * fx_fbm(s * 3.0 + 7.1) + 0.012 * (fx_vnoise(s * 70.0) - 0.5);

  // the edges soften as the light travels: crisp on one side of the patch, soft on the other
  float far = clamp(u_shape.w > 0.0 ? w.x : 1.0 - w.x, 0.0, 1.0);
  float pen = 0.003 + 0.014 * far;
  vec2 pw = pen / P.zw;
  float v = u_shape.x, sun;
  if (v < 0.5) {            // a tall pane with one transom near the top
    sun = edge2(w, pw) * (1.0 - bar(w.y, 0.28, 0.011 / P.w, pw.y));
  } else if (v < 1.5) {     // blinds: soft slats
    float n = u_shape.z;
    float g = abs(fract(w.y * n + 0.5) - 0.5);             // distance to the middle of the nearest lit slat
    sun = edge2(w, pw) * (1.0 - smoothstep(0.3 - pw.y * n, 0.3 + pw.y * n, g));
  } else if (v < 2.5) {     // an arched opening with a mullion
    vec2 q = vec2((w.x - 0.5) * P.z, m.y);
    float r = 0.5 * P.z;
    float arch = q.y < r ? 1.0 - smoothstep(-pen, pen, length(q - vec2(0.0, r)) - r) : 1.0;
    sun = smoothstep(-pw.x, pw.x, w.x) * smoothstep(-pw.x, pw.x, 1.0 - w.x) * smoothstep(-pw.y, pw.y, 1.0 - w.y) * arch;
    sun *= 1.0 - bar(w.x, 0.5, 0.011 / P.z, pw.x);
  } else {                  // a soft beam: no frame, a wide penumbra, a little fine dapple
    sun = edge2(w, (0.02 + 0.05 * far) / P.zw);
  }
  // leaves of a tree outside, a little denser toward the soft side (smaller and sparser in the beam)
  vec2 lm = v > 2.5 ? m * 2.6 : m;
  float lf = 0.5 + 0.55 * fx_fbm(lm * 3.6 + 2.3) + 0.05 * (fx_vnoise(lm * 38.0) - 0.5) + 0.1 * far - 0.08 * w.y;
  float le = 0.035 + 0.09 * far;                           // leaf edges blur with the penumbra
  float occ = smoothstep(0.64 - le, 0.64 + le, lf);
  sun *= (1.0 - u_leaf * occ) * (1.0 - 0.1 * clamp(w.y, 0.0, 1.0));
  return clamp(wall + 0.56 * sun, 0.0, 1.0);
}
#endif

void main() {
  vec2 uv = fx_uv();
  float asp = u_res.x / u_res.y;
  // an optional slow push-in toward the focus (drift 0: a still photograph)
  float k = 0.5 - 0.5 * cos(FX_TAU * u_time / 48.0 + u_phase);
  float z = 1.0 + u_drift * (0.01 + 0.035 * k);
  float t;
  vec2 gp; // grain position, fixed to the picture so it travels with it
#ifdef FX_PHOTO
  // object-fit: cover, at the image's object-position
  float ir = u_imgRes.x / max(1.0, u_imgRes.y);
  vec2 vis = asp > ir ? vec2(1.0, ir / asp) : vec2(asp / ir, 1.0);
  vec2 iu = (1.0 - vis) * u_pos + uv * vis;
  iu = u_focus + (iu - u_focus) / z;
  // the photo's lightness, stretched between its own black and white points
  t = clamp((fx_oklab(texture(u_img, iu).rgb).x - u_levels.x) / max(0.05, u_levels.y - u_levels.x), 0.0, 1.0);
  gp = iu * u_res / vis;
#else
  vec2 s = vec2(uv.x * asp, uv.y);
  vec2 f = u_focus * vec2(asp, 1.0);
  s = f + (s - f) / z;
  t = lightStudy(s);
  gp = s * u_res.y;
#endif
  t = pow(max(t, 1e-4), u_gamma);
  t = mix(t, t * t * (3.0 - 2.0 * t), u_contrast);

  // the grade: shadow to highlight, through the middle tone as a smooth curve, in OKLab
  vec3 col = u_tones > 2.5 ? mix(mix(u_kS, u_kM, t), mix(u_kM, u_kH, t), t) : mix(u_kS, u_kH, t);
  // with a yellow key, a yellow-hued pixel gives up its chroma below lightness 0.7 (a dark yellow is khaki)
  float cy = length(col.yz);
  if (u_mud > 0.5 && cy > 1e-4) {
    float hy = degrees(atan(col.z, col.y));
    hy = hy < 0.0 ? hy + 360.0 : hy;
    col.yz *= 1.0 - smoothstep(45.0, 60.0, hy) * (1.0 - smoothstep(120.0, 135.0, hy)) * (1.0 - smoothstep(0.4, 0.7, col.x));
  }

  // burn (or lift) where text sits: a gradient off the frame edge nearest the text (a centred text dims
  // the whole frame instead) and a flat core under the text itself, so a line of type reads on it
  vec2 cp = vec2(u_calmX, u_calmY);
  vec2 off = (vec2(0.5) - cp) * vec2(asp, 1.0);
  float lo = length(off);
  float along = dot((uv - cp) * vec2(asp, 1.0), off / max(lo, 1e-3));
  float scrim = 1.0 - smoothstep(-0.15, 0.2 + 0.45 * u_calm, along);
  scrim = mix(0.55, scrim, smoothstep(0.08, 0.3, lo));
