/* fx-map: the real streets around the place in the page's colours, a pin, the walk from the station and
   an address card. Light pages: white streets on a land a step darker than the page; dark pages: lighter
   streets on a land a step lighter. Water and parks keep their natural blue and green, mixed into the land. */
.cx-map {
  position: relative; border-radius: var(--r-lg); overflow: hidden; border: 1px solid var(--cx-line); container-type: inline-size;
  --map-land: color-mix(in oklab, var(--ink) 6%, var(--bg));
  --map-road: var(--bg);
  --map-casing: color-mix(in oklab, var(--ink) 15%, var(--bg));
  --map-path: color-mix(in oklab, var(--ink) 20%, var(--bg));
  --map-rail: color-mix(in oklab, var(--ink) 30%, var(--bg));
  --map-water: color-mix(in oklab, #86b4d8 46%, var(--map-land));
  --map-green: color-mix(in oklab, #a4cf8f 40%, var(--map-land));
  --map-plaza: color-mix(in oklab, var(--ink) 2.5%, var(--bg));
  --map-name: color-mix(in oklab, var(--ink) 66%, var(--bg));
}
.cx-map.is-dark {
  --map-land: color-mix(in oklab, var(--ink) 7%, var(--bg));
  --map-road: color-mix(in oklab, var(--ink) 19%, var(--bg));
  --map-casing: color-mix(in oklab, var(--ink) 11%, var(--bg));
  --map-path: color-mix(in oklab, var(--ink) 16%, var(--bg));
  --map-rail: color-mix(in oklab, var(--ink) 26%, var(--bg));
  --map-water: color-mix(in oklab, #3d7bab 34%, var(--map-land));
  --map-green: color-mix(in oklab, #4f8f4f 26%, var(--map-land));
  --map-plaza: color-mix(in oklab, var(--ink) 12%, var(--bg));
  --map-name: color-mix(in oklab, var(--ink) 62%, var(--bg));
}
/* the height from the width (16:7), never under 380px; a height, not aspect-ratio with a min-height, which
   widened the ground past the card at 820 */
.cx-map__ground { position: relative; isolation: isolate; height: max(380px, 43.75cqw); background: var(--map-land); overflow: hidden; }
.cx-map.has-ground .cx-map__ground { background: var(--cx-panel); }
/* the fallback ground is no map data: no OpenStreetMap credit on it */
.cx-map.has-ground .cx-map__credit { display: none; }
/* nor a scale: the fallback is a picture, not a map at any scale */
.cx-map.has-ground .cx-map__scale { display: none; }
.cx-map__svg { position: absolute; inset: 0; width: 100%; height: 100%; display: block; --m: 1; --k: 1; }

/* the layers; widths are screen pixels (--m is metres per pixel, --k thins them when zoomed out) */
.cx-map__land { fill: var(--map-land); }
.cx-map__svg .is-area { stroke: none; fill-rule: evenodd; }
.cx-map__sea, .cx-map__water { fill: var(--map-water); }
.cx-map__land, .cx-map__svg path.cx-map__land { fill: var(--map-land); }
.cx-map__green { fill: var(--map-green); }
.cx-map__plaza { fill: var(--map-plaza); }
.cx-map__svg .is-line, .cx-map__svg .is-casing { fill: none; stroke-linecap: round; stroke-linejoin: round; }
.cx-map__river { stroke: var(--map-water); stroke-width: calc(7px * var(--m)); }
.cx-map__canal { stroke: var(--map-water); stroke-width: calc(4px * var(--m)); }
.cx-map__stream { stroke: var(--map-water); stroke-width: calc(1.6px * var(--m)); }
.cx-map__path.is-line { stroke: var(--map-path); stroke-width: calc(1px * var(--m)); stroke-dasharray: calc(3px * var(--m)) calc(2px * var(--m)); }
.cx-map__rail { stroke: var(--map-rail); stroke-width: calc(1.6px * var(--m)); }
.cx-map__tram { stroke: var(--map-rail); stroke-width: calc(1px * var(--m)); opacity: .8; }
.cx-map__minor.is-line { stroke: var(--map-road); stroke-width: calc(2.6px * var(--m) * var(--k)); }
.cx-map__street.is-casing { stroke: var(--map-casing); stroke-width: calc(6.4px * var(--m) * var(--k)); }
.cx-map__street.is-line { stroke: var(--map-road); stroke-width: calc(4.6px * var(--m) * var(--k)); }
.cx-map__major.is-casing { stroke: var(--map-casing); stroke-width: calc(10px * var(--m) * var(--k)); }
.cx-map__major.is-line { stroke: var(--map-road); stroke-width: calc(8px * var(--m) * var(--k)); }
.cx-map.is-dark .cx-map__street.is-casing, .cx-map.is-dark .cx-map__major.is-casing { stroke: transparent; }
.cx-map.is-dark .cx-map__major.is-line { stroke: color-mix(in oklab, var(--ink) 24%, var(--bg)); }

/* the walk from the station: dots at rest; pointed at, a solid line runs from the station to the door */
.cx-map__route-casing { fill: none; stroke: var(--bg); stroke-width: calc(7px * var(--m)); stroke-linecap: round; stroke-linejoin: round; opacity: .7; }
.cx-map__route { fill: none; stroke: var(--accent); stroke-width: calc(5px * var(--m)); stroke-linecap: round; stroke-linejoin: round; }
.cx-map__pass {
  fill: none; stroke: var(--accent); stroke-width: calc(4.5px * var(--m)); stroke-linecap: round; stroke-linejoin: round;
  stroke-dasharray: 100 100; stroke-dashoffset: 100; opacity: 0;
  transition: opacity .25s var(--cx-ease);
}
.cx-map.is-walking .cx-map__pass { opacity: 1; animation: cx-map-walk 1.1s var(--cx-ease) forwards; }
@keyframes cx-map-walk { from { stroke-dashoffset: 100; } to { stroke-dashoffset: 0; } }

/* street names, set along their streets with a halo of the land */
.cx-map__name {
  font: 500 calc(11.5px * var(--m)) / 1 var(--font-text); letter-spacing: .01em;
  fill: var(--map-name); stroke: var(--map-land); stroke-width: calc(3px * var(--m)); stroke-linejoin: round; paint-order: stroke;
  pointer-events: none; user-select: none;
}
.cx-map__name.is-major { font-weight: 600; fill: color-mix(in oklab, var(--ink) 74%, var(--bg)); }

/* the pin, the station and the walk time */
.cx-map__pin { position: absolute; left: 64%; top: 42%; z-index: 2; width: 0; height: 0; }
.cx-map__dot {
  position: absolute; left: -10px; top: -10px; width: 20px; height: 20px; border-radius: 99px;
  background: var(--accent); border: 3px solid var(--bg);
  box-shadow: 0 0 0 1px color-mix(in oklab, var(--ink) 18%, transparent), 0 6px 16px -4px rgb(0 0 0 / .35);
}
.cx-map__halo {
  position: absolute; left: -36px; top: -36px; width: 72px; height: 72px; border-radius: 99px;
  background: radial-gradient(closest-side, color-mix(in oklab, var(--accent) 30%, transparent), transparent);
  transform: scale(.8); opacity: .8;
}
/* the halo answers once when the walk is drawn, then rests */
.cx-map.is-walking .cx-map__halo { animation: cx-map-breathe 1.2s var(--cx-ease) .9s 1; }
@keyframes cx-map-breathe { 0%, 100% { transform: scale(.8); opacity: .8; } 45% { transform: scale(1.25); opacity: .35; } }
.cx-map__tag {
  position: absolute; left: 18px; top: -15px; white-space: nowrap; height: 30px; display: inline-flex; align-items: center;
  padding: 0 11px; border-radius: var(--r-md); background: var(--bg); color: var(--ink); font-size: 14px; font-weight: 600;
  box-shadow: var(--cx-shadow);
}
.cx-map__pin[data-side="l"] .cx-map__tag { left: auto; right: 18px; }
.cx-map__pin[data-side="t"] .cx-map__tag { left: 0; top: -50px; transform: translateX(-50%); }
.cx-map__pin[data-side="b"] .cx-map__tag { left: 0; top: 20px; transform: translateX(-50%); }
.cx-map__stop { position: absolute; z-index: 1; width: 0; height: 0; pointer-events: none; }
.cx-map__stop i {
  position: absolute; left: -7px; top: -7px; width: 14px; height: 14px; border-radius: 4px;
  background: var(--ink); border: 2px solid var(--bg); box-shadow: 0 1px 4px rgb(0 0 0 / .25);
}
.cx-map__stop b {
  position: absolute; left: 13px; top: -11px; white-space: nowrap; height: 22px; display: inline-flex; align-items: center;
  padding: 0 7px; border-radius: 6px; background: color-mix(in oklab, var(--bg) 88%, transparent);
  font: 500 12.5px/1 var(--font-text); color: var(--ink);
}
.cx-map__stop[data-side="l"] b { left: auto; right: 13px; }
.cx-map__stop[data-side="t"] b { left: 0; top: -36px; transform: translateX(-50%); }
.cx-map__stop[data-side="b"] b { left: 0; top: 13px; transform: translateX(-50%); }
.cx-map__walk {
  position: absolute; z-index: 1; transform: translate(-50%, -50%); display: inline-flex; align-items: center; gap: 5px;
  height: 26px; padding: 0 10px 0 8px; border-radius: 99px; white-space: nowrap; pointer-events: none;
  background: var(--accent); color: var(--accent-ink, #fff); font: 600 12.5px/1 var(--font-text);
  box-shadow: 0 2px 8px -2px rgb(0 0 0 / .3);
}
.cx-map__walk svg circle { fill: currentColor; }
.cx-map__walk[hidden] { display: none; }

.cx-map__scale {
  position: absolute; right: var(--s-5); bottom: var(--s-5); z-index: 2; display: grid; justify-items: end; gap: 5px;
  font: 500 11px/1 var(--font-text); color: var(--map-name);
}
.cx-map__scale span { width: 72px; height: 6px; border: 1.5px solid var(--map-name); border-top: 0; }
.cx-map__credit {
  position: absolute; right: 0; bottom: 0; z-index: 2; padding: 3px 8px; border-top-left-radius: 6px;
  font: 400 10.5px/1.3 var(--font-text); color: var(--map-name); text-decoration: none;
  background: color-mix(in oklab, var(--map-land) 80%, transparent);
}
.cx-map__credit:hover { color: var(--ink); text-decoration: underline; }
.cx-map__scale { bottom: calc(var(--s-5) + 8px); }

.cx-map__card {
  position: absolute; left: var(--s-5); bottom: var(--s-5); z-index: 3; width: min(340px, calc(100% - 48px));
  display: grid; gap: var(--s-2); padding: var(--s-5); border-radius: var(--r-md);
  background: var(--bg); box-shadow: var(--cx-shadow);
}
.cx-map__addr { font-style: normal; font-size: var(--t-small); line-height: 1.55; color: var(--ink); }
.cx-map__line { display: flex; align-items: center; gap: 8px; margin: 0; font-size: var(--t-label); color: var(--muted); }
.cx-map__hours { display: flex; align-items: center; gap: 8px; margin: 0; font-size: var(--t-label); color: var(--muted); }
.cx-map__open { width: 7px; height: 7px; border-radius: 9px; background: color-mix(in oklab, var(--accent) 85%, var(--ink)); }
.cx-map__actions { display: flex; flex-wrap: wrap; gap: var(--s-2); margin-top: var(--s-3); }
.cx-map__coords { display: none; }
@media (prefers-reduced-motion: reduce) {
  .cx-map.is-walking .cx-map__halo { animation: none; }
  .cx-map.is-walking .cx-map__pass { animation: none; opacity: 0; }
}
/* under 900px (a tablet, a phone, a half column) the card sits below the map, so it never covers the
   pin, the walk or the scale bar, and the map keeps the whole width */
@container (max-width: 899px) {
  .cx-map__ground { height: max(340px, 50cqw); }
  .cx-map__card {
    position: relative; left: auto; bottom: auto; width: auto; border-radius: 0; box-shadow: none; border-top: 1px solid var(--cx-line);
    grid-template-columns: 1fr auto; column-gap: var(--s-6); align-items: end;
  }
  .cx-map__card > * { grid-column: 1; }
  .cx-map__actions { grid-column: 2; grid-row: 1 / span 5; align-self: end; margin-top: 0; }
  .cx-map__scale { bottom: calc(var(--s-4) + 8px); right: var(--s-4); }
}
@container (max-width: 559px) {
  .cx-map__ground { height: 340px; }
  .cx-map__card { grid-template-columns: 1fr; }
  .cx-map__actions { grid-column: 1; grid-row: auto; margin-top: var(--s-3); }
  .cx-map__actions .btn { flex: 1; }
}

components/fx-map/component.js:
// fx-map: a street map of the real place, in the page's own colours. The streets, water, parks, rails,
// street names and the walk from the nearest station come from OpenStreetMap, baked once at build time
// by bake.mjs into a small JSON (inline in <script type="application/json" class="cx-map__data">, or a
// file named by data-cx-map). Plain SVG: no map service, no key, no WebGL, nothing moves at rest.
// Pointed at, the walk lights up from the station to the door and the pin's halo answers once.
// Without baked data (no network at build time) it falls back to a still effect ground with the pin.
import { still, palette, tone, bag, color, isDark, reduced } from '../shared.js';

const NS = 'http://www.w3.org/2000/svg';
let uid = 0;

// the fallback grounds, each with its own params only (one effect's numbers mean something else to another)
const PARAMS = {
  'contour-lines': narrow => ({ levels: 30, scale: narrow ? 1.6 : 1.25, lineWidth: 1, indexEvery: 5, opacity: 0.32, speed: 0, tint: 0.45, shade: 0.35, edge: 0.4, calm: narrow ? 0 : 0.55, calmX: 0.17, calmY: 0.78 }),
  'dot-terrain': narrow => ({ spacing: narrow ? 11 : 13, dot: 2.4, amplitude: 0.2, waveScale: 1.1, speed: 0, opacity: 0.9, shade: 0.8, crest: 0.7, horizon: 0.16, fog: 0.35, haze: 0.25, calm: narrow ? 0 : 0.55, calmX: 0.17, calmY: 0.8 }),
  'ruled-grounds': narrow => ({ cell: narrow ? 14 : 16, major: 4, ink: 0.85, focus: 0.5, speed: 0, reach: 0.85, grain: 0.35, calm: narrow ? 0 : 0.45, calmX: 0.17, calmY: 0.78 }),
};
// bottom to top; lines are stroked, areas filled
const LAYERS = [
  ['sea', 'area'], ['land', 'area'], ['green', 'area'], ['plaza', 'area'], ['water', 'area'],
  ['stream', 'line'], ['canal', 'line'], ['river', 'line'],
  ['path', 'line'], ['rail', 'line'], ['tram', 'line'], ['minor', 'line'],
  ['street', 'casing'], ['major', 'casing'], ['street', 'line'], ['major', 'line'],
];
const NICE = [50, 100, 200, 250, 500, 1000, 2000];

async function readData(root) {
  const inline = root.querySelector('script.cx-map__data[type="application/json"]');
  if (inline) { try { return JSON.parse(inline.textContent); } catch (e) { console.warn('fx-map: bad inline data', e); } }
  const src = root.dataset.cxMap;
  if (!src) return null;
  try { const r = await fetch(new URL(src, document.baseURI)); return r.ok ? await r.json() : null; } catch (e) { console.warn('fx-map: no map data', e); return null; }
}
const el = (name, attrs = {}) => { const n = document.createElementNS(NS, name); for (const k in attrs) n.setAttribute(k, attrs[k]); return n; };

export default function init(root) {
  const b = bag();
  let dead = false;
  const ground = root.querySelector('.cx-map__ground');
  const svg = root.querySelector('.cx-map__svg');
  const pin = root.querySelector('.cx-map__pin');
  const tag = root.querySelector('.cx-map__tag');
  const scale = root.querySelector('.cx-map__scale');
  const card = root.querySelector('.cx-map__card');
  b.add(() => { dead = true; });
  root.classList.toggle('is-dark', isDark(palette(root)));

  readData(root).then(data => {
    if (dead) return;
    if (data && data.box && svg) draw(data); else fallback();
  });

  /* ------------------------------------------------------------------ the street map */
  function draw(data) {
    root.classList.add('has-streets');
    const id = `cxm${++uid}`;
    const [bx, by, bw, bh] = data.box;
    svg.setAttribute('preserveAspectRatio', 'none');
    svg.replaceChildren();
    const g = el('g');
    g.append(el('rect', { class: 'cx-map__land', x: bx, y: by, width: bw, height: bh }));
    for (const [name, kind] of LAYERS) {
      if (!data[name]) continue;
      g.append(el('path', { class: `cx-map__${name} is-${kind}`, d: data[name] }));
    }
    // the walk: a dotted line at rest, a solid pass drawn over it when pointed at
    let walk = null, pass = null, stop = null, chip = null;
    if (data.route && data.route.d) {
      // the bake writes the walk in rounded relative steps, so its end drifts a few metres off the door:
      // close it on the pin (0 0) so the walk reaches the dot
      const rd = `${data.route.d} L0 0`;
      g.append(el('path', { class: 'cx-map__route-casing', d: rd }));
      walk = el('path', { class: 'cx-map__route', d: rd });
      pass = el('path', { class: 'cx-map__pass', d: rd, pathLength: 100 });
      g.append(walk, pass);
    }
    // street names along their streets
    const defs = el('defs');
    const names = (data.labels || []).map((l, i) => {
      const pid = `${id}-s${i}`;
      defs.append(el('path', { id: pid, d: l.d }));
      const t = el('text', { class: `cx-map__name is-${l.cls}` });
      const tp = el('textPath', { href: `#${pid}`, startOffset: '50%', 'text-anchor': 'middle' });
      tp.textContent = l.name;
      t.append(tp);
      return { t, len: l.len, name: l.name };
    });
    g.prepend(defs);
    const nameLayer = el('g', { class: 'cx-map__names' });
    for (const n of names) nameLayer.append(n.t);
    g.append(nameLayer);
    svg.append(g);

    if (data.route && data.route.from) {
      stop = document.createElement('span');
      stop.className = 'cx-map__stop';
      stop.setAttribute('aria-hidden', 'true');
      stop.innerHTML = '<i></i><b></b>';
      stop.querySelector('b').textContent = data.route.from.name;
      chip = document.createElement('span');
      chip.className = 'cx-map__walk';
      chip.setAttribute('aria-hidden', 'true');
      chip.innerHTML = '<svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true"><circle cx="9" cy="2.6" r="1.6"/><path d="M8.2 5.2 6 6.6 5 9.4m3.2-4.2 1.1 4 2.4 1.6M9.3 9.2 7.6 12.4 6.2 14.6m3.1-5.4 1 3.2 1.2 2.2" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg><span></span>';
      chip.querySelector('span').textContent = `${data.route.min} min walk`;
      ground.append(stop, chip);
      b.add(() => { stop.remove(); chip.remove(); });
    }

    // fit: the place and the walk in the free part of the frame (right of the card when it sits on
    // the map), at a zoom where streets still read as streets
    const layout = () => {
      if (dead) return;
      const W = ground.clientWidth, H = ground.clientHeight;
      if (!W || !H) return;
      const narrow = root.clientWidth < 560;
      const R = ground.getBoundingClientRect();
      let fx0 = narrow ? 20 : 48, fy0 = 44, fx1 = W - 40, fy1 = H - 56;
      // the card covers the map only from 900px of width (the CSS container query); then the free part is right of it
      if (root.clientWidth >= 900 && card) { const c = card.getBoundingClientRect(); if (c.right - R.left < W * 0.6) fx0 = c.right - R.left + 48; }
      const from = data.route && data.route.from;
      // the pin's name and the station's name sit on the side the walk does not leave by; on a narrow
      // frame above or below, so the walk keeps the width
      const sideAway = (vx0, vy0) => {
        if (Math.abs(vx0) >= Math.abs(vy0) && !narrow) return vx0 > 0 ? 'l' : 'r';
        return vy0 > 0 ? 't' : 'b';
      };
      let tagSide = narrow ? 't' : 'r', stopSide = 'r';
      if (walk) {
        const L = walk.getTotalLength();
        const a = walk.getPointAtLength(Math.max(0, L - 70)), z = walk.getPointAtLength(Math.min(L, 70));
        tagSide = sideAway(a.x, a.y);
        stopSide = sideAway(z.x - from.x, z.y - from.y);
      }
      // each mark with its name as a box in pixels around its point
      const boxOf = (side, w, h, r) => side === 'r' ? [-r, -h / 2, r + 8 + w, h / 2] : side === 'l' ? [-(r + 8 + w), -h / 2, r, h / 2]
        : side === 't' ? [-w / 2, -(h + r + 8), w / 2, r] : [-w / 2, -r, w / 2, h + r + 8];
      const marks = [[0, 0, boxOf(tagSide, tag ? tag.offsetWidth : 120, 30, 12)]];
      if (from) marks.push([from.x, from.y, boxOf(stopSide, stop.querySelector('b').offsetWidth, 22, 8)]);
      const fw = Math.max(80, fx1 - fx0), fh = Math.max(80, fy1 - fy0);
      const extent = mm => {
        const xs = marks.flatMap(([x, , bx4]) => [x / mm + bx4[0], x / mm + bx4[2]]), ys = marks.flatMap(([, y, bx4]) => [y / mm + bx4[1], y / mm + bx4[3]]);
        return [Math.min(...xs), Math.min(...ys), Math.max(...xs), Math.max(...ys)];
      };
      const fits = mm => { const e = extent(mm); return e[2] - e[0] <= fw && e[3] - e[1] <= fh; };
      // the closest zoom (streets still read as streets) at which the marks and their names fit
      const minM = narrow ? 1.1 : 1.05, maxM = Math.min(3, bw / W, bh / H);
      let m = minM;
      if (!fits(minM)) {
        let lo = minM, hi = maxM;
        if (!fits(hi)) m = hi; else { for (let i = 0; i < 18; i++) { const mid = (lo + hi) / 2; if (fits(mid)) hi = mid; else lo = mid; } m = hi; }
      }
      const e = extent(m);
      let vx = -(((fx0 + fx1) / 2) - (e[0] + e[2]) / 2) * m, vy = -(((fy0 + fy1) / 2) - (e[1] + e[3]) / 2) * m;
      vx = Math.min(Math.max(vx, bx), bx + bw - W * m);
      vy = Math.min(Math.max(vy, by), by + bh - H * m);
      svg.setAttribute('viewBox', `${vx} ${vy} ${W * m} ${H * m}`);
      // strokes and type in screen pixels: --m is metres per pixel; --k thins the lines when zoomed out
      svg.style.setProperty('--m', m.toFixed(4));
      svg.style.setProperty('--k', Math.min(1.15, Math.max(0.62, 1.25 / m)).toFixed(3));
      const at = ([x, y]) => [(x - vx) / m, (y - vy) / m];
      const [px, py] = at([0, 0]);
      pin.style.left = `${px}px`; pin.style.top = `${py}px`;
      pin.dataset.side = tagSide;
      if (walk) walk.style.strokeDasharray = `0 ${(9 * m).toFixed(2)}`;
      if (stop) {
        const [sx, sy] = at([from.x, from.y]);
        stop.style.left = `${sx}px`; stop.style.top = `${sy}px`;
        stop.dataset.side = stopSide;
      }
      if (chip && walk) {
        const L = walk.getTotalLength(), mid = walk.getPointAtLength(L * 0.5);
        const [hx, hy] = at([mid.x, mid.y]);
        chip.style.left = `${hx}px`; chip.style.top = `${hy}px`;
      }
      // the scale bar: a round distance 60 to 130 px long
      if (scale) {
        const d = NICE.find(n => n / m >= 60) || NICE[NICE.length - 1];
        scale.querySelector('span').style.width = `${Math.round(d / m)}px`;
        scale.lastChild.nodeValue = d >= 1000 ? `${d / 1000} km` : `${d} m`;
      }
      // names: only those that fit their street, stay inside the frame and clear of every label
      const marksEls = [tag, root.querySelector('.cx-map__dot'), stop && stop.querySelector('b'), stop && stop.querySelector('i')].filter(Boolean);
      const block = [...marksEls, chip, scale, root.querySelector('.cx-map__credit'), root.clientWidth >= 900 ? card : null]
        .filter(Boolean).map(n => n.getBoundingClientRect()).filter(r => r.width);
      const hit = (a, r, pad) => a.left < r.right + pad && a.right > r.left - pad && a.top < r.bottom + pad && a.bottom > r.top - pad;
      const kept = [], shown = new Set();
      const most = narrow ? 3 : 6;
      for (const n of names) {
        n.t.style.display = '';
        let ok = kept.length < most && !shown.has(n.name);
        if (ok) { try { ok = n.t.getComputedTextLength() < n.len * 0.94; } catch { ok = false; } }
        if (ok) {
          const r = n.t.getBoundingClientRect();
          ok = r.width > 0 && r.left > R.left + 10 && r.right < R.right - 10 && r.top > R.top + 10 && r.bottom < R.bottom - 10 &&
            !block.some(x => hit(r, x, 8)) && !kept.some(x => hit(r, x, 14));
          if (ok) { kept.push(r); shown.add(n.name); }
        }
        if (!ok) n.t.style.display = 'none';
      }
      if (chip) {
        const c = chip.getBoundingClientRect();
        chip.hidden = false;
        chip.hidden = marksEls.some(n => hit(c, n.getBoundingClientRect(), 4));
      }
    };
    layout();
    let raf = 0;
    const ro = new ResizeObserver(() => { cancelAnimationFrame(raf); raf = requestAnimationFrame(layout); });
    ro.observe(ground);
    if (card) ro.observe(card);
    b.add(() => { ro.disconnect(); cancelAnimationFrame(raf); svg.replaceChildren(); root.classList.remove('has-streets', 'is-walking'); });
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(() => { if (!dead) layout(); });

    // pointed at: the walk is drawn from the station to the door, the halo answers once
    if (pass && !reduced()) {
      let t = 0;
      const on = () => { clearTimeout(t); root.classList.remove('is-walking'); void pass.getBoundingClientRect(); root.classList.add('is-walking'); };
      const off = () => { clearTimeout(t); t = setTimeout(() => root.classList.remove('is-walking'), 260); };
      ground.addEventListener('pointerenter', on);
      ground.addEventListener('pointerleave', off);
      const btns = [...root.querySelectorAll('.cx-map__actions a')];
      for (const a of btns) { a.addEventListener('pointerenter', on); a.addEventListener('focus', on); a.addEventListener('blur', off); a.addEventListener('pointerleave', off); }
      b.add(() => {
        clearTimeout(t);
        ground.removeEventListener('pointerenter', on); ground.removeEventListener('pointerleave', off);
        for (const a of btns) { a.removeEventListener('pointerenter', on); a.removeEventListener('focus', on); a.removeEventListener('blur', off); a.removeEventListener('pointerleave', off); }
      });
    }
  }

  /* ------------------------------------------------------------------ no data: a still ground */
  function fallback() {
    root.classList.add('has-ground');
    if (svg) svg.remove();
    const page = palette(root);
    const effect = PARAMS[root.dataset.cxEffect] ? root.dataset.cxEffect : 'contour-lines';
    const narrow = root.clientWidth < 560;
    const bg = tone(page, 0.065);
    b.add(still(ground, effect, {
      palette: { ...page, bg, ...(effect === 'dot-terrain' ? { ink: color.mix(page.ink, bg, 0.25) } : {}) },
      seed: root.dataset.cxSeed,
      params: PARAMS[effect](narrow),
    }));
    pin.style.left = 'var(--x, 64%)';
    pin.style.top = 'var(--y, 42%)';
  }

  /* ------------------------------------------------------------------ copy address */
  const btn = root.querySelector('[data-copy]');
  if (btn) {
    const label = btn.textContent;
    let t = 0;
    const copy = async () => {
      try { await navigator.clipboard.writeText(btn.dataset.copy || (root.querySelector('address') || {}).innerText || ''); btn.textContent = 'Copied'; }
      catch (_) { btn.textContent = 'Select and copy'; }
      clearTimeout(t);
      t = setTimeout(() => { btn.textContent = label; }, 1600);
    };
    btn.addEventListener('click', copy);
    b.add(() => { clearTimeout(t); btn.textContent = label; btn.removeEventListener('click', copy); });
  }
  return b;
}

