  inset panel with its own 8px margin (radius = card radius - margin) holding a still effect ground
  and one smaller UI window. Two panels (one per row) run a short pointer demo; the others show a
  settled still. The cards and panels never move.
*/
.cx-feat { --cx-feat-m: var(--s-2); --cx-feat-h: 340px; display: grid; gap: var(--s-7); }
.cx-feat__head { display: grid; justify-items: center; gap: var(--s-3); text-align: center; }
