.cx-feat__sub { margin: 0; max-width: 54ch; font-size: var(--t-lead); line-height: 1.5; color: var(--muted); text-wrap: balance; }

/* each card spans two rows of the grid (text, panel) as a subgrid, so the text zones of a row share
   one height and the panels of a row start on one line */
.cx-feat__grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--s-4); }
.cx-feat__card {
  display: grid; grid-row: span 2; grid-template-rows: subgrid; row-gap: 0; min-width: 0; overflow: hidden;
  border-radius: var(--r-lg); background: var(--cx-card); border: 1px solid var(--cx-line);
  box-shadow: inset 0 1px 0 var(--cx-hi);
}
/* the text zone: same height in every card of a row (the grid row sizes it), never over the panel */
.cx-feat__copy { display: grid; align-content: start; gap: 6px; padding: var(--s-5) var(--s-5) var(--s-5); }
.cx-feat__title { font: 500 var(--t-card)/1.3 var(--font-text); letter-spacing: -0.01em; margin: 0; }
.cx-feat__text { margin: 0; font-size: 15px; line-height: 1.5; color: var(--muted); max-width: 50ch; text-wrap: pretty; }

/* the inset panel: one step off the card, its radius the card's minus its margin */
.cx-feat__panel {
  position: relative; isolation: isolate; overflow: hidden; height: var(--cx-feat-h); align-self: end;
  margin: 0 var(--cx-feat-m) var(--cx-feat-m); border-radius: calc(var(--r-lg) - var(--cx-feat-m));
  background: var(--cx-panel);
}

/* ---- the UI window on the ground (opaque, page ground colour) */
.cx-feat__win {
  position: absolute; z-index: 1; display: grid; align-content: start;
  background: var(--bg); color: var(--ink); border-radius: var(--r-md);
  box-shadow: 0 0 0 1px var(--cx-line-2), 0 2px 4px rgb(0 0 0 / .12), 0 18px 40px -12px rgb(0 0 0 / .45);
  font-size: 13px; line-height: 1.4;
}
/* every window starts some way down the panel and runs out through its bottom edge, so it reads as a
   cut from a real screen, never as a dialog floating in the middle of an empty ground */
.cx-feat__win--bleed { left: 12%; right: 12%; top: 56px; bottom: -24px; }
.cx-feat__win--narrow { left: 50%; width: min(300px, calc(100% - 64px)); transform: translateX(-50%); top: 44px; bottom: -24px; }
.cx-feat__win--side { left: 9%; right: 22%; top: 72px; bottom: -24px; }

.cx-feat__bar { display: flex; align-items: center; gap: 10px; height: 48px; padding: 0 10px 0 16px; border-bottom: 1px solid var(--cx-line); }
.cx-feat__name { font-weight: 500; font-size: 13px; }
/* in a window's bar the title keeps one line (it gives way with an ellipsis, never wraps) */
.cx-feat__bar .cx-feat__name { min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.cx-feat__chip {
  display: inline-flex; align-items: center; gap: 6px; height: 22px; padding: 0 8px; border-radius: var(--r-sm);
  font: 500 11.5px/1 var(--font-text); font-style: normal; color: var(--muted); background: var(--cx-panel);
  transition: background-color .3s var(--cx-ease), color .3s var(--cx-ease);
}
.cx-feat__chip::before { content: ""; width: 6px; height: 6px; border-radius: 9px; background: currentColor; opacity: .7; }
.cx-feat__chip.is-on { color: var(--ink); background: color-mix(in oklab, var(--accent) 22%, var(--bg)); }
.cx-feat__chip.is-on::before { background: var(--accent); opacity: 1; }
.cx-feat__btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; height: 30px; padding: 0 14px; margin-left: auto;
  border-radius: var(--r-sm); background: var(--action); color: var(--action-ink); font: 500 12.5px/1 var(--font-text);
  transition: transform .12s var(--cx-ease), filter .2s var(--cx-ease);
}
.cx-feat__btn.is-down { transform: scale(.96); filter: brightness(.92); }
.cx-feat__btn.is-done::before {
  content: ""; width: 9px; height: 5px; margin-top: -3px; border-left: 1.6px solid currentColor; border-bottom: 1.6px solid currentColor; transform: rotate(-45deg);
}
.cx-feat__btn--wide { margin: 10px 0 0; width: 100%; height: 36px; font-size: 13px; }

.cx-feat__meta { display: grid; gap: 8px; margin: 0; padding: 14px 16px; border-bottom: 1px solid var(--cx-line); }
.cx-feat__meta div { display: grid; grid-template-columns: 88px 1fr; }
.cx-feat__meta dt { color: var(--muted); }
.cx-feat__meta dd { margin: 0; }
.cx-feat__lines { margin: 0; padding: 6px 16px; list-style: none; }
.cx-feat__lines li { display: flex; justify-content: space-between; gap: 12px; padding: 8px 0; }
.cx-feat__lines li + li { border-top: 1px solid var(--cx-line); }
.cx-feat__lines b { font-weight: 500; }
.cx-feat__lines .is-total span { color: var(--muted); }
.cx-feat__foot { display: flex; justify-content: space-between; gap: 12px; padding: 12px 16px; border-top: 1px solid var(--cx-line); background: var(--cx-card); color: var(--muted); }
.cx-feat__foot span:last-child { color: var(--ink); text-align: right; }

/* payment link */
.cx-feat__pay { gap: 4px; padding: 18px; justify-items: start; }
.cx-feat__pay .cx-feat__name { color: var(--muted); font-weight: 400; }
.cx-feat__amount { font: 560 28px/1.15 var(--font-display); letter-spacing: -0.025em; }
.cx-feat__note { color: var(--muted); font-size: 12px; }
.cx-feat__label { margin-top: 12px; color: var(--muted); font-size: 12px; }
.cx-feat__label + .cx-feat__field { margin-top: 2px; }
.cx-feat__field {
  display: flex; align-items: center; justify-content: space-between; gap: 10px; width: 100%; height: 38px; margin: 0 0 4px;
  padding: 0 12px; border-radius: var(--r-sm); box-shadow: inset 0 0 0 1px var(--cx-line-2); font-size: 12.5px; letter-spacing: .02em;
}
.cx-feat__marks { display: inline-flex; align-items: center; gap: 5px; color: var(--muted); }
.cx-feat__marks .cx-mark { height: 11px; width: auto; flex: none; fill: currentColor; }
.cx-feat__or { justify-self: center; margin-top: 10px; color: var(--muted); font-size: 12px; }

/* payout: the schedule switch in the window's bar, then the payouts */
.cx-feat__payout .cx-feat__bar { justify-content: space-between; }
.cx-feat__seg { display: grid; grid-template-columns: repeat(3, auto); padding: 2px; border-radius: var(--r-sm); background: var(--cx-panel); }
.cx-feat__seg span { display: grid; place-items: center; height: 26px; padding: 0 10px; border-radius: calc(var(--r-sm) - 2px); color: var(--muted); font-size: 12px; }
.cx-feat__seg .is-on { background: var(--bg); color: var(--ink); font-weight: 500; box-shadow: 0 0 0 1px var(--cx-line-2), 0 1px 2px rgb(0 0 0 / .12); }
.cx-feat__payout .cx-feat__lines li:first-child span { color: var(--ink); }
.cx-feat__payout .cx-feat__lines li:not(:first-child) { color: var(--muted); }

/* invite */
.cx-feat__invite { display: flex; align-items: center; gap: 8px; padding: 12px; border-bottom: 1px solid var(--cx-line); }
.cx-feat__input, .cx-feat__select {
  display: inline-flex; align-items: center; height: 32px; padding: 0 10px; border-radius: var(--r-sm);
  box-shadow: inset 0 0 0 1px var(--cx-line-2); white-space: nowrap;
}
.cx-feat__input { flex: 1; min-width: 0; overflow: hidden; }
.cx-feat__select { gap: 6px; color: var(--muted); }
.cx-feat__invite .cx-feat__btn { margin-left: 0; height: 32px; }
.cx-feat__caret { width: 1px; height: 15px; margin-left: 1px; background: var(--ink); animation: cx-feat-caret 1s steps(1) infinite; }
@keyframes cx-feat-caret { 50% { opacity: 0; } }
.cx-feat__people { margin: 0; padding: 6px 12px; list-style: none; }
.cx-feat__people li { display: flex; align-items: center; gap: 10px; height: 44px; }
.cx-feat__people li + li { border-top: 1px solid var(--cx-line); }
.cx-feat__people em { margin-left: auto; font-style: normal; color: var(--muted); font-size: 12px; }
.cx-feat__people em.cx-feat__chip { color: var(--ink); background: color-mix(in oklab, var(--accent) 22%, var(--bg)); }
.cx-feat__people em.cx-feat__chip::before { background: var(--accent); opacity: 1; }
.cx-feat__ava {
  display: grid; place-items: center; width: 26px; height: 26px; border-radius: 999px; flex: none;
  background: color-mix(in oklab, var(--accent) var(--a), var(--cx-raise)); font-size: 10.5px; font-weight: 500; letter-spacing: .02em;
}
/* the new invite opens at the top of the list and pushes the others down (never a blank row) */
.cx-feat__new { overflow: hidden; transition: opacity .35s var(--cx-ease), height .35s var(--cx-ease); }
.cx-feat__win:not(.is-added) .cx-feat__new { opacity: 0; height: 0; }
.cx-feat__win:not(.is-added) .cx-feat__new + li { border-top: 0; }

/* ---- the pointer and its click ring (added by the script) */
.cx-feat__ptr {
  position: absolute; left: 0; top: 0; z-index: 3; width: 20px; height: 20px; pointer-events: none; opacity: 0;
  transition: transform 1.1s cubic-bezier(.45, 0, .2, 1), opacity .3s var(--cx-ease);
  filter: drop-shadow(0 2px 3px rgb(0 0 0 / .35));
}
.cx-feat__ptr svg { display: block; width: 20px; height: 20px; }
.cx-feat__ptr path { fill: var(--ink); stroke: var(--bg); stroke-width: 1.5; stroke-linejoin: round; }
.cx-feat__ring {
  position: absolute; left: -14px; top: -14px; z-index: 2; width: 28px; height: 28px; border-radius: 99px; pointer-events: none;
  border: 1.5px solid color-mix(in oklab, var(--ink) 70%, transparent); opacity: 0;
}
.cx-feat__ring.is-on { animation: cx-feat-ring .5s var(--cx-ease) forwards; }
@keyframes cx-feat-ring { from { opacity: .9; scale: .4; } to { opacity: 0; scale: 1.25; } }

/* the pause sits in the panel's top-right corner, above the window */
.cx-feat__panel > .cx-pause { top: var(--s-3); right: var(--s-3); bottom: auto; }

@media (prefers-reduced-motion: reduce) { .cx-feat__caret { animation: none; } }
@media (max-width: 899px) {
  .cx-feat__grid { grid-template-columns: minmax(0, 1fr); }
}
@media (max-width: 639px) {
  .cx-feat { --cx-feat-h: 300px; gap: var(--s-6); }
  .cx-feat__copy { padding: var(--s-5) var(--s-4) var(--s-4); }
  /* the ground keeps a clear margin round the window on a phone, as on a wide screen */
  .cx-feat__win--bleed, .cx-feat__win--side { left: 28px; right: 28px; top: 52px; }
  .cx-feat__win--narrow { top: 44px; width: calc(100% - 56px); }
  .cx-feat__invite .cx-feat__select { display: none; }
  /* the window title keeps one line: the state chip gives way (the button says Sent) */
  .cx-feat__bar .cx-feat__chip { display: none; }
  .cx-feat__meta div { grid-template-columns: 76px 1fr; }
}

components/fx-feature-card/component.js:
// fx-feature-card: every inset panel gets its own still ground (a painted landscape or a soft grain),
// drawn once and kept as a picture: the four grounds render one after another through one WebGL context
// that is freed straight after, so the cards hold no context and draw no frames at rest. The UI window on
// each ground is plain HTML, cut by the panel's bottom edge. Panels marked data-cx-loop run a short
// pointer demo (glide about 1 s, click, the state changes, rest about 3 s) while on screen, with a pause
// button in the panel's corner; the others show a settled still. Reduced motion shows every demo in its
// end state with no pointer.
import { fx, still, palette, color, bag, reduced, held, pauser, paramsOf } from '../shared.js';

// each ground: still (no drift), no calm patch (the window covers the middle)
const GROUNDS = {
  'painterly-landscape': { drift: 0, calm: 0, blur: 0.65, brush: 0.55, grain: 0.035 },
  'grain-gradient': { speed: 0, grainMotion: 0, grain: 0.45, tint: 0.7, contrast: 0.6, softness: 0.55, calm: 0.3, calmX: 0.5, calmY: 0.5 },
  'ruled-grounds': { speed: 0, focus: 0, ink: 0.5, grain: 0.4, calm: 0.4, calmX: 0.5, calmY: 0.6 },
};

/* ------------------------------------------------------------------ the light of each panel */

const ok = (l, c, h) => color.fromLch([l, Math.max(0, c), h]);
const lum = c => color.lab(c)[0];
const coolHue = h => Math.min(265, Math.max(205, h));

/* what the page gives the pictures: its kind, the accent's hue family, its darkest and palest tone */
function read(page) {
  const [La, Ca, ha] = color.lch(page.accent);
  const [Lb, Cb, hb] = color.lch(page.bg);
  const inkLight = lum(page.ink) > lum(page.bg);
  return {
    kind: fx.paletteKind(page), La, Ca, ha, Lb, Cb, hb,
    warm: Ca > 0.05 && (ha < 80 || ha >= 330),             // red, orange, amber
    cool: Ca > 0.04 && ha >= 190 && ha <= 285,             // blue, teal
    dark: inkLight ? page.bg : page.ink,
    pale: inkLight ? page.ink : page.bg,
  };
}

/*
  A painted landscape is a picture, so it takes a natural light, near the page but never one hue laid
  over everything:
  - day: a pale sky (the accent's hue at low chroma when the accent is cool, else almost grey) over
    hills that step down to the near slope: graphite under a warm accent (an orange hill reads as rust),
    a misty blue-grey under a cool one, the accent itself when it is green or neutral; on a colour page
    deeper shades of the page colour.
  - dusk: a deep blue sky that lights up in gold only along the horizon, dark hills with a lit crest
    (the gold leans toward a warm accent, between amber and gold); on a colour page a light shade of the
    page colour (never its complementary accent).
  - meadow: daylight as a photograph shows it, whatever the page: a clear blue sky that pales toward the
    horizon, a blue far ridge and a sunlit field of grass in front. On a blue colour page the sky is the
    page colour itself. The natural picture among the panels, as on x.ai's cards.
*/
const SCENES = {
  day(page, k) {
    let sky, hill;
    if (k.kind === 'colour') {
      sky = ok(0.87, Math.min(k.Cb * 0.3, 0.06), k.hb);
      hill = ok(0.46, Math.min(k.Cb * 0.8, 0.14), k.hb);
    } else {
      const h = k.cool ? coolHue(k.ha) : k.kind === 'light' && k.Cb > 0.012 ? k.hb : 235;
      const L = k.kind === 'light' ? Math.min(0.93, Math.max(0.8, k.Lb - 0.05)) : 0.84;
      sky = ok(L, k.cool ? 0.04 : k.kind === 'light' ? Math.min(k.Cb, 0.03) : 0.012, h);
      hill = k.warm ? ok(0.42, 0.008, k.ha)
        : k.cool ? ok(Math.min(k.La, 0.62), Math.min(k.Ca * 0.55, 0.07), coolHue(k.ha))
          : ok(Math.min(k.La, 0.6), Math.min(k.Ca, 0.1), k.ha);
    }
    return { bg: sky, surface: color.lighten(sky, -0.04), ink: k.dark, muted: color.mix(sky, k.dark, 0.4), accent: hill, accentInk: k.pale };
  },
  dusk(page, k) {
    // a natural evening: a deep blue sky with a band of gold low on the horizon, whatever the accent
    // (a blue glow under a blue accent read as the day panel again, only darker). The gold leans toward a
    // warm accent's hue but stays between amber and gold: a red-orange glow paints the lit crests rust.
    // A gold that mixes with the cool grey of the hills turns beige, never mauve or violet.
    const colourPage = k.kind === 'colour';
    const h = colourPage ? k.hb : k.cool ? coolHue(k.ha) : 248;
    const c = colourPage ? Math.min(k.Cb * 0.5, 0.065) : 0.04;
    const sky = ok(0.26, c, h);
    const glow = colourPage ? ok(0.78, Math.min(k.Cb * 0.4, 0.08), k.hb)
      : ok(0.8, 0.115, k.warm ? Math.min(80, Math.max(58, k.ha < 180 ? k.ha : 58)) : 74);
    return { bg: sky, surface: color.lighten(sky, 0.04), ink: k.pale, muted: ok(0.58, 0.012, h), accent: glow, accentInk: k.dark };
  },
  meadow(page, k) {
    // a sky with chroma above 0.07 is painted as a colour sky over a field of the accent: here a clear
    // blue (never toward violet) over sunlit grass
    const blue = k.kind === 'colour' && k.hb >= 220 && k.hb <= 270;
    const sky = blue ? ok(0.62, Math.min(Math.max(k.Cb * 0.6, 0.09), 0.12), k.hb) : ok(0.66, 0.1, 238);
    const grass = ok(0.74, 0.12, 112);
    return { bg: sky, surface: color.lighten(sky, -0.05), ink: ok(0.97, 0.01, 238), muted: ok(0.8, 0.03, 238), accent: grass, accentInk: k.dark };
  },
};

/* a soft grain: light grounds under a warm accent (a warm accent on a dark ground mixes to rust), deep
   ones under a cool accent, the page colour's own shades on a colour page */
function grainGround(page, k) {
  if (k.kind === 'colour') {
    return { ...page, bg: ok(0.5, Math.min(k.Cb * 0.8, 0.16), k.hb), surface: ok(0.42, Math.min(k.Cb * 0.9, 0.18), k.hb), accent: ok(0.8, Math.min(k.Cb * 0.4, 0.09), k.hb), muted: ok(0.66, 0.04, k.hb) };
  }
  if (k.kind === 'dark') {
    if (k.cool) return { ...page, bg: ok(0.34, Math.min(k.Ca * 0.4, 0.06), k.ha), surface: ok(0.42, Math.min(k.Ca * 0.5, 0.07), k.ha), muted: ok(0.6, 0.03, k.ha) };
    return { ...page, bg: ok(0.8, 0.025, k.ha), surface: ok(0.72, 0.04, k.ha), ink: k.dark, muted: ok(0.6, 0.02, k.ha) };
  }
  return { ...page, bg: color.mix(page.bg, page.accent, 0.16), surface: color.mix(page.bg, page.accent, 0.3), muted: color.mix(page.bg, page.ink, 0.5) };
}

function groundPalette(page, id, scene) {
  const k = read(page);
  if (id === 'painterly-landscape') return (SCENES[scene] || SCENES.day)(page, k);
  if (id === 'grain-gradient') return grainGround(page, k);
  return { ...page, bg: color.mix(page.bg, page.accent, 0.16), surface: color.mix(page.bg, page.accent, 0.3), muted: color.mix(page.bg, page.ink, 0.5) };
}

/* ------------------------------------------------------------------ the pointer demo */

const POINTER = '<svg viewBox="0 0 20 20" aria-hidden="true"><path d="M4 2.8v13.4l3.5-3.3 2.3 5.1 2.5-1.1-2.3-5h5Z"/></svg>';

/* one demo: a pointer and a click ring in the panel; script(api) runs once per loop */
function demo(panel, script, end) {
  const ptr = document.createElement('span');
  ptr.className = 'cx-feat__ptr';
  ptr.innerHTML = POINTER;
  const ring = document.createElement('span');
  ring.className = 'cx-feat__ring';
  panel.append(ring, ptr);
  let alive = true, onScreen = false;
  const io = new IntersectionObserver(e => { onScreen = e[e.length - 1].isIntersecting; });
  io.observe(panel);
  const running = () => onScreen && !document.hidden && !held(panel);
  // wait ms of running time: off screen, in a hidden tab or paused, the clock stops
  const wait = ms => new Promise(res => {
    let acc = 0, last = performance.now();
    const step = () => {
      if (!alive) return;
      const now = performance.now();
      if (running()) acc += now - last;
      last = now;
      if (acc >= ms) res(); else setTimeout(step, running() ? Math.min(100, ms - acc) : 250);
    };
    step();
  });
  const move = (x, y, instant) => {
    if (instant) ptr.style.transition = 'none';
    ptr.style.transform = `translate(${(x - 4).toFixed(1)}px, ${(y - 3).toFixed(1)}px)`;
    if (instant) { ptr.getBoundingClientRect(); ptr.style.transition = ''; }
  };
  const spot = el => {
    const pr = panel.getBoundingClientRect(), r = el.getBoundingClientRect();
    return [r.left - pr.left + r.width * 0.56, r.top - pr.top + r.height * 0.62];
  };
  const show = on => { ptr.style.opacity = on ? '1' : '0'; };
  const click = async el => {
    const [x, y] = spot(el);
    // the ring is placed with the translate property and grows with scale: the two compose as
    // translate then scale, so the ring grows on the spot (a translate inside transform would be
    // scaled too and fly off across the window)
    ring.style.translate = `${x.toFixed(1)}px ${y.toFixed(1)}px`;
    ring.classList.remove('is-on'); void ring.offsetWidth; ring.classList.add('is-on');
    el.classList.add('is-down');
    await wait(140);
    el.classList.remove('is-down');
  };
  const api = { wait, move, spot, show, click, panel };
  if (reduced()) end();
  else {
    end();   // the finished picture first, so a panel that is off screen, paused or never seen is never empty
    (async () => { while (alive) { await wait(600); await script(api); } })();
  }
  return { destroy() { alive = false; io.disconnect(); ptr.remove(); ring.remove(); } };
}

const SCRIPTS = {
  invoice(panel) {
    const btn = panel.querySelector('[data-target]'), label = btn.querySelector('[data-label]');
    const state = panel.querySelector('[data-state]');
    const reset = () => { btn.classList.remove('is-done'); label.textContent = 'Send'; state.textContent = 'Draft'; state.classList.remove('is-on'); };
    const done = () => { btn.classList.add('is-done'); label.textContent = 'Sent'; state.textContent = 'Sent'; state.classList.add('is-on'); };
    return {
      still: done,
      async run({ wait, move, spot, show, click, panel: p }) {
        reset();
        const [x, y] = spot(btn);
        show(false);
        move(x - 150, y + 150, true);
        await wait(900);
        show(true);
        move(x, y);
        await wait(1300);
        await click(btn);
        label.textContent = 'Sending';
        await wait(700);
        done();
        await wait(500);
        move(x + 40, Math.min(p.clientHeight - 30, y + 110));
        show(false);
        await wait(3200);
      },
    };
  },
  invite(panel) {
    const btn = panel.querySelector('[data-target]'), label = btn.querySelector('[data-label]');
    const typed = panel.querySelector('[data-type]'), win = panel.querySelector('[data-demo]');
    const EMAIL = 'ana@northwind.co';
    const reset = () => { typed.textContent = ''; win.classList.remove('is-added'); btn.classList.remove('is-done'); label.textContent = 'Invite'; };
    const done = () => { typed.textContent = ''; win.classList.add('is-added'); btn.classList.add('is-done'); label.textContent = 'Invited'; };
    return {
      still: done,
      async run({ wait, move, spot, show, click, panel: p }) {
        reset();
        const [x, y] = spot(btn);
        show(false);
        move(x - 160, y + 140, true);
        await wait(700);
        for (const ch of EMAIL) { typed.textContent += ch; await wait(55); }
        await wait(300);
        show(true);
        move(x, y);
        await wait(1300);
        await click(btn);
        await wait(250);
        done();
        await wait(500);
        move(x + 30, Math.min(p.clientHeight - 30, y + 120));
        show(false);
        await wait(3400);
      },
    };
  },
};

export default function init(root) {
  const b = bag();
  const page = palette(root);
  root.querySelectorAll('.cx-feat__panel').forEach(panel => {
    const id = panel.dataset.cxEffect || 'painterly-landscape';
    const ground = groundPalette(page, id, panel.dataset.cxScene);
    const params = { ...(GROUNDS[id] || {}), ...(paramsOf(panel) || {}), speed: 0, drift: 0 };
    // the ground never moves: drawn once, kept as a picture, its context freed
    b.add(still(panel, id, { palette: ground, seed: panel.dataset.cxSeed, params }));
    const loop = SCRIPTS[panel.dataset.cxLoop];
    if (loop) {
      // the pause button holds the pointer demo (the ground is a picture and has nothing to pause)
      if (!reduced()) b.add(pauser(panel, { label: 'the demo', corner: 'tr' }));
      const s = loop(panel);
      b.add(demo(panel, s.run, s.still));
    }
  });
  return b;
}

export { groundPalette };

