};
const allIds = JSON.parse(fs.readFileSync(path.join(SKILL, 'library', 'palettes.json'), 'utf8')).map(p => p.id);
const palIds = opt('palettes') ? String(opt('palettes')).split(',') : allIds;

/* ---------------------------------------------------------------- PNG (8-bit RGB/RGBA) */
function decodePNG(buf) {
